import React, { useState, useEffect } from 'react';
import { FaPlus, FaDoorOpen, FaDoorClosed, FaQuestion, FaThumbsUp, FaCalculator, FaUser, FaTrash, FaFileImport, FaCopy } from 'react-icons/fa';
import Table from 'rc-table';
import { PerformGetRequest, PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import RknButton from '../components/RknUI/RknButton';
import { GridLoader, MoonLoader, PulseLoader } from 'react-spinners';
import UpdateClockingEventPopup from '../components/UpdateClockingEventPopup';
import NewEcePopup from '../components/NewEcePopup';
import useDocumentTitle from '@tanem/use-document-title';
import RknBottomToolbar from '../components/RknUI/RknBottomToolbar';
import { GetDateTimeDMYHM } from '../Reaknotron/Libs/RknTimeTools';

const EmployeeClockingBoard = () => {

    useDocumentTitle("Gestion du Pointage");

    useEffect(() => {

        GetEventListFromDB();
        GetEmployeeListFromDB();

    }, []);

    const GetEventListFromDB = async (ParamEmployeeID) => {

        setLoading(true);
        PerformGetRequest("/api/get-employee-clocking-event-list?id=" + (ParamEmployeeID || ""), (res) => {
            setLoading(false);
            console.log("RES = " + JSON.stringify(res.data));
            UpdateTableData(res.data);
        });

    }

    const UpdateTableData = (ParamResponseData) => {

        let tmpTableData = [];
        let lastStates = {};

        let sourceEventList = null;

        if (ParamResponseData) {
            sourceEventList = ParamResponseData;
        } else {
            sourceEventList = tableData;
        }

        // ParamResponseData.forEach(e => {
        sourceEventList.forEach(e => {

            let anomaly = "NULL";

            if (lastStates[e.employee] === e.type) {
                if (e.type === "ENTRY") {
                    anomaly = "ENTRY_IN_ROW";
                } else if (e.type === "EXIT") {
                    anomaly = "EXIT_IN_ROW";
                }
            }

            lastStates[e.employee] = e.type;

            tmpTableData.push({
                _id: e._id,
                employee: e.employee,
                employeeID: e.employeeID,
                type: e.type,
                time: e.time,
                anomaly: anomaly,
                fromTAS: e.fromTAS
            });
        });

        setTableData(tmpTableData);
    }

    const GenerateEventButton = (ParamEvent) => {

        if (ParamEvent.type == "ENTRY") {
            return <div onClick={() => setUpdateECEPopupTarget(ParamEvent)} className='flex flex-row items-center justify-center m-1 p-1 rounded-full text-neutral-100 bg-green-800 hover:bg-green-600 transition duration-150 cursor-pointer active:scale-95'><FaDoorOpen className='mr-2' />Entrée</div>
        } else if (ParamEvent.type == "EXIT") {
            return <div onClick={() => setUpdateECEPopupTarget(ParamEvent)} className='flex flex-row items-center justify-center m-1 p-1 rounded-full text-neutral-100 bg-red-800 hover:bg-red-600 transition duration-150 cursor-pointer active:scale-95'><FaDoorClosed className='mr-2' />Sortie</div>
        } else {
            return <div onClick={() => setUpdateECEPopupTarget(ParamEvent)} className='flex flex-row items-center justify-center m-1 p-1 rounded-full text-neutral-100 bg-neutral-800 hover:bg-neutral-600 transition duration-150 cursor-pointer active:scale-95'><FaQuestion className='mr-2' />Indéfinie</div>
        }
    }

    const GenerateAnomalyMessage = (ParamAnomaly) => {

        if (ParamAnomaly == "ENTRY_IN_ROW") {
            return <div className='flex flex-row items-center justify-center'><FaDoorOpen className='text-green-500 mr-2' />Deux entrées d'affilée</div>
        } else if (ParamAnomaly == "EXIT_IN_ROW") {
            return <div className='flex flex-row items-center justify-center'><FaDoorClosed className='text-red-500 mr-2' />Deux sorties d'affilée</div>
        } else {
            return <div className='flex flex-row items-center justify-center'><FaThumbsUp className='text-neutral-500' /></div>
        }
    }

    const DeleteECEInDB = (ParamProductID) => {

        if (operating)
            return;

        setOperating(true);

        let eceToPost = { id: ParamProductID };
        PerformSecurePostRequest("/api/delete-ece", eceToPost, (res) => {
            // GetEventListFromDB(selectedEmployee._id);
            setTableData(prevTableData =>
                prevTableData.filter(item => item._id !== ParamProductID)
            );
            setOperating(false);
        });
    }

    const GenerateOperationButtons = (ParamItem) => {

        const buttonStyle = 'bg-gray-900 text-gray-100 rounded-lg p-2 my-2 mx-1 text-sm hover:bg-gray-700 inline';

        if (ParamItem) {
            return (
                <div className='flex flex-row'>
                    {/* <button className={buttonStyle} onClick={() => { console.log("EDIT"); }}> <FaEdit size={20} /> </button> */}
                    <button className={buttonStyle} onClick={() => { console.log("DELETE"); DeleteECEInDB(ParamItem._id) }}> <FaTrash size={20} /> </button>
                </div>
            )
        }

        return "N/A";
    }

    const columns = [
        // {
        //     title: "ID",
        //     dataIndex: '_id',
        //     key: '_id',
        //     width: 256,
        //     className: 'border border-gray-500'
        // },
        {
            title: 'Opérations',
            dataIndex: '',
            key: 'operations',
            width: 128,
            className: 'border border-gray-500',
            render: i => GenerateOperationButtons(i)
        },
        {
            title: "Employé",
            dataIndex: 'employee',
            key: 'employee',
            width: 320,
            className: 'border border-gray-500'
        },
        {
            title: 'Date et Heure',
            dataIndex: 'time',
            key: 'time',
            width: 256,
            className: 'border border-gray-500',
            render: d => <p className='inline text-sm'>{(new Date(d)).toLocaleDateString('fr-FR', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' })}</p>
        },
        {
            title: 'Source',
            dataIndex: 'fromTAS',
            key: 'fromTAS',
            width: 128,
            className: 'border border-gray-500',
            render: s => <div className='bg-gray-900 text-gray-100 p-0.5 m-0.5 rounded flex flex-row items-center justify-center'>{s ? <FaCalculator class="mr-1" /> : <FaUser class="mr-1" />}{s ? "Pointeuse" : "Utilisateur"}</div>
        },
        {
            title: 'Evénement',
            dataIndex: '',
            key: 'type',
            width: 128,
            className: 'border border-gray-500',
            render: e => GenerateEventButton(e)
        },
        {
            title: 'Anomalie',
            dataIndex: 'anomaly',
            key: 'anomaly',
            width: 256,
            className: 'border border-gray-500',
            render: t => GenerateAnomalyMessage(t)
        }
    ];

    const [updateECEPopupTarget, setUpdateECEPopupTarget] = useState(null);
    const [newECEPopupOpen, setNewECEPopupOpen] = useState(false);
    const [loading, setLoading] = useState(true);
    const [tableData, setTableData] = useState([]);
    const [importing, setImporting] = useState(false);
    const [operating, setOperating] = useState(false); // When on update or delete
    const [employees, setEmployees] = useState(null);
    const [selectedEmployee, setSelectedEmployee] = useState(null);

    const ImportAttendance = () => {
        setImporting(true);
        PerformGetRequest("/api/import-attendance-list", (res) => {
            setImporting(false);
            GetEventListFromDB();
        });
    }

    const handleUpdateOnConfirm = (ParamNewVersion) => {

        setUpdateECEPopupTarget(null);

        // Find the index of the item to update
        const indexToUpdate = tableData.findIndex(item => item._id === ParamNewVersion.id);

        if (indexToUpdate !== -1) {
            // Create a new array with the updated item
            const updatedTableData = [...tableData];
            updatedTableData[indexToUpdate].time = ParamNewVersion.time;
            updatedTableData[indexToUpdate].type = ParamNewVersion.type;

            // Update the table data
            setTableData(updatedTableData);
            UpdateTableData(null);
        }

    }

    const GetEmployeeListFromDB = () => {
        PerformGetRequest("/api/get-employee-list", (res) => {
            // console.log(JSON.stringify(res.data));
            setEmployees(res.data);
        });
    }

    const handleEmployeeChange = (e) => {
        setSelectedEmployee(employees.find(emp => emp._id === e.target.value));
        GetEventListFromDB(e.target.value);
    }

    const handleNewECEOnConfirm = () => {
        setNewECEPopupOpen(false);
        GetEventListFromDB(selectedEmployee?._id || '');
    }

    const eventTypeToLabel = (ParamEvent) => {

        if (ParamEvent == "ENTRY") {
            return "Entrée";
        } else if (ParamEvent == "EXIT") {
            return "Sortie";
        } else {
            return "Indéfinie";
        }

    }

    const handleCopyOnClick = async () => {

        // if (!navigator) {
        //     alert('Erreur lors de la copie.');
        //     return;
        // }

        // if (!navigator.clipboard) {
        //     alert('Erreur lors de la copie : Press papier indisponible.');
        //     return;
        // }

        try {
            // Create a temporary textarea element
            const tempTextArea = document.createElement('textarea');

            const tmpArrangedData = tableData.map(row => [row.employee, eventTypeToLabel(row.type), GetDateTimeDMYHM(row.time)]);
            // Set the value of the textarea to the formatted data
            tempTextArea.value = tmpArrangedData.map(row => row.join('\t')).join('\n');

            // Position the textarea off-screen
            tempTextArea.style.position = 'absolute';
            tempTextArea.style.left = '-9999px';
            tempTextArea.style.top = '-9999px';

            // Append the textarea to the body
            document.body.appendChild(tempTextArea);

            // Select the textarea content
            tempTextArea.select();

            if (navigator && navigator.clipboard) {
                await navigator.clipboard.writeText(tempTextArea.value);
            } else {
                document.execCommand('copy');
            }

            // Remove the temporary textarea
            document.body.removeChild(tempTextArea);

            alert('Données Excel copiées avec succée.');
        } catch (err) {
            console.error('Failed to copy text: ', err);
        }

    }

    return (
        <div className='flex flex-col items-center justify-center pt-16'>

            {/* Top Bar */}
            <div className='z-20 fixed top-16 right-0 left-0 bg-gray-900 border-y border-gray-400 py-1 flex flex-row items-center justify-center'>
                <h1 className='text-gray-400 font-bold text-base'>Liste des Pointage : </h1>
                <select value={selectedEmployee?._id || ''} onChange={handleEmployeeChange} className="bg-gray-50 border border-gray-300 text-gray-900 text-xs rounded-lg focus:ring-blue-500 focus:border-blue-500 my-0 mx-2 py-1 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500" >
                    <option value="">Séléctionner un Employé</option>
                    {employees && employees.map(emp => (
                        <option key={emp._id} value={emp._id}>{`${emp.firstName} ${emp.familyName}`}</option>
                    ))}
                </select>
            </div>

            {/* Operating */}
            {operating && <div className='z-10 fixed top-0 right-0 left-0 bottom-0 backdrop-blur-xl flex flex-col items-center justify-center'>
                <MoonLoader color='#AAAAAA' />
                <div className='text-gray-100 font-bold mt-4'>Opération en cours...</div>
            </div>}

            {/* <div className='flex flex-row items-center justify-center mt-16 space-x-2'>

            </div> */}

            {/* Table */}
            <div className='text-gray-900 dark:text-gray-100 text-xs flex flex-col items-center mb-16'>

                {loading ? <GridLoader color='#AAAAAA' /> : <Table columns={columns} data={tableData} rowKey="id" className='mx-4 mb-2' />}
                {updateECEPopupTarget && <UpdateClockingEventPopup onCancel={() => { setUpdateECEPopupTarget(null); }} onConfirm={handleUpdateOnConfirm} ece={updateECEPopupTarget} />}
                {newECEPopupOpen && <NewEcePopup onCancel={() => { setNewECEPopupOpen(false); }} onConfirm={handleNewECEOnConfirm} />}
            </div>

            <RknBottomToolbar>
                <RknButton label="Nouveau Pointage" before={<FaPlus />} className="w-52" onPress={() => setNewECEPopupOpen(true)} />
                <div>
                    {!importing && <RknButton before={<FaFileImport />} label="Importer" onPress={ImportAttendance} />}
                    {importing && <PulseLoader color='#AAAAAA' />}
                </div>
                <RknButton label="Copier" before={<FaCopy />} className="w-32" onPress={() => handleCopyOnClick()} />
            </RknBottomToolbar>
        </div>
    )
}

export default EmployeeClockingBoard