import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import { AwesomeButton } from 'react-awesome-button';
import { FaPlus } from 'react-icons/fa';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';

const ProviderList = () => {

    useEffect(() => {

        GetProviderListFromDb();

    }, []);

    const [providerList, setProviderList] = useState(null);

    const columns = [
        {
            title: 'Désignation',
            dataIndex: 'designation',
            key: 'designation',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Prénom',
            dataIndex: 'firstName',
            key: 'firstName',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Nom',
            dataIndex: 'lastName',
            key: 'lastName',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Catégorie',
            dataIndex: 'category',
            key: 'category',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Balance',
            dataIndex: 'balance',
            key: 'balance',
            className: 'border border-gray-500',
            width: 256
        },
    ];

    const GetProviderListFromDb = async () => {

        PerformGetRequest("/api/get-provider-list", (res) => setProviderList(res.data));

    }

    return (
        <div className='text-gray-100 flex flex-col items-center'>
            <br />
            <h3 className='text-xl font-bold'>Liste des Fournisseurs</h3>
            <br />
            {/* <AwesomeButton before={<FaPlus />}><a href='/provider-editor'>Ajouter Un Fournisseur</a></AwesomeButton> */}
            <br />
            <br />
            {providerList && <Table columns={columns} data={providerList} rowKey="_id" />}
            <br />
            <br />
        </div>
    )
}

export default ProviderList