    const BuildPDF = async () => {

        var receiptWidth = 60;

        if (localStorage.getItem("receiptWidth")) {
            receiptWidth = Number(localStorage.getItem("receiptWidth"));
            console.log("RECEIPT WIDTH = " + receiptWidth);
        }

        const halfReceiptWidth = receiptWidth / 2;

        const doc = new jspdf.jsPDF('p', 'mm', [192, receiptWidth]); // Portrait, Milimeter, Height, Width
        var cursorY = 10;

        // Impact
        const impactBinary = Impact_GetBinaryString();
        doc.addFileToVFS('impact', impactBinary);
        doc.addFont('impact', 'impact', 'normal');

        // Init
        doc.setFont('impact', 'normal');
        doc.setTextColor(0, 0, 0);
        doc.setFontSize(36);

        // Promotion
        doc.text("PROMOTION", halfReceiptWidth, cursorY, 'center');
        cursorY += 1;

        console.log(doc.getFontList());
        doc.setFont('helvetica', 'normal');
        doc.setTextColor(0, 0, 0);
        doc.setFontSize(30);

        // Name
        var initialFontSize = 36;
        var text = productInfo.name;
        var textWidth = doc.getStringUnitWidth(text) * doc.getFontSize() / doc.internal.scaleFactor;

        var pageWidth = doc.internal.pageSize.getWidth(); // Get page width

        while (textWidth > pageWidth) {
            initialFontSize -= 1;
            doc.setFontSize(initialFontSize);
            textWidth = doc.getStringUnitWidth(text) * doc.getFontSize() / doc.internal.scaleFactor;
        }

        var textHeight = initialFontSize * (25.4 / 72); // convert to mm
        cursorY += textHeight;

        doc.text(text, halfReceiptWidth, cursorY, 'center');
        cursorY += 16;

        // Price
        doc.setFontSize(36);
        doc.text(productInfo.promotionPrice + ' DA', halfReceiptWidth, cursorY, 'center');
        cursorY += 8;

        doc.setFont(undefined, 'normal');

        return doc;
    }

