import { React, useState, useEffect, useRef } from 'react';
import Popup from 'reactjs-popup';
import { FaTimesCircle } from 'react-icons/fa';
import RknButton from './RknButton';
import FileSelectAndDrop from '../FileSelectAndDrop';

const RknImageUploadPopup = (props) => {

    const ref = useRef(null);

    const [id, setID] = useState(null);
    const [selectedFile, setSelectedFile] = useState("");
    const [imageURL, setImageURL] = useState();
    const [imageAvailable, setImageAvailable] = useState(false);

    const handleOnOpen = () => {
        if (props.defaultValue) {
            console.log("DEFAULT VALUE = " + JSON.stringify(props.defaultValue));
            setID(props.defaultValue._id);
        } else {
            setID(null);
        }
    }

    const CloseModal = () => {
        if (props.onClose)
            props.onClose();
    }

    const handleConfirmOnClick = (event) => {

        event.preventDefault();

        if (props.onConfirm)
            props.onConfirm(selectedFile);
    }

    const handleFileSelect = (event) => {
        console.log("SELECTED FILE = " + event.target.files[0].name);
        setSelectedFile(event.target.files[0]);
        setImageURL(URL.createObjectURL(event.target.files[0]));
        setImageAvailable(true);
    }

    const handleImageClear = () => {
        setSelectedFile("");
        setImageAvailable(false);
    }

    return (
        <div>
            <Popup
                open={props.isOpen}
                modal
                closeOnDocumentClick
                onClose={() => { CloseModal(); }}
                onOpen={handleOnOpen}
            >
                <div className="modal bg-gray-900 text-gray-100 p-2">
                    <button className="close" onClick={() => { CloseModal(); }}>
                        <FaTimesCircle />
                    </button>
                    <div className="header">Séléctionner une Image</div>
                    <form onSubmit={handleConfirmOnClick} className="content flex flex-col items-center">
                        <br />
                        {!imageAvailable && <FileSelectAndDrop name="picture" onChange={handleFileSelect} />}
                        {imageAvailable && <img src={imageURL} alt="preview" className="object-cover h-64 w-64 m-auto border-2 border-gray-300 rounded-2xl" />}
                        {imageAvailable && <div className='text-xl text-gray-500 font-bold border-2 border-gray-500 rounded-2xl w-64 m-auto mt-1 hover:bg-gray-500 hover:text-gray-100' onClick={handleImageClear}>X</div>}
                        <br />
                        <RknButton label="Valider" onClick={handleConfirmOnClick} />
                    </form>
                </div>

            </Popup>
        </div>
    )
}

export default RknImageUploadPopup