import { React, useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { FaTimesCircle, FaCheckCircle } from 'react-icons/fa';
import { useHotkeys } from 'react-hotkeys-hook';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';

import { useTranslation } from 'react-i18next';

const ProductSearchPopup = (props) => {
    const { t } = useTranslation();

    const probeRef = useRef(null);

    useEffect(() => {
        setTimeout(() => { probeRef.current.focus(); }, 400);
    }, []);

    const [probe, setProbe] = useState("");
    const [searchResults, setSearchResults] = useState(null);

    useHotkeys('1', () => { TriggerPropsOnConfirm(searchResults[0].item._id) });
    useHotkeys('2', () => { TriggerPropsOnConfirm(searchResults[1].item._id) });
    useHotkeys('3', () => { TriggerPropsOnConfirm(searchResults[2].item._id) });
    useHotkeys('4', () => { TriggerPropsOnConfirm(searchResults[3].item._id) });
    useHotkeys('5', () => { TriggerPropsOnConfirm(searchResults[4].item._id) });

    const TriggerPropsOnConfirm = (ParamBarcode) => {
        if (props.onConfirm)
            props.onConfirm(ParamBarcode);
    }

    const OnSubmit = (e) => {
        e.preventDefault();
        // TriggerPropsOnConfirm();
        if (probe) {
            PerformGetRequest("/api/product-search?probe=" + probe, OnSearchDone);
        }
    }

    const OnSearchDone = (ParamResult) => {
        // console.log("Search Result = " + JSON.stringify(ParamResult.data));
        setSearchResults(ParamResult.data);
        probeRef.current.blur();
    }

    const TriggerPropsOnCancel = () => {
        if (props.onCancel)
            props.onCancel();
    }

    return (
        <motion.div
            className='fixed top-0 left-0 right-0 z-10 flex flex-col items-center justify-center w-screen h-screen bg-black bg-opacity-60 backdrop-blur-lg'
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.3 }}
        >
            <motion.div
                className='flex flex-col items-center justify-center p-8 m-auto text-gray-100 bg-gray-900 border-4 border-gray-500 rounded-3xl w-96'
                initial={{ opacity: 0, y: "-50%" }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.3 }}
            >
                <h3 className='mb-4 text-xl font-bold text-gray-100'>{t("pos.toolbar.search.productSearch")}</h3>

                <form onSubmit={OnSubmit} className='flex flex-col items-center justify-center w-80'>
                    <input type="text" value={probe} ref={probeRef} onChange={(e) => { setProbe(e.target.value); }} className={'bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 mb-1 w-64 mx-auto md:w-64'} placeholder={t("pos.toolbar.search.productName")} autoComplete="off" list="autocompleteOff" />


                    {searchResults && <div className='w-full p-2 my-4 bg-gray-800 rounded-xl'>
                        {searchResults.map((r,index) => {
                            return <div onClick={() => {TriggerPropsOnConfirm(r.item._id); }} className='w-full p-1 my-1 transition duration-150 bg-gray-700 cursor-pointer rounded-xl hover:text-gray-700 hover:bg-gray-100'>
                                <div className='absolute border border-gray-500 w-6 h-6 text-xs font-bold rounded-3xl pt-0.5'>{index + 1}</div>
                                {r.item.name}
                            </div>
                        })}
                    </div>}
                    <div className='flex flex-row items-center justify-center mt-4'>
                        <button type='submit' className="px-4 py-2 font-bold text-white bg-blue-500 border-b-4 border-blue-700 rounded hover:bg-blue-400 hover:border-blue-500"><FaCheckCircle className='inline mb-1' size={20} /> {t("button.confirm")}</button>
                        <span className='mx-2'></span>
                        <button type='button' onClick={TriggerPropsOnCancel} className="px-4 py-2 font-bold text-white bg-blue-500 border-b-4 border-blue-700 rounded hover:bg-blue-400 hover:border-blue-500"><FaTimesCircle className='inline mb-1' size={20} /> {t("button.cancel")}</button>
                    </div>
                </form>
                <br />



            </motion.div>
        </motion.div>
    )
}

export default ProductSearchPopup