import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';

const SalesPerTable = (props) => {

    const columns = [
        {
            title: 'Cible',
            dataIndex: 'table',
            key: 'table',
            className: 'border border-gray-500',
            width: 320
        },
        {
            title: "Montant",
            dataIndex: 'total',
            key: 'total',
            width: 256,
            className: 'border border-gray-500'
        }
    ];

    // Effects
    useEffect(() => {

        GetSalesPerTable();

    }, [props]);

    // States
    const [tableData, setTableData] = useState(null);

    const GetSalesPerTable = async () => {

        // Build Req/Res
        let url;

        if (props.start && props.end)
            url = "/api/catering-order-stats?start=" + props.start.toISOString() + "&end=" + props.end.toISOString();
        else
            url = "/api/catering-order-stats";

        PerformGetRequest(url, (res) => {
            setTableData(res.data);
        });

    }

    return (
        <div className='p-1 m-1'>
            {/* <h3 className='mb-2 text-lg text-gray-100'>Liste des Clients</h3> */}
            <div className='flex flex-col items-center justify-center text-base'>
                <Table columns={columns} data={tableData} rowKey="id" tableLayout='auto' className='m-auto text-gray-100' />
            </div>
        </div>
    )
}

export default SalesPerTable