import React, { useState, useEffect, useRef } from 'react';
import { PerformGetRequest, PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import { motion } from 'framer-motion';
import { FaTimesCircle, FaPaperPlane } from 'react-icons/fa';
import { MessageBox } from 'react-chat-elements';

const ChatBox = (props) => {

    const [chatInput, setChatInput] = useState("");
    const [messages, setMessages] = useState([]);
    const [targetChatUser, setTargetChatUser] = useState(null);

    // const [messages, setMessages] = useState([
    //   { id: 1, text: 'Hello, how can I help you today?', type: 'user' },
    //   { id: 2, text: 'Welcome How can I assist you?', type: 'admin' },
    //   { id: 3, text: 'Hello, how can I help you today?', type: 'user' },
    //   { id: 4, text: 'Welcome How can I assist you?', type: 'admin' },
    //   { id: 5, text: 'Hello, how can I help you today?', type: 'user' },
    //   { id: 6, text: 'Hello, how can I help you today?', type: 'user' },
    //   { id: 7, text: 'Hello, how can I help you today?', type: 'user' },
    //   { id: 8, text: 'Hello, how can I help you today?', type: 'user' },
    //   { id: 9, text: 'Hello, how can I help you today?', type: 'user' },
    //   { id: 10, text: 'Hello, how can I help you today?', type: 'user' },
    //   { id: 11, text: 'Hello, how can I help you today?', type: 'user' },
    // ]);

    useEffect(() => {
        if (props.targetChatUser && props.targetChatUser.id && props.targetChatUser.name) {
            setTargetChatUser(props.targetChatUser);
            GetMessagesFromDB(props.targetChatUser);
        }
    }, [props.targetChatUser])

    const handleChatInputChange = (e) => {
        setChatInput(e.target.value);
    }

    const handleReturnKeyDown = (event) => {
        if (event.key === 'Enter') {
            send(chatInput);
        }
    };

    const send = async (ParamContent) => {

        console.log('Sending message...');

        if (chatInput.trim() === "" || !targetChatUser || !targetChatUser.id) {
            return;
        }

        let messageToPost = {};

        PerformSecurePostRequest("/api/post-message", messageToPost, (res)=>{

        });

        setChatInput("");
    };

    const GetMessagesFromDB = async (ParamUser) => {

        const url = "/api/get-messages?source=" + "SOURCE" + "&target=" + "TARGET";

        PerformGetRequest(url, (res) => {
            console.log("MESSAGES = " + JSON.stringify(res.data));

            let tmpMessageArray = [];
            for (let i = 0; i < res.data.length; i++) {
                const m = res.data[i];

                if (!m) {
                    console.log("Skipping undefined message...");
                    continue;
                }

                console.log("MESSAGE " + i + " = " + JSON.stringify(m));
                tmpMessageArray.push({ id: m.id, text: m.content, position: (m.target_user_id == ParamUser.id ? 'right' : 'left') });
                // console.log(`Message ID: ${message.id}, Content: ${message.content}`);
            }
            setMessages(tmpMessageArray);
        });
    };

    const handleCloseOnClick = () => {

    }

    return (
        <div className='fixed bottom-0 right-0 m-4 z-20' style={{ width: "336px" }}>
            <motion.div
                initial={{ opacity: 0, x: "15%" }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ duration: 0.25 }}
                className='bg-gray-100 rounded-xl border-2 border-gray-700 shadow-md p-4'
            >

                {/* Title and Close button */}
                <div className='flex justify-between items-center mb-4'>
                    <span className='text-xl font-semibold'>{(targetChatUser && targetChatUser.name) ? targetChatUser.name : "-"}</span>
                    <button className='text-gray-400 hover:text-gray-600' onClick={handleCloseOnClick}><FaTimesCircle /></button>
                </div>

                {/* Messages */}
                <div className='h-80 overflow-y-scroll overflow-x-hidden bg-gray-300 p-1 m-1 border-2 border-gray-500 rounded-l-lg' >
                    {messages.map((message) => (
                        <MessageBox
                            className='text-gray-800'
                            key={message.id}
                            position={message.position}
                            type='text'
                            text={message.text}
                            align={'left'}
                            date={new Date().toLocaleTimeString()}
                            isSender={true}
                            isReceiver={false}
                        />
                    ))}
                </div>

                {/* Input */}
                <div className='mt-2 flex flex-row items-center justify-center'>
                    <input
                        type='text'
                        placeholder='Rédigez votre message...'
                        className='w-80 p-2 border text-gray-100 border-gray-300 rounded-md'
                        // onChange={(e) => addMessage(e.target.value, 'user')}
                        value={chatInput}
                        onChange={handleChatInputChange}
                        onKeyDown={handleReturnKeyDown}
                    />
                    <FaPaperPlane
                        size={24}
                        className='cursor-pointer opacity-80 hover:opacity-100 active:scale-95 transition duration-150 ml-2'
                        onClick={() => send(chatInput)}
                    />
                </div>

            </motion.div>
        </div>
    )
}

export default ChatBox