import { React, useState, useEffect } from 'react';
import useDocumentTitle from '@tanem/use-document-title';
import { useNavigate, useSearchParams } from 'react-router-dom';
import AppData from '../App.json';
import FileSelectAndDrop from '../components/FileSelectAndDrop';
import { AwesomeButton } from 'react-awesome-button';
import { FaDollarSign, FaCalendarAlt, FaPen, FaDownload, FaFileAlt, FaEye } from 'react-icons/fa';
import { PulseLoader } from 'react-spinners';
import { PerformFileGetRequestAndDownload, PerformGetRequest, PerformImageGetRequest, PerformSecurePostRequestWithFormData } from '../Reaknotron/Libs/RknQueryTools';
import RknButton from '../components/RknUI/RknButton';
import RknNumericInput from '../components/RknUI/RknNumericInput';
import RknDateInput from '../components/RknUI/RknDateInput';
import { Link } from 'react-router-dom';
import Table from 'rc-table';
import { GetShortDateOf, TimeStampToDMY, ConvertMsToHMS, GetDateTimeDMYHM } from '../Reaknotron/Libs/RknTimeTools';
import GeneratePayslipPopup from '../components/GeneratePayslipPopup';
import { GetBaseUrl } from '../Reaknotron/Libs/RknRouterUtils';
import RknIconButton from '../components/RknUI/RknIconButton';
import RknSmartSelector from '../components/RknUI/RknSmartSelector';
import { GenerateAttendanceReport } from '../Reaknotron/PDF/AttendanceReport';
import RknDateRangeDialog from '../components/RknUI/RknDateRangeDialog';

const inputFieldStyle = 'bg-inherit border-2 border-neutral-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2.5 dark:bg-inherit dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 mt-2 w-4/5';
const inputFieldStyleDisabled = 'bg-neutral-800 border-2 border-neutral-300 text-gray-900 text-sm rounded-lg p-2.5 dark:bg-inherit dark:border-gray-600 dark:placeholder-gray-400 dark:text-white mt-2 w-4/5';
const buttonStyle = "bg-blue-500 hover:bg-blue-400 text-white font-bold py-2 px-4 border-b-4 border-blue-700 hover:border-blue-500 rounded mt-2";

const EmployeeEditor = () => {

    useDocumentTitle("Editeur d'Employé");

    // Effect
    useEffect(() => {

        if (searchParams.get("id")) {
            GetEmployeeFromDB(searchParams.get("id"));
            setTargetID(searchParams.get("id"));
            GetEmploymentContracts(searchParams.get("id"));
            GetPayslips(searchParams.get("id"));
            GetShifts(searchParams.get("id"));
        }

        // getCategoryListFromDB();

    }, []);

    // Navigation
    const navigate = useNavigate();
    const [searchParams, setSearchParams] = useSearchParams();

    // State
    const [employeeInfo, setEmployeeInfo] = useState({
        firstName: "",
        familyName: "",
        DOB: "",
        POB: "",
        NIN: "",
        address: "",
        sexe: "f",
        professionalTitleID: "",
        civilityTitle: "mr",
        entryDate: "",
        baseSalary: 0,
        PRI: 0,
        technicity: 0,
        basketBonus: 0,
        transportBonus: 0,
        requiredWorkHoursPerWeek: 0,
        requiredWorkHoursPerMonth: 0,
        tasID: 0,
        hourlyRate: 150,
        socialSecurityNumber: "",
        bankAccountNumber: ""
    });

    const [selectedFile, setSelectedFile] = useState("");
    const [imageURL, setImageURL] = useState();
    const [imageAvailable, setImageAvailable] = useState(false);

    const [employmentContracts, setEmploymentContracts] = useState(null);
    const [payslips, setPayslips] = useState(null);
    const [shifts, setShifts] = useState(null);

    const [changesAvailable, setChangesAvailable] = useState(false);
    const [targetID, setTargetID] = useState("");
    const [saving, setSaving] = useState(false);
    const [isGeneratingContract, setIsGeneratingContract] = useState(false);

    const [generatePayslipPopupOpen, setGeneratePayslipPopupOpen] = useState(false);
    const [generateAttendaceReportPopupOpen, setGenerateAttendaceReportPopupOpen] = useState(false);

    const GenerateEmploymentContractOperationButtons = (ParamItem) => {

        const buttonStyle = 'bg-gray-900 text-gray-100 rounded-lg p-2 my-2 mx-1 text-sm hover:bg-gray-700 inline active:scale-90 transition duration-150';

        if (ParamItem) {
            return (
                <div className='flex flex-row'>
                    {/* <button className={buttonStyle}> <Link to={"/employee-editor?id=" + ParamItem._id}> <FaDownload size={20} /></Link> </button> */}
                    <button
                        className={buttonStyle}
                        onClick={() => { PerformFileGetRequestAndDownload("/api/download-employment-contract?id=" + ParamItem._id, `Contrat De Travail ${ParamItem.ref}.docx`); }} >
                        <FaDownload size={20} />
                    </button>
                </div>
            )
        }

        return "N/A";
    }

    const columns_employment_contracts = [
        {
            title: 'Opérations',
            dataIndex: '',
            key: 'operations',
            width: 128,
            className: 'border border-gray-500',
            render: i => GenerateEmploymentContractOperationButtons(i)
        },
        {
            title: "Ref",
            dataIndex: 'ref',
            key: 'ref',
            width: 256,
            className: 'border border-gray-500'
        },
        {
            title: 'Date',
            dataIndex: 'creationDate',
            key: 'creationDate',
            width: 256,
            className: 'border border-gray-500',
            render: d => TimeStampToDMY(d)
        }
    ];

    const columns_shifts = [
        {
            title: "Début",
            dataIndex: 'start',
            key: 'start',
            width: 256,
            className: 'border border-gray-500',
            render: d => GetDateTimeDMYHM(d)
        },
        {
            title: 'Fin',
            dataIndex: 'end',
            key: 'end',
            width: 256,
            className: 'border border-gray-500',
            render: d => GetDateTimeDMYHM(d)
        },
        {
            title: 'Durée',
            dataIndex: 'duration',
            key: 'duration',
            width: 256,
            className: 'border border-gray-500',
            render: d => ConvertMsToHMS(d)
        }
    ];

    const columns_payslips = [
        {
            title: 'Opérations',
            dataIndex: '',
            key: 'operations',
            width: 128,
            className: 'border border-gray-500',
            render: i => <a href={GetBaseUrl() + "/payslip-editor?id=" + i._id} target="_blank" rel="noreferrer">
                <RknIconButton icon={<FaEye />} />
            </a>
        },
        {
            title: "Début",
            dataIndex: 'from',
            key: 'from',
            width: 192,
            className: 'border border-gray-500',
            render: d => TimeStampToDMY(d)
        },
        {
            title: 'Fin',
            dataIndex: 'to',
            key: 'to',
            width: 192,
            className: 'border border-gray-500',
            render: d => TimeStampToDMY(d)
        },
        {
            title: 'PRI',
            dataIndex: 'PRI',
            key: 'PRI',
            width: 192,
            className: 'border border-gray-500'
        }
    ];

    // var imageAvailable = false;
    const handleFileSelect = (event) => {
        setSelectedFile(event.target.files[0]);
        setImageURL(URL.createObjectURL(event.target.files[0]));
        setImageAvailable(true);
        setChangesAvailable(true);
    }

    const handleImageClear = () => {
        setSelectedFile("");
        setImageAvailable(false);
        setChangesAvailable(true);
    }

    const OnSubmit = async (event) => {

        event.preventDefault();

        console.log("RESULT = " + JSON.stringify(employeeInfo));
        // return;

        if (targetID == "") {
            addEmployeeToDB();
        }
        else {
            updateEmployeeInDB();
        }
    }

    const addEmployeeToDB = async () => {
        try {

            setSaving(true);

            // Build form
            const formData = new FormData();
            formData.append("firstName", employeeInfo.firstName);
            formData.append("familyName", employeeInfo.familyName);
            formData.append("DOB", employeeInfo.DOB);
            formData.append("POB", employeeInfo.POB);
            formData.append("NIN", employeeInfo.NIN);
            formData.append("address", employeeInfo.address);
            formData.append("sexe", employeeInfo.sexe);
            formData.append("professionalTitleID", employeeInfo.professionalTitleID);
            formData.append("civilityTitle", employeeInfo.civilityTitle);
            formData.append("entryDate", employeeInfo.entryDate);
            formData.append("baseSalary", employeeInfo.baseSalary);
            formData.append("PRI", employeeInfo.PRI);
            formData.append("technicity", employeeInfo.technicity);
            formData.append("basketBonus", employeeInfo.basketBonus);
            formData.append("transportBonus", employeeInfo.transportBonus);
            formData.append("requiredWorkHoursPerWeek", employeeInfo.requiredWorkHoursPerWeek);
            formData.append("requiredWorkHoursPerMonth", employeeInfo.requiredWorkHoursPerMonth);
            formData.append("picture", selectedFile);
            formData.append("tasID", employeeInfo.tasID);
            formData.append("hourlyRate", employeeInfo.hourlyRate);
            formData.append("socialSecurityNumber", employeeInfo.socialSecurityNumber);
            formData.append("bankAccountNumber", employeeInfo.bankAccountNumber);

            PerformSecurePostRequestWithFormData("/api/new-employee", formData, async (res) => {
                setChangesAvailable(false);
                setSaving(false);

                console.log("NEW ID = " + res.data.id);

                if (res.data.id) {
                    setTargetID(res.data.id);
                    setImageAvailable(true);
                    // setImageURL(GetBackEndUrl() + "/api/get-product-image?id=" + response.data.id);
                    setImageURL(await PerformImageGetRequest("/api/employee-picture?id=" + res.data.id));
                }
            });

        } catch (error) {
            console.log("ERROR : " + error);
        }
    }

    const updateEmployeeInDB = async () => {
        try {

            setSaving(true);

            // Build form
            const formData = new FormData();
            formData.append("id", targetID);
            formData.append("firstName", employeeInfo.firstName);
            formData.append("familyName", employeeInfo.familyName);
            formData.append("DOB", employeeInfo.DOB);
            formData.append("POB", employeeInfo.POB);
            formData.append("NIN", employeeInfo.NIN);
            formData.append("address", employeeInfo.address);
            formData.append("sexe", employeeInfo.sexe);
            formData.append("professionalTitleID", employeeInfo.professionalTitleID);
            formData.append("civilityTitle", employeeInfo.civilityTitle);
            formData.append("entryDate", employeeInfo.entryDate);
            formData.append("baseSalary", employeeInfo.baseSalary);
            formData.append("PRI", employeeInfo.PRI);
            formData.append("technicity", employeeInfo.technicity);
            formData.append("basketBonus", employeeInfo.basketBonus);
            formData.append("transportBonus", employeeInfo.transportBonus);
            formData.append("requiredWorkHoursPerWeek", employeeInfo.requiredWorkHoursPerWeek);
            formData.append("requiredWorkHoursPerMonth", employeeInfo.requiredWorkHoursPerMonth);
            formData.append("picture", selectedFile);
            formData.append("tasID", employeeInfo.tasID);
            formData.append("hourlyRate", employeeInfo.hourlyRate);
            formData.append("socialSecurityNumber", employeeInfo.socialSecurityNumber);
            formData.append("bankAccountNumber", employeeInfo.bankAccountNumber);

            PerformSecurePostRequestWithFormData("/api/update-employee", formData, async (res) => {
                setChangesAvailable(false);
                setSaving(false);
                setImageURL(await PerformImageGetRequest("/api/employee-picture?id=" + targetID));
            });

        } catch (error) {
            console.log("ERROR : " + error);
        }
    }

    const GetEmployeeFromDB = async (ParamID) => {

        try {

            // Build Req/Res
            var url = "/api/get-employee?id=" + ParamID;

            PerformGetRequest(url, async (res) => {
                if (res) {

                    // console.log("RESULT = " + JSON.stringify(res.data));

                    setEmployeeInfo({
                        firstName: res.data.firstName,
                        familyName: res.data.familyName,
                        DOB: res.data.DOB,
                        POB: res.data.POB,
                        NIN: res.data.NIN,
                        address: res.data.address,
                        sexe: res.data.sexe,
                        title: res.data.title,
                        civilityTitle: res.data.civilityTitle,
                        professionalTitleID: res.data.professionalTitleID,
                        entryDate: res.data.entryDate,
                        baseSalary: res.data.baseSalary,
                        PRI: res.data.PRI,
                        technicity: res.data.technicity,
                        basketBonus: res.data.basketBonus,
                        transportBonus: res.data.transportBonus,
                        requiredWorkHoursPerWeek: res.data.requiredWorkHoursPerWeek,
                        requiredWorkHoursPerMonth: res.data.requiredWorkHoursPerMonth,
                        tasID: res.data.tasID,
                        hourlyRate: res.data.hourlyRate,
                        socialSecurityNumber: res.data.socialSecurityNumber,
                        bankAccountNumber: res.data.bankAccountNumber
                    });

                    setImageAvailable(true);
                    setImageURL(await PerformImageGetRequest("/api/employee-picture?id=" + ParamID));
                }
            });

        } catch (error) {
            console.log("ERROR : " + error);

            if (error.response && error.response.status >= 400 && error.response.status <= 500) {

                console.log(error.response.data);

            }
        }
    }

    const handleChange = ({ currentTarget: input }) => {
        setEmployeeInfo({ ...employeeInfo, [input.name]: input.value });
        setChangesAvailable(true);
    }

    const handleNumericChange = (ParamName, ParamValue) => {
        // console.log(ParamName + " = " + ParamValue);
        setEmployeeInfo({ ...employeeInfo, [ParamName]: ParamValue });
        setChangesAvailable(true);
    }

    const handleDateChange = (ParamName, ParamValue) => {
        // console.log(ParamName + " = " + ParamValue);
        setEmployeeInfo({ ...employeeInfo, [ParamName]: ParamValue });
        setChangesAvailable(true);
    }

    const GenerateCDI = () => {
        setIsGeneratingContract(true);
        const url = "/api/generate-employment-contract?id=" + targetID;
        PerformGetRequest(url, (res) => {
            GetEmploymentContracts(targetID);
            setIsGeneratingContract(false);
        });
    }

    const GetEmploymentContracts = (ParamEmployeeID) => {

        if (!ParamEmployeeID)
            return;

        const url = "/api/get-employment-contracts?id=" + ParamEmployeeID;
        PerformGetRequest(url, (res) => {
            setEmploymentContracts(res.data);
        });
    }

    const GetShifts = (ParamEmployeeID) => {

        if (!ParamEmployeeID)
            return;

        const url = "/api/get-shift-list?id=" + ParamEmployeeID;
        PerformGetRequest(url, (res) => {
            setShifts(res.data);
        });
    }

    const GetPayslips = (ParamEmployeeID) => {
        PerformGetRequest("/api/get-payslip-list?id=" + ParamEmployeeID, (res) => {
            setPayslips(res.data);
        });
    }

    const handleGeneratePayslipOnConfirm = () => {
        GetPayslips(targetID);
    }

    const handleProfessionalTitleOnChange = (ParamItem) => {
        console.log("ITEM = " + JSON.stringify(ParamItem));
        setEmployeeInfo({ ...employeeInfo, ["professionalTitleID"]: ParamItem._id, ["baseSalary"]: ParamItem.baseSalary });
        setChangesAvailable(true);
    }

    const DownloadAttendanceReport = (ParamRange) => {

        console.log("RANGE = " + JSON.stringify(ParamRange));
        const start = ParamRange.start;
        const end = ParamRange.end;

        PerformGetRequest(`/api/get-employee-clocking-event-list?id=${targetID}&start=${start}&end=${end}`, async (res) => {
            // console.log("RES = " + JSON.stringify(res.data));
            // UpdateTableData(res.data);

            // Sort the data by time ascending
            res.data.sort((a, b) => {
                return new Date(a.time).getTime() - new Date(b.time).getTime();
            });

            PerformGetRequest(`/api/get-shift-list?id=${targetID}&start=${start}&end=${end}`, async (resShifts) => {
                console.log("RES = " + JSON.stringify(resShifts.data));
                const employeeLabel = employeeInfo.firstName + " " + employeeInfo.familyName;
                const doc = await GenerateAttendanceReport(employeeLabel, res.data, resShifts.data, new Date(start), new Date(end));
                doc.save(`Fiche De Pointage(${employeeLabel}).pdf`);
                setGenerateAttendaceReportPopupOpen(false);
            });


        });

    }

    return (
        <div>
            <br />
            <h1 className='text-gray-100 font-bold text-3xl'>{targetID == "" ? "Ajouter un nouveau employé" : "Editeur d'employé"}</h1>
            <br />
            <form onSubmit={OnSubmit} className='flex flex-col items-center px-4'>

                <div className='bg-gray-800 rounded-t-lg p-2 mx-4 w-full text-xl font-bold text-gray-100'>
                    <FaPen className='inline mr-2 pb-1' />
                    Identification
                </div>
                <div className='bg-gray-900 bg-opacity-50 rounded-b-xl p-2 mx-4 w-full mb-4'>

                    <label className="block text-sm font-medium text-gray-900 dark:text-white">Numéro d'Identification National</label>
                    <input type="text" name="NIN" className={inputFieldStyle} placeholder="Numéro d'Identification National..." value={employeeInfo.NIN} onChange={handleChange} />
                    <span className='block mb-4' />

                    <label className="block text-sm font-medium text-gray-900 dark:text-white">N° de Sécurité Sociale</label>
                    <input type="text" name="socialSecurityNumber" className={inputFieldStyle} placeholder="N° de Sécurité Sociale..." value={employeeInfo.socialSecurityNumber} onChange={handleChange} />
                    <span className='block mb-4' />

                    <label className="block text-sm font-medium text-gray-900 dark:text-white mt-2">Prénom</label>
                    <input type="text" name="firstName" className={inputFieldStyle} placeholder="Prénom..." value={employeeInfo.firstName} onChange={handleChange} required />
                    <span className='block mb-6' />

                    <label className="block text-sm font-medium text-gray-900 dark:text-white">Nom</label>
                    <input type="text" name="familyName" className={inputFieldStyle} placeholder="Nom..." value={employeeInfo.familyName} onChange={handleChange} />
                    <span className='block mb-4' />

                    <label className="block text-sm font-medium text-gray-900 dark:text-white">Sexe</label>
                    <select name="sexe" className={inputFieldStyle} value={employeeInfo.sexe} onChange={handleChange}>
                        <option value="f">Féminin</option>
                        <option value="m">Masculin</option>
                    </select>
                    <span className='block mb-4' />

                    <label className="block text-sm font-medium text-gray-900 dark:text-white">Titre de Civilité</label>
                    <select name="civilityTitle" className={inputFieldStyle} value={employeeInfo.civilityTitle} onChange={handleChange}>
                        <option value="mr">Monsieur (Mr.)</option>
                        <option value="mrs">Madame (Mme.)</option>
                        <option value="ms">Mademoiselle (Mlle.)</option>
                        {/* <option value="mx">Miks (Mx.)</option> https://fr.wikipedia.org/wiki/Mx_(titre)*/}
                    </select>
                    <span className='block mb-4' />

                    <label className="block text-sm font-medium text-gray-900 dark:text-white">Date de Naissance</label>
                    <RknDateInput value={employeeInfo.DOB} onChange={(v) => { handleDateChange("DOB", v); }} />
                    <span className='block mb-4' />

                    <label className="block text-sm font-medium text-gray-900 dark:text-white">Lieu de Naissance</label>
                    <input type="text" name="POB" className={inputFieldStyle} placeholder="Lieu de Naissance..." value={employeeInfo.POB} onChange={handleChange} />
                    <span className='block mb-4' />

                    <label className="block text-sm font-medium text-gray-900 dark:text-white">Adresse Personnelle</label>
                    <input type="text" name="address" className={inputFieldStyle} placeholder="Adresse Personnelle..." value={employeeInfo.address} onChange={handleChange} />
                    <span className='block mb-4' />

                    <label className="block text-sm font-medium text-gray-900 dark:text-white">Titre Professionnel</label>
                    {/* <input type="text" name="professionalTitle" className={inputFieldStyle} placeholder="Titre professionnel..." value={employeeInfo.professionalTitle} onChange={handleChange} /> */}
                    <RknSmartSelector url={"/api/pt-list"} idKey="_id" value={employeeInfo.professionalTitleID} labelKey="name" reaktorContext="PT" onChange={handleProfessionalTitleOnChange} quickAddRoute="/pt-editor" />
                    <span className='block mb-4' />

                    <label className="block text-sm font-medium text-gray-900 dark:text-white">Identifiant Pointeuse</label>
                    <input type="text" name="tasID" className={inputFieldStyle} placeholder="Identifiant Pointeuse..." value={employeeInfo.tasID} onChange={handleChange} />
                    <span className='block mb-4' />

                    <label className="block text-sm font-medium text-gray-900 dark:text-white">N° du Compte Banquaire</label>
                    <input type="text" name="bankAccountNumber" className={inputFieldStyle} placeholder="N° du Compte Banquaire..." value={employeeInfo.bankAccountNumber} onChange={handleChange} />
                    <span className='block mb-4' />

                    {/* Image */}
                    <label className="block mb-2 text-sm font-medium text-gray-900 dark:text-white">Image</label>
                    {!imageAvailable && <FileSelectAndDrop name="picture" onChange={handleFileSelect} />}
                    {imageAvailable && <img src={imageURL} alt="preview" className="object-cover h-64 w-64 m-auto border-2 border-gray-300 rounded-2xl" />}
                    {imageAvailable && <div className='text-xl text-gray-500 font-bold border-2 border-gray-500 rounded-2xl w-64 m-auto mt-1 hover:bg-gray-500 hover:text-gray-100' onClick={handleImageClear}>X</div>}
                    {/* <div className='text-xs bg-gray-900 text-gray-500 p-1 m-auto my-2 w-48 rounded-3xl'>Enlever l'arrière plan</div> */}
                    <span className='block mb-4' />
                </div>

                <div className='bg-green-900 rounded-t-lg p-2 mx-4 w-full text-xl font-bold text-gray-100'>
                    <FaDollarSign className='inline mr-2 pb-1' />
                    Salaire
                </div>
                <div className='bg-green-900 bg-opacity-50 rounded-b-xl p-2 mx-4 w-full mb-4'>

                    <label className="block text-sm font-medium text-gray-900 dark:text-white mt-2">Salaire de Base</label>
                    <RknNumericInput value={employeeInfo.baseSalary} onChange={(v) => { handleNumericChange("baseSalary", v); }} />
                    <span className='block mb-4' />

                    <label className="block text-sm font-medium text-gray-900 dark:text-white mt-2">Prime de rendement individuel</label>
                    <RknNumericInput value={employeeInfo.PRI} onChange={(v) => { handleNumericChange("PRI", v); }} />
                    <span className='block mb-4' />

                    <label className="block text-sm font-medium text-gray-900 dark:text-white mt-2">Technicité</label>
                    <RknNumericInput value={employeeInfo.technicity} onChange={(v) => { handleNumericChange("technicity", v); }} />
                    <span className='block mb-4' />

                    <label className="block text-sm font-medium text-gray-900 dark:text-white mt-2">Prime du Panier</label>
                    <RknNumericInput value={employeeInfo.basketBonus} onChange={(v) => { handleNumericChange("basketBonus", v); }} />
                    <span className='block mb-4' />

                    <label className="block text-sm font-medium text-gray-900 dark:text-white mt-2">Prime du Transport</label>
                    <RknNumericInput value={employeeInfo.transportBonus} onChange={(v) => { handleNumericChange("transportBonus", v); }} />
                    <span className='block mb-4' />

                    <label className="block text-sm font-medium text-gray-900 dark:text-white mt-2">Taux Horraire</label>
                    <RknNumericInput value={employeeInfo.hourlyRate} onChange={(v) => { handleNumericChange("hourlyRate", v); }} />
                    <span className='block mb-4' />

                </div>

                <div className='bg-amber-900 rounded-t-lg p-2 mx-4 w-full text-xl font-bold text-gray-100'>
                    <FaCalendarAlt className='inline mr-2 pb-1' />
                    Emploie du Temps
                </div>
                <div className='bg-amber-500 bg-opacity-50 rounded-b-xl p-2 mx-4 w-full mb-4 flex flex-col items-center'>

                    <label className="block text-sm font-medium text-gray-900 dark:text-white">Date de Recrutement</label>
                    <RknDateInput value={employeeInfo.entryDate} onChange={(v) => { handleDateChange("entryDate", v); }} />
                    <span className='block mb-4' />

                    <label className="block text-sm font-medium text-gray-900 dark:text-white mt-2">Heures par Semaine</label>
                    <RknNumericInput value={employeeInfo.requiredWorkHoursPerWeek} onChange={(v) => { handleNumericChange("requiredWorkHoursPerWeek", v); }} />
                    <span className='block mb-4' />

                    <label className="block text-sm font-medium text-gray-900 dark:text-white mt-2">Heures par Moi</label>
                    <RknNumericInput value={employeeInfo.requiredWorkHoursPerMonth} onChange={(v) => { handleNumericChange("requiredWorkHoursPerMonth", v); }} />
                    <span className='block mb-4' />

                </div>

                <div className='bg-blue-900 bg-opacity-50 rounded-t-lg p-2 mx-4 w-full text-xl font-bold text-gray-100'>
                    <FaCalendarAlt className='inline mr-2 pb-1' />
                    Contrats de Travail
                </div>
                <div className='bg-blue-800 bg-opacity-20 rounded-b-xl p-2 mx-4 w-full mb-4 flex flex-col items-center text-gray-100'>
                    {targetID && employmentContracts && <div>
                        <Table columns={columns_employment_contracts} data={employmentContracts} rowKey="_id" className='mx-4' />
                    </div>}
                    {isGeneratingContract ? <PulseLoader className='mt-2' size={44} color='#AAAAAA' /> : <RknButton className="mt-2" label="Générer" onPress={GenerateCDI} before={<FaFileAlt />} />}
                </div>

                <div className='bg-green-900 bg-opacity-50 rounded-t-lg p-2 mx-4 w-full text-xl font-bold text-gray-100'>
                    <FaCalendarAlt className='inline mr-2 pb-1' />
                    Bulletins de Paie
                </div>
                <div className='bg-green-500 bg-opacity-20 rounded-b-xl p-2 mx-4 w-full mb-4 flex flex-col items-center text-gray-100'>
                    {targetID && payslips && <div>
                        <Table columns={columns_payslips} data={payslips} rowKey="_id" className='mx-4' />
                    </div>}
                    {targetID && <RknButton className="mt-2" label="Générer" onPress={() => { setGeneratePayslipPopupOpen(true); }} before={<FaFileAlt />} />}
                </div>

                <div className='bg-purple-900 rounded-t-lg p-2 mx-4 w-full text-xl font-bold text-gray-100'>
                    <FaCalendarAlt className='inline mr-2 pb-1' />
                    Shift(s) de Travail
                </div>
                <div className='bg-purple-500 bg-opacity-50 rounded-b-xl p-2 mx-4 w-full mb-4 flex flex-col items-center text-gray-100'>
                    {targetID && shifts && <div>
                        <Table columns={columns_shifts} data={shifts} rowKey="start" className='mx-4' />
                    </div>
                    }
                </div>

                <div className='bg-neutral-700 rounded-t-lg p-2 mx-4 w-full text-xl font-bold text-gray-100'>
                    <FaCalendarAlt className='inline mr-2 pb-1' />
                    Rapport de Pointage Journalier
                </div>
                <div className='bg-black bg-opacity-50 rounded-b-xl p-2 mx-4 w-full mb-4 flex flex-col items-center text-gray-100'>
                    {targetID && shifts && <div>
                        <Table columns={columns_shifts} data={shifts} rowKey="start" className='mx-4' />
                    </div>
                    }
                </div>

                <br />
                <br />
                <br />
                <br />
                <br />
            </form >

            <GeneratePayslipPopup
                isOpen={generatePayslipPopupOpen}
                onClose={() => { setGeneratePayslipPopupOpen(false); }}
                employeeID={targetID}
                onConfirm={() => { setGeneratePayslipPopupOpen(false); GetPayslips(targetID); }}
            />

            <RknDateRangeDialog
                isOpen={generateAttendaceReportPopupOpen}
                onClose={() => { setGenerateAttendaceReportPopupOpen(false); }}
                onConfirm={DownloadAttendanceReport}
            />

            {/* Bottom Tool Bar */}
            <div className='fixed z-20 bottom-0 right-0 left-0 bg-gray-900 text-white h-16 border-t-2 border-gray-500 flex flex-row items-center justify-center space-x-2'>

                {/* Save */}
                <AwesomeButton type={changesAvailable ? 'primary' : 'disabled'} onPress={OnSubmit}>{saving ? <PulseLoader color='#AAAAAA' /> : "Enregistrer"}</AwesomeButton>
                <RknButton label="Fiche de Pointage" before={<FaDownload />} onPress={() => setGenerateAttendaceReportPopupOpen(true)} />

            </div>

        </div>
    )
}

export default EmployeeEditor