import { React, useState, useEffect } from 'react';
import { FaTimesCircle } from 'react-icons/fa';
import Popup from 'reactjs-popup';
import RknButton from '../components/RknUI/RknButton';
import RknNumericInput from './RknUI/RknNumericInput';
import { FaDownload } from 'react-icons/fa';
import { Impact_GetBinaryString } from "../Reaknotron/Fonts/impact-normal";
import { EncodeToCode128 } from '../Reaknotron/Libs/RknBarcode';

import "jspdf-barcode";
const jspdf = require('jspdf');

const PrintStickerPopup = (props) => {

    const [product, setProduct] = useState("");
    const [width, setWidth] = useState(40);
    const [height, setHeight] = useState(20);

    const handleOnOpen = () => {
        setProduct(props.product);
    }

    const CloseModal = () => {
        props.onClose();
    }

    const BuildPDF = async () => {

        const halfReceiptWidth = width / 2;

        const doc = new jspdf.jsPDF('landscape', 'mm', [height, width]); // Landscape, Milimeter, Height, Width
        var cursorY = 5;

        // Impact
        // const impactBinary = Impact_GetBinaryString();
        // doc.addFileToVFS('impact', impactBinary);
        // doc.addFont('impact', 'impact', 'normal');
        
        // Name
        doc.setTextColor(0, 0, 0);
        doc.setFontSize(8);
        doc.text(product.name, halfReceiptWidth, cursorY, 'center');
        cursorY += 8;

        // Barcode
        doc.setFontSize(20);
        doc.setFont("code128", "normal");
        const encoded = EncodeToCode128(product.barcode);
        const textWidth = doc.getStringUnitWidth(encoded) * doc.getFontSize() / doc.internal.scaleFactor;
        const halfTextWidth = textWidth / 2;
        // console.log("1/2 WIDTH = " + halfTextWidth);
        doc.text(encoded, halfReceiptWidth, cursorY, 'center');
        cursorY += 2;

        // Barcode Text
        doc.setFont('helvetica', 'normal');
        doc.setFontSize(6);
        doc.text(product.barcode, halfReceiptWidth, cursorY, 'center');
        cursorY += 8;

        return doc;
    }

    const DownloadPDF = async () => {
        const doc = await BuildPDF();
        doc.save("Etiquette.pdf");
    }

    return (
        <div>
            <Popup
                open={props.isOpen}
                modal
                closeOnDocumentClick
                onClose={() => { CloseModal(); }}
                onOpen={handleOnOpen}
            >
                <div className="modal bg-gray-900 text-gray-100 p-2">
                    <button className="close" onClick={() => { CloseModal(); }}>
                        <FaTimesCircle />
                    </button>
                    <div className="header"> Impression de Vignette </div>
                    <div className="content flex flex-col items-center">
                        <RknNumericInput value={width} onChange={setWidth} />
                        <RknNumericInput value={height} onChange={setHeight} />
                        <RknButton label="Télécharger" className="w-48 mx-auto" before={<FaDownload />} onPress={DownloadPDF} />
                    </div>
                </div>
            </Popup>
        </div>
    )
}

export default PrintStickerPopup