import { React, useState, useEffect, useRef } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { AwesomeButton } from 'react-awesome-button';
import { FaSearch, FaPrint, FaDownload, FaDollarSign, FaHistory, FaQuestionCircle, FaMagic, FaSave, FaCheckCircle, FaStoreSlash, FaTimesCircle, FaTruck, FaUser, FaArrowAltCircleRight, FaArrowAltCircleLeft } from 'react-icons/fa';
import { PerformGetRequest, PerformGetRequest_Promise, PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import hotkeys from 'hotkeys-js';
import SalesPointMiscProductAdder from '../components/SalesPointMiscProductAdder';
import { motion } from 'framer-motion';
import AppData from '../App.json';
import useDocumentTitle from '@tanem/use-document-title';
import ProductSearchPopup from '../components/ProductSearchPopup';
import RknButton from '../components/RknUI/RknButton';
import RknProductsTable from '../components/RknUI/RknProductsTable';
import CountUp from 'react-countup';
import { StringToNumber_2DecAtMost } from '../Reaknotron/Libs/RknStringTools';
import autoTable from 'jspdf-autotable';
import { GetShortDate, GetTimeHM2Digits } from '../Reaknotron/Libs/RknTimeTools';
import EditAmountPopup from '../components/EditAmountPopup';
const jspdf = require('jspdf');

const ReturnSlipEditor = () => {

    // Title
    useDocumentTitle("Editeur de Bon de Retour");

    // Navigation
    const navigate = useNavigate();
    const [searchParams, setSearchParams] = useSearchParams();

    // Effect
    useEffect(() => {

        PerformGetRequest("/api/get-establishment-list", async (estRes) => {
            setEstList(estRes.data);
            if (searchParams.get("id")) {
                GetRsFromDb(searchParams.get("id"));
            }
        });

    }, []);

    const GetRsFromDb = (ParamID) => {
        PerformGetRequest("/api/get-rs?id=" + ParamID, (res) => {
            setTargetEstID(res.data.establishmentID);
            setProducts(res.data.products);
            setOperation(res.data.operation);
            setFinalized(res.data.finalized);
            tableRef.current.load(res.data.products);
        });
    }

    useEffect(() => {
        if (searchParams.get("id")) {
            setTargetID(searchParams.get("id"));
            GetRsFromDb(searchParams.get("id"));
        }
        else {
            setTargetID(null);
        }
    }, []);

    // Refs
    const searchRef = useRef(null);
    const tableRef = useRef();

    const [targetID, setTargetID] = useState(null);
    const [targetEstID, setTargetEstID] = useState(null);
    const [operation, setOperation] = useState("TO");
    const [products, setProducts] = useState({});
    const [totalPrice, setTotalPrice] = useState(0);
    const [finalizedRSTableData, setFinalizedRSTableData] = useState(null);
    const [changesAvailable, setChangesAvailable] = useState(false);
    const [finalized, setFinalized] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [estList, setEstList] = useState([]);
    const [searchProductWindowOpen, setSearchProductWindowOpen] = useState(false);
    const [addMiscProductWindowOpen, setAddMiscProductWindowOpen] = useState(false);
    const [finalizePopupOpen, setFinalizePopupOpen] = useState(false);

    useEffect(() => {
        let newTotal = 0;
        Object.values(products).forEach(product => {
            newTotal += product.total;
        });
        setTotalPrice(newTotal);
    }, [products]);

    useEffect(() => {

        hotkeys('F3', event => {
            event.preventDefault();
            F3_OnPress();
        });

        hotkeys('F4', event => {
            event.preventDefault();
            F4_OnPress();
            // console.log("F4 Pressed");
        });

    }, []);

    const columns = [
        {
            title: 'Produit',
            dataIndex: 'name',
            key: 'name',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Qte',
            dataIndex: 'amount',
            key: 'amount',
            className: 'border border-gray-500',
            width: 128
        },
        {
            title: 'P.U.H.T.',
            dataIndex: 'PUHT',
            key: 'PUHT',
            className: 'border border-gray-500',
            width: 128
        },
        {
            title: 'T.V.A.',
            dataIndex: 'TVA',
            key: 'TVA',
            className: 'border border-gray-500',
            width: 128
        },
        {
            title: 'Prix',
            dataIndex: 'price',
            key: 'price',
            className: 'border border-gray-500',
            width: 128
        },
        {
            title: 'Total',
            dataIndex: 'total',
            key: 'total',
            className: 'border border-gray-500',
            width: 128
        }
    ];

    const handleEstOnChange = (e) => {
        const selectedValue = e.target.value;

        if (selectedValue === 'NULL') {
            setTargetEstID(null);
        } else {
            // const optionValue = JSON.parse(selectedValue);
            setTargetEstID(e.target.value);
        }

        setChangesAvailable(true);
    };

    const handleOnSaveToDB = async () => {

        if (targetID)
            updateRSInDB();
        else
            saveNewRSInDB();

    }

    const saveNewRSInDB = async () => {

        setIsSaving(true);
        let rsToPost = { establishmentID: targetEstID, products: products, operation: operation, totalPrice: totalPrice };

        PerformSecurePostRequest("/api/new-rs", rsToPost, (res) => {
            setTargetID(res.data.id);
            navigate('/return-slip-editor?id=' + res.data.id);
            setChangesAvailable(false);
            setIsSaving(false);
        });
    }

    const updateRSInDB = async () => {

        setIsSaving(true);
        let receptionToPost = { id: targetID, establishmentID: targetEstID, products: products, totalPrice: totalPrice };

        PerformSecurePostRequest("/api/update-rs", receptionToPost, (res) => {
            setChangesAvailable(false);
            setIsSaving(false);
        });

    }

    const handleFinalizeOnConfirm = (ParamInitialPaymentAmount) => {
        setIsSaving(true);
        let rsToPost = { id: targetID, initialPayment: ParamInitialPaymentAmount };

        PerformSecurePostRequest("/api/finalize-rs", rsToPost, (res) => {
            if (res.data.code == "OK") {
                setFinalized(true);
                setChangesAvailable(false);
            }
            setIsSaving(false);
        });
    }

    const OnProductFound = (ParamResult) => {

        if (finalized)
            return;

        // console.log("R = " + JSON.stringify(ParamResult.data));
        tableRef.current.addNewRow(ParamResult.data);
    }

    // TODO : Move to Table
    const onProductDelete = (ParamID) => {
        // // console.log("ON DELETE : " + ParamID);

        // // Create a new object of products
        // const newProducts = { ...products };

        // // Remove the deleted product from the new object
        // delete newProducts[ParamID];

        // // Remove null keys from the new object
        // const cleanedNewProducts = Object.fromEntries(
        //     Object.entries(newProducts).filter(([_, value]) => value !== null)
        // );

        // // console.log("TMP 2 = " + JSON.stringify(cleanedNewProducts));

        // setProducts(cleanedNewProducts);
    };

    // TODO : Move to table
    const handleItemOnChange = (ParamID, ParamAmount, ParamPUHT, ParamTVA, ParamPUTTC, ParamTotal, ParamBatchID, ParamExpDate) => {

        // // console.log(ParamID);
        // let item = products[ParamID];
        // // console.log("ITEM BEFORE CHANGE = " + JSON.stringify(item));

        // if (item) {
        //     let tmpArray = products;
        //     tmpArray[ParamID] = {
        //         id: item.id,
        //         name: item.name,
        //         amount: ParamAmount,
        //         PUHT: ParamPUHT,
        //         TVA: ParamTVA,
        //         price: ParamPUTTC,
        //         total: ParamTotal,
        //         batchID: ParamBatchID,
        //         expirationDate: ParamExpDate,
        //         lastReceptionPrice: item.lastReceptionPrice
        //     };

        //     if (item.custom) {
        //         // console.log("Custom");
        //         tmpArray[ParamID].custom = true;
        //     }

        //     setProducts(tmpArray);

        //     let tmpTotal = 0;
        //     Object.keys(tmpArray).forEach((pk) => {
        //         tmpTotal += tmpArray[pk].total;
        //     });
        //     setTotal(tmpTotal);

        //     setChangesAvailable(true);
        // }
    }

    const F3_OnPress = () => {
        setSearchProductWindowOpen(true);
    }

    const F4_OnPress = () => {
        AddMiscProductOnClick();
    }

    const AddMiscProductOnClick = () => {
        setAddMiscProductWindowOpen(true);
    }

    const AddMiscProductConfirmOnClick = (ParamProduct) => {

        // setAddMiscProductWindowOpen(false);

        // if (products[ParamProduct]) {
        //     setLastProductFound(true);
        //     setQuery("");
        //     searchRef.current.focus();
        //     return;
        // } else {
        //     var tmp = products;
        //     tmp[ParamProduct] = {
        //         id: ParamProduct,
        //         name: ParamProduct,
        //         amount: 1,
        //         price: 1,
        //         total: 1,
        //         batchID: "",
        //         expirationDate: "",
        //         custom: true
        //     };
        //     // console.log("TMP = " + JSON.stringify(tmp[ParamProduct]));
        //     setProducts(tmp);
        //     setCount(count + 1);
        //     setChangesAvailable(true);
        // }

    }

    const PopupWindowsCancelOnClick = () => {
        setAddMiscProductWindowOpen(false);
    }

    const SearchProductOnConfirm = (ParamID) => {
        PerformGetRequest("/api/get-product?id=" + ParamID, OnProductFound);
        setSearchProductWindowOpen(false);
    }

    const handleOnChange = (ParamProducts) => {
        // console.log("PRODUCTS = " + JSON.stringify(ParamProducts));
        setProducts(ParamProducts);
        setChangesAvailable(true);
    }

    const DownloadPDF = async () => {

        let d = "Divers";

        if (targetEstID) {
            let result = await PerformGetRequest_Promise("/api/get-establishment?id=" + targetEstID);
            d = result.response.data.designation;
            // console.log("EST DATE = " + JSON.stringify(data));
        }

        const doc = await BuildPDF(d);
        doc.save("Bon-De-Retour.pdf");
    }

    const buildProductsTableDataForPDF = () => {

        var head = ['Qte', 'Designation', 'Lot N°', 'P.U', 'T.V.A.', 'Montant T.T.C.'];

        let body = [];

        Object.keys(products).forEach((pk) => {
            let p = products[pk];
            let tableLine = [];
            tableLine.push(p.amount);
            tableLine.push(p.name);
            tableLine.push(p.batchID);
            tableLine.push(StringToNumber_2DecAtMost(p.price));
            tableLine.push(StringToNumber_2DecAtMost(p.tva));
            tableLine.push(StringToNumber_2DecAtMost(p.price * p.amount));
            body.push(tableLine);
        });

        let result = { head: head, body: body };
        return result;
    }

    const BuildPDF = async (ParamEstDesignation) => {

        var receiptWidth = 210;

        // if (localStorage.getItem("receiptWidth")) {
        //     receiptWidth = Number(localStorage.getItem("receiptWidth"));
        //     console.log("RECEIPT WIDTH = " + receiptWidth);
        // }

        const halfReceiptWidth = receiptWidth / 2;

        const doc = new jspdf.jsPDF('p', 'mm', [270, receiptWidth]); // Portrait, Milimeter, Height, Width
        var cursorY = 10;

        // Label
        doc.setFont(undefined, 'bold');
        doc.setTextColor(0, 0, 0);
        doc.setFontSize(11);
        doc.text("Bon de Retour", halfReceiptWidth, cursorY, 'center');
        cursorY += 4;
        doc.setFont(undefined, 'normal');

        // ...
        let operationLabel = "Depuis/Vers";
        if (operation === "FROM") {
            operationLabel = "Retour depuis";
        } else if (operation === "TO") {
            operationLabel = "Retour vers";
        }

        // Est
        doc.setFont(undefined, 'bold');
        doc.setTextColor(0, 0, 0);
        doc.setFontSize(9);
        doc.text(operationLabel + " : " + ParamEstDesignation, halfReceiptWidth, cursorY, 'center');
        cursorY += 4;
        doc.setFont(undefined, 'normal');

        // Date
        doc.setFontSize(8);
        doc.text(GetShortDate() + " à " + GetTimeHM2Digits(), halfReceiptWidth, cursorY, 'center'); // TODO : Date
        cursorY += 4;

        // Sold Products Table
        const tableData = buildProductsTableDataForPDF();

        let cellTextFontSize = 9;
        autoTable(doc, {
            head: [tableData.head],
            body: tableData.body,
            startY: cursorY,
            margin: 6,
            theme: 'grid',
            tableWidth: receiptWidth - 12,
            styles: {
                fontSize: cellTextFontSize,
                cellPadding: 1,
                fontStyle: 'bold',
                textColor: 'black'
            },
            headStyles: { fillColor: [0, 0, 0], textColor: [255, 255, 255] },
            didDrawPage: (d) => { cursorY = d.cursor.y },
        });
        cursorY += 9;

        // Total
        doc.setFontSize(12);
        doc.text("Total : " + StringToNumber_2DecAtMost(totalPrice) + " DA", halfReceiptWidth, cursorY, 'center');
        cursorY += 8;

        return doc;
    }

    return (
        <div className='flex flex-col items-center'>

            {/* Fixed Tool Bar */}
            <div className='fixed z-10 top-16 h-80 sm:h-32 left-0 right-0 bg-gray-800 bg-opacity-20 m-2 border-2 border-gray-500 rounded-lg backdrop-blur-lg flex flex-col sm:flex-row items-center justify-center'>

                {/* Operation Selection Field */}
                <motion.div
                    initial={{ opacity: 0, y: "-25%" }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.3, delay: 0.2 }}
                    className='mx-2'
                >
                    <p className='text-gray-100 text-sm font-bold bg-gray-700 p-1 border-gray-500 border-2 rounded-t-xl w-64 mx-auto md:w-96'>Operation</p>
                    <select
                        name="targetEstID"
                        className='bg-gray-800 border-8 border-gray-500 focus:border-cyan-500 text-gray-100 text-lg rounded-b-lg p-2.5 mb-1 w-64 mx-auto md:w-96'
                        value={operation}
                        onChange={(e) => { setOperation(e.target.value) }}
                    >
                        <option value="TO" className='flex flex-row items-center justify-center' defaultValue>🚛 ⏩ Retour vers...</option>
                        <option value="FROM" className='flex flex-row items-center justify-center'>🤵 ⏪ Retour Depuis...</option>
                    </select>
                </motion.div>

                {/* Target EstablishmentID Selection Field */}
                <motion.div
                    initial={{ opacity: 0, y: "-25%" }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.3, delay: 0.2 }}
                    className='mx-2'
                >
                    <p className='text-gray-100 text-sm font-bold bg-gray-700 p-1 border-gray-500 border-2 rounded-t-xl w-64 mx-auto md:w-96'>Fournisseur</p>
                    <select
                        name="targetEstID"
                        className='bg-gray-800 border-8 border-gray-500 focus:border-cyan-500 text-gray-100 text-lg rounded-b-lg p-2.5 mb-1 w-64 mx-auto md:w-96'
                        value={targetEstID}
                        onChange={(handleEstOnChange)}
                    >
                        <option value="NULL" defaultValue>Aucun</option>
                        {estList.map((e, index) => (
                            <option key={index} value={e._id}>
                                {e.designation}
                            </option>
                        ))}
                    </select>
                </motion.div>

                <div className='flex flex-col items-center justify-center p-2.5 text-gray-100 font-bold bg-gray-700 border-4 border-gray-500 rounded-xl mb-2 ml-1.5'>
                    <div className='mb-1'>Total</div>
                    <CountUp end={totalPrice} duration={1} separator=" " decimals={2} suffix=" DA" className='text-3xl' />
                </div>

            </div>

            {/* Grid */}
            <motion.div
                className={'fixed border-2 border-gray-500 text-gray-100 overflow-auto scrollbar p-1 pt-2 sm:pt-1 bg-gray-900 bg-opacity-20 rounded-lg top-96 sm:top-52 bottom-20 left-2 right-2 transition duration-700 flex flex-col items-start'}
                initial={{ opacity: 0, y: "-25%" }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.3, delay: 0.4 }}
            >
                <RknProductsTable ref={tableRef} onChange={handleOnChange} operation={operation} />
            </motion.div>

            {/* Bottom Tool Bar */}
            <div className='fixed z-20 bottom-0 right-0 left-0 bg-gray-900 text-white h-16 border-t-2 border-gray-500 flex flex-row items-center justify-center space-x-2'>

                {true && <RknButton label="Enregistrer" before={<FaSave size={20} />} onPress={handleOnSaveToDB} busy={isSaving} disabled={!changesAvailable} />}
                {true && <RknButton label="Finalizer" before={<FaCheckCircle size={20} />} onPress={() => setFinalizePopupOpen(true)} busy={false} disabled={!targetID || changesAvailable || finalized} />}
                {true && <RknButton label="Dévérouiller" before={<FaTimesCircle size={20} />} onPress={null} busy={false} disabled={true} />}
                {true && <RknButton label="Télécharger" before={<FaDownload size={20} />} onPress={DownloadPDF} busy={false} disabled={false} />}

                {!finalized && <AwesomeButton type={'primary'} onPress={() => { setSearchProductWindowOpen(true); }} before={<FaSearch size={24} />}><p className='hidden sm:block text-xs'>Recherche (F3)</p></AwesomeButton>}
                {!finalized && <AwesomeButton type={'primary'} onPress={AddMiscProductOnClick} before={<FaQuestionCircle size={24} />}><p className='hidden sm:block text-xs'>Divers (F4)</p></AwesomeButton>}

            </div>

            {/* Windows */}
            {addMiscProductWindowOpen && <SalesPointMiscProductAdder onConfirm={AddMiscProductConfirmOnClick} onCancel={PopupWindowsCancelOnClick} />}
            {searchProductWindowOpen && <ProductSearchPopup onConfirm={SearchProductOnConfirm} onCancel={PopupWindowsCancelOnClick} />}

            {/* Initial Payment and Stockage */}
            {
                finalizePopupOpen &&
                <EditAmountPopup
                    isOpen={true}
                    onClose={() => setFinalizePopupOpen(false)}
                    onConfirm={handleFinalizeOnConfirm}
                    label="Paiement Initial"
                    max={totalPrice}
                />
            }

        </div>
    )
}

export default ReturnSlipEditor