import React, { useState, useEffect } from 'react';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import { GridLoader } from 'react-spinners';

const MailManager = () => {

    useEffect(() => {

        GetEMails();

    }, []);

    const [eMails, setEMails] = useState(null);

    const GetEMails = async () => {

        PerformGetRequest("/api/get-email-list", (res) => {
            setEMails(res.data);
        });

    }

    return (
        <div>
            <div className='fixed w-48 left-2 top-28 bottom-2 p-2 bg-gray-500 m-1 rounded border-4 border-gray-300 flex flex-col items-center justify-start'>
                <div className='p-1 w-full my-0.5 text-sm text-gray-100 bg-gray-900 px-2 rounded cursor-pointer active:scale-95 hover:bg-gray-700 transition duration-150'>✉ Boite de Réception</div>
                <div className='p-1 w-full my-0.5 text-sm text-gray-100 bg-gray-900 px-2 rounded cursor-pointer active:scale-95 hover:bg-gray-700 transition duration-150'>🚀 eMail Envoyé</div>
                <div className='p-1 w-full my-0.5 text-sm text-gray-100 bg-gray-900 px-2 rounded cursor-pointer active:scale-95 hover:bg-gray-700 transition duration-150'>📜 Brouillon</div>
                <div className='p-1 w-full my-0.5 text-sm text-gray-100 bg-gray-900 px-2 rounded cursor-pointer active:scale-95 hover:bg-gray-700 transition duration-150'>🤢 Spam</div>
                <div className='p-1 w-full my-0.5 text-sm text-gray-100 bg-gray-900 px-2 rounded cursor-pointer active:scale-95 hover:bg-gray-700 transition duration-150'>♻ Archives</div>
            </div>
            <div className='text-gray-100 flex flex-col items-center fixed left-52 right-2 top-28 bottom-2 bg-red-500'>
                <br />
                <h3 className='text-xl font-bold'>Gestion de la messagerie</h3>
                <br />
                {!eMails && <GridLoader color='#AAAAAA' />}
                <div>{eMails && eMails.map((e, i) => {
                    return (
                        <div className='bg-gray-900 m-1 p-1 rounded-lg flex flex-col items-center justify-center' key={i}>
                            <div className='text-gray-500 w-full h-8 bg-gray-800 m-1 p-1 rounded-lg flex flex-row'>
                                <div className='w-1/4 font-bold bg-gray-700 rounded-l-lg'>From</div>
                                <div className='w-3/4 bg-gray-900 rounded-r-lg'>{e.from}</div>
                            </div>
                            <div className='text-gray-500 w-full h-8 bg-gray-800 m-1 p-1 rounded-lg flex flex-row'>
                                <div className='w-1/4 font-bold bg-gray-700 rounded-l-lg'>Subject</div>
                                <div className='w-3/4 bg-gray-900 rounded-r-lg'>{e.subject}</div>
                            </div>
                            <div className='w-full h-64 bg-gray-800 m-1 p-1 rounded-lg'>{e.body}</div>
                        </div>
                    )
                })}</div>
            </div>
        </div>
    )
}

export default MailManager