import { React, useState, useEffect, useLayoutEffect, useRef } from 'react';
import { PerformGetRequest, PerformGetRequest_Promise, PerformImageGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import { FaQuestionCircle, FaStar, FaTag } from 'react-icons/fa';
import { motion } from 'framer-motion';
import ProductImage from '../components/ProductImage';
import '../ScrollBar.css';
import { GetIfShowProductsOutOfStock } from '../const';
import AppData from '../App.json';

const CategorizedProductSelector = (props) => {

    const DEFAULT_HEIGHT = 320;

    const ref = useRef(null);
    const [dimensions, setDimensions] = useState({ width: 0, height: 0 });
    const [imageCache, setImageCache] = useState({});

    // use useUseLayoutEffect over useEffect so that we update the dimensions after the dom has finished updating
    useLayoutEffect(() => {

        function updateSize() {
            if (ref.current) {
                const { clientWidth, clientHeight } = ref.current;
                // console.log("H = " + clientHeight);

                let finalHeight = clientHeight;
                if (clientHeight < DEFAULT_HEIGHT) {
                    finalHeight = DEFAULT_HEIGHT;
                }

                setDimensions({
                    width: clientWidth,
                    height: finalHeight,
                });
            }
        }

        window.addEventListener('resize', updateSize);
        window.addEventListener('fullscreenchange', updateSize);
        updateSize();

        return () => {
            window.removeEventListener('resize', updateSize);
            window.removeEventListener('fullscreenchange', updateSize);
        }

    }, []);

    // Get categories and favorites
    useEffect(() => {

        PerformGetRequest("/api/get-category-list", (res) => {
            setCategories(res.data);
            handleCategorySelection("rkn-137-favorites");
        });

    }, []);

    // Build image cache
    useEffect(() => {

        let tmpImageCache = {};
        PerformGetRequest("/api/get-category-list", async (res) => {
            // console.log("CATS = " + JSON.stringify(res.data));

            for (const c of res.data) {
                const c_res = await PerformGetRequest_Promise("/api/product-by-category?id=" + c._id);
                // console.log("BY CAT : " + JSON.stringify(c_res.response.data));

                for (const p of c_res.response.data) {
                    const imgRes = await PerformImageGetRequest("/api/get-product-image?id=" + p._id);
                    tmpImageCache[p._id] = imgRes;
                    // console.log("ID = " + JSON.stringify(p._id));
                }

            }

            setImageCache(tmpImageCache);

        });

    }, []);

    // Mouse Position
    useEffect(() => {

        const handleMouseMove = (event) => {
            setMousePos({ x: event.clientX, y: event.clientY });
        };

        window.addEventListener('mousemove', handleMouseMove);

        return () => {
            window.removeEventListener(
                'mousemove',
                handleMouseMove
            );
        };
    }, []);

    const [categories, setCategories] = useState(null);
    const [products, setProducts] = useState(null);
    const [selectedId, setSelectedId] = useState(null);

    const [mousePos, setMousePos] = useState({});
    const [productCounter, setProductCounter] = useState(1);
    const [priceBubbles, setPriceBubbles] = useState([]);

    const handleCategorySelection = (ParamID) => {
        setSelectedId(ParamID);
        PerformGetRequest("/api/product-by-category?id=" + ParamID, (res) => {
            setProducts(res.data);
            // console.log("BY CAT : " + JSON.stringify(res.data));
        });
    }

    const handleProductClick = (ParamProduct) => {
        // console.log("P-CLICK : " + JSON.stringify(ParamProduct));

        if (ParamProduct.sellable) {
            let bubble = { key: productCounter, x: mousePos.x, y: mousePos.y, price: ParamProduct.price, pack: false };
            setPriceBubbles(priceBubbles => [...priceBubbles, bubble]);
            setTimeout(() => { handleBubbleExpire(productCounter) }, 1000);
            setProductCounter(productCounter + 1);

            if (props.onProductClick)
                props.onProductClick(ParamProduct, false);

        } else {
            let bubble = { key: productCounter, x: mousePos.x, y: mousePos.y, price: "2 Produits", pack: true };
            setPriceBubbles(priceBubbles => [...priceBubbles, bubble]);
            setTimeout(() => { handleBubbleExpire(productCounter) }, 1000);
            setProductCounter(productCounter + 1);

            if (props.onProductClick)
                props.onProductClick(ParamProduct, true);
        }


    }

    const handleBubbleExpire = (ParamProductKey) => {
        let bubble = priceBubbles.filter(b => b.key == ParamProductKey);
        setPriceBubbles(priceBubbles => priceBubbles.filter(b => b.key !== ParamProductKey));
    }

    return (
        <div className='bg-transparent w-full h-full' ref={ref}>

            {/* Price Bubbles */}
            <div>
                {priceBubbles.map(b =>
                    <div key={b.key} style={{
                        backgroundColor: "white",
                        position: "fixed",
                        top: b.y - 16,
                        left: b.x,
                        padding: "4px",
                        border: "solid white 1px",
                        borderRadius: "16px",
                        zIndex: "20",
                        color: "black",
                        fontWeight: "600",
                        opacity: "0.7",
                        WebkitUserSelect: "none",
                        msUserSelect: "none",
                        userSelect: "none",
                        pointerEvents: "none"
                    }} className='vfx-fadeout-2s'>
                        + {b.price} {b.pack ? "" : "DA"}
                    </div>
                )}
            </div>

            {/* Trans-Parent */}
            <div className='bg-transparent w-full h-full flex flex-col items-center justify-center'>

                <div className='h-16 w-full rounded-xl flex flex-row items-center justify-start'>

                    {/* Favorites */}
                    <motion.div className={`h-16 w-10 sm:w-16 ${"rkn-137-favorites" === selectedId ? 'border-gray-100' : 'border-gray-800'} bg-gray-900 text-gray-100 rounded-t-xl p-1 border-t-4 border-x-4 flex flex-col items-center justify-center text-lg sm:text-3xl cursor-pointer hover:bg-gray-500 transition duration-300`}
                        onClick={() => { handleCategorySelection("rkn-137-favorites") }}
                        initial={{ opacity: 0, x: -16 * 0 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ duration: 0.1, delay: 0 }}
                    >
                        {<FaStar />}
                        {"rkn-137-favorites" === selectedId && <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.15 }} className='absolute h-2 w-8 sm:w-14 translate-y-8 bg-gray-900' />}
                    </motion.div>

                    {/* Cats */}
                    {categories && categories.map((c, i) => {
                        return (
                            <motion.div className={`h-16 w-10 sm:w-16 ${c._id === selectedId ? 'border-gray-100' : 'border-gray-800'} bg-gray-900 text-gray-100 rounded-t-xl p-1 border-t-4 border-x-4 flex flex-col items-center justify-center text-lg sm:text-3xl cursor-pointer hover:bg-gray-500 transition duration-300`}
                                onClick={() => { handleCategorySelection(c._id) }}
                                initial={{ opacity: 0, x: -16 * (i + 1) }}
                                animate={{ opacity: 1, x: 0 }}
                                transition={{ duration: 0.1, delay: 0.05 * i }}
                                key={c._id}
                            >
                                {c.icon ? c.icon : <FaTag />}
                                {c._id === selectedId && <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.15 }} className='absolute h-2 w-8 sm:w-14 translate-y-8 bg-gray-900' />}
                            </motion.div>)
                    })}

                    {/* Misc */}
                    <motion.div className={`h-16 w-10 sm:w-16 ${"NULL" === selectedId ? 'border-gray-100' : 'border-gray-800'} bg-gray-900 text-gray-100 rounded-t-xl p-1 border-t-4 border-x-4 flex flex-col items-center justify-center text-lg sm:text-3xl cursor-pointer hover:bg-gray-500 transition duration-300`}
                        onClick={() => { handleCategorySelection("NULL") }}
                        initial={{ opacity: 0, x: -16 * (categories ? categories.length + 1 : 0) }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ duration: 0.1, delay: 0.5 }}
                    >
                        {<FaQuestionCircle />}
                        {"NULL" === selectedId && <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.15 }} className='absolute h-2 w-8 sm:w-14 translate-y-8 bg-gray-900' />}
                    </motion.div>

                </div>

                {/* Product Grid */}
                <div className='bg-gray-900 p-1 w-full rounded-b-xl border-4 rounded-tr-xl border-gray-100'>
                    <div style={{ height: dimensions.height - 72 }} className='flex flex-row content-start justify-start flex-wrap overflow-auto scrollbar'>
                        {products && products.map((p, i) => {
                            if (p.buyable && p.availableAmount > 0 || !p.buyable || !props.hideNotAvailable || GetIfShowProductsOutOfStock())
                                return (
                                    <motion.div
                                        key={p._id}
                                        initial={{ opacity: 0 }}
                                        animate={{ opacity: 1 }}
                                        transition={{ duration: 0.15 }}
                                    >
                                        {/* If sellable it's not a pack */}
                                        <ProductImage pack={p.sellable ? false : true} id={p._id} size={AppData.PROD_IMG_SIZE || 64} onClick={() => { handleProductClick(p); }} showLabel={props.showLabels ? p.name : false} image={imageCache[p._id]} />
                                    </motion.div>
                                )
                        })}
                    </div>
                </div>



            </div>
        </div>
    )
}

export default CategorizedProductSelector