function StringToNumber_2DecAtMost(ParamString, ParamRounding = false) {

    if (ParamRounding) {
        let num = parseFloat(ParamString);
        if (isNaN(num)) {
            return '(Invalid)';
        }
        return Math.round((num + Number.EPSILON) * 100) / 100;
    } else {
        let num = parseFloat(ParamString);
        if (isNaN(num)) {
            return 'Invalid input';
        }
        return Math.floor(num * 100) / 100;
    }

}

function StringToNumber_2DecAlways(ParamString, ParamRounding, ParamGrouping) {
    let num = parseFloat(ParamString);
    if (isNaN(num)) {
        return 'Invalid input';
    }

    if (ParamRounding) {
        num = Math.round((num + Number.EPSILON) * 100) / 100;
    } else {
        num = Math.floor(num * 100) / 100;
    }

    // Use toFixed to ensure there are always two digits after the decimal point
    if (ParamGrouping)
        return DecimalNumberToGroupsOfThree(num.toFixed(2));
    else
        return num.toFixed(2);
}

function DecimalNumberToGroupsOfThree(ParamNum) {

    // console.log("PARAM NUM = " + ParamNum);

    let wholePart = "";
    let decimalPart = "";
    if (!ParamNum.includes('.')) {
        wholePart = ParamNum.toString();
    } else {
        const split = ParamNum.split('.');
        wholePart = split[0];
        decimalPart = split[1];
    }
    // console.log("WHOLE PART = " + wholePart);

    let c = 0;
    let stageOneResult = "";
    for (let i = wholePart.length - 1; i >= 0; i--) {
        stageOneResult += wholePart[i];
        c++;

        if (c == 3) {
            stageOneResult += " ";
            c = 0;
        }
    }
    // console.log("STAGE ONE = " + stageOneResult);

    let result = stageOneResult.split("").reverse().join("");
    // console.log("REVERSE = " + result);

    if (result.endsWith(" ")) {
        // console.log("YES");
        result = result.slice(0, -1);
    } else {
        // console.log("NO");
    }

    if (decimalPart) {
        // console.log("WITH DECIMAL = " + result);
        result = result + "." + decimalPart;
    }

    return result;
}

