function ConvertCharsToDigits(inputString) {
    // Mapping of characters to digits
    const charMap = {
        "&": '1',
        "é": '2',
        "\"": '3',
        "'": '4',
        "(": '5',
        "-": '6',
        "è": '7',
        "_": '8',
        "ç": '9',
        "à": '0'
    };

    let outputString = '';

    // Iterate over each character in the input string
    for (let i = 0; i < inputString.length; i++) {
        const char = inputString[i];
        // Check if the character exists in our map
        if (charMap.hasOwnProperty(char)) {
            // Replace the character with its mapped digit
            outputString += charMap[char];
        } else {
            // If the character is not in our map, append it as-is
            outputString += char;
        }
    }

    return outputString;
}

