import React, { useState } from 'react';
import RknDateInput from '../components/RknUI/RknDateInput';
import { IsIsoDate } from '../Reaknotron/Libs/RknTimeTools';

const RknUiDemo = () => {

    const [date, setDate] = useState(null);

    return (
        <div className='flex flex-col items-center justify-center text-gray-100'>
            <div className='flex flex-col items-center justify-center p-4 bg-gray-900 m-2 rounded-xl border-2 border-gray-500'>
                <label className="text-xl font-bold text-gray-900 dark:text-gray-100">RknDateInput</label>
                <RknDateInput onChange={setDate} />
                <div>Raw Value : {date}</div>
                <div>Stringified Raw Value : {JSON.stringify(date)}</div>
                <div>Data Type : {typeof date}</div>
                <div>Is ISO Date : {IsIsoDate(date) ? "Yes" : "No"}</div>
            </div>
        </div>
    )
}

export default RknUiDemo