import React, { useState, useEffect, useRef } from 'react';
import { Navigate, useSearchParams } from 'react-router-dom';
import useDocumentTitle from '@tanem/use-document-title';
import { FaPrint, FaDownload, FaSave, FaUser, FaTimesCircle, FaQuestionCircle, FaSearch, FaSearchDollar, FaUserPlus, FaStar, FaCog, FaRocket, FaPause, FaCheckCircle, FaStop } from 'react-icons/fa';
import { AnimatePresence, motion } from "framer-motion";
import AppData from '../App.json';
import { PerformGetRequest, PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import '../VFX.css';
import RknDebouncedInput from '../components/RknUI/RknDebouncedInput';
import ConsumedProductTag from '../components/ConsumedProductTag';
import RknButton from '../components/RknUI/RknButton';
import { StringToNumber_2DecAtMost } from '../Reaknotron/Libs/RknStringTools';
import FinalizeProductionPopup from '../components/FinalizeProductionPopup';

const ProductionCycleEditor = () => {

    // ...
    useDocumentTitle("Cycle de Production");

    const ingredientRef = useRef(null);
    const [ingredients, setIngredients] = useState({});
    const [ingredientsTotal, setIngredientsTotal] = useState(0);

    const expectedRef = useRef(null);
    const [expectedProducts, setExpectedProducts] = useState({});
    const [expectedProductsTotal, setExpectedProductsTotal] = useState(0);

    const finalRef = useRef(null);
    const [finalProducts, setFinalProducts] = useState({});
    const [finalProductsTotal, setFinalProductsTotal] = useState(0);

    const [pcID, setPcID] = useState(null);
    const [count, setCount] = useState(0);
    const [changesAvailable, setChangesAvailable] = useState(null);
    const [isSaving, setIsSaving] = useState(false);
    const [status, setStatus] = useState("AWAITING_LAUNCH"); // AWAITING_LAUNCH / RUNNING / ON_PAUSE / ON_HALT / FINALIZED

    const [videoSource, setVideoSource] = useState(null);

    const [FPPopupOpen, setFPPopupOpen] = useState(false);
    const [finalBatch, setFinalBatch] = useState({});

    useEffect(() => {

        // setVideoSource(require(`../assets/${AppData.SALES_POINT_BG_VIDEO}`));
        setVideoSource(require(`../assets/Cyber Tech Background.mp4`));

    }, []);

    useEffect(() => {

        updateIngredientsTotal(ingredients);

    }, [ingredients]);

    useEffect(() => {

        updateExpectedProductsTotal(expectedProducts);

    }, [expectedProducts]);

    useEffect(() => {

        updateFinalProductsTotal(finalProducts);

    }, [finalProducts]);

    const handleIngredientSignal = (ParamQuery) => {
        // console.log("Query = " + ParamQuery);
        PerformGetRequest("/api/get-product?barcode=" + ParamQuery, OnIngredientFound);
    }

    const handleExpectedProductSignal = (ParamQuery) => {
        // console.log("Expected Product = " + ParamQuery);
        PerformGetRequest("/api/get-product?barcode=" + ParamQuery, OnExpectedProductFound);
    }

    const handleFinalProductSignal = (ParamQuery) => {
        // console.log("Final Product = " + ParamQuery);
        PerformGetRequest("/api/get-product?barcode=" + ParamQuery, OnFinalProductFound);
    }

    const updateIngredientsTotal = (ParamNewIngredients) => {

        let total = 0;

        // console.log("Ingr = " + JSON.stringify(ParamNewIngredients));

        let keys = Object.keys(ParamNewIngredients);

        for (let key of keys) {
            const myTotal = ParamNewIngredients[key].price * ParamNewIngredients[key].amount;
            total += myTotal;
        }

        setIngredientsTotal(total);
        return total;
    }

    const updateExpectedProductsTotal = (ParamNewProducts) => {

        let total = 0;

        // console.log("Ingr = " + JSON.stringify(ParamNewIngredients));

        let keys = Object.keys(ParamNewProducts);

        for (let key of keys) {
            const myTotal = ParamNewProducts[key].price * ParamNewProducts[key].amount;
            total += myTotal;
        }

        setExpectedProductsTotal(total);
        return total;
    }

    const updateFinalProductsTotal = (ParamNewProducts) => {

        let total = 0;

        // console.log("Ingr = " + JSON.stringify(ParamNewIngredients));

        let keys = Object.keys(ParamNewProducts);

        for (let key of keys) {
            const myTotal = ParamNewProducts[key].price * ParamNewProducts[key].amount;
            total += myTotal;
        }

        setFinalProductsTotal(total);
        return total;
    }

    const handleIngredientAmountUpdate = (ParamID, ParamAmount) => {
        // console.log("Amount = " + ParamAmount);

        setIngredients(prevIngredients => {
            // Create a new object based on the previous state
            const newIngredients = { ...prevIngredients };

            // Update the amount for the specified ingredient
            if (newIngredients[ParamID]) {
                newIngredients[ParamID] = {
                    ...newIngredients[ParamID],
                    amount: Number(ParamAmount),
                };
            }

            return newIngredients;
        });

        setChangesAvailable(true);
        setCount(count + 1);
        // updateIngredientsTotal(newIngredients); // Assuming you have a way to calculate the total
        // setIngredientsTotal(ingredientsTotal + price); // Update total if necessary
    };

    const handleExpectedProductsAmountUpdate = (ParamID, ParamAmount) => {
        // console.log("Amount = " + ParamAmount);

        setExpectedProducts(prevProds => {
            // Create a new object based on the previous state
            const newProds = { ...prevProds };

            // Update the amount for the specified ingredient
            if (newProds[ParamID]) {
                newProds[ParamID] = {
                    ...newProds[ParamID],
                    amount: Number(ParamAmount),
                };
            }

            return newProds;
        });

        setChangesAvailable(true);
        setCount(count + 1);
    };

    const handleFinalProductsAmountUpdate = (ParamID, ParamAmount) => {
        // console.log("Amount = " + ParamAmount);

        setFinalProducts(prevProds => {
            // Create a new object based on the previous state
            const newProds = { ...prevProds };

            // Update the amount for the specified ingredient
            if (newProds[ParamID]) {
                newProds[ParamID] = {
                    ...newProds[ParamID],
                    amount: Number(ParamAmount),
                };
            }

            return newProds;
        });

        setChangesAvailable(true);
        setCount(count + 1);
    };

    const deleteIngredientById = (ParamID) => {
        setIngredients(prevIngredients => {
            // Create a new object without the ingredient to be deleted
            const newIngredients = { ...prevIngredients };
            delete newIngredients[ParamID];
            return newIngredients;
        });
    };

    const deleteExpectedProductById = (ParamID) => {
        setExpectedProducts(prevProds => {
            // Create a new object without the ingredient to be deleted
            const newProds = { ...prevProds };
            delete newProds[ParamID];
            return newProds;
        });
    };

    const deleteFinalProductById = (ParamID) => {
        setFinalProducts(prevProds => {
            // Create a new object without the ingredient to be deleted
            const newProds = { ...prevProds };
            delete newProds[ParamID];
            return newProds;
        });
    };

    const OnIngredientFound = (ParamResult) => {

        if (ParamResult.data && ParamResult.data._id) {

            const price = ParamResult.data.wap;
            // const price = ParamResult.data.price;
            // const price = GetAppropriatePrice(ParamResult.data);
            // console.log("Price = " + price);
            var tmp = ingredients;

            if (tmp[ParamResult.data._id]) {
                tmp[ParamResult.data._id].amount += 1;
                tmp[ParamResult.data._id].price = price;
            } else {
                tmp[ParamResult.data._id] = ParamResult.data;
                tmp[ParamResult.data._id].amount = 1;
                tmp[ParamResult.data._id].price = price;
            }

            setIngredients(tmp);
            setChangesAvailable(true);
            ingredientRef.current.clear();
            setCount(count + 1);
            setIngredientsTotal(ingredientsTotal + price);
        }

    }

    const OnExpectedProductFound = (ParamResult) => {

        if (ParamResult.data && ParamResult.data._id) {

            const price = ParamResult.data.price;
            // const price = GetAppropriatePrice(ParamResult.data);
            // console.log("Price = " + price);
            var tmp = expectedProducts;

            if (tmp[ParamResult.data._id]) {
                tmp[ParamResult.data._id].amount += 1;
                tmp[ParamResult.data._id].price = price;
            } else {
                tmp[ParamResult.data._id] = ParamResult.data;
                tmp[ParamResult.data._id].amount = 1;
                tmp[ParamResult.data._id].price = price;
            }

            setExpectedProducts(tmp);
            setChangesAvailable(true);
            expectedRef.current.clear();
            setCount(count + 1);
            setExpectedProductsTotal(expectedProductsTotal + price);
        }

    }

    const OnFinalProductFound = (ParamResult) => {

        if (ParamResult.data && ParamResult.data._id) {

            const price = ParamResult.data.price;
            // const price = GetAppropriatePrice(ParamResult.data);
            // console.log("Price = " + price);
            var tmp = finalProducts;

            if (tmp[ParamResult.data._id]) {
                tmp[ParamResult.data._id].amount += 1;
                tmp[ParamResult.data._id].price = price;
            } else {
                tmp[ParamResult.data._id] = ParamResult.data;
                tmp[ParamResult.data._id].amount = 1;
                tmp[ParamResult.data._id].price = price;
            }

            setFinalProducts(tmp);
            setChangesAvailable(true);
            finalRef.current.clear();
            setCount(count + 1);
            setFinalProductsTotal(finalProductsTotal + price);
        }

    }

    const handleSaveOnClick = async () => {

        if (pcID) {
            await Update();
        } else {
            await Save();
        }

    }

    const Save = () => {

        return new Promise(async (resolve) => {

            if (!changesAvailable)
                resolve(false);

            setIsSaving(true);

            const pcToPost = {
                ingredients: ingredients,
                expectedProducts: expectedProducts,
                finalProducts: finalProducts,
                ingredientsTotal: ingredientsTotal,
                expectedProductsTotal: expectedProductsTotal,
                finalProductsTotal: finalProductsTotal,
                status: status,
                batch: finalBatch
            }

            PerformSecurePostRequest("/api/new-prod-cycle", pcToPost, (res) => {

                setIsSaving(false);

                if (res) {
                    console.log("ID =  " + res.data.id);
                    setPcID(res.data.id);
                    setChangesAvailable(false);
                    resolve(true);
                } else {
                    resolve(false);
                }

            });
        });

    }

    const Update = () => {

        return new Promise(async (resolve) => {

            if (!changesAvailable)
                resolve(false);

            setIsSaving(true);

            const pcToPost = {
                id: pcID,
                ingredients: ingredients,
                expectedProducts: expectedProducts,
                finalProducts: finalProducts,
                ingredientsTotal: ingredientsTotal,
                expectedProductsTotal: expectedProductsTotal,
                finalProductsTotal: finalProductsTotal,
                status: status,
                batch: finalBatch
            }

            PerformSecurePostRequest("/api/update-prod-cycle", pcToPost, (res) => {

                setIsSaving(false);

                if (res) {
                    // console.log("ID =  " + res.data.id);
                    // setSaleID(res.data.id);
                    setChangesAvailable(false);
                    resolve(true);
                } else {
                    resolve(false);
                }

            });

        });
    }

    const handleLaunch = () => {
        setStatus("RUNNING");
        setChangesAvailable(true);
    }

    const handlePause = () => {
        setStatus("ON_PAUSE");
        setChangesAvailable(true);
    }

    const handleStop = () => {
        setStatus("ON_HALT");
        setChangesAvailable(true);
    }

    const handleFinalize = () => {
        // setStatus("FINALIZED");
        // setChangesAvailable(true);
        setFPPopupOpen(true);
    }

    const handlePaymentOnConfirm = (ParamBatch, ParamExpiryDate) => {
        setStatus("FINALIZED");
        setFinalBatch({ batchID: ParamBatch, expiryDate: ParamExpiryDate });
        console.log("FINAL BATCH = " + JSON.stringify({ batchID: ParamBatch, expiryDate: ParamExpiryDate }));
        setChangesAvailable(true);
    }

    return (
        <div className='text-gray-100 bg-black'>

            <video src={videoSource} className='fixed h-screen w-full object-cover opacity-100' autoPlay loop muted />

            {/* Control Buttons */}
            <div className='fixed top-16 right-1 left-1 h-11 bg-black bg-opacity-80 backdrop-blur-xl border-2 border-neutral-900 m-1 p-1 rounded-xl flex flex-row items-center justify-center space-x-2'>
                <RknButton className="h-7 text-sm mb-1" label="Enregistrer" before={<FaSave className='mb-1' />} disabled={!changesAvailable} onPress={handleSaveOnClick} />
                <RknButton className="h-7 text-sm mb-1" label="Lancer" before={<FaRocket className='mb-1' />} onPress={handleLaunch} disabled={(status === "RUNNING" || status === "FINALIZED")} />
                <RknButton className="h-7 text-sm mb-1" label="Pause" before={<FaPause className='mb-1' />} onPress={handlePause} disabled={(status === "ON_PAUSE" || status === "FINALIZED")} />
                <RknButton className="h-7 text-sm mb-1" label="Stop" before={<FaStop className='mb-1' />} onPress={handleStop} disabled={(status === "ON_HALT" || status === "FINALIZED")} />
                <RknButton className="h-7 text-sm mb-1" label="Finalizer" before={<FaCheckCircle className='mb-1' />} onPress={handleFinalize} disabled={(status === "FINALIZED")} />
            </div>

            <div className='fixed top-28 right-1 left-1 h-10 bg-black bg-opacity-80 border-2 border-neutral-900 m-1 p-1 rounded-xl flex flex-col items-center justify-center'>
                <div style={{ fontSize: 14 }} className='text-gray-100 font-bold flex flex-row items-center justify-center space-x-2'>

                    {status === "AWAITING_LAUNCH" && <FaRocket size={20} className='mr-0.5' />}
                    {status === "AWAITING_LAUNCH" && <div>Cycle de Production N° 01</div>}
                    {status === "AWAITING_LAUNCH" && <span className='text-xs bg-neutral-500 text-neutral-800 p-0.5 px-2 rounded-full mx-2'>En attente de lancement...</span>}

                    {status === "RUNNING" && <FaCog size={20} className='animate-spin mr-0.5' />}
                    {status === "RUNNING" && <div>Cycle de Production N° 01</div>}
                    {status === "RUNNING" && <span className='text-xs bg-green-700 text-neutral-100 p-0.5 px-2 rounded-full mx-2'>Production en cours</span>}

                    {status === "ON_PAUSE" && <FaPause size={20} className='animate-pulse mr-0.5' />}
                    {status === "ON_PAUSE" && <div className='animate-pulse'>Cycle de Production N° 01</div>}
                    {status === "ON_PAUSE" && <span className='text-xs bg-orange-700 text-neutral-100 p-0.5 px-2 rounded-full mx-2 animate-pulse'>Production en pause</span>}

                    {status === "ON_HALT" && <FaTimesCircle size={20} className='animate-ping mr-0.5 text-red-700' />}
                    {status === "ON_HALT" && <div className='animate-pulse'>Cycle de Production N° 01</div>}
                    {status === "ON_HALT" && <span className='text-xs bg-red-700 text-neutral-100 p-0.5 px-2 rounded-full mx-2 animate-pulse'>Production en arrêt</span>}

                    {status === "FINALIZED" && <FaCheckCircle size={20} className='animate-bounce mr-0.5 text-green-500' />}
                    {status === "FINALIZED" && <div>Cycle de Production N° 01</div>}
                    {status === "FINALIZED" && <span className='text-xs bg-green-900 text-green-100 border-2 border-green-500 p-0.5 px-2 rounded-full mx-2'>Production Terminée</span>}

                </div>

                {/* Three Parts */}
                <div className='flex flex-row items-center justify-center bg-transparent fixed top-40 bottom-2 right-1 left-1'>
                    <div className='bg-red-900 m-1 p-1 w-1/3 rounded-xl h-full bg-opacity-20 backdrop-blur-xl flex flex-col items-center justify-start'>
                        <div className='bg-black bg-opacity-50 border-2 border-neutral-500 w-full h-10 m-1 p-1 rounded-xl font-bold text-lg'>Ingrédients</div>
                        <RknDebouncedInput ref={ingredientRef} label="Ingrédient" onSignal={handleIngredientSignal} />

                        {/* List */}
                        <div className='w-full bg-red-900 rounded-xl flex-grow bg-opacity-50 p-1'>
                            {Object.keys(ingredients).map((k) => {
                                const p = ingredients[k];
                                return (
                                    <div key={p._id} className='my-1'>
                                        <ConsumedProductTag key={p._id} amount={p.amount} label={p.name} onConfirm={(ParamAmount) => handleIngredientAmountUpdate(p._id, ParamAmount)} onDelete={() => { deleteIngredientById(p._id); }} editable />
                                        <br />
                                    </div>
                                )
                            })}
                        </div>

                        {/* Total */}
                        <div className='w-full h-10 rounded-lg bg-black bg-opacity-50 text-gray-100 font-bold mt-1 flex flex-col items-center justify-center'>
                            {StringToNumber_2DecAtMost(ingredientsTotal)} DA
                        </div>

                    </div>
                    <div className='bg-blue-900 m-1 p-1 w-1/3 rounded-xl h-full bg-opacity-20 backdrop-blur-xl flex flex-col items-center justify-start'>
                        <div className='bg-black bg-opacity-50 border-2 border-neutral-500 w-full h-10 m-1 p-1 rounded-xl font-bold text-lg'>Résultats Anticipés</div>
                        <RknDebouncedInput ref={expectedRef} label="Produit" onSignal={handleExpectedProductSignal} />

                        {/* List */}
                        <div className='w-full bg-blue-900 rounded-xl flex-grow bg-opacity-50 p-1'>
                            {Object.keys(expectedProducts).map((k) => {
                                const p = expectedProducts[k];
                                return (
                                    <div key={p._id} className='my-1'>
                                        <ConsumedProductTag key={p._id} amount={p.amount} label={p.name} onConfirm={(ParamAmount) => handleExpectedProductsAmountUpdate(p._id, ParamAmount)} onDelete={() => { deleteExpectedProductById(p._id); }} editable />
                                        <br />
                                    </div>
                                )
                            })}
                        </div>

                        {/* Total */}
                        <div className='w-full h-10 rounded-lg bg-black bg-opacity-50 text-gray-100 font-bold mt-1 flex flex-col items-center justify-center'>
                            {StringToNumber_2DecAtMost(expectedProductsTotal)} DA
                        </div>

                    </div>
                    <div className='bg-green-900 m-1 p-1 w-1/3 rounded-xl h-full bg-opacity-20 backdrop-blur-xl flex flex-col items-center justify-start'>
                        <div className='bg-black bg-opacity-50 border-2 border-neutral-500 w-full h-10 m-1 p-1 rounded-xl font-bold text-lg'>Résultats Réels</div>
                        <RknDebouncedInput ref={finalRef} label="Produit" onSignal={handleFinalProductSignal} />

                        {/* List */}
                        <div className='w-full bg-green-900 rounded-xl flex-grow bg-opacity-50 p-1'>
                            {Object.keys(finalProducts).map((k) => {
                                const p = finalProducts[k];
                                return (
                                    <div key={p._id} className='my-1'>
                                        <ConsumedProductTag key={p._id} amount={p.amount} label={p.name} onConfirm={(ParamAmount) => handleFinalProductsAmountUpdate(p._id, ParamAmount)} onDelete={() => { deleteFinalProductById(p._id); }} editable />
                                        <br />
                                    </div>
                                )
                            })}
                        </div>

                        {/* Total */}
                        <div className='w-full h-10 rounded-lg bg-black bg-opacity-50 text-gray-100 font-bold mt-1 flex flex-col items-center justify-center'>
                            {StringToNumber_2DecAtMost(finalProductsTotal)} DA
                        </div>

                    </div>
                </div>

            </div>

            {FPPopupOpen && <FinalizeProductionPopup isOpen={FPPopupOpen} onClose={() => { setFPPopupOpen(false); }} onConfirm={handlePaymentOnConfirm} />}
        </div>
    )
}

export default ProductionCycleEditor