import React, { useState, useEffect } from 'react';
import BankData from '../../assets/Cities/Banks_Of_Algeria.json';
import { InputFieldStyle } from '../../Styles';
import { FaEdit } from 'react-icons/fa';

const RknBankSelector = (props) => {

    const [bankList, setBankList] = useState(null);
    const [selectedBank, setSelectedBank] = useState(null);
    const [editMode, setEditMode] = useState(false);
    const [editValue, setEditValue] = useState("");

    useEffect(() => {
        // console.log('Loaded Banks :' + JSON.stringify(BankData));
        setBankList(BankData);
    }, []);

    const handleBankChange = (e) => {
        const selectedId = e.target.value;
        setSelectedBank(selectedId);

        if (props.onChange) {
            const selectedBankObject = bankList.find(bank => bank.id === selectedId);
            props.onChange({ id: selectedId, name: selectedBankObject.name });
        }
    }

    const handleEditValueChange = (e) => {
        const v = e.target.value;
        setEditValue(v);

        if (props.onChange) {
            props.onChange({ id: v, name: v });
        }
    }

    return (
        <div className='text-gray-100 flex flex-col items-start justify-center'>
            <label className="ml-1 text-sm font-medium text-gray-900 dark:text-white">Banque</label>
            <div className='flex flex-row items-center justify-center'>

                {/* Input or Selector */}
                {editMode ?
                    <input value={editValue} onChange={handleEditValueChange} className={InputFieldStyle + " w-64"} />
                    :
                    <select value={selectedBank} onChange={handleBankChange} className={InputFieldStyle + " mt-1"} >
                        {bankList && bankList.map((w, i) => {
                            return (
                                <option key={w.id} value={w.id}>{w.name}</option>
                            )
                        })}
                    </select>
                }

                {/* Edit Button */}
                <div className='h-10 w-10 pt-2 pl-0.5 ml-1 mt-1 bg-gray-900 border border-gray-500 rounded-lg hover:bg-gray-500 active:scale-90 transition duration-150 flex flex-col items-center justify-start cursor-pointer'
                    onClick={() => setEditMode(!editMode)}>
                    <FaEdit size={20} />
                </div>
            </div>
        </div>
    );
};

export default RknBankSelector;