import React, { useState, useEffect, useRef } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import RknNumericInput from './RknUI/RknNumericInput';
import RknButton from './RknUI/RknButton';
import { FaCheckCircle, FaTimesCircle } from 'react-icons/fa';

const ConsumedProductTag = (props) => {

    const ref = useRef(null);

    const [showEditor, setShowEditor] = useState(false);
    const [amount, setAmount] = useState(0);

    useEffect(() => {
        const handleKeyDown = (event) => {
            if (event.key === 'Enter' || event.keyCode === 13) {
                handleConfirm();
            }
        };

        document.addEventListener('keydown', handleKeyDown);
        return () => {
            document.removeEventListener('keydown', handleKeyDown);
        };
    }, [amount]);

    useEffect(() => {
        setAmount(props.amount);
    }, [props.amount])

    const handleClick = () => {

        if (!showEditor && props.editable) {
            setShowEditor(true);
            setTimeout(() => { ref.current.focus(); }, 150);
        }
    }

    const handleConfirm = () => {

        if (props.onConfirm) {
            props.onConfirm(amount);
        }

        setShowEditor(false);

    }

    const handleDelete = () => {

        if (props.onDelete)
            props.onDelete();

    }

    const changeAmountOnClick = (ParamAmount) => {
        let tmpAmount = Number(amount) + Number(ParamAmount);

        if (tmpAmount < 1)
            tmpAmount = 1;

        setAmount(tmpAmount);
    }

    return (
        // <div className='inline m-1 bg-gray-700 rounded-xl px-2 py-1 text-sm cursor-pointer select-none hover:bg-gray-500' onClick={props.onClick}>
        <div className='inline m-1 bg-gray-700 rounded-xl px-2 py-1 text-sm cursor-pointer select-none hover:bg-gray-500' onClick={handleClick}>

            {props.amount && props.amount > 1 &&
                <div className='inline mr-1 px-2 py-0.5 bg-gray-900 rounded-xl font-bold'>
                    {props.amount}
                </div>
            }

            {props.amount && props.amount < 1 &&
                <div className='inline mr-1 px-2 py-0.5 bg-red-900 rounded-xl font-bold'>
                    {props.amount}
                </div>
            }

            {props.label}

            <AnimatePresence>
                {showEditor && <motion.div
                    key={showEditor}
                    initial={props.centered ? { opacity: 0, scale: "20%", x: 0, y: -72 } : { opacity: 0, scale: "20%", x: -64, y: -96 }}
                    animate={{ opacity: 1, scale: "100%", x: "5%", y: -64 }}
                    exit={props.centered ? { opacity: 0, scale: "20%", x: 0, y: -72 } : { opacity: 0, scale: "20%", x: -64, y: -96 }}
                    transition={{ duration: 0.2 }}
                    className={props.centered ?
                        'absolute flex flex-col items-center justify-center bg-gray-700 bg-opacity-80 backdrop-blur-xl border-4 border-gray-500 rounded-3xl p-2 sm:w-5/6 w-11/12'
                        :
                        'absolute flex flex-col items-center justify-center bg-gray-700 bg-opacity-80 backdrop-blur-xl border-4 border-gray-500 rounded-3xl p-2 w-80 mt-10'
                    }
                >
                    <div className='flex flex-row items-center justify-center'>
                        <div className='bg-gray-900 py-0.5 px-1 mx-0.5 mt-1 text-base text-gray-100 h-7 hover:bg-gray-600 font-bold rounded-lg cursor-pointer transition duration-150 active:scale-90 mr-0.5' onClick={() => changeAmountOnClick(-10)}>-10</div>
                        <div className='bg-gray-900 py-0.5 px-1 mx-0.5 mt-1 text-base text-gray-100 h-7 hover:bg-gray-600 font-bold rounded-lg cursor-pointer transition duration-150 active:scale-90 mr-1.5' onClick={() => changeAmountOnClick(-1)}>-1</div>
                        <RknNumericInput value={amount} onChange={(v) => setAmount(Number(v))} ref={ref} width="64px" />
                        <div className='bg-gray-900 py-0.5 px-1 mx-0.5 mt-1 text-base text-gray-100 h-7 hover:bg-gray-600 font-bold rounded-lg cursor-pointer transition duration-150 active:scale-90' onClick={() => changeAmountOnClick(1)}>+1</div>
                        <div className='bg-gray-900 py-0.5 px-1 mx-0.5 mt-1 text-base text-gray-100 h-7 hover:bg-gray-600 font-bold rounded-lg cursor-pointer transition duration-150 active:scale-90' onClick={() => changeAmountOnClick(10)}>+10</div>
                    </div>
                    <div className='flex flex-row items-center justify-center space-x-1.5 my-1'>
                        <RknButton className="h-7 text-sm mb-1" label="Confirmer" before={<FaCheckCircle className='mb-1' />} disabled={false} onPress={handleConfirm} />
                        <RknButton className="h-7 text-sm mb-1" label="Supprimer" before={<FaTimesCircle className='mb-1' />} disabled={false} onPress={handleDelete} />
                    </div>
                </motion.div>}
            </AnimatePresence>

        </div>
    )
}

export default ConsumedProductTag