import { React, useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { FaTimesCircle, FaCheckCircle, FaTrash } from 'react-icons/fa';
import hotkeys from 'hotkeys-js';
import { PulseLoader } from 'react-spinners';
import { PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import RknNumericInput from './RknUI/RknNumericInput';
import { IsIsoDate } from '../Reaknotron/Libs/RknTimeTools';
import RknButton from './RknUI/RknButton';

const AdjustDdoPopup = (props) => {

    const inputFieldStyle = 'bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 mt-0.5 h-9';

    const amountRef = useRef(null);

    useEffect(() => {

        // console.log("USE EFFECT : E = " + JSON.stringify(props.adjustment));

        if (props.adjustment) {

            if (props.adjustment.amount) {
                setAmount(props.adjustment.amount);
            } else {
                setAmount("-");
            }

            setBankName(props.adjustment.bankName);
            setAccountNumber(props.adjustment.accountNumber);
            setReason(props.adjustment.reason);
            setStatus(props.adjustment.status);
        }

        setTimeout(() => { amountRef.current.focus(); }, 150);
    }, []);

    useEffect(() => {

        // console.log("USE EFFECT : E = " + JSON.stringify(props.adjustment));

        if (props.state) {

            let count = 0;
            props.state.forEach(ddo => {
                if (ddo.selected) {
                    count++;
                }
            });
            setSelectionCount(count);
        }

        setTimeout(() => { amountRef.current.focus(); }, 150);
    }, []);

    useEffect(() => {

        hotkeys.filter = function (event) {
            var tagName = (event.target || event.srcElement).tagName;
            hotkeys.setScope(/^(INPUT|TEXTAREA|SELECT)$/.test(tagName) ? 'input' : 'other');
            return true;
        }

        hotkeys('escape', event => {
            event.preventDefault();
            TriggerPropsOnCancel();
        });

        return () => {
            hotkeys.unbind('escape');
        }

    }, []);

    // Basic
    const [amount, setAmount] = useState(null);
    const [reason, setReason] = useState(null);
    const [bankName, setBankName] = useState("");
    const [accountNumber, setAccountNumber] = useState("");
    const [status, setStatus] = useState("PENDING");

    const [selectionCount, setSelectionCount] = useState(0);

    const [saving, setSaving] = useState(false);

    const handleStatusChange = (event) => {
        setStatus(event.target.value);
    }

    const TriggerPropsOnConfirm = (ParamAdjustment) => {

        if (props.onConfirm) {
            props.onConfirm(ParamAdjustment);
        }

    }

    const OnSubmit = (e) => {
        e.preventDefault();
        // TriggerPropsOnConfirm();

        if (selectionCount > 0) {
            AdjustMultiDdoInDB();
        } else {
            AdjustDdoInDB();
        }

    }

    const TriggerPropsOnCancel = () => {
        if (props.onCancel)
            props.onCancel();
    }

    const AdjustDdoInDB = async () => {

        setSaving(true);

        try {

            const ddoToPost = { id: props.adjustment.id, amount: amount, reason: reason, status: status, accountNumber: accountNumber, bankName: bankName };

            PerformSecurePostRequest("/api/update-ddo", ddoToPost, (res) => {
                TriggerPropsOnConfirm(ddoToPost);
                setSaving(false);
            });

        } catch (error) {
            console.log("ERROR : " + error);

            if (error.response && error.response.status >= 400 && error.response.status <= 500) {
                console.log(error.response.data);
            }

            setSaving(false);
        }
    }

    const AdjustMultiDdoInDB = async () => {

        setSaving(true);
        let done = 0;

        props.state.forEach(ddo => {
            if (ddo.selected) {
                let ddoToPost = { id: ddo._id, amount: amount, reason: reason, status: status };
                PerformSecurePostRequest("/api/update-ddo", ddoToPost, (res) => {

                    done++;

                    if (done >= selectionCount) {
                        TriggerPropsOnConfirm();
                        setSaving(false);
                    }

                });
            }
        });

    }

    return (
        <motion.div
            className='fixed top-0 right-0 left-0 w-screen h-screen bg-black bg-opacity-60 z-10 flex flex-col items-center justify-center backdrop-blur-lg'
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.3 }}
        >
            <motion.div
                className='bg-gray-900 border-4 border-gray-500 rounded-3xl m-auto w-96 p-4 pb-0 flex flex-col items-center justify-center'
                initial={{ opacity: 0, y: "-50%" }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.3 }}
            >
                <h1 className='mb-4 font-bold text-gray-100 text-lg'>Ajustement d'Ordre de Virement</h1>
                {selectionCount > 1 && <div className='text-sm text-gray-100 mb-4'>Vous avez sélectionné {selectionCount} ordres de virement.</div>}

                <form onSubmit={OnSubmit} className='flex flex-col items-center justify-center'>

                    <div className='flex flex-row items-center justify-start my-1'>
                        <label className="mr-2 text-sm font-medium text-gray-900 dark:text-white">Montant</label>
                        <RknNumericInput value={amount} onChange={(v) => setAmount(v)} ref={amountRef} placeholder='Montant...' allowNegative />
                    </div>

                    <div className='flex flex-row items-center justify-start my-1'>
                        <label className="mr-7 text-sm font-medium text-gray-900 dark:text-white">Motif</label>
                        <input type="text" name='reason' placeholder='Motif...' value={reason} className={inputFieldStyle} onChange={(e) => { setReason(e.target.value) }} />
                    </div>

                    <div className='flex flex-row items-center justify-start my-1' style={{ opacity: selectionCount > 0 ? 0.25 : 1 }}>
                        <label className="mr-4 text-sm font-medium text-gray-900 dark:text-white">Banque</label>
                        <input type="text" name='bankName' placeholder='Banque...' value={bankName} className={inputFieldStyle} onChange={(e) => { setBankName(e.target.value) }} />
                    </div>

                    <div className='flex flex-row items-center justify-start my-1' style={{ opacity: selectionCount > 0 ? 0.25 : 1 }}>
                        <label className="mr-10 text-sm font-medium text-gray-900 dark:text-white">RIB</label>
                        <input type="text" name='accountNumber' placeholder='RIB...' value={accountNumber} className={inputFieldStyle} onChange={(e) => { setAccountNumber(e.target.value) }} />
                    </div>

                    <div className='flex flex-row items-center justify-start my-1'>
                        <label className="mr-10 text-sm font-medium text-gray-900 dark:text-white">Etat</label>
                        <select name="state" className='bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-0.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 mt-0.5 h-9 w-44' value={status} onChange={handleStatusChange}>
                            <option value="PENDING">⌛ En Attente...</option>
                            <option value="DONE">✅ Effectué</option>
                            <option value="IGNORED">❌ Ignoré</option>
                        </select>
                    </div>

                    <div className='flex flex-row items-center justify-center mt-6 space-x-2'>
                        <RknButton submit label="Confirmer" busy={saving} />
                        <button type='button' onClick={TriggerPropsOnCancel} className="bg-blue-500 hover:bg-blue-400 text-white font-bold py-2 px-4 border-b-4 border-blue-700 hover:border-blue-500 rounded"><FaTimesCircle className='inline mb-1' size={20} /> Annuler</button>
                    </div>
                </form>

                <br />

            </motion.div>
        </motion.div>
    )
}

export default AdjustDdoPopup