import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import { GetShortDate, GetShortDateOf } from '../Reaknotron/Libs/RknTimeTools';
import AppData from '../App.json';
import BatchRemovalPopup from '../components/BatchRemovalPopup';
import { Link } from 'react-router-dom';
import { FaEdit, FaStickyNote, FaTrash } from 'react-icons/fa';
import PrintMedicationStickerPopup from '../components/PrintMedicationStickerPopup';

const BatchManager = () => {

    const [batches, setBatches] = useState(null);
    const [batchRemovalPopupTarget, setBatchRemovalPopupTarget] = useState(null);
    const [stickerPopupOpen, setStickerPopupOpen] = useState(false);
    const [stickerPopupTarget, setStickerPopupTarget] = useState(null);
    // const [makeStickerPopupOpen, setMakeStickerPopupOpen] = useState(false);

    useEffect(() => {

        GetBatchListFromDb();

    }, []);

    const columns = [
        {
            title: 'Opérations',
            dataIndex: '',
            key: 'operations',
            width: 128,
            className: 'border border-gray-500',
            render: i => GenerateOperationButtons(i)
        },
        {
            title: 'Produit',
            dataIndex: 'product',
            key: 'product',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Lot N°',
            dataIndex: 'batchID',
            key: 'batchID',
            className: AppData.BATCH_ID_FLAG ? 'border border-gray-500' : 'hidden',
            width: 256
        },
        {
            title: 'Date de péremption',
            dataIndex: '',
            key: 'expiryDateStatus',
            className: 'border border-gray-500',
            width: 256,
            render: b => RenderExpirationStatus(b._id, b.expiryDateStatus)
        },
        {
            title: 'Qte. Disponible/Orginal',
            dataIndex: '',
            key: 'amount',
            className: 'border border-gray-500',
            width: 256,
            render: b => <div>{b.currentAmount} / {b.originalAmount}</div>
        }
    ];

    const GenerateOperationButtons = (ParamItem) => {

        const buttonStyle = 'bg-gray-900 text-gray-100 rounded-lg p-2 my-2 mx-1 text-sm hover:bg-gray-700 inline';

        if (ParamItem) {
            return (
                <div className='flex flex-row'>
                    {AppData.MEDICATION_STICKER_MAKER && <button className={buttonStyle} onClick={() => { setStickerPopupTarget(ParamItem); setStickerPopupOpen(true); }}> <FaStickyNote size={20} /> </button>}
                    <button className={buttonStyle} onClick={() => { console.log("EDIT"); }}> <FaEdit size={20} /> </button>
                    <button className={buttonStyle} onClick={() => { console.log("DELETE"); DeleteBatchInDB(ParamItem._id) }}> <FaTrash size={20} /> </button>
                </div>
            )
        }

        return "N/A";
    }

    const DownloadStickerOnClick = (ParamBatch) => {
        console.log("Open Popup : " + JSON.stringify(ParamBatch));
    }

    const DeleteBatchInDB = (ParamProductID) => {

    }

    const GetBatchListFromDb = async () => {

        PerformGetRequest("/api/get-batch-list", (res) => {
            console.log("BATCHES = " + JSON.stringify(res.data));
            setBatches(res.data);
        }
        );
    }

    // TODO : Use get expiration status function from sales point and then render the component
    const RenderExpirationStatus = (ParamID, ParamStatus) => {

        // console.log("STATUS = " + JSON.stringify(ParamStatus));

        // console.log("ID = " + ParamID);

        if (ParamStatus && ParamStatus.date) {

            const date = new Date(ParamStatus.date);

            if (ParamStatus.status === "SAFE") {
                return <div className='text-xs font-bold bg-green-700 rounded-xl m-2 p-1'>{GetShortDateOf(date)}</div>
            } else if (ParamStatus.status === "WARNING") {
                return <div className='text-xs font-bold bg-yellow-400 text-black rounded-xl m-2 p-1'>{GetShortDateOf(date)}<div style={{ fontSize: "10px" }} className='text-neutral-700'>{"Dans " + ParamStatus.remaining + " jour(s)"}</div></div>
            } else if (ParamStatus.status === "DANGER") {
                return <div onClick={() => { setBatchRemovalPopupTarget(ParamID); }} className='text-xs font-bold neon-pulse-critical rounded-xl m-2 p-1 text-yellow-200 select-none cursor-pointer active:scale-95 transition duration-150'>{GetShortDateOf(date)}<div>{"Dans " + ParamStatus.remaining + " jour(s) !"}</div></div>
            } else if (ParamStatus.status === "EXPIRED") {
                return <div onClick={() => { setBatchRemovalPopupTarget(ParamID); console.log("BATCH ON CLICK : " + ParamID); }} className='text-xs font-bold neon-pulse-danger rounded-xl m-2 p-1 select-none cursor-pointer active:scale-95 transition duration-150'>{GetShortDateOf(date)}<div className='text-white mt-1 text-lg'>! Périmé !</div></div>
            } else if (ParamStatus.status === "UNKNOWN") {
                return <div className='font-bold bg-neutral-700 text-gray-300 rounded-3xl h-8 m-2 p-1'>?</div>
            } else {
                return <div className='font-bold bg-neutral-700 text-gray-300 rounded-3xl h-8 m-2 p-1'>?</div>
            }
        } else {
            return <div className='font-bold bg-neutral-700 text-gray-300 rounded-3xl h-8 m-2 p-1'>?</div>
        }

    }

    const handleBatchRemovalOnConfirm = () => {
        GetBatchListFromDb();
        setBatchRemovalPopupTarget(null);
    }

    return (
        <div className='text-gray-100'>
            <br />
            <h3 className='text-xl font-bold'>Liste des Lots</h3>
            <br />
            <div className='flex flex-col items-center'>
                <Table columns={columns} data={batches} rowKey="_id" />
            </div>
            <br />
            <br />

            {batchRemovalPopupTarget && <BatchRemovalPopup onCancel={() => { setBatchRemovalPopupTarget(null); }} onConfirm={handleBatchRemovalOnConfirm} batchID={batchRemovalPopupTarget} />}
            {stickerPopupTarget && <PrintMedicationStickerPopup isOpen={stickerPopupOpen} onClose={() => { setStickerPopupTarget(null); setStickerPopupOpen(false); }} batch={stickerPopupTarget} />}

        </div>
    )
}

export default BatchManager