/**
 * Draws a dotted line on a jsPDF doc between two points.
 * Note that the segment length is adjusted a little so
 * that we end the line with a drawn segment and don't
 * overflow.
*/
function DottedLine(doc, xFrom, yFrom, xTo, yTo, segmentLength) {
    // Calculate line length (c)
    var a = Math.abs(xTo - xFrom);
    var b = Math.abs(yTo - yFrom);
    var c = Math.sqrt(Math.pow(a, 2) + Math.pow(b, 2));

    // Make sure we have an odd number of line segments (drawn or blank)
    // to fit it nicely
    var fractions = c / segmentLength;
    var adjustedSegmentLength = (Math.floor(fractions) % 2 === 0) ? (c / Math.ceil(fractions)) : (c / Math.floor(fractions));

    // Calculate x, y deltas per segment
    var deltaX = adjustedSegmentLength * (a / c);
    var deltaY = adjustedSegmentLength * (b / c);

    var curX = xFrom, curY = yFrom;
    while (curX <= xTo && curY <= yTo) {
        doc.setLineWidth(0.25);
        doc.line(curX, curY, curX + deltaX, curY + deltaY);
        curX += 2 * deltaX;
        curY += 2 * deltaY;
    }
}

function DrawLine(doc, xFrom, yFrom, xTo, yTo, w, color) {
    doc.setDrawColor(color.r, color.g, color.b);
    doc.setLineWidth(w);
    doc.line(xFrom, yFrom, xTo, yTo);
}

function DrawFilledRect(doc, x, y, w, h, color) {
    doc.setFillColor(color.r, color.g, color.b);
    doc.rect(x, y, w, h, 'F');
    doc.stroke();
}

function DrawFilledRoundedRect(doc, x, y, w, h, rx, ry, color) {
    doc.setFillColor(color.r, color.g, color.b);
    doc.roundedRect(x, y, w, h, rx, ry, 'F');
    doc.stroke();
}

module.exports = { DottedLine, DrawFilledRect, DrawLine, DrawFilledRoundedRect }