import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';

const DischargedInventory = () => {

    useEffect(() => {

        GetInventoryFromDb();

    }, []);

    const [inventory, setInventory] = useState(null);

    const columns_1 = [
        {
            title: 'Designation',
            dataIndex: 'name',
            key: 'name',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Quantité',
            dataIndex: 'amount',
            key: 'amount',
            className: 'border border-gray-500',
            width: 256
        }
    ];

    const columns_2 = [
        {
            title: 'Designation',
            dataIndex: 'name',
            key: 'name',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Quantité Total',
            dataIndex: 'amount',
            key: 'amount',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Quantité en Mouvement',
            dataIndex: 'discharged',
            key: 'discharged',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Quantité en Stock',
            dataIndex: '',
            key: 'stock',
            className: 'border border-gray-500',
            width: 256,
            render: p => <div>{Number(p.amount) - Number(p.discharged)}</div>
        }
    ];

    const GetInventoryFromDb = async () => {

        PerformGetRequest("/api/get-discharged-inventory-state", (res) => {
            console.log(JSON.stringify(res.data));
            setInventory(res.data);
        });

    }

    return (
        <div className='text-gray-100 flex flex-col items-center justify-center'>
            <br />
            <h3 className='text-xl font-bold'>Inventaire Déchargé</h3>
            <br />
            <div className='flex flex-col items-center'>

                {inventory && inventory.customers && inventory.customers.map((c) => (
                    <div className='my-4 flex flex-col items-center justify-center'>
                        {/* <div>{JSON.stringify(c)}</div> */}
                        <div>{c.customer}</div>
                        <Table columns={columns_1} data={c.products} rowKey="_id" />
                    </div>
                ))}

                <div className='mt-4 mb-1 text-xl font-bold'>Inventaire</div>
                {inventory && inventory.products && <Table columns={columns_2} data={inventory.products} rowKey="_id" />}

                {/* <Table columns={columns} data={inventory} rowKey="_id" /> */}
            </div>
            <br />
            <br />
        </div>
    )
}

export default DischargedInventory