import React, { useState, useEffect } from 'react';

const Pricing = () => {

    const CURRENCY_LABEL = "DA";

    const [total, setTotal] = useState([]);
    const [cateringPrices, setCateringPrices] = useState([
        { id: 1, selected: false, label: "Fonctionalité de Base : Restauration", price: 10000 },
        { id: 2, selected: false, label: "Commande par Smartphone ou Tablette", price: 2000 },
        { id: 3, selected: false, label: "Connexion à distance", price: 2000 },
        { id: 4, selected: false, label: "Commande à distance", price: 1000 },
        { id: 5, selected: false, label: "Menu animé", price: 2000 },
        { id: 6, selected: false, label: "Gestion de Stock", price: 2000 },
        { id: 7, selected: false, label: "Gestion des dates de péremption", price: 1000 }
    ]);

    useEffect(() => {
        console.log("PRICES = " + JSON.stringify(cateringPrices));
        const selectedPrices = cateringPrices.filter(item => item.selected).map(item => item.price);
        setTotal(selectedPrices.reduce((acc, curr) => acc + curr, 0));
    }, [cateringPrices]);

    const handleCheckboxChange = (id) => {
        setCateringPrices(prevPrices =>
            prevPrices.map(item =>
                item.id === id ? { ...item, selected: !item.selected } : item
            )
        );
    };

    // const total = selectedPrices.reduce((acc, curr) => acc + curr, 0);

    return (
        <div className='flex flex-col items-center'>
            <h1 className='mb-2 mt-8 text-gray-100 font-bold text-3xl'>Devis</h1>
            <div className='flex flex-col items-start justify-center'>
                {cateringPrices.map((item, index) => (
                    <div key={index}>
                        <input
                            className='mr-2'
                            type="checkbox"
                            value={item.selected}
                            id={item.id}
                            onChange={() => handleCheckboxChange(item.id)}
                        />
                        <label className='text-gray-100' htmlFor={`price-${index}`}>{item.label} - {item.price} <span>{CURRENCY_LABEL}</span></label>
                    </div>
                ))}
            </div>
            <h2 className='text-gray-100 font-bold mt-4 text-5xl'>Total: {total} <span>{CURRENCY_LABEL}</span></h2>
        </div>
    );
}

export default Pricing