import { React, useState, useEffect, useRef } from 'react';
import Popup from 'reactjs-popup';
import { FaTimesCircle } from 'react-icons/fa';
import Table from 'rc-table';
import { GetDateTimeDMYHM } from '../Reaknotron/Libs/RknTimeTools';

const PaymentHistoryPopup = (props) => {

    const columns = [
        {
            title: 'Date',
            dataIndex: 'time',
            key: 'time',
            className: 'border border-gray-500 p-2',
            width: 256,
            render: t => <div>{GetDateTimeDMYHM(t)}</div>
        },
        {
            title: 'Montant',
            dataIndex: 'amount',
            key: 'amount',
            className: 'border border-gray-500 p-2',
            width: 128,
            render: amnt => <div>{amnt} DA</div>
        }
    ];

    const CloseModal = () => {
        props.onClose();
    }

    return (
        <div>
            <Popup
                open={props.isOpen}
                modal
                closeOnDocumentClick
                onClose={() => { CloseModal(); }}
            // onOpen={() => { ref.current.focus(); }}
            >
                <div className="modal bg-gray-900 text-gray-100 p-2">
                    <button className="close" onClick={() => { CloseModal(); }}>
                        <FaTimesCircle />
                    </button>
                    <div className="header">Historique des Paiements</div>
                    <br />
                    <div className="content flex flex-col items-center">
                        <Table className='text-gray-100' columns={columns} data={props.value} rowKey="_id" />
                        <br />
                    </div>
                </div>
            </Popup>
        </div>
    )
}

export default PaymentHistoryPopup