import { React, useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import Switch from 'react-switch';
import { motion } from 'framer-motion';
// import { AwesomeButton } from 'react-awesome-button';
import { Logout } from '../LoginManager';
import RknButton from './RknUI/RknButton';
import { switchLanguage } from '../i18n';

import { useTranslation } from 'react-i18next';
import ReactCountryFlag from 'react-country-flag';

const UserProfileMenu = (props) => {

    const { t } = useTranslation();

    // State
    const [lightMode, setLightMode] = useState(true);
    const [user, setUser] = useState("");
    const [level, setLevel] = useState("");

    // Ref
    const divRef = useRef(null);

    // Navigation
    const navigate = useNavigate();

    useEffect(() => {
        divRef.current.focus();
        console.log("FOCUS EFFECT");

        if (localStorage.getItem('color-theme'))
            if (localStorage.getItem('color-theme') === 'dark')
                setLightMode(false);
            else
                setLightMode(true);
        else
            setLightMode(false);

        if (localStorage.getItem('user')) {
            setUser(localStorage.getItem('user'));
        }

        if (localStorage.getItem('level')) {
            setLevel(localStorage.getItem('level'));
        }

    }, []);

    const handleChange = (checked) => {
        setLightMode(!lightMode);
        SetThemeMode(!checked);
    }

    const SetThemeMode = (ParamIsDark) => {
        document.documentElement.classList.remove('dark');
        if (ParamIsDark) {
            document.documentElement.classList.add('dark');
        }
        localStorage.setItem('color-theme', ParamIsDark ? 'dark' : 'light');
    };

    const handleOnBlur = () => {
        if (props.onBlur)
            props.onBlur();
    }

    const handleLogoutOnPress = () => {
        Logout();
        navigate('/');
    }

    return (
        <motion.div className='fixed z-40 flex flex-col items-center p-2 m-1 text-gray-100 bg-gray-900 border-gray-500 shadow-xl profile-menu top-16 w-60 h-80 border-1 dark:border-gray-100 rounded-xl'
            onBlur={handleOnBlur}
            ref={divRef}
            // onFocus={() => console.log("ON FOCUS EVENT")}
            initial={{ opacity: 0, y: "-25%" }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.15 }}
        >
            <div className='mt-4 text-xs text-gray-500'>{t("profileMenu.login")}</div>
            <div className='text-xl text-gray-100'>{user}</div>
            <div className='mb-6 text-xs text-gray-900 transition duration-1000 cursor-default select-none hover:text-gray-700'>{level}</div>

            <div className='text-gray-500 text-xs mb-1.5'>{t("profileMenu.mode")}</div>
            <Switch checked={lightMode} onChange={handleChange} className='mb-8' />

            <div className='flex flex-row items-center justify-center gap-2 my-2'>
                <ReactCountryFlag
                    onClick={() => switchLanguage("ar")}
                    className="transition duration-150 cursor-pointer active:scale-95"
                    countryCode="SA"
                    svg
                    style={{
                        width: '2em',
                        height: '2em',
                    }}
                    title="SA"
                />

                <ReactCountryFlag
                    onClick={() => switchLanguage("fr")}
                    className="transition duration-150 cursor-pointer active:scale-95"
                    countryCode="FR"
                    svg
                    style={{
                        width: '2em',
                        height: '2em',
                    }}
                    title="FR"
                />

                <ReactCountryFlag
                    onClick={() => switchLanguage("en")}
                    className="transition duration-150 cursor-pointer active:scale-95"
                    countryCode="US"
                    svg
                    style={{
                        width: '2em',
                        height: '2em',
                    }}
                    title="US"
                />
            </div>

            {/* <AwesomeButton onPress={handleLogoutOnPress}>Se Déconnecter</AwesomeButton> */}
            <RknButton label={t("profileMenu.logout")} onPress={handleLogoutOnPress} />
        </motion.div>
    )
}

export default UserProfileMenu