import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import RknSubmitButton from '../components/RknUI/RknSubmitButton';
import { InputFieldStyle, LabelStyle } from '../Styles';
import { PerformGetRequest, PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import AppData from '../App.json';
import privileges from '../privilege-labels.json';

const UserRoleEditor = () => {

    const [name, setName] = useState("");
    const [targetID, setTargetID] = useState(null);
    const [changesAvailable, setChangesAvailable] = useState(false);
    const [checkedItems, setCheckedItems] = useState({});

    const navigate = useNavigate();
    const location = useLocation();

    useEffect(() => {
        const params = new URLSearchParams(location.search);
        const idFromUrl = params.get('id');
        if (idFromUrl) {
            setTargetID(idFromUrl);
            PerformGetRequest("/api/get-user-role?id=" + idFromUrl, (res) => {
                // console.log("Role = " + JSON.stringify(res.data));
                setName(res.data.name);
                
                // Initialize checkedItems with all privileges unchecked
                const initialCheckedItems = {};
                Object.keys(privileges).forEach(key => {
                    initialCheckedItems[key] = false;
                });

                // Mark the role's privileges as checked
                res.data.privileges.forEach(privilege => {
                    // console.log("PRIVIL = " + privilege);
                    // if (initialCheckedItems[privilege]) {
                        initialCheckedItems[privilege] = true;
                    // }
                });
                
                // console.log("ICI = " + JSON.stringify(initialCheckedItems));
                setCheckedItems(initialCheckedItems);
            });
        }
    }, []);

    const handleNameChange = (e) => {
        setName(e.target.value);
        setChangesAvailable(true);
    }
    
    function getSelectedPrivileges(checkedItems) {
        return Object.keys(checkedItems)
            .filter(key => checkedItems[key])
            .map(key => key);
    }

    const handleCheckboxChange = (event) => {
        const { name, checked } = event.target;
        setCheckedItems(prevState => ({
            ...prevState,
            [name]: checked
        }));

        // console.log("Checked Items = " + JSON.stringify(getSelectedPrivileges(checkedItems)));
        setChangesAvailable(true);
    };

    const OnSubmit = async (event) => {

        event.preventDefault();

        let ur = { name: name, privileges: getSelectedPrivileges(checkedItems) };

        if (targetID) {

            ur.id = targetID;
            PerformSecurePostRequest("/api/update-user-role", ur, (res) => {
                if (res.data && res.data.message && res.data.message == "OK") {
                    setChangesAvailable(false);
                }
            });

        } else {

            PerformSecurePostRequest("/api/new-user-role", ur, (res) => {
                if (res.data && res.data.id) {
                    setTargetID(res.data.id);
                    navigate('/role-editor?id=' + res.data.id);
                    setChangesAvailable(false);
                }
            });

        }

    }

    return (
        <div className='flex flex-col items-center justify-center text-gray-900 dark:text-gray-100'>
            <br />
            <h3 className='font-bold text-xl'>Editeur de Role</h3>
            <br />
            <form onSubmit={OnSubmit}>
                <label className={LabelStyle}>Designation</label>
                <input type="text" className={InputFieldStyle} placeholder="Designation..." value={name} onChange={handleNameChange} required />
                <br />
                <br />
                <RknSubmitButton label={targetID ? "Enregistrer" : "Ajouter"} onPress={OnSubmit} disabled={!changesAvailable} />
            </form>
            <br />
            <div className='bg-gray-900 p-2 m-2 rounded-xl flex flex-col items-start justify-center'>
                {Object.entries(privileges).map(([key, value]) => {

                    return (
                        <label key={key} className='font-bold text-lg pb-1'>
                            <input
                                type="checkbox"
                                name={key}
                                onChange={handleCheckboxChange}
                                checked={!!checkedItems[key]}
                                className='mx-1 my-1 w-4 h-4'
                            />
                            {/* Render the label only if the condition is met */}
                            {value.label}
                        </label>
                    );
                })}

            </div>
        </div>
    )
}

export default UserRoleEditor