import { React, useState, useEffect } from 'react';
import useDocumentTitle from '@tanem/use-document-title';
import RknSmartSelector from '../components/RknUI/RknSmartSelector';
import AppData from '../App.json';
import { InputFieldStyle } from '../Styles';
import RknWilayaCommuneSelector from '../components/RknUI/RknWilayaCommuneSelector';
import RknBankSelector from '../components/RknUI/RknBankSelector';
import RknStatusSelector from '../components/RknUI/RknStatusSelector';
import RknNumericInput from '../components/RknUI/RknNumericInput';
import RknButton from '../components/RknUI/RknButton';
import { PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';

const DDOEditor = () => {

    useDocumentTitle("Ordre de Virement");

    const [targetType, setTargetType] = useState("OTHER");
    const [customer, setCustomer] = useState(null);
    const [provider, setProvider] = useState(null);
    const [otherDesignation, setOtherDesignation] = useState("");
    const [month, setMonth] = useState("1");
    const [year, setYear] = useState(2024);
    const [wilaya, setWilaya] = useState("");
    const [commune, setCommune] = useState("");
    const [bank, setBank] = useState("");
    const [accountNumber, setAccountNumber] = useState("");
    const [amount, setAmount] = useState(0);
    const [status, setStatus] = useState("PENDING");
    const [changesAvailable, setChangesAvailable] = useState(false);

    const handleTargetTypeChange = (e) => {
        setTargetType(e.target.value);
        setChangesAvailable(true);
    }

    const handleCustomerChange = (ParamItem) => {
        setCustomer(ParamItem._id);
        setChangesAvailable(true);
    }

    const handleProviderChange = (ParamItem) => {
        setProvider(ParamItem._id);
        setChangesAvailable(true);
    }

    const handleOtherDesignationChange = (e) => {
        setOtherDesignation(e.target.value);
        setChangesAvailable(true);
    }

    const handleMonthChange = (e) => {
        setMonth(e.target.value);
        setChangesAvailable(true);
    }

    const handleYearChange = (e) => {
        setYear(e.target.value);
        setChangesAvailable(true);
    }

    const handleStatusChange = (ParamStatus) => {
        setStatus(ParamStatus);
        console.log("STATUS = " + ParamStatus);
        setChangesAvailable(true);
    }

    const handleBankChange = (ParamValue) => {
        console.log("V = " + JSON.stringify(ParamValue));
        setBank(ParamValue.name);
        setChangesAvailable(true);
    }

    const handleWilayaAndCommuneChange = (ParamValue) => {
        console.log("V = " + JSON.stringify(ParamValue));
        setWilaya(ParamValue.wilaya.name);
        setCommune(ParamValue.commune.name);
        setChangesAvailable(true);
    }

    const handleAmountChange = (ParamValue) => {
        setAmount(ParamValue);
        setChangesAvailable(true);
    }

    const handleAccountNumberChange = (e) => {
        setAccountNumber(e.target.value);
        setChangesAvailable(true);
    }

    const handleSaveOnClick = () => {
        let ddoToPost = {
            month: month,
            year: year,
            targetType: targetType,
            targetID: otherDesignation,
            targetWilaya: wilaya,
            targetCommune: commune,
            bankName: bank,
            accountNumber: accountNumber,
            baseAmount: amount,
            finalAmount: amount,
            status: status
        }

        PerformSecurePostRequest("/api/new-ddo", ddoToPost, (res) => {
            setChangesAvailable(false);
        });
    }

    return (
        <div className='flex flex-col items-center text-gray-900 dark:text-white'>
            <h3 className='mt-4 mb-2 text-xl font-bold'>Editeur d'Ordre de Virement</h3>

            <div className='flex flex-row items-center justify-start my-2'>
                <label className="text-sm mr-2">Cible : </label>
                <select name="state" className='bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-0.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 mt-0.5 h-9 w-44'
                    value={targetType}
                    onChange={handleTargetTypeChange}
                >
                    {AppData.CUSTOMER_MANAGEMENT_FLAG && <option value="CUSTOMER">👑 Client</option>}
                    {AppData.STORAGE_MANAGEMENT_FLAG && <option value="PROVIDER">🚛 Fournisseur</option>}
                    {AppData.EMPLOYEE_MANAGEMENT_FLAG && <option value="EMPLOYEE">👷‍♀️ Employé</option>}
                    <option value="OTHER">❓ Autre</option>
                </select>
            </div>

            {targetType === "CUSTOMER" &&
                <div className='flex flex-row items-center justify-start my-2'>
                    <label className='text-sm mr-2'>Client : </label>
                    <RknSmartSelector url={"/api/get-customer-list"} idKey="_id" value={customer} labelKey="name" reaktorContext="CATEGORY" onChange={handleCustomerChange} quickAddRoute="/new-customer" />
                </div>
            }

            {targetType === "PROVIDER" &&
                <div className='flex flex-row items-center justify-start my-2'>
                    <label className='text-sm mr-2'>Fournisseur : </label>
                    <RknSmartSelector url={"/api/get-provider-list"} idKey="_id" value={provider} labelKey="name" reaktorContext="PROVIDER" onChange={handleProviderChange} quickAddRoute="/new-provider" />
                </div>
            }

            {targetType === "OTHER" &&
                <div className='flex flex-row items-center justify-start my-2'>
                    <label className='text-sm mr-2'>Designation : </label>
                    <input type='text' value={otherDesignation} onChange={handleOtherDesignationChange} className={InputFieldStyle} />
                </div>
            }

            <div className='flex flex-row items-center justify-start my-2'>
                <label className='text-sm mr-2'>Moi : </label>
                <select
                    name="month"
                    className='bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-0.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 mt-0.5 h-9 w-44'
                    value={month}
                    onChange={handleMonthChange}
                >
                    <option value="1">Janvier</option>
                    <option value="2">Février</option>
                    <option value="3">Mars</option>
                    <option value="4">Avril</option>
                    <option value="5">Mai</option>
                    <option value="6">Juin</option>
                    <option value="7">Juillet</option>
                    <option value="8">Août</option>
                    <option value="9">Septembre</option>
                    <option value="10">Octobre</option>
                    <option value="11">Novembre</option>
                    <option value="12">Décembre</option>
                </select>
                <span className='mr-4' />
                <label className='text-sm mr-2'>Année : </label>
                <input type='number' step={1} value={year} onChange={handleYearChange} className={InputFieldStyle} />
            </div>

            <RknWilayaCommuneSelector onChange={handleWilayaAndCommuneChange} />
            <span className='my-2' />
            <RknBankSelector onChange={handleBankChange} />
            <span className='my-2' />
            <input type='text' value={accountNumber} onChange={handleAccountNumberChange} className={InputFieldStyle} placeholder='RIB...' />
            <span className='my-2' />
            <RknNumericInput value={amount} onChange={handleAmountChange} label="Montant" placeholder='Montant...' />
            <span className='my-2' />
            <RknStatusSelector value={status} onChange={handleStatusChange} />
            <span className='my-2' />
            {changesAvailable && <RknButton label="Enregistrer" onPress={handleSaveOnClick} />}

        </div>


    )
}

export default DDOEditor