import { React, useState, useEffect, useRef } from 'react';
import Popup from 'reactjs-popup';
import { FaTimesCircle } from 'react-icons/fa';
import RknSubmitButton from './RknSubmitButton';

const RknInputDialog = (props) => { // TODO : Add regex prop

    const inputFieldStyle = 'bg-gray-50 border border-gray-300 text-gray-900 text-lg font-bold rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 mt-2';

    const ref = useRef(null);

    const [userInput, setUserInput] = useState("");

    const handleOnOpen = () => {
        if (props.defaultValue) {
            setUserInput(props.defaultValue);
            // ref.current.focus();
        }

        setTimeout(() => {
            ref.current.focus();
        }, 150);
    }

    const CloseModal = () => {
        if (props.onClose)
            props.onClose();
    }

    const handleUserInputChange = (event) => {
        setUserInput(event.target.value);
    }

    const handleConfirmOnClick = (event) => {

        event.preventDefault();

        if (props.onConfirm)
            props.onConfirm(userInput);
    }

    return (
        <div>
            <Popup
                open={props.isOpen}
                modal
                closeOnDocumentClick
                onClose={() => { CloseModal(); }}
                onOpen={handleOnOpen}
            >
                <div className="modal bg-gray-900 text-gray-100 p-2">
                    <button className="close" onClick={() => { CloseModal(); }}>
                        <FaTimesCircle />
                    </button>
                    <div className="header">{props.label ? props.label : "Saisissez votre texte"}</div>
                    <form onSubmit={handleConfirmOnClick} className="content flex flex-col items-center">
                        <br />
                        <input ref={ref} type="text" name='userInput' placeholder='...' value={userInput} className={inputFieldStyle} onChange={handleUserInputChange} autocomplete="off" />
                        <br />
                        <RknSubmitButton label="Valider" onClick={handleConfirmOnClick} />
                    </form>
                </div>
            </Popup>
        </div>
    )
}

export default RknInputDialog