import React from 'react'

const RknContainer = (props) => {
    return (
        <div>
            <div className='bg-gray-800 rounded-t-lg p-2 mx-4 w-full text-xl font-bold text-gray-100'>
                {/* <FaPen className='inline mr-2 pb-1' /> */}
                {props.title || "Title"}
            </div>
            <div className='bg-gray-900 bg-opacity-50 rounded-b-xl p-2 mx-4 w-full mb-4'>
                <div className={props.className}>
                    {props.children}
                </div>
            </div>
        </div>
    )
}

export default RknContainer