import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import { FaPlus } from 'react-icons/fa';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import RknButton from '../components/RknUI/RknButton';
import { Link } from 'react-router-dom';

const ProductPackManager = () => {

    useEffect(() => {

        GetPackList();

    }, []);

    const [packs, setPacks] = useState(null);

    const columns = [
        {
            title: 'Designation',
            dataIndex: 'name',
            key: 'name',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Produits',
            dataIndex: 'products',
            key: 'products',
            className: 'border border-gray-500',
            width: 256,
            render: prods => <div>{prods ? Object.keys(prods).length : "0"}</div>
        }
    ];

    const GetPackList = async () => {

        PerformGetRequest("/api/product-packs", (res) => setPacks(res.data));
    }

    return (
        <div className='text-gray-100 flex flex-col items-center justify-center'>
            <br />
            <h3 className='text-xl font-bold'>Liste des Packs</h3>
            <br />
            <Link to={'/product-pack-editor'}><RknButton label="Ajouter un Pack" before={<FaPlus />} className='w-48' /></Link>
            <br />
            <br />
            <div className='flex flex-col items-center'>
                <Table columns={columns} data={packs} rowKey="_id" />
            </div>
            <br />
            <br />
        </div>
    )
}

export default ProductPackManager