import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { PerformGetRequest, PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import { GetBackEndUrl } from '../const';
import { FaArrowLeft, FaArrowRight, FaPalette, FaSort, FaTimesCircle } from 'react-icons/fa';
import RknButton from '../components/RknUI/RknButton';
import RknInputDialog from '../components/RknUI/RknInputDialog';
import RknColorDialog from '../components/RknUI/RknColorDialog';
import RknConfirmationPopup from '../components/RknUI/RknConfirmationPopup';
import GenericMessagePopup from '../components/GenericMessagePopup';
import RknContainer from '../components/RknUI/RknContainer';
import RknNumericInput from '../components/RknUI/RknNumericInput';
import CstMap from '../components/CstMap';

const TableManager = () => {

    const [cstList, setCstList] = useState();
    const [selectedCst, setSelectedCst] = useState(null);
    const [selectedCstName, setSelectedCstName] = useState("");
    const [selectedCstForColorChange, setSelectedCstForColorChange] = useState(null);
    const [selectedCstForOrderChange, setSelectedCstForOrderChange] = useState(null);
    const [newTableDialogOpen, setNewTableDialogOpen] = useState(false);
    const [tableToDelete, setTableToDelete] = useState(null);
    const [width, setWidth] = useState(0);
    const [length, setLength] = useState(0);
    const [onError, setOnError] = useState(false);
    const [errorMessage, setErrorMessage] = useState("");

    useEffect(() => {

        PerformGetRequest("/api/get-customer-sitting-tables-list", (ParamResult) => {
            // console.log(JSON.stringify(ParamResult.data));
            setCstList(ParamResult.data);
        });

        PerformGetRequest("/api/get-self-establishment", (ParamResult) => {
            // console.log("EST = " + JSON.stringify(ParamResult.data));
            setWidth(ParamResult.data.width);
            setLength(ParamResult.data.length);
        });
    }, []);

    const handleConfirmNameChangeOnClick = (ParamUserInput) => {
        UpdateCstInDb(selectedCst, ParamUserInput);
        setSelectedCst(null);
    }

    const handleConfirmColorChangeOnClick = (ParamUserInput) => {
        UpdateCstColorInDb(selectedCstForColorChange, ParamUserInput);
        setSelectedCstForColorChange(null);
    }

    const handleConfirmOrderChangeOnClick = (ParamUserInput) => {
        UpdateCstOrderInDb(selectedCstForOrderChange, ParamUserInput);
        setSelectedCstForOrderChange(null);
    }

    const UpdateCstInDb = async (ParamID, ParamName) => {

        let cstToPost = {
            id: ParamID,
            name: ParamName
        };

        PerformSecurePostRequest("/api/update-cst", cstToPost, (res) => {
            PerformGetRequest("/api/get-customer-sitting-tables-list", (ParamResult) => { setCstList(ParamResult.data); });
        });
    }

    const UpdateCstColorInDb = async (ParamID, ParamColor) => {

        let cstToPost = {
            id: ParamID,
            color: ParamColor
        };

        PerformSecurePostRequest("/api/update-cst", cstToPost, (res) => {
            PerformGetRequest("/api/get-customer-sitting-tables-list", (ParamResult) => { setCstList(ParamResult.data); });
        });

    }

    const UpdateCstOrderInDb = async (ParamID, ParamOrder) => {

        let cstToPost = {
            id: ParamID,
            order: ParamOrder
        };

        PerformSecurePostRequest("/api/update-cst", cstToPost, (res) => {
            PerformGetRequest("/api/get-customer-sitting-tables-list", (ParamResult) => { setCstList(ParamResult.data); });
        });

    }

    const newTableOnConfirm = async (ParamName) => {

        setNewTableDialogOpen(false);

        let cstToPost = {
            name: ParamName
        };

        PerformSecurePostRequest("/api/new-cst", cstToPost, (res) => {
            PerformGetRequest("/api/get-customer-sitting-tables-list", (ParamResult) => { setCstList(ParamResult.data); });
        });

    }

    const DeleteCSTFromDB = (ParamCstID) => {

        PerformSecurePostRequest("/api/delete-cst", { id: ParamCstID }, (res) => {
            setTableToDelete(null);

            if (res.data == "OK") {
                PerformGetRequest("/api/get-customer-sitting-tables-list", (ParamResult) => { setCstList(ParamResult.data); });
            } else {
                setErrorMessage("Impossible de supprimer une table occupée.");
                setOnError(true);
            }
        });
    }

    const handleFreeFinalizedCsts = () => {
        PerformGetRequest("/api/free-finalized-csts", (res) => {
            console.log("RES = " + JSON.stringify(res.data));
        });
    }

    const handleSaveWidthLengthOnClick = () => {
        const toPost = { width: width, length: length }

        PerformSecurePostRequest("/api/update-self-width-length", toPost, (res) => {
            console.log("RES = " + res.data);
        });
    }

    return (
        <div className='mx-8'>
            <br />
            <h3 className='text-3xl font-bold text-gray-100'>Gestion des Tables</h3>
            <br />
            {/* <div className='text-gray-100 font-bold text-xl flex flex-wrap items-center justify-center'> */}
            <div className='text-gray-100 font-bold text-xl grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 place-items-center mb-8'>
                {cstList && cstList.map((cst) => {
                    return (
                        <div key={cst._id} className='w-64 h-32 m-1 p-1 rounded-xl border-2 border-gray-100 grid grid-cols-2 cursor-pointer hover:bg-gray-600 transition duration-300 place-items-center' style={{ backgroundColor: cst.color ? cst.color : '#555555' }} >

                            {/* Name and Shape */}
                            <div className='h-28 w-28 m-0.5 p-1 text-sm rounded-lg bg-gray-800 bg-opacity-50 hover:bg-gray-900 transition duration-300 flex flex-col items-center justify-center' onClick={() => { setSelectedCst(cst._id); setSelectedCstName(cst.name); }}>Table {cst.name}</div>

                            {/* Controls */}
                            <div className='flex flex-col items-center justify-center h-28 w-36 text-sm'>

                                <div className='flex flex-row items-center justify-center h-10 w-28 m-0.5 p-1 rounded-lg bg-gray-800 bg-opacity-50 hover:bg-gray-900 transition duration-300' onClick={() => { setSelectedCstForColorChange(cst._id); }}>
                                    <FaPalette className='mr-2' size={20} />
                                    Colorier
                                </div>

                                <div className='flex flex-row items-center justify-center h-10 w-28 m-0.5 p-1 rounded-lg bg-gray-800 bg-opacity-50 hover:bg-gray-900 transition duration-300' onClick={() => { setTableToDelete(cst._id); }}>
                                    <FaTimesCircle className='mr-2' size={20} />
                                    Supprimer
                                </div>

                                <div className='flex flex-row items-center justify-center h-10 w-28 m-0.5 p-1 rounded-lg bg-gray-800 bg-opacity-50 hover:bg-gray-900 transition duration-300' onClick={() => { setSelectedCstForOrderChange(cst._id); }}>
                                    <FaSort className='mr-2' size={20} />
                                    Ordre ({cst.order})
                                </div>

                            </div>
                        </div>
                    )
                })}
                <div key={"+"} className='w-32 h-32 bg-gray-900 text-3xl font-bold m-1 p-1 rounded-xl border-2 border-gray-100 flex flex-col items-center justify-center cursor-pointer hover:bg-gray-600 transition duration-300' onClick={() => setNewTableDialogOpen(true)}>
                    +
                </div>
            </div>

            <RknContainer title="Outils">
                <div className='flex flex-col items-center justify-center'>
                    <RknButton className="w-64 my-2" label="Libérer les tables vides" onPress={handleFreeFinalizedCsts} />
                </div>
            </RknContainer>

            <RknContainer title="Emplacements des Tables">
                <div className='flex flex-row items-center justify-center mt-4'>
                    <label className='text-gray-100 text-sm font-bold mr-2'>Largeur : </label>
                    <RknNumericInput value={width} placeholder="Largeur..." onChange={setWidth} />
                    <span className='mx-4' />
                    <label className='text-gray-100 text-sm font-bold mr-2'>Hauteur : </label>
                    <RknNumericInput value={length} placeholder="Height..." onChange={setLength} />
                </div>
                <div className='flex flex-col items-center justify-center mt-4'>
                    <RknButton label="Enregistrer" className="w-64 mt-2 mb-4" onPress={handleSaveWidthLengthOnClick} />
                    <CstMap width={width} length={length} editMode />
                    <span className='my-4' />
                </div>
            </RknContainer>

            <RknInputDialog
                isOpen={selectedCst ? true : false}
                onClose={() => setSelectedCst(null)}
                defaultValue={selectedCstName}
                onConfirm={handleConfirmNameChangeOnClick}
            />

            <RknColorDialog
                isOpen={selectedCstForColorChange ? true : false}
                onClose={() => setSelectedCstForColorChange(null)}
                defaultValue={selectedCstName}
                onConfirm={handleConfirmColorChangeOnClick}
            />

            <RknInputDialog
                isOpen={newTableDialogOpen}
                onClose={() => setNewTableDialogOpen(false)}
                onConfirm={newTableOnConfirm}
            />

            <RknInputDialog
                isOpen={selectedCstForOrderChange ? true : false}
                onClose={() => setSelectedCstForOrderChange(null)}
                defaultValue={selectedCstName}
                onConfirm={handleConfirmOrderChangeOnClick}
            />

            {tableToDelete && <RknConfirmationPopup
                danger={true}
                onConfirm={() => { DeleteCSTFromDB(tableToDelete); }}
                onCancel={() => { setTableToDelete(null); }}
            />}

            <GenericMessagePopup isOpen={onError} onClose={() => setOnError(false)} message={errorMessage} closeButton={true} sad={true} />
        </div >
    )
}

export default TableManager