const IsLoggedIn = () => {
    let result = false;

    const storedValue = localStorage.getItem("isLoggedIn");

    if (storedValue && storedValue == "true")
        result = true;

    return result;
}

const Login = (ParamToken, ParamUsername, ParamPrivileges, ParamForensics) => {
    localStorage.setItem("token", ParamToken);
    localStorage.setItem("user", ParamUsername);
    localStorage.setItem("privileges", ParamPrivileges);
    console.log("F = " + ParamForensics);
    localStorage.setItem("forensics", ParamForensics);
    localStorage.setItem("isLoggedIn", true);
    localStorage.setItem("QUEUE_MODULES_TO_OPEN_AFTER_LOGIN", true); // Indicates that the user just logged in and we must open some tabs, like the sales point and the products list, saving them some few clicks.
}

const Logout = () => {
    localStorage.setItem("token", null);
    localStorage.setItem("level", null);
    localStorage.setItem("isLoggedIn", false);
    localStorage.setItem("forensics", false);
}

const CheckPrivilege = (ParamPrivilege) => {

    // console.log("PARAM = " + JSON.stringify(ParamPrivilege));

    let privils = localStorage.getItem("privileges");
    // console.log("STORED = " + privils);
    // console.log("TYPE = " + typeof (privils));

    if (!privils) {
        // console.log("NO PRIVILS");
        return false;
    }

    if (typeof (privils) === "string" && privils === "ALL") {
        // console.log("Privilege : All (String)");
        return true;
    } else if (typeof (privils) === "string") {
        const privilegesArray = privils.split(','); // Store privileges as array on login / Can you store an array object in local storage ?

        // console.log("ARRAY = " + JSON.stringify(privilegesArray));

        if (Array.isArray(privilegesArray) && privilegesArray.includes("ALL")) {
            // console.log("Privilege : All (Array Element)");
            // console.log("ALL");
            return true;
        } else if (Array.isArray(privilegesArray) && privils.includes(ParamPrivilege)) {
            // console.log("PARAM PRIVIL FOUND");
            return true;
        }
    }

    return false;
}

const InForensicsMode = () => {
    let result = false;

    const storedValue = localStorage.getItem("forensics");

    if (storedValue && storedValue == "true")
        result = true;

    return result;
}

module.exports = { IsLoggedIn, Login, Logout, CheckPrivilege, InForensicsMode };