import React from "react";
import AppData from "../App.json";
import { GetIfReducedPerformance } from "../const";
import { Link } from "react-router-dom";
import { motion } from "framer-motion";

const MainMenuCard = (props) => {
  const color = AppData.PRIMARY_COLOR;
  // console.log(color);

  const reducedPerfValue = GetIfReducedPerformance();

  var NO_BLUR = false;
  if (reducedPerfValue == "true") NO_BLUR = true;

  function randomFloatBetween(min, max) {
    return Math.random() * (max - min) + min;
  }

  return (
    <motion.div
      // className={'text-xl font-bold text-yellow-100 w-24 h-32 md:w-48 md:h-64 rounded-3xl backdrop-blur border-2 border-yellow-700 shadow-3xl bg-yellow-500 bg-opacity-0  hover:bg-opacity-10 hover:border-yellow-500 m-2'}
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{
        duration: randomFloatBetween(0.1, 0.9),
        delay: randomFloatBetween(0.1, 0.4),
      }}
      className={`
      mb:flex mb:items-center mb:h-28 mb:w-full
      text-xl font-bold text-${color}-100 w-48 h-64 rounded-3xl border-${color}-700 shadow-3xl shadow-[0_15px_16px_-5px_rgba(0,0,0,0.45)] transition duration-300 hover:-translate-y-1 hover:shadow-[0_15px_16px_-5px_rgba(0,0,0,0.9)]
      hover:border-${color}-500 m-2
          ${NO_BLUR
          ? "  border-2  bg-gray-800 bg-opacity-75  hover:bg-opacity-95 "
          : (props.forensics ? "backdrop-blur border-2 bg-gradient-to-b from-red-700 to-indigo-700 bg-opacity-60 hover:bg-opacity-30" : "backdrop-blur border-2 bg-black bg-opacity-40 hover:bg-opacity-10")
        } `}
      onClick={props.onClick}
    >
      {/*  text-xl font-bold text-${color}-100 w-48 h-64 rounded-3xl  border-${color}-700 shadow-3xl shadow-[0_15px_16px_-5px_rgba(0,0,0,0.45)] transition duration-300 hover:-translate-y-1 hover:shadow-[0_15px_16px_-5px_rgba(0,0,0,0.9)]
 hover:border-${color}-500 m-2
*/}
      <Link
        to={props.href}
        className="mb:flex-row mb:gap-4 mb:justify-between mb:px-6 flex flex-col items-center w-full h-full justify-center"
      >
        {/* Before */}
        <div className="inline mt-2">
          {props.before && props.before}
        </div>

        {/* Label */}
        <div className="mt-0.5 md:mt-1 p-0.5 md:p-2 text-sm md:text-xl mb:text-sm">
          {props.label ? props.label : "? Label ?"}
        </div>
      </Link>
    </motion.div>
  );
};

export default MainMenuCard;