import { React, useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { FaTimesCircle, FaCheckCircle } from 'react-icons/fa';
import hotkeys from 'hotkeys-js';

import { useTranslation } from 'react-i18next';

const SalesPointMiscProductAdder = (props) => {

    const { t } = useTranslation();

    const miscProductNameRef = useRef(null);
    const miscProductPriceRef = useRef(null);

    useEffect(() => {
        setTimeout(() => { miscProductNameRef.current.focus(); }, 400);

        if (props.askForPrice) {

        } else {
            setMiscProductPriceEdited(true);
        }

    }, []);

    useEffect(() => {

        hotkeys.filter = function (event) {
            var tagName = (event.target || event.srcElement).tagName;
            hotkeys.setScope(/^(INPUT|TEXTAREA|SELECT)$/.test(tagName) ? 'input' : 'other');
            return true;
        }

        hotkeys('escape', event => {
            event.preventDefault();
            TriggerPropsOnCancel();
        });

        return () => {
            hotkeys.unbind('escape');
        }

    }, []);

    const [miscProductName, setMiscProductName] = useState("");
    const [miscProductNameEdited, setMiscProductNameEdited] = useState(false);
    const [miscProductPrice, setMiscProductPrice] = useState(0);
    const [miscProductPriceEdited, setMiscProductPriceEdited] = useState(false);

    const TriggerPropsOnConfirm = () => {
        if (props.onConfirm && miscProductNameEdited && miscProductPriceEdited)
            props.onConfirm(miscProductName, miscProductPrice);
    }

    const OnSubmit = (e) => {
        e.preventDefault();
        TriggerPropsOnConfirm();
    }

    const TriggerPropsOnCancel = () => {
        if (props.onCancel)
            props.onCancel();
    }

    const handleMiscProductNameChange = (e) => {

        var v = e.target.value;

        if (props.autoComplete) {

            var jump = false;

            if (v === "t" || v === "T") {
                jump = true;
                v = "Total";
            }
            else if (v === "f" || v === "F") {
                jump = true;
                v = "Fruit(s)";
            }
            else if (v === "d" || v === "D") {
                jump = true;
                v = "Divers";
            }

            if (jump) {
                miscProductPriceRef.current.focus();
                miscProductPriceRef.current.select();
            }

        }

        setMiscProductName(v);
        setMiscProductNameEdited(true);
    }

    return (
        <motion.div
            className='fixed top-0 left-0 right-0 z-10 flex flex-col items-center justify-center w-screen h-screen bg-black bg-opacity-60 backdrop-blur-lg'
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.3 }}
        >
            <motion.div
                className='flex flex-col items-center justify-center p-8 m-auto bg-gray-900 border-4 border-gray-500 rounded-3xl'
                initial={{ opacity: 0, y: "-50%" }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.3 }}
            >
                <h3 className='mb-4 text-xl font-bold text-gray-100'>{t("pos.toolbar.miscellaneous.addProduct")}</h3>

                <form onSubmit={OnSubmit} className='flex flex-col items-center justify-center'>
                    <input type="text" value={miscProductName} ref={miscProductNameRef} onChange={handleMiscProductNameChange} className={'bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 mb-1 w-64 mx-auto md:w-64'} placeholder={t("pos.toolbar.miscellaneous.productName")} />
                    {props.askForPrice && <input type="number" min={0} value={miscProductPrice} ref={miscProductPriceRef} onChange={(e) => { setMiscProductPrice(e.target.value); setMiscProductPriceEdited(true); }} className={'bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 mb-1 w-64 mx-auto md:w-64'} placeholder='Prix du Produit...' />}
                    <div className='flex flex-row items-center justify-center mt-4'>
                        <button type='submit' className="px-4 py-2 font-bold text-white bg-blue-500 border-b-4 border-blue-700 rounded hover:bg-blue-400 hover:border-blue-500"><FaCheckCircle className='inline mb-1' size={20} /> {t("button.confirm")}</button>
                        <span className='mx-2'></span>
                        <button type='button' onClick={TriggerPropsOnCancel} className="px-4 py-2 font-bold text-white bg-blue-500 border-b-4 border-blue-700 rounded hover:bg-blue-400 hover:border-blue-500"><FaTimesCircle className='inline mb-1' size={20} /> {t("button.cancel")}</button>
                    </div>
                </form>
                <br />

            </motion.div>
        </motion.div>
    )
}

export default SalesPointMiscProductAdder