import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import Table from 'rc-table';
import { FaPlus, FaEye, FaCheckCircle, FaHourglass } from 'react-icons/fa';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import RknButton from '../components/RknUI/RknButton';
import { GetBaseUrl } from '../Reaknotron/Libs/RknRouterUtils';
import RknIconButton from '../components/RknUI/RknIconButton';

const InventoryManager = () => {

    useEffect(() => {

        GetInventorySHeetsFromDb();

    }, []);

    const [invList, setInvList] = useState();

    const columns = [
        {
            title: 'Etat',
            dataIndex: 'finalized',
            key: 'finalized',
            className: 'border border-gray-500',
            width: 32,
            render: f => f ? <FaCheckCircle size={16} className='text-green-500 ml-1' /> : <FaHourglass size={16} className='text-neutral-700 ml-1' />
        },
        {
            title: 'Opérations',
            dataIndex: '',
            key: 'operations',
            width: 128,
            className: 'border border-gray-500',
            render: inv => <Link to={"/inventory-sheet-editor?id=" + inv._id}>
                <RknIconButton icon={<FaEye />} />
            </Link>
            // render: ds => JSON.stringify(ds)
        },
        {
            title: 'Date',
            dataIndex: 'time',
            key: 'time',
            className: 'border border-gray-500',
            width: 256,
            render: d => <p className='inline text-sm'>{(new Date(d)).toLocaleDateString('fr-FR', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' })}</p>
        },
        {
            title: 'Produit(s)',
            dataIndex: 'products',
            key: 'products',
            className: 'border border-gray-500',
            width: 256,
            render: p => <div>{p ? p.length : "0"}</div>
        }
    ];

    const GetInventorySHeetsFromDb = async () => {

        PerformGetRequest("/api/get-inventory-sheet-list", (res) => {
            // console.log(JSON.stringify(res.data));
            setInvList(res.data);
        });

    }

    return (
        <div className='text-gray-100 flex flex-col items-center justify-center'>
            <br />
            <h3 className='text-xl font-bold'>Liste des Fiche(s) d'Inventaire</h3>
            <br />
            {/* <AwesomeButton before={<FaPlus />}><a href='/provider-editor'>Ajouter Un Fournisseur</a></AwesomeButton> */}
            <RknButton className="w-80" before={<FaPlus />} label={<Link className='text-sm' to='/inventory-sheet-editor'>Créer une fiche d'Inventaire</Link>} onPress={null} />
            <br />
            <br />
            <div className='flex flex-col items-center'>
                <Table
                    columns={columns}
                    data={invList}
                    rowKey="_id"
                />
            </div>
            <br />
            <br />
        </div>
    )
}

export default InventoryManager