import { React, useState, useEffect, useRef } from 'react';
import axios from 'axios';
import DeviceIconList from './DeviceIconList';
import DeviceStateSelector from './DeviceStateSelector';
import { AwesomeButtonProgress } from 'react-awesome-button';
import { FaCheckCircle, FaTimesCircle } from 'react-icons/fa';
import Popup from 'reactjs-popup';
import { GetBackEndUrl } from '../const';
import ProblemListValidator from './ProblemListValidator';
import ReactHotkeys from 'react-hot-keys';
import { motion } from "framer-motion";
import { PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import RknButton from '../components/RknUI/RknButton';
import { PulseLoader } from 'react-spinners';

const RepairOrderValidationPopupV2 = (props) => {

    const inputFieldStyle = 'bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 mt-2';

    const [locked, setLocked] = useState(true);
    const [roState, setRoState] = useState("DONE");
    const [note, setNote] = useState("");
    const [total, setTotal] = useState("");
    const [payment, setPayment] = useState("");
    const [paymentMessage, setPaymentMessage] = useState("");
    const [items, setItems] = useState(null);
    const [busy, setBusy] = useState(false);

    const paymentFieldRef = useRef();

    useEffect(() => {
        // console.log("VALIDATOR EFFECT");
        if (props && props.value && props.value.totalPrice) {
            setTotal(props.value.totalPrice);
            paymentFieldRef.current.focus();
        }

        updatePaymentMessage(props.value.totalPrice, 0);
    }, [props.value]);

    const handleLockedChange = () => {
        setLocked(!locked);
    };

    const CloseModal = () => {
        if (props.onClose)
            props.onClose();
    }

    const ValidateRepairOrderInDB = async (ParamROID, ParamState, ParamPaiement, ParamTotalPrice, ParamLock, ParamNote, ParamItems) => {

        if (total >= 0 && payment >= 0 && total !== "" && payment !== "") {

            const validationToPost = { roid: ParamROID, state: ParamState, fulfilledPaiement: ParamPaiement, totalPrice: ParamTotalPrice, locked: ParamLock, note: ParamNote, items: ParamItems };
            setBusy(true);
            PerformSecurePostRequest("/api/validate-repair-order", validationToPost, (res) => {
                setBusy(false);

                if (res.data == "OK") {
                    CloseModal();
                }
            });

            try {

                // let validationToPost = { roid: ParamROID, state: ParamState, fulfilledPaiement: ParamPaiement, totalPrice: ParamTotalPrice, locked: ParamLock, note: ParamNote, items: ParamItems };
                // let url = GetBackEndUrl() + "/api/validate-repair-order";
                // let res = await axios.post(url, validationToPost);

            } catch (error) {
                console.log("ERROR : " + error);
            }
        }

    }

    const handleRoStateOnChange = (ParamValue) => {
        setRoState(ParamValue);
    }

    const handleTotalPriceChange = (event) => {

        if (event.target.value === '') {
            setTotal("");
            return;
        }

        const regex = /^[0-9\b]+$/;
        if (event.target.value === '' || regex.test(event.target.value)) {
            setTotal(Number(event.target.value));
            updatePaymentMessage(Number(event.target.value), payment);
        }
    }

    function handlePaymentChange(event) {

        console.log("P = " + event.target.value);

        if (event.target.value === '') {
            setPayment("");
            return;
        }

        const regex = /^[0-9\b]+$/;
        if (event.target.value === '' || regex.test(event.target.value)) {
            setPayment(Number(event.target.value));
            updatePaymentMessage(total, Number(event.target.value));
        }

    }

    // const handlePaymentChange = (event) => {
    //     setPayment(Number(event.target.value));
    // }

    const GetTotalPrice = (ParamRepairOrder) => {

        if (!ParamRepairOrder || !ParamRepairOrder.items)
            return 0;

        let total = Number(0);
        ParamRepairOrder.items.forEach(i => {

            if (i.problems) {
                i.problems.forEach(p => {
                    total += Number(p.price);
                });
            }

        });

        return total;
    }

    const handleProblemListValidatorOnChange = (ParamItemKey, ParamValue) => {

        let target = props.value.items.filter(i => i.key == ParamItemKey);
        target[0].problems = ParamValue;

        let others = props.value.items.filter((i) => {
            return i.key !== ParamItemKey;
        });

        others.push(target);
        setItems(others);
    }

    const updatePaymentMessage = (ParamTotal, ParamPayed) => {

        const t = Number(ParamTotal);
        const p = Number(ParamPayed);

        if (p > t) {
            setPaymentMessage("⚠️ Le montant payer ne peut être supérieur au montant total.");
        } else if (p >= 0 && t >= 0) {
            let remaining = Number(ParamTotal) - Number(ParamPayed);
            setPaymentMessage("Reste à payer : " + remaining + " DA");
        } else {
            setPaymentMessage("Reste à payer : ❓❓❓");
        }

    }

    const handleValidateOnClick = () => {
        ValidateRepairOrderInDB(props.value.roid, roState, payment, total, locked, note, items);
    }

    return (
        <div className='bg-black bg-opacity-60 backdrop-blur fixed top-0 w-screen h-screen z-10'>

            <motion.div className='fixed top-20 bottom-4 right-4 left-4 flex flex-col items-center justify-center'
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ duration: 0.25 }}
            >

                <div className='bg-gray-100 border-4 border-gray-700 border-b-0 rounded-t-xl h-8 flex flex-row items-center justify-center text-gray-900 text-sm font-bold'
                    style={{ width: "100%" }}
                >
                    <div className='flex-1'>Validation de l'Ordre de Réparation</div>
                    <div><FaTimesCircle size={20} className='mr-1 cursor-pointer hover:text-gray-700' onClick={CloseModal} />
                        <ReactHotkeys
                            keyName="Escape"
                            onKeyDown={CloseModal}
                            filter={(event) => {
                                return true;
                            }}>
                        </ReactHotkeys>
                    </div>
                </div>

                <div className='flex-grow bg-gray-900 border-4 border-gray-700 rounded-b-xl flex flex-col items-center overflow-auto scrollbar shadow-[0_15px_16px_-5px_rgba(0,0,0,0.9)]'
                    style={{ width: "100%" }}
                    initial={{ opacity: 0, y: "-50%" }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.5, delay: 0.1 }}
                >
                    <div className='bg-gray-800 text-gray-200 p-2 text-lg border-2 border-gray-500 font-bold rounded-full m-2 mt-4 w-96'>Identifiant : {props.value.roid}</div>

                    <div className='m-1 bg-gray-800 rounded-xl p-2'>
                        <DeviceIconList value={props.value.items} />
                    </div>

                    <div className='bg-gray-800 p-2 pt-0.5 m-2 rounded-xl w-96'>
                        {props.value.items && props.value.items.map((item) =>
                            <div key={item.key} className='m-2'>
                                <div className='mb-1 mr-1 p-2 bg-gray-800 rounded-xl font-bold text-lg'>
                                    {item.ref}
                                </div>
                                <ProblemListValidator key={item.key} value={item.problems} onChange={(v) => { handleProblemListValidatorOnChange(item.key, v); }} />
                            </div>)
                        }
                    </div>

                    <div className='flex flex-row w-96 m-2'>
                        <div className='text-xl font-base bg-gray-800 text-gray-500 border-2 border-gray-500 p-2 rounded-l-full w-4/6'>Prix Total Estimé</div>
                        <div className='text-2xl font-bold bg-gray-900 text-gray-100 border-2 border-gray-500 p-2 pt-1 rounded-r-full w-2/6'>
                            <div className='animate-pulse'>
                                {props.value.totalPrice} DA
                            </div>
                        </div>
                    </div>

                    <div className='flex flex-col md:flex-row items-center justify-center'>
                        <div className='bg-gray-800 p-1 m-1 rounded-xl w-96 flex flex-col items-center justify-center'>
                            <label>Montant total à payer</label>
                            <input type="text" name='total' value={total} placeholder='Montant total...' className={inputFieldStyle} onChange={handleTotalPriceChange} />
                            <span className='mb-2' />
                        </div>

                        <div className='bg-gray-800 p-1 m-1 rounded-xl w-96 flex flex-col items-center justify-center'>
                            <label>Montant payer</label>
                            <input ref={paymentFieldRef} type="text" name='payment' value={payment} placeholder='Montant payer...' className={inputFieldStyle} onChange={handlePaymentChange} />
                            <span className='mb-2' />
                        </div>
                    </div>

                    <div>{paymentMessage}</div>

                    <div className='h-24 m-1 w-96 pt-1'>
                        <textarea name="note" className='bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-1 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 w-full' value={note} rows="3" placeholder="Ajouter une Note/Observation..." onChange={(e) => { setNote(e.target.value) }} />
                    </div>

                    <label className='mb-2'>
                        <input type="checkbox" checked={locked} onChange={handleLockedChange} className='mx-1' />
                        Vérouiller
                    </label>

                    {/* {total != 0 && payment != 0 && */}
                    <div>
                        {total >= 0 && payment >= 0 && total !== "" && payment !== "" && !busy && <RknButton className='w-48 mt-2 h-10' label="Valider" before={<FaCheckCircle size={24} />} onPress={handleValidateOnClick} />}
                        {busy && <PulseLoader color='#9999AA' size={48} />}
                    </div>
                    {/* } */}


                    <span className='my-2' />

                </div>
            </motion.div>

        </div>
    )

}

export default RepairOrderValidationPopupV2