import { React, useState, useEffect } from 'react';
import RknNumericInput from '../components/RknUI/RknNumericInput';
import RknDateInput from '../components/RknUI/RknDateInput';
import { GetShortDate, IsIsoDate, TimeStampToDMY } from '../Reaknotron/Libs/RknTimeTools';
import { StringToNumber_2DecAtMost } from '../Reaknotron/Libs/RknStringTools';
import RknContainer from '../components/RknUI/RknContainer';
import { FaClock, FaDownload } from 'react-icons/fa';
import CountUp from 'react-countup';
import RknButton from '../components/RknUI/RknButton';
import { useNavigate, useSearchParams } from 'react-router-dom';

// JsPDF
import autoTable from 'jspdf-autotable';
import { PerformFileGetRequestAndDownload, PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
const jspdf = require('jspdf');

const PayslipEditor = () => {

    const HOURS_PER_DAY = 8;

    const infoStyle = 'p-1 px-2 m-1 font-bold bg-gray-800 rounded-full';

    const [employee, setEmlployee] = useState(null);

    const [from, setFrom] = useState(0);
    const [to, setTo] = useState(0);

    const [holidays, setHolidays] = useState(0);

    const [workDaysCount, setWorkDaysCount] = useState(0);
    const [hourlyRate, setHourlyRate] = useState(250);

    const [absenceHours, setAbsenceHours] = useState(0);
    const [absenceDays, setAbsenceDays] = useState(0);

    const [baseNetSalary, setBaseNetSalary] = useState(0);

    const [socialSecurityBaseSalary, setSocialSecurityBaseSalary] = useState(9);
    const [socialSecurityTaxRate, setSocialSecurityTaxRate] = useState(9);
    const [socialSecurityTax, setSocialSecurityTax] = useState(0);

    const [basketBonusPerMonth, setBasketBonusPerMonth] = useState(7500);
    const [transportBonusPerMonth, setTransportBonusPerMonth] = useState(2500);

    const [PRI, setPRI] = useState(10);
    const [finalPRI, setFinalPRI] = useState(0);

    const [technicity, setTechnicity] = useState(10);
    const [finalTechnicity, setFinalTechnicity] = useState(0);

    const [basketBonusPerDay, setBasketBonusPerDay] = useState(0);
    const [lostBasketBonus, setLostBasketBonus] = useState(0);
    const [transportBonusPerDay, setTransportBonusPerDay] = useState(0);
    const [lostTransportBonus, setLostTransportBonus] = useState(0);

    const [nonTaxedSalary, setNonTaxedSalary] = useState(0);
    const [IRG, setIRG] = useState(0);

    const [finalSalary, setFinalSalry] = useState(0);
    const [targetID, setTargetID] = useState(null);

    const [searchParams, setSearchParams] = useSearchParams();

    const [shifts, setShifts] = useState(null);
    const [workHoursFromShifts, setWorkHoursFromShifts] = useState(0);

    // Effect
    useEffect(() => {

        if (searchParams.get("id")) {
            GetPayslipFromDB(searchParams.get("id"));
            setTargetID(searchParams.get("id"));
        }

    }, []);

    useEffect(() => {

        if (workHoursFromShifts) {
            const totalWorkHours = workDaysCount * 8;
            const tmpAbsenceHours = totalWorkHours - workHoursFromShifts;
            setAbsenceHours(tmpAbsenceHours);
        }

    }, [workDaysCount, workHoursFromShifts])

    function GetWorkingDays(ParamStart, ParamEnd) {
        var count = 0;
        var curDate = ParamStart;

        while (curDate <= ParamEnd) {
            var dayOfWeek = curDate.getDay();

            // If day is between Monday and Friday
            if (!((dayOfWeek == 6) || (dayOfWeek == 0)))
                count++;

            curDate.setDate(curDate.getDate() + 1);
        }
        return count;
    }

    const CalculateSalary = (ParamFrom, ParamTo, ParamHoursPerDay, ParamHolidaysCount, ParamAbsenceHours, ParamHourlyRate, ParamMonthlyBasketBonus, ParamMonthlyTransportBonus, ParamPRI, ParamTechnicity) => {

        if (!IsIsoDate(ParamFrom) || !IsIsoDate(ParamTo))
            return;

        let result = {};

        const tmpWorkDaysCount = GetWorkingDays(new Date(ParamFrom), new Date(ParamTo)) - ParamHolidaysCount;

        const netHoursOfWork = (tmpWorkDaysCount * ParamHoursPerDay) - ParamAbsenceHours;
        const absenceDays = Math.trunc(ParamAbsenceHours / ParamHoursPerDay);

        const tmpBaseNetSalary = netHoursOfWork * ParamHourlyRate;
        // setBaseNetSalary(tmpBaseNetSalary); // 🟢
        result.BaseNetSalary = tmpBaseNetSalary;

        const basketBonusPerDay = ParamMonthlyBasketBonus / (tmpWorkDaysCount + holidays);
        const transportBonusPerDay = ParamMonthlyTransportBonus / (tmpWorkDaysCount + holidays);
        const tmpLostBasketBonus = (basketBonusPerDay * absenceDays);
        const tmpLostTransportBonus = (transportBonusPerDay * absenceDays);

        const priAmount = (tmpWorkDaysCount * ParamHoursPerDay * ParamHourlyRate) * (ParamPRI / 100); // QUESTION : Why is PRI 10% of default base salary ? it should be 10% of baseNetSalary
        // setFinalPRI(tmpPri); // 🟢
        result.FinalPRI = priAmount;

        const technicityAmount = (tmpWorkDaysCount * ParamHoursPerDay * ParamHourlyRate) * (ParamTechnicity / 100);
        // setFinalTechnicity(technicityAmount); // 🟢
        result.FinalTechnicity = technicityAmount;

        const tmpSocialSecurityBaseSalary = tmpBaseNetSalary + priAmount + technicityAmount;
        const tmpSocialSecurityTax = tmpSocialSecurityBaseSalary * (socialSecurityTaxRate / 100);
        setSocialSecurityTax(tmpSocialSecurityTax);  // 🟢
        setSocialSecurityBaseSalary(tmpSocialSecurityBaseSalary);  // 🟢

        const nonTaxedSalary =
            tmpBaseNetSalary
            - tmpSocialSecurityTax
            + basketBonusPerMonth
            + transportBonusPerMonth
            - tmpLostBasketBonus
            - tmpLostTransportBonus
            + priAmount
            + technicityAmount;

        setWorkDaysCount(tmpWorkDaysCount);  // 🟢

        setBasketBonusPerDay(basketBonusPerDay);  // 🟢
        setLostBasketBonus(tmpLostBasketBonus); // 🟢

        setTransportBonusPerDay(transportBonusPerDay); // 🟢
        setLostTransportBonus(tmpLostTransportBonus); // 🟢

        setAbsenceDays(absenceDays); // 🟢
        setNonTaxedSalary(nonTaxedSalary); // 🟢

        const irg = CalculateIRG(nonTaxedSalary);
        setIRG(irg); // 🟢

        setFinalSalry(nonTaxedSalary - irg);  // 🟢
    }

    useEffect(() => {

        if (IsIsoDate(from) && IsIsoDate(to)) {
            const tmpWorkDaysCount = GetWorkingDays(new Date(from), new Date(to)) - holidays;

            const netHoursOfWork = (tmpWorkDaysCount * HOURS_PER_DAY) - absenceHours;
            const absenceDays = Math.trunc(absenceHours / HOURS_PER_DAY);

            const tmpBaseNetSalary = netHoursOfWork * hourlyRate;
            setBaseNetSalary(tmpBaseNetSalary); // 🟢

            const BASKET_BONUS_PER_DAY = basketBonusPerMonth / (tmpWorkDaysCount + holidays);
            const TRANSPORT_BONUS_PER_DAY = transportBonusPerMonth / (tmpWorkDaysCount + holidays);
            const tmpLostBasketBonus = (BASKET_BONUS_PER_DAY * absenceDays);
            const tmpLostTransportBonus = (TRANSPORT_BONUS_PER_DAY * absenceDays);

            const tmpPri = (tmpWorkDaysCount * HOURS_PER_DAY * hourlyRate) * (PRI / 100);
            setFinalPRI(tmpPri); // 🟢
            const tmpTechnicity = (tmpWorkDaysCount * HOURS_PER_DAY * hourlyRate) * (technicity / 100);
            setFinalTechnicity(tmpTechnicity); // 🟢

            const tmpSocialSecurityBaseSalary = tmpBaseNetSalary + tmpPri + tmpTechnicity;
            const tmpSocialSecurityTax = tmpSocialSecurityBaseSalary * (socialSecurityTaxRate / 100);
            setSocialSecurityTax(tmpSocialSecurityTax);  // 🟢
            setSocialSecurityBaseSalary(tmpSocialSecurityBaseSalary);  // 🟢

            const nonTaxedSalary =
                tmpBaseNetSalary
                - tmpSocialSecurityTax
                + basketBonusPerMonth
                + transportBonusPerMonth
                - tmpLostBasketBonus
                - tmpLostTransportBonus
                + tmpPri
                + tmpTechnicity;

            setWorkDaysCount(tmpWorkDaysCount);  // 🟢

            setBasketBonusPerDay(BASKET_BONUS_PER_DAY);  // 🟢
            setLostBasketBonus(tmpLostBasketBonus); // 🟢

            setTransportBonusPerDay(TRANSPORT_BONUS_PER_DAY); // 🟢
            setLostTransportBonus(tmpLostTransportBonus); // 🟢

            setAbsenceDays(absenceDays); // 🟢
            setNonTaxedSalary(nonTaxedSalary); // 🟢

            const irg = CalculateIRG(nonTaxedSalary);
            setIRG(irg); // 🟢

            setFinalSalry(nonTaxedSalary - irg);  // 🟢
        } else {
            return;
        }

    }, [from, to, hourlyRate, absenceHours, PRI, technicity, holidays, socialSecurityTaxRate]);

    const GetPayslipFromDB = (ParamID) => {
        PerformGetRequest("/api/get-payslip?id=" + ParamID, (res) => {
            setFrom(res.data.from);
            setTo(res.data.to);
            setPRI(res.data.PRI);
            setHolidays(res.data.holidays);
            setShifts(res.data.shifts);
            setBasketBonusPerMonth(res.data.basketBonus);
            setTransportBonusPerMonth(res.data.transportBonus);

            if (res.data.workHours) {
                const h = Number(res.data.workHours) / 1000 / 3600;
                setWorkHoursFromShifts(h);
            } else {
                setWorkHoursFromShifts(0);
            }

            PerformGetRequest(("/api/get-employee?id=" + res.data.employeeID), (res) => {
                setEmlployee(res.data);
                setHourlyRate(res.data.hourlyRate);
            });

        });
    }

    function CalculateIRG(ParamSalary) {

        const brackets = [
            { max: 30000, irg: 0 },
            { max: 35000, irg: ((ParamSalary - 20000) * (138 / 1000)) * (137 / 51) - (27925 / 8) },
            { max: 3340000 / 92, irg: ((ParamSalary - 20000) * (138 / 1000)) },
            { max: 40000, irg: 2250 + ((ParamSalary - (3340000 / 92)) * (23 / 100)) },
            { max: 80000, irg: ((78200 / 92) + 2250) + ((ParamSalary - 40000) * (27 / 100)) },
            { max: 160000, irg: 13900 + ((ParamSalary - 80000) * (30 / 100)) },
            { max: 320000, irg: 37900 + ((ParamSalary - 160000) * (33 / 100)) },
            { max: Infinity, irg: 90700 + ((ParamSalary - 320000) * (35 / 100)) }
        ];

        let result = 0;

        for (let i = 0; i < brackets.length; i++) {
            if (ParamSalary <= brackets[i]["max"]) {
                result = brackets[i]["irg"];
                break;
            }
        }

        return result;
    }

    const buildTable = () => {

        var head = ['Designation', 'Montant'];

        let body = [];

        // Base salary
        let tableLine = [];
        tableLine.push("Salaire de Base");
        tableLine.push(baseNetSalary);
        body.push(tableLine);

        // SS
        tableLine = [];
        tableLine.push("Sécurité Sociale");
        tableLine.push(socialSecurityTax);
        body.push(tableLine);

        // PRI
        tableLine = [];
        tableLine.push("PRI");
        tableLine.push(finalPRI);
        body.push(tableLine);

        // Technicité
        tableLine = [];
        tableLine.push("Technicity");
        tableLine.push(finalTechnicity);
        body.push(tableLine);

        // Basket Bonus
        tableLine = [];
        tableLine.push("Prime du Panier");
        tableLine.push(basketBonusPerMonth);
        body.push(tableLine);

        // Transport Bonus
        tableLine = [];
        tableLine.push("Prime de Transport");
        tableLine.push(transportBonusPerMonth);
        body.push(tableLine);

        let result = { head: head, body: body };
        return result;
    }

    const BuildPDF = async () => {
        var receiptWidth = 210;

        const halfReceiptWidth = receiptWidth / 2;
        const rightBlockXCoord = receiptWidth * 0.7;

        const doc = new jspdf.jsPDF('p', 'mm', [270, receiptWidth]); // Portrait, Milimeter, Height, Width
        var cursorY = 11;

        // Bulletin de Paie
        doc.setFont(undefined, 'bold');
        doc.setTextColor(0, 0, 0);
        doc.setFontSize(26);
        doc.text("Bulletin de Paie", halfReceiptWidth, cursorY, 'center');
        cursorY += 14;

        doc.setLineWidth(0.5); // Set border thickness
        doc.rect(6, cursorY - 4, halfReceiptWidth * 0.9, 38); // Draw square
        doc.stroke(); // Apply stroke to draw the border

        // Raison social
        doc.setFontSize(7);
        doc.setFont(undefined, 'bold');
        doc.text("Raison social:", 8, cursorY, 'left');
        cursorY += 3;
        doc.setFont(undefined, 'normal');
        doc.text("SARL VITA SOURCE", 8, cursorY, 'left');
        cursorY += 6;

        // Dénomination commercial
        doc.setFontSize(7);
        doc.setFont(undefined, 'bold');
        doc.text("Dénomination commercial:", 8, cursorY, 'left');
        cursorY += 3;
        doc.setFont(undefined, 'normal');
        doc.text("Vitasource", 8, cursorY, 'left');
        cursorY += 6;

        // Addr
        doc.setFontSize(7);
        doc.setFont(undefined, 'bold');
        doc.text("Adresse:", 8, cursorY, 'left');
        cursorY += 3;
        doc.setFont(undefined, 'normal');
        doc.text("Zone industrielle N°112 Local N°02 Chetouane, TLEMCEN", 8, cursorY, 'left');
        cursorY += 6;

        // Tel
        doc.setFont(undefined, 'bold');
        doc.setFontSize(7);
        doc.text("N° Employeur:", 8, cursorY, 'left');
        cursorY += 3;
        doc.setFont(undefined, 'normal');
        doc.text("123456789 (A venir...)", 8, cursorY, 'left');
        cursorY += 12;

        cursorY -= 42;

        doc.setLineWidth(0.5); // Set border thickness
        doc.rect(halfReceiptWidth, cursorY - 4, halfReceiptWidth * 0.9, 38); // Draw square
        doc.stroke(); // Apply stroke to draw the border

        // Full name
        doc.setFontSize(7);
        doc.setFont(undefined, 'bold');
        doc.text("Nom et Prénom : " + employee.firstName + " " + employee.familyName, halfReceiptWidth + 2, cursorY, 'left');
        cursorY += 3;

        // DOB
        doc.setFontSize(7);
        doc.setFont(undefined, 'bold');
        doc.text("Date de Naissance : " + TimeStampToDMY(employee.DOB), halfReceiptWidth + 2, cursorY, 'left');
        cursorY += 3;

        // Situation
        doc.setFontSize(7);
        doc.setFont(undefined, 'bold');
        doc.text("Situation Familliale : Célibataire ", halfReceiptWidth + 2, cursorY, 'left');
        cursorY += 3;

        // ID Number
        doc.setFontSize(7);
        doc.setFont(undefined, 'bold');
        doc.text("Matricule : 00000000", halfReceiptWidth + 2, cursorY, 'left');
        cursorY += 3;

        // Function
        doc.setFontSize(7);
        doc.setFont(undefined, 'bold');
        doc.text("Function : " + employee.professionalTitle, halfReceiptWidth + 2, cursorY, 'left');
        cursorY += 3;

        // SSN
        doc.setFontSize(7);
        doc.setFont(undefined, 'bold');
        doc.text("N° Sécurité Sociale : " + employee.socialSecurityNumber, halfReceiptWidth + 2, cursorY, 'left');
        cursorY += 3;

        // Bank
        doc.setFontSize(7);
        doc.setFont(undefined, 'bold');
        doc.text("N° Compte Banquaire : " + employee.bankAccountNumber, halfReceiptWidth + 2, cursorY, 'left');
        cursorY += 3;

        cursorY += 23;

        // PRI
        doc.text("PRI : " + PRI + "%", 3, cursorY, 'left');
        // cursorY += 4;

        // Abscence
        doc.text("Abscence : " + StringToNumber_2DecAtMost(absenceHours) + " Heure(s)", halfReceiptWidth, cursorY, 'center');
        // cursorY += 4;

        // Holidays
        doc.text("Congé : " + holidays + " Jour(s)", receiptWidth - 3, cursorY, 'right');
        cursorY += 2;

        // Date
        // doc.text("Date : " + GetShortDate(), rightBlockXCoord, cursorY, 'left');
        // cursorY += 4;

        // Logo
        // doc.setFont(undefined, 'bold');
        // doc.setFontSize(26);
        // doc.text("VITASOURCE", 8, cursorY, 'left');
        // cursorY += 4;

        // Text under logo
        // doc.setFont(undefined, 'normal');
        // doc.setFontSize(10);
        // doc.text("Complement Alimentaire", 8, cursorY, 'left');
        // cursorY += 16;

        // Customer name
        // doc.setFontSize(12);
        // doc.text(`Employé(e) : ${employee.firstName + " " + employee.familyName}`, halfReceiptWidth, cursorY, 'center');
        // cursorY += 8;

        // Consumption table
        const tableData = buildTable();

        let cellTextFontSize = 10;
        autoTable(doc, {
            head: [tableData.head],
            body: tableData.body,
            startY: cursorY,
            margin: 2,
            theme: 'grid',
            tableWidth: receiptWidth - 4,
            styles: {
                fontSize: cellTextFontSize,
                cellPadding: 1,
                fontStyle: 'bold',
                textColor: 'black'
            },
            headStyles: { fillColor: [0, 0, 0], textColor: [255, 255, 255] },
            didDrawPage: (d) => { cursorY = d.cursor.y },
        });
        cursorY += 5;

        // Total
        doc.setFontSize(12);
        doc.text("Salaire Net à Payer : " + StringToNumber_2DecAtMost(finalSalary) + " DA", halfReceiptWidth, cursorY, 'center');
        cursorY += 8;

        return doc;
    };


    const DownloadPDF = async () => {
        const doc = await BuildPDF();
        doc.save("Bulletin-de-Paie.pdf");
    }

    const DownloadExcel = async () => {

        const d = new Date(from);
        // employee.firstName + " " + employee.familyName
        const url = `/api/generate-payslip-xls?FirstName=${employee.firstName}&LastName=${employee.familyName}&Month=${d.getMonth() + 1}&Year=${d.getFullYear()}&PRI=${PRI}&AbscenceHours=${absenceHours}&Holidays=${holidays}&BaseSalary=${hourlyRate}`;

        PerformFileGetRequestAndDownload(url, "Bulletin de Paie.xlsx");
    }

    return (
        <div className='text-gray-100 mr-8'>
            <br />
            <h1 className='mt-4 text-xl font-bold'>Bulletin de Paie</h1>
            <h3 className='mt-4 text-sm font-bold text-gray-500'>{employee && ("Employé(e) : " + employee.firstName + " " + employee.familyName)}</h3>
            <br />

            <div>
                <div className='bg-gray-800 rounded-t-lg p-2 mx-4 w-full text-base font-bold text-gray-100'>
                    🕒 Chronométrage
                </div>
                <div className='bg-gray-900 bg-opacity-50 rounded-b-xl p-2 mx-4 w-full mb-4 flex flex-col items-center justify-center'>

                    <div className='flex flex-row items-center justify-center'>
                        <label className="block text-sm font-medium text-gray-900 dark:text-white">Du</label>
                        <RknDateInput value={from} onChange={setFrom} />
                        <span className='mx-4' />
                        <label className="block text-sm font-medium text-gray-900 dark:text-white">Au</label>
                        <RknDateInput value={to} onChange={setTo} />
                        <span className='mx-4' />
                        <label className="block text-sm font-medium text-gray-900 dark:text-white mr-1">Jour(s) de Congé</label>
                        <RknNumericInput value={holidays} onChange={setHolidays} />
                        <span className='mx-4' />
                    </div>
                    <span className='mb-4' />

                    <div className='flex flex-row items-center justify-center'>
                        <div className={infoStyle}>Total en Jour(s) : {workDaysCount}</div>
                        <span className='mx-4' />
                        <div className={infoStyle}>Total en Heure(s) : {workDaysCount * 8} </div>
                    </div>
                    <span className='mb-4' />

                    {/* Shifts */}
                    <div className='w-3/4'>
                        <div className='bg-gray-800 border-t-2 border-r-2 border-l-2 border-gray-500 h-7 rounded-t-lg p-1 mx-4 w-full text-sm font-bold text-gray-100'>
                            Shift(s)
                        </div>
                        <div className='bg-gray-900 border-b-2 border-r-2 border-l-2 border-gray-500 bg-opacity-50 rounded-b-xl p-2 mx-4 w-full mb-4'>
                            <div className='flex flex-row items-center justify-center'>
                                <label className="block text-sm font-medium text-gray-900 dark:text-white mr-1">Durée Total : </label>
                                <div className={infoStyle}>{StringToNumber_2DecAtMost(workHoursFromShifts)} Heure(s)</div>
                                <span className='mx-4' />
                                <label className="block text-sm font-medium text-gray-900 dark:text-white mr-1">Nombre de Shifts : </label>
                                <div className={infoStyle}>{shifts && shifts.length} Shift(s)</div>
                            </div>
                        </div>
                    </div>

                </div>
            </div>

            <div>
                <div className='bg-red-800 rounded-t-lg p-2 mx-4 w-full text-base font-bold text-gray-100'>
                    😴 Absence
                </div>
                <div className='bg-red-900 bg-opacity-50 rounded-b-xl p-2 mx-4 w-full mb-4'>
                    <div className='flex flex-row items-center justify-center'>
                        <label className="block text-sm font-medium text-gray-900 dark:text-white mr-1">Heures d'absence</label>
                        <RknNumericInput value={absenceHours} onChange={setAbsenceHours} />
                        <span className='mx-4' />
                        <div className={infoStyle}>Jours d'absence : {absenceDays}</div>
                    </div>
                </div>
            </div>

            <div>
                <div className='bg-green-800 rounded-t-lg p-2 mx-4 w-full text-base font-bold text-gray-100'>
                    💲 Salaire de Base
                </div>
                <div className='bg-green-900 bg-opacity-50 rounded-b-xl p-2 mx-4 w-full mb-4'>
                    <div className='flex flex-row items-center justify-center'>
                        <label className="block text-sm font-medium text-gray-900 dark:text-white mr-1">Salaire Horaire</label>
                        <RknNumericInput value={hourlyRate} onChange={setHourlyRate} />
                        <span className='mx-4' />
                        <div className={infoStyle}>Salaire de Base : {StringToNumber_2DecAtMost(baseNetSalary)} DA</div>
                    </div>
                </div>
            </div>

            {/* Prime */}
            <div>
                <div className='bg-gray-800 rounded-t-lg p-2 mx-4 w-full text-base font-bold text-gray-100'>
                    ❤️ Prime
                </div>
                <div className='bg-gray-900 bg-opacity-50 rounded-b-xl p-2 mx-4 w-full mb-4'>
                    <div className='flex flex-col w-full'>

                        {/* Labels */}
                        <div className='flex flex-row flex-grow space-x-0.5 space-y-0.5'>
                            <div style={{ width: '4%' }} className='h-7 mt-0.5 p-0.5 bg-gray-800 rounded-lg'>👁️</div>
                            <div style={{ width: '24%' }} className='p-0.5 bg-gray-800 rounded-lg'>Designation</div>
                            <div style={{ width: '24%' }} className='p-0.5 bg-gray-800 rounded-lg'>Taux</div>
                            <div style={{ width: '24%' }} className='p-0.5 bg-gray-800 rounded-lg'>Montant Retenue</div>
                            <div style={{ width: '24%' }} className='p-0.5 bg-gray-800 rounded-lg'>Montant Final</div>
                        </div>

                        {/* Panier */}
                        <div className='flex flex-row flex-grow space-x-0.5 space-y-0.5'>
                            <div style={{ width: '4%' }} className='h-7 mt-0.5 p-0.5 bg-gray-800 rounded-lg'>🍔</div>
                            <div style={{ width: '24%' }} className='p-0.5 bg-gray-800 rounded-lg'>Prime du Panier</div>
                            <div style={{ width: '24%' }} className='p-0.5 bg-gray-800 rounded-lg'>{basketBonusPerMonth} DA <span className='text-xs rounded-full bg-gray-700 text-gray-400 px-2'>{StringToNumber_2DecAtMost(basketBonusPerDay)} DA / Jours</span></div>
                            <div style={{ width: '24%' }} className='p-0.5 bg-gray-800 rounded-lg'>{StringToNumber_2DecAtMost(lostBasketBonus)} DA</div>
                            <div style={{ width: '24%' }} className='p-0.5 bg-gray-800 rounded-lg'>{StringToNumber_2DecAtMost(basketBonusPerMonth - lostBasketBonus)} DA</div>
                        </div>

                        {/* Transport */}
                        <div className='flex flex-row flex-grow space-x-0.5 space-y-0.5'>
                            <div style={{ width: '4%' }} className='h-7 mt-0.5 p-0.5 bg-gray-800 rounded-lg'>🚗</div>
                            <div style={{ width: '24%' }} className='p-0.5 bg-gray-800 rounded-lg'>Prime de Transport</div>
                            <div style={{ width: '24%' }} className='p-0.5 bg-gray-800 rounded-lg'>{transportBonusPerMonth} DA <span className='text-xs rounded-full bg-gray-700 text-gray-400 px-2'>{StringToNumber_2DecAtMost(transportBonusPerDay)} DA / Jours</span></div>
                            <div style={{ width: '24%' }} className='p-0.5 bg-gray-800 rounded-lg'>{StringToNumber_2DecAtMost(lostTransportBonus)} DA</div>
                            <div style={{ width: '24%' }} className='p-0.5 bg-gray-800 rounded-lg'>{StringToNumber_2DecAtMost(transportBonusPerMonth - lostTransportBonus)} DA</div>
                        </div>

                        {/* PRI */}
                        <div className='flex flex-row flex-grow space-x-0.5 space-y-0.5'>
                            <div style={{ width: '4%' }} className='h-7 mt-0.5 p-0.5 bg-gray-800 rounded-lg'>🌟</div>
                            <div style={{ width: '24%' }} className='p-0.5 bg-gray-800 rounded-lg'>PRI</div>
                            <div style={{ width: '24%' }} className='p-0.5 bg-gray-800 rounded-lg'><RknNumericInput value={PRI} onChange={setPRI} height="16px" unit="%" /></div>
                            <div style={{ width: '24%' }} className='p-0.5 bg-gray-800 rounded-lg'>-</div>
                            <div style={{ width: '24%' }} className='p-0.5 bg-gray-800 rounded-lg'>{StringToNumber_2DecAtMost(finalPRI)} DA</div>
                        </div>

                        {/* Technicité */}
                        <div className='flex flex-row flex-grow space-x-0.5 space-y-0.5'>
                            <div style={{ width: '4%' }} className='h-7 mt-0.5 p-0.5 bg-gray-800 rounded-lg'>🧠</div>
                            <div style={{ width: '24%' }} className='p-0.5 bg-gray-800 rounded-lg'>Technicité</div>
                            <div style={{ width: '24%' }} className='p-0.5 bg-gray-800 rounded-lg'><RknNumericInput value={technicity} onChange={setTechnicity} height="16px" unit="%" /></div>
                            <div style={{ width: '24%' }} className='p-0.5 bg-gray-800 rounded-lg'>-</div>
                            <div style={{ width: '24%' }} className='p-0.5 bg-gray-800 rounded-lg'>{StringToNumber_2DecAtMost(finalTechnicity)} DA</div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Social Security */}
            <div>
                <div className='bg-purple-800 rounded-t-lg p-2 mx-4 w-full text-base font-bold text-gray-100'>
                    🛡️ Securité Sociale
                </div>
                <div className='bg-purple-900 bg-opacity-50 rounded-b-xl p-2 mx-4 w-full mb-4'>
                    <div className='flex flex-row items-center justify-center'>
                        <div className={infoStyle}>Base : {StringToNumber_2DecAtMost(socialSecurityBaseSalary)} DA</div>
                        <span className='mx-4' />
                        <label className="block text-sm font-medium text-gray-900 dark:text-white mr-1">Taux</label>
                        <RknNumericInput value={socialSecurityTaxRate} onChange={setSocialSecurityTaxRate} unit="%" />
                        <span className='mx-4' />
                        <div className={infoStyle}>Montant : {StringToNumber_2DecAtMost(socialSecurityTax)} DA</div>
                    </div>
                </div>
            </div>

            {/* IRG */}
            <div>
                <div className='bg-orange-800 rounded-t-lg p-2 mx-4 w-full text-base font-bold text-gray-100'>
                    🧾 Impôt sur le Revenu Global
                </div>
                <div className='bg-orange-900 bg-opacity-50 rounded-b-xl p-2 mx-4 w-full mb-4'>
                    <div className='flex flex-row items-center justify-center'>
                        <label className={infoStyle}>🟢 Salaire Non-Taxé : {StringToNumber_2DecAtMost(nonTaxedSalary)} DA</label>
                        <label className={infoStyle}>🔴 IRG : {StringToNumber_2DecAtMost(IRG)} DA</label>
                    </div>
                </div>
            </div>

            {/* Net */}
            <div>
                <div className='bg-neutral-700 rounded-t-lg p-2 mx-4 w-full text-base font-bold text-gray-100'>
                    🧾 Salaire Net à Payer
                </div>
                <div className='bg-neutral-800 bg-opacity-50 rounded-b-xl p-2 mx-4 w-full mb-4'>
                    <div className='flex flex-row items-center justify-center'>
                        <CountUp end={finalSalary} useEasing={false} preserveValue={true} duration='0.4' style={{ fontSize: 128 }} />
                        <div style={{ fontSize: 36 }} className='mx-2 text-neutral-200'>DA</div>
                    </div>
                </div>
            </div>

            <RknButton label="Télécharger (PDF)" className="w-48 mx-auto" before={<FaDownload />} onPress={DownloadPDF} />
            <RknButton label="Télécharger (Excel)" className="w-48 mx-auto" before={<FaDownload />} onPress={DownloadExcel} />

        </div>
    )
}

export default PayslipEditor