import React, { useState, useEffect } from 'react';
import { PerformGetRequest, PerformGetRequest_Promise, PerformImageGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import { AnimatePresence, motion } from "framer-motion";
import AppData from '../App.json';

const AnimatedCateringMenu = () => {

    const bigMode = true;

    const [isRecording, setIsRecording] = useState(false);
    const [mediaRecorder, setMediaRecorder] = useState(null);
    const [videoUrl, setVideoUrl] = useState('');

    const [categories, setCategories] = useState(null);
    const [currentCategoryId, setCurrentCategoryId] = useState(null);
    const [imageCache, setImageCache] = useState({});

    const startRecording = async () => {
        if (!navigator.mediaDevices || !navigator.mediaDevices.getDisplayMedia) {
            console.error('Screen recording is not supported in this browser.');
            return;
        }

        const stream = await navigator.mediaDevices.getDisplayMedia({ video: true });
        const mediaRecorder = new MediaRecorder(stream, { mimeType: 'video/webm' });
        setMediaRecorder(mediaRecorder);

        // !! It seems like data is not being captured in real time, so we avoid this method for now !!
        // mediaRecorder.dataavailable = (event) => {
        //     console.log("DATA");
        //     if (event.data.size > 0) {
        //         console.log('Recording chunk of size: ', event.data.size);
        //         setVideoChunks((prev) => [...prev, event.data]);
        //     } else {
        //         console.log('No data...');
        //     }
        // };

        // We capture all the data at once at the end of the recording, 
        // since this event seems to only trigger at the end of the recording.
        mediaRecorder.ondataavailable = (e) => {
            console.log("On DATA : " + e.data.size);
            const blob = new Blob([e.data], { type: 'video/webm' });
            console.log('Blob size: ', blob.size);
            setVideoUrl(URL.createObjectURL(blob));
        };

        mediaRecorder.start();
        setIsRecording(true);
    };

    const handleKeyPress = (event) => {
        if (event.key === 'r' || event.key === 'R') {
            // Toggle the state
            isRecording ? stopRecording() : startRecording();
        }
    };

    // Add event listener for R key press
    useEffect(() => {
        window.addEventListener('keypress', handleKeyPress);
        // Cleanup event listener on component unmount
        return () => {
            window.removeEventListener('keypress', handleKeyPress);
        };
    }, [isRecording]);

    useEffect(() => {
        PerformGetRequest("/api/menuk?id=self", async (res) => {

            // console.log("RES = " + JSON.stringify(res.data));
            setCategories(res.data.categories);

            const catKeys = Object.keys(res.data.categories);

            if (catKeys && catKeys.length > 0) {

                let tmpImageCache = {};
                for (const k of catKeys) {
                    // console.log(JSON.stringify(res.data.categories[k].products));

                    const prodKeys = Object.keys(res.data.categories[k].products);

                    if (prodKeys && prodKeys.length > 0) {

                        for (const pk of prodKeys) {
                            const prod = res.data.categories[k].products[pk];
                            // console.log(JSON.stringify(prod));
                            const imgRes = await PerformImageGetRequest("/api/get-product-image?id=" + prod.id);
                            // console.log('IMG RES = ' + JSON.stringify(imgRes));
                            // tmpImageCache[prod.id] = imgRes.response.data;
                            tmpImageCache[prod.id] = imgRes;
                        }

                    }
                }

                console.log("Keys = " + JSON.stringify(Object.keys(tmpImageCache)));
                console.log("Content = " + JSON.stringify(tmpImageCache));
                setImageCache(tmpImageCache);

                // Start with the first category
                setCurrentCategoryId(catKeys[0]);
            }

        });
    }, []);

    useEffect(() => {
        if (categories) {
            const categoryIds = Object.keys(categories);
            const currentIndex = categoryIds.indexOf(currentCategoryId);
            const nextIndex = (currentIndex + 1) % categoryIds.length;
            const timer = setTimeout(() => {
                setCurrentCategoryId(categoryIds[nextIndex]);
            }, (categoryIds.length * 300) + 5000); // Change category every 5 seconds plus 300ms for each item
            return () => clearTimeout(timer); // Cleanup timer on component unmount
        }
    }, [categories, currentCategoryId]);

    if (!categories || !currentCategoryId) return null;

    const currentCategory = categories[currentCategoryId];

    const stopRecording = () => {
        if (mediaRecorder) {
            mediaRecorder.stop();
            setIsRecording(false);
        }
    };

    const downloadVideo = () => {
        if (videoUrl) {
            const link = document.createElement('a');
            link.href = videoUrl;
            link.download = 'screen-recording.webm';
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        }
    };

    return (
        <div>
            <video src={require(`../assets/${AppData.SALES_POINT_BG_VIDEO}`)} className='fixed h-screen w-full object-cover opacity-20' autoPlay loop muted />

            {videoUrl &&
                <div className='fixed bottom-4 z-20 right-2 flex flex-col items-center justify-center bg-gray-100 bg-opacity-40 p-1 rounded-lg'>
                    <button onClick={downloadVideo}>Download Video</button>
                </div>
            }

            <AnimatePresence>
                {currentCategory && (
                    <motion.div
                        key={currentCategoryId}
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className='fixed mt-1 top-16 bottom-2 right-2 left-2 rounded-xl flex flex-col items-center justify-start'
                    >

                        {/* Category */}
                        <div className='text-gray-100 border-4 border-gray-500 rounded-3xl m-1 text-3xl w-full p-2 font-bold backdrop-blur-xl'>
                            {currentCategory.icon + " " + currentCategory.name}
                        </div>

                        {/* Products */}
                        <div className='grid grid-cols-3 w-full text-gray-100 font-bold'>
                            {currentCategory.products.map((product, i) => (
                                <motion.div
                                    className='flex flex-row m-1'
                                    key={product.id}
                                    initial={{ opacity: 0, x: "-25%" }}
                                    animate={{ opacity: 1, x: 0 }}
                                    transition={{ duration: 0.5, delay: i * 0.15 }}
                                >
                                    <img className={`${bigMode ? "w-1/4" : "w-1/6"} ${bigMode ? "h-32" : "h-16"} object-cover rounded-l-xl border-2 border-gray-500`} src={imageCache[product.id]} />
                                    {/* <div className={`${bigMode ? "w-1/2" : "w-4/6"} ${bigMode ? "h-32" : "h-16"} bg-gray-700 border-y-2 border-gray-100 text-ellipsis flex flex-col items-start justify-center pl-2 text-xl`}>{product.name}</div>
                                    <div className={`${bigMode ? "w-1/4" : "w-1/6"} ${bigMode ? "h-32" : "h-16"} bg-gradient-to-b from-gray-800 to-gray-600 rounded-r-xl text-gray-100 border-2 border-gray-100 animate-pulse overflow-clip flex flex-row items-center justify-center ${bigMode ? "text-2xl" : "text-xl"}`}>{product.price.join(', ')} <span className='text-sm pt-1 ml-1'>DA</span></div> */}
                                    <div className={`${bigMode ? "w-3/4" : "w-5/6"} ${bigMode ? "h-32" : "h-16"} bg-gray-900 bg-opacity-60 flex flex-col items-start justify-start pl-2 rounded-r-xl`}>
                                        <div className='text-4xl text-ellipsis whitespace-nowrap'>{product.name}</div>
                                        <div className='text-2xl whitespace-nowrap' >{product.price.join(', ')} <span className='text-sm pt-1 ml-1'>DA</span></div>
                                    </div>
                                </motion.div>
                            ))}
                        </div>

                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};

export default AnimatedCateringMenu;