import React, { useState, useEffect } from 'react';
import CateringSalesRevenueStats from '../components/CateringSalesRevenueStats';
import CateringSalesProductCount from '../components/CateringSalesProductCount';
import AppData from '../App.json';
import CateringSalesPaymentPerProduct from '../components/CateringSalesPaymentPerProduct';
import ReceptionTotalCounter from '../components/ReceptionTotalCounter';
import FeeStats from '../components/FeeStats';
import GlobalIncomeOutcomeStats from '../components/GlobalIncomeOutcomeStats';
import { GetDateTimeDMYHM, IsIsoDate } from '../Reaknotron/Libs/RknTimeTools';
import { StringToDateRange } from '../Reaknotron/Libs/RknTimeRange';
import CateringSalesTypeStats from '../components/CateringSalesTypeStats';
import RepairOrderStats from '../components/RepairOrderStats';
import SalesTotalCounter from '../components/SalesTotalCounter';
import RknContainer from '../components/RknUI/RknContainer';
import SalesPerCustomer from '../components/SalesPerCustomer';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css';
import SalesPerTable from '../components/SalesPerTable';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';

const Statistics = () => {

    const [dateRange, setDateRange] = useState("TODAY");
    const [dateRangeLabel, setDateRangeLabel] = useState("");
    const [startDate, setStartDate] = useState(null);
    const [endDate, setEndDate] = useState(null);
    const [userList, setUserList] = useState(null);
    const [selectedUser, setSelectedUser] = useState("ALL");

    useEffect(() => {
        setDateRange("TODAY");
        // setDateRangeLabel(event.target.value);
        const range = StringToDateRange("TODAY");

        if (range) {
            // setDateRangeLabel("Du " + GetDateTimeDMYHM(range.start) + " Au " + GetDateTimeDMYHM(range.end));
            setStartDate(range.start);
            setEndDate(range.end);
        }
        else {
            // setDateRangeLabel("Du ? Au ?");
            setStartDate(null);
            setEndDate(null);
        }

        PerformGetRequest("/api/get-user-list", (res) => {
            console.log(JSON.stringify(res.data));
            setUserList(res.data);
        });

    }, []);

    useEffect(() => {
        setDateRangeLabel("Du " + GetDateTimeDMYHM(startDate) + " Au " + GetDateTimeDMYHM(endDate));
    }, [startDate, endDate]);

    const handleChange = (event) => {
        setDateRange(event.target.value);
        // setDateRangeLabel(event.target.value);
        const range = StringToDateRange(event.target.value);

        if (event.target.value === "ALL_TIME") {
            setDateRangeLabel("");
            setStartDate(null);
            setEndDate(null);
        }
        else if (event.target.value === "CUSTOME_RANGE") {
            // setDateRangeLabel("Du " + GetDateTimeDMYHM(startDate) + " Au " + GetDateTimeDMYHM(endDate));
            // setStartDate(range.start);
            // setEndDate(range.end);
        }
        else if (range) {
            // setDateRangeLabel("Du " + GetDateTimeDMYHM(range.start) + " Au " + GetDateTimeDMYHM(range.end));
            setStartDate(range.start);
            setEndDate(range.end);
        }
        else {
            // setDateRangeLabel("Du ? Au ?");
            setStartDate(null);
            setEndDate(null);
        }
    }

    const startCalendarOnChange = (ParamValue) => {
        // console.log("S = " + ParamValue);
        const d = new Date(ParamValue);
        // console.log("D = " + d.toISOString());
        setStartDate(d);
    }

    const endCalendarOnChange = (ParamValue) => {
        const d = new Date(ParamValue);
        setEndDate(d);
    }

    const handleCustomerChange = (e) => {
        setSelectedUser(userList.find(c => c._id === e.target.value));
        // GetSalesListFromDB(e.target.value);
    }

    return (
        <div className='mr-8 flex flex-col items-center justify-center'>
            <br />
            <h3 className='text-3xl font-bold text-gray-100 mb-2' >Statistiques</h3>
            <select name="date-range" className="bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 my-0 mx-2 py-1 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500"
                value={dateRange}
                onChange={handleChange}
            >
                <option value="TODAY">Aujourd'hui</option>
                <option value="YESTERDAY">Hier</option>
                <option value="LAST_24_HOURS">Dernières 24 heures</option>
                <option value="THIS_WEEK">Cette semaine</option>
                <option value="LAST_WEEK">Les 7 derniers jours</option>
                <option value="THIS_MONTH">Ce mois-ci</option>
                <option value="LAST_MONTH">Les 30 derniers jours</option>
                <option value="THIS_YEAR">Cette année</option>
                <option value="LAST_YEAR">L'Année dernière</option>
                <option value="ALL_TIME">Depuis toujours</option>
                <option value="CUSTOME_RANGE">Période Spécifique</option>
            </select>
            <p className='text-sm text-gray-300 mt-2'>{dateRangeLabel}</p>

            {dateRange == "CUSTOME_RANGE" &&
                <div className='flex flex-row items-center justify-center space-x-4 mt-2'>
                    <Calendar onChange={startCalendarOnChange} value={startDate} />
                    <Calendar onChange={endCalendarOnChange} value={endDate} />
                </div>
            }

            {userList && <select value={selectedUser?._id || ''} onChange={handleCustomerChange} className="py-1 mx-2 mt-4 text-xs text-gray-900 border border-gray-300 rounded-lg bg-gray-50 focus:ring-blue-500 focus:border-blue-500 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500" >
                <option value="ALL">Tous</option>
                {userList.map(customer => (
                    <option key={customer._id} value={customer._id}>{`${customer.username}`}</option>
                ))}
            </select>}

            <br />
            <br />

            {AppData.DEVICE_MAINTENANCE_FLAG &&
                <RknContainer title="Statistiques des Ordres de Réparations">
                    <RepairOrderStats start={startDate} end={endDate} />
                </RknContainer>
            }

            {AppData.CATERING_FLAG &&
                <RknContainer title="Statistiques des Revenues">
                    <CateringSalesRevenueStats start={startDate} end={endDate} user={selectedUser?._id || 'ALL'} />
                </RknContainer>
            }
            {AppData.CATERING_FLAG &&
                <RknContainer title="Statistiques des Ventes par Table/Cible">
                    <SalesPerTable start={startDate} end={endDate} />
                </RknContainer>
            }
            {AppData.CATERING_FLAG &&
                <RknContainer title="Statistiques des Ventes par Produit">
                    <CateringSalesProductCount start={startDate} end={endDate} />
                </RknContainer>
            }
            {AppData.CATERING_FLAG &&
                <RknContainer title="Statistiques des Ventes par Produit en DA">
                    <CateringSalesPaymentPerProduct start={startDate} end={endDate} />
                </RknContainer>
            }
            {AppData.CATERING_FLAG &&
                <RknContainer title="Statistiques des Ventes par type">
                    <CateringSalesTypeStats start={startDate} end={endDate} />
                </RknContainer>
            }

            {startDate && endDate && AppData.STORAGE_MANAGEMENT_FLAG &&
                <RknContainer title="Statistiques des Réceptions">
                    <ReceptionTotalCounter start={startDate} end={endDate} />
                </RknContainer>
            }

            {startDate && endDate && AppData.SALES_POINT_FLAG && // TODO : All time stats
                <RknContainer title="Statistiques des Ventes">
                    <SalesTotalCounter start={startDate} end={endDate} />
                </RknContainer>
            }

            {/* {startDate && endDate && AppData.SALES_POINT_FLAG &&
                <RknContainer title="Statistiques des Ventes par Client">
                    <SalesPerCustomer start={startDate} end={endDate} />
                </RknContainer>
            } */}

            {AppData.FEE_MANAGEMENT_FLAG &&
                <RknContainer title="Statistiques des Frais">
                    <FeeStats start={startDate} end={endDate} />
                </RknContainer>
            }

            {AppData.CATERING_FLAG &&
                <RknContainer title="Statistiques Générale">
                    <GlobalIncomeOutcomeStats start={startDate} end={endDate} />
                </RknContainer>
            }

            <br />
            <br />
        </div>
    )
}

export default Statistics