import { React, useState, useEffect } from 'react';

const DefaultPriceLabel = (props) => {

    const [label, setLabel] = useState("Prix de Détail");
    const [bgColor, setBgColor] = useState("bg-green-900");

    const renderDefaultPriceLabel = (ParamDefaultPrice) => {
        if (ParamDefaultPrice) {

            if (ParamDefaultPrice == "HALF_WHOLESALE") {
                setBgColor("bg-orange-900");
                setLabel("Prix Demi-Gros");
            }
            else if (ParamDefaultPrice == "WHOLESALE") {
                setBgColor("bg-purple-900");
                setLabel("Prix de Gros");
            } else {
                setBgColor("bg-green-900");
                setLabel("Prix de Détail");
            }

        } else {
            setBgColor("bg-green-900");
            setLabel("Prix de Détail");
        }

    }

    useEffect(() => {
        renderDefaultPriceLabel(props.defaultPrice);
    }, [props]);

    return (
        <div className={`inline p-1 px-4 mx-2 text-xs text-gray-300 ${bgColor} rounded-xl whitespace-nowrap`}>{label}</div>
    )
}

export default DefaultPriceLabel