import React, { useState, useEffect } from 'react';
import { InputFieldStyle } from '../../Styles';
import { FaPlusCircle } from 'react-icons/fa';
import RknNumericInput from './RknNumericInput';
import { StringToNumber_2DecAlways } from '../../Reaknotron/Libs/RknStringTools';
import BatchIdInputField from '../BatchIdInputField';

const RknProductsTableRow = (props) => {

    const [product, setProduct] = useState({
        id: null,
        name: '',
        batchID: '',
        price: 0,
        amount: 0,
        tva: 0,
        total: 0,
        discount: 0
    });

    useEffect(() => {
        if (props.product)
            setProduct(props.product);
    }, []);

    useEffect(() => {
        const total = (product.price * product.amount) * (1 + product.tva / 100) * (1 - product.discount / 100);
        setProduct(prevProduct => ({ ...prevProduct, total }));
    }, [product.price, product.amount, product.discount]);

    useEffect(() => {
        // console.log("Product changed: " + JSON.stringify(product));
        if (props.onChange)
            props.onChange(props.id, product);
    }, [product.total, product.batchID]);

    // const handleBatchOnChange = (e) => {
    //     setProduct({ ...product, batchID: e.target.value });
    // }

    const handleAmountOnChange = (value) => {
        setProduct({ ...product, amount: value });
    }

    const handlePriceOnChange = (value) => {
        setProduct({ ...product, price: value });
    }

    // const handleDiscountOnChange = (value) => {
    //     setProduct({ ...product, discount: value });
    // }

    const handleValidBatch = (ParamStatus, ParamBatchIdString) => {
        setProduct({ ...product, batchID: ParamBatchIdString });
    }

    return (
        <tr className='w-full flex flex-row items-center justify-center' key={props.id}>

            {/* Designation */}
            <td className='w-64 flex flex-row items-center justify-center border border-gray-700 h-16'>
                {product.name}
            </td>

            {/* Batch */}
            <td className='w-64 flex flex-row items-center justify-center border border-gray-700 h-16 pt-1'>
                {/* <input type='text' className={InputFieldStyle} value={product.batchID} onChange={handleBatchOnChange} /> */}
                {/* <BatchIdInputField value={product.batchID} productID={products.id} onValidBatch={(ParamStatus, ParamBatchIdString) => handleValidBatch(pk, ParamStatus, ParamBatchIdString)} /> */}
                <BatchIdInputField value={product.batchID} productID={product.id} onValidBatch={(ParamStatus, ParamBatchIdString) => handleValidBatch(ParamStatus, ParamBatchIdString)} />
                {/* <FaPlusCircle className='mx-1 mt-1.5 text-gray-700 hover:text-gray-300 transition duration-150 cursor-pointer active:scale-90' size={24} onClick={() => { handleExtraBatch(pk); }} /> */}
            </td>

            {/* Price */}
            <td className='w-48 flex flex-row items-center justify-center border border-gray-700 h-16'>
                <RknNumericInput width="128px" value={product.price} onChange={handlePriceOnChange} />
            </td>

            {/* Amount */}
            <td className='w-48 flex flex-row items-center justify-center border border-gray-700 h-16'>
                <RknNumericInput width="128px" value={product.amount} onChange={handleAmountOnChange} />
            </td>

            {/* TVA */}
            <td className='w-48 flex flex-row items-center justify-center border border-gray-700 h-16'>
                {product.tva}
            </td>

            {/* Total */}
            <td className='w-48 flex flex-row items-center justify-center border border-gray-700 h-16'>
                {StringToNumber_2DecAlways(product.total)}
            </td>

            {/* Discount */}
            {/* <td className='w-48 flex flex-row items-center justify-center border border-gray-700 h-16'>
                <RknNumericInput unit="%" width="128px" value={product.discount} onChange={handleDiscountOnChange} />
            </td> */}
        </tr>
    )
}

export default RknProductsTableRow