import { React, useState } from 'react';
import { AwesomeButton } from 'react-awesome-button';
import "jspdf-barcode";
const jspdf = require('jspdf');
const QRCode = require('qrcode');

const QrCodeLoginMaker = () => {

    const [user, setUser] = useState("");
    const [pass, setPass] = useState("");

    const CreatePdfWithQrCode = async (ParamText) => {
        // Generate QR code
        // const qrCodeDataUrl = await QRCode.toDataURL(ParamText);

        // Create a new jsPDF instance
        // const doc = new jspdf.jsPDF();

        var receiptWidth = 60;

        if (localStorage.getItem("receiptWidth")) {
            receiptWidth = Number(localStorage.getItem("receiptWidth"));
            // console.log("RECEIPT WIDTH = " + receiptWidth);
        }

        const halfReceiptWidth = receiptWidth / 2;

        const doc = new jspdf.jsPDF('p', 'mm', [160, receiptWidth]); // Portrait, Milimeter, Height, Width
        var cursorY = 14;

        // ROID Barcode
        doc.barcode(ParamText, {
            fontSize: 40,
            textColor: "#000000",
            x: halfReceiptWidth - (halfReceiptWidth / 2) - 9,
            y: cursorY
        });
        cursorY += 4;

        // Add the QR code to the PDF
        // doc.addImage(qrCodeDataUrl, 'JPEG', 15, 40, 180, 160);

        return doc;
    }

    const DownloadPDF = async (ParamText) => {
        const doc = await CreatePdfWithQrCode(ParamText);
        doc.save("QR-Code.pdf");
    }

    return (
        <div className='flex flex-col items-center justify-center text-gray-100 border-4 border-gray-500 rounded-3xl p-4'>
            <h2 className='text-xl m-2'>Générer Un Code QR</h2>
            <input className='bg-gray-800 w-48 p-1 rounded-lg border border-gray-500 m-2' name='username' placeholder="Nom d'utilisateur..." value={user} onChange={(e) => { setUser(e.target.value); }} />
            <input className='bg-gray-800 w-48 p-1 rounded-lg border border-gray-500 m-2' name='password' placeholder="Mot de Passe..." value={pass} onChange={(e) => { setPass(e.target.value); }} />
            <AwesomeButton type='primary' onPress={() => { DownloadPDF(user + "[sep]" + pass); }}>Télécharger</AwesomeButton>
        </div>
    )
}

export default QrCodeLoginMaker