import { React, useState, useEffect, useRef } from 'react';
import Popup from 'reactjs-popup';
import { FaQuestionCircle, FaTimesCircle } from 'react-icons/fa';
import RknSubmitButton from './RknUI/RknSubmitButton';
import RknEmojiSelector from './RknUI/RknEmojiSelector';
import { TagsInput } from "react-tag-input-component";
import './Components.css';
import AppData from '../App.json';

const RknCategoryEditorPopup = (props) => {

    const inputFieldStyle = 'bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 mt-2';

    const ref = useRef(null);

    const [id, setID] = useState(null);
    const [userInput, setUserInput] = useState("");
    const [emoji, setEmoji] = useState("");
    const [priceTiers, setPriceTiers] = useState([]);

    const handleOnOpen = () => {
        if (props.defaultValue) {
            console.log("DEFAULT VALUE = " + JSON.stringify(props.defaultValue));
            setID(props.defaultValue._id);
            setUserInput(props.defaultValue.name);
            setEmoji(props.defaultValue.icon);
            // ref.current.focus();
        } else {
            setID(null);
            setUserInput("");
            setEmoji("");
        }

        setTimeout(() => {
            ref.current.focus();
        }, 150);
    }

    const CloseModal = () => {
        if (props.onClose)
            props.onClose();
    }

    const handleUserInputChange = (event) => {
        setUserInput(event.target.value);
    }

    const handleConfirmOnClick = (event) => {

        event.preventDefault();

        if (props.onConfirm)
            props.onConfirm({ name: userInput, emoji: emoji, id: id, priceTiers: priceTiers });
    }

    const handlePriceTierOnChange = (ParamValue) => {
        setPriceTiers(ParamValue);
        // console.log("V = " + JSON.stringify(ParamValue));
    }

    return (
        <div>
            <Popup
                open={props.isOpen}
                modal
                closeOnDocumentClick
                onClose={() => { CloseModal(); }}
                onOpen={handleOnOpen}
            >
                <div className="modal bg-gray-900 text-gray-100 p-2">
                    <button className="close" onClick={() => { CloseModal(); }}>
                        <FaTimesCircle />
                    </button>
                    <div className="header">Saisissez votre texte</div>
                    <form onSubmit={handleConfirmOnClick} className="content flex flex-col items-center">
                        <br />
                        <input ref={ref} type="text" name='userInput' placeholder='...' value={userInput} className={inputFieldStyle} onChange={handleUserInputChange} />
                        <br />
                        <RknEmojiSelector onChange={(ParamEmoji) => setEmoji(ParamEmoji)} />
                        <br />
                        {/* <RknStringList /> */}
                        {AppData.PRICE_TIERS_FLAG &&
                            <div className='p-2 pt-1 border-2 border-gray-500 rounded-xl flex flex-col items-center justify-center'>
                                <div className='py-0 px-2 m-1 text-sm font-bold text-gray-300 bg-gray-700 rounded-full'>Paliers des Prix</div>
                                <TagsInput
                                    value={priceTiers}
                                    onChange={handlePriceTierOnChange}
                                    name="Prix"
                                    placeHolder="..."
                                    classNames={{
                                        input: "bg-gray-900 text-gray-100 p-1",
                                        tag: "bg-gray-900 text-gray-100 border border-gray-500"
                                    }}
                                />
                            </div>}
                        <br />
                        <RknSubmitButton label="Valider" onClick={handleConfirmOnClick} />
                    </form>
                </div>

            </Popup>
        </div>
    )
}

export default RknCategoryEditorPopup