import { React, useState, useEffect } from 'react';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';

const InventoryMovementCell = (props) => {

    const [result, setResult] = useState("?");
    const [amount, setAmount] = useState("?");
    const [diff, setDiff] = useState("?");

    useEffect(() => {
        PerformGetRequest("/api/inventory-movement?id=" + props.id, (res) => {
            setResult(res.data.result);
            setAmount(res.data.amount);
            setDiff(Number(res.data.result) - Number(res.data.amount));
        })
    }, [props.id]);

    return (
        <div className={`flex flex-col items-start justify-center rounded-lg m-1 p-1 ${result === amount ? "bg-green-900" : "bg-red-700"}`}>
            <div>Calculé : {result}</div>
            <div>Enregistré : {amount}</div>
            <div>Différence : {diff}</div>
        </div>
    )
}

export default InventoryMovementCell