import { React, useState, useEffect } from 'react';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';

const CateringMenu = () => {

    const [products, setProducts] = useState(null);

    useEffect(() => {
        PerformGetRequest("/api/get-product-list", (res) => { setProducts(res.data); });
    }, [])

    return (
        <div className='text-gray-100 text-xl font-bold grid grid-cols-2 w-screen'>
            {/* {products && JSON.stringify(products)} */}
            {products && products.map((p, i) => {
                return (<div className='flex flex-row m-1'>
                    <div className='w-3/4 bg-gray-700 rounded-l-xl border-2 border-gray-100 text-ellipsis'>{p.name}</div>
                    <div className='w-1/4 bg-gradient-to-b from-gray-800 to-gray-600 rounded-r-xl text-gray-100 border-2 border-gray-100 animate-pulse overflow-clip'>{p.price} DA</div>
                </div>)
            })}
        </div>
    )
}

export default CateringMenu