import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import { Link } from 'react-router-dom';
import RknIconButton from '../components/RknUI/RknIconButton';
import { FaEye } from 'react-icons/fa';

const ProformaInvoiceManager = () => {

    useEffect(() => {

        GetListFromDb();

    }, []);

    const [invoiceList, setInvoiceList] = useState(null);

    const columns = [
        {
            title: 'Vente',
            dataIndex: 'sourceID',
            key: 'sourceID',
            className: 'border border-gray-500',
            width: 64,
            render: s => <Link to={`/sales-point?id=${s}`} className='flex flex-row items-center justify-center' ><RknIconButton icon={<FaEye />} /></Link>
        },
        {
            title: 'Date',
            dataIndex: 'creationDate',
            key: 'creationDate',
            className: 'border border-gray-500',
            width: 256,
            render: d => <div className='inline text-sm'>{(new Date(d)).toLocaleDateString('fr-FR', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' })}</div>
        },
        {
            title: 'Référence',
            dataIndex: 'ref',
            key: 'ref',
            className: 'border border-gray-500',
            width: 128
        }
    ];

    const GetListFromDb = async () => {

        PerformGetRequest("/api/get-pf-invoice-list", (res) => setInvoiceList(res.data));

    }

    return (
        <div className='text-gray-100 flex flex-col items-center'>
            <br />
            <h3 className='text-xl font-bold'>Liste des Factures Proforma</h3>
            <br />
            {invoiceList && <Table columns={columns} data={invoiceList} rowKey="_id" />}
            <br />
            <br />
        </div>
    )
}

export default ProformaInvoiceManager