import React, { useState, useEffect } from 'react';
import RknNumericInput from '../components/RknUI/RknNumericInput';
import { PerformGetRequest, PerformGetRequest_Promise, PerformSecurePostRequest, PerformSecurePostRequestWithFormData } from '../Reaknotron/Libs/RknQueryTools';
import RknButton from '../components/RknUI/RknButton';
import { PulseLoader } from 'react-spinners';
import { useSearchParams, useNavigate } from 'react-router-dom';
import Table from 'rc-table';
import { FaCheckCircle, FaDownload, FaHome, FaKey, FaMagic, FaPrint, FaSave, FaTimesCircle, FaTruck } from 'react-icons/fa';
import { GenerateDischargeSheet } from '../Reaknotron/PDF/DischargeSheet';
import { GetPrinterName } from '../const';
import { InputFieldStyle } from '../Styles';
import RknDateInput from '../components/RknUI/RknDateInput';
import { render } from '@testing-library/react';

function InventoryEditor() {

    // Navigation
    const navigate = useNavigate();
    const [searchParams, setSearchParams] = useSearchParams();

    const [products, setProducts] = useState(null);
    const [targetID, setTargetID] = useState(null);
    const [changesAvailable, setChangesAvailable] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [errorMessage, setErrorMessage] = useState(null);
    const [finalized, setFinalized] = useState(false);

    const columns = [
        {
            title: 'Inclus',
            dataIndex: 'included',
            key: 'included',
            className: 'border border-gray-500',
            width: 64,
            render: i => i ? <div className='font-bold text-green-500 m-1 ml-5'><FaCheckCircle /></div> : <div className='font-bold text-neutral-800 m-1 ml-5'><FaTimesCircle /></div>
        },
        {
            title: 'Produit',
            dataIndex: 'productLabel',
            key: 'productLabel',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Ancienne Quantité',
            dataIndex: 'oldAmount',
            key: 'oldAmount',
            className: 'border border-gray-500',
            width: 128
        },
        {
            title: 'Nouvelle Quantité',
            dataIndex: 'newAmount',
            key: 'newAmount',
            className: 'border border-gray-500',
            width: 128
        },
        {
            title: 'Raison du Conflit',
            dataIndex: 'reason',
            key: 'reason',
            className: 'border border-gray-500',
            width: 128
        }
        // {
        //     title: 'En Movement',
        //     dataIndex: 'dischargedAmount',
        //     key: 'dischargedAmount',
        //     className: 'border border-gray-500',
        //     width: 128
        // }
    ];

    const InitNewInventorySheet = () => {
        PerformGetRequest("/api/get-product-list?resolveCategoryID=true&ignoreDeleted=true&sort=alpha&ds=1", (res) => {
            if (res) {
                // console.log("RESULT = " + JSON.stringify(ParamResult.data));

                let tmpProducts = [];

                res.data.forEach(p => {
                    let row = {
                        id: p._id,
                        productLabel: p.name,
                        oldAmount: p.availableAmount,
                        newAmount: 0,
                        expiryDate: null,
                        reason: "",
                        dischargedAmount: p.dischargedAmount,
                        included: false
                    };
                    tmpProducts.push(row);
                });

                setProducts(tmpProducts);
            }
        });
    }

    const LoadInventorySheetFromDB = (ParamID) => {
        PerformGetRequest("/api/get-inventory-sheet?id=" + ParamID, (res) => {
            setProducts(res.data.products);
            setFinalized(res.data.finalized);
        });
    }

    useEffect(() => {

        if (searchParams.get("id")) {
            LoadInventorySheetFromDB(searchParams.get("id"));
            setTargetID(searchParams.get("id"));
        }
        else {
            InitNewInventorySheet();
        }

    }, []);

    const handleNewAmountChange = (id, value) => {
        setProducts(products.map(row =>
            row.id === id ? {
                ...row,
                newAmount: Number(value)
            } : row
        ));
        setChangesAvailable(true);
    };

    const handleExpiryDateChange = (id, value) => {
        setProducts(products.map(row =>
            row.id === id ? {
                ...row,
                expiryDate: value
            } : row
        ));
        setChangesAvailable(true);
    };

    const handleReasonChange = (id, value) => {
        setProducts(products.map(row =>
            row.id === id ? {
                ...row,
                reason: value
            } : row
        ));
        setChangesAvailable(true);
    };

    const toggleIncluded = (id) => {
        setProducts(products.map(row =>
            row.id === id ? {
                ...row,
                included: !row.included
            } : row
        ));
        setChangesAvailable(true);
    };

    const Save = () => {

        if (finalized || isSaving)
            return;

        setIsSaving(true);

        let invToPost = { products: products };

        if (targetID) {

            // Update
            invToPost.id = targetID;
            PerformSecurePostRequest("/api/update-inventory-sheet", invToPost, async (res) => {
                setIsSaving(false);
                setChangesAvailable(false);
            });

        } else {

            // Save
            PerformSecurePostRequest("/api/new-inventory-sheet", invToPost, async (res) => {
                navigate('/inventory-sheet-editor?id=' + res.data.id);
                setTargetID(res.data.id);
                setIsSaving(false);
                setChangesAvailable(false);
            });

        }

    }

    const DownloadPDF = async () => {
        // const doc = await GenerateDischargeSheet(customerLabel, products, totalOfProducts, finalized);
        // doc.save("Fiche d'Inventaire.pdf");
    }

    const PrintPDF = async () => {

        // const doc = await GenerateDischargeSheet(customerLabel, products, totalOfProducts, finalized);

        // Build form
        const formData = new FormData();
        // formData.append("pdf", doc.output('blob'));

        PerformSecurePostRequestWithFormData("/printer/print?printer=" + GetPrinterName(), formData, (res) => {

        });
    }

    const handleFinalizeOnClick = () => {

        if (finalized || isSaving)
            return;

        setIsSaving(true);

        if (targetID) {

            let invToPost = { id: targetID, products: products };
            PerformSecurePostRequest("/api/finalize-inventory-sheet", invToPost, async (res) => {
                setFinalized(true);
                setIsSaving(false);
            });

        } else {
            setIsSaving(false);
        }
    }

    return (
        <div className='flex flex-col items-center justify-center text-gray-900 dark:text-gray-100'>
            <br />
            <h1 className='text-xl font-bold '>Fiche d'Inventaire</h1>
            <br />
            {!finalized && <div className="w-full overflow-x-auto">
                <table className="w-full text-left border-collapse text-sm mb-20">
                    <thead>
                        <tr>
                            <th className="border w-12 p-1">Inclus</th>
                            <th className="border pl-2 p-1">Produit</th>
                            <th className="border pl-2 p-1">Ancienne Quantité</th>
                            <th className="border pl-2 p-1">Nouvelle Quantité</th>
                            <th className="border pl-2 p-1">Date de Péremption</th>
                            <th className="border pl-2 p-1">Raison du Conflit</th>
                        </tr>
                    </thead>
                    <tbody>
                        {products && products.map(p => (
                            <tr key={p.id} className={p.included ? "opacity-100" : "opacity-40"} >
                                <td className="border p-1">
                                    <div onClick={() => toggleIncluded(p.id)} className='text-3xl'>
                                        {p.included ? <FaCheckCircle className='cursor-pointer text-green-600 active:scale-95 transition duration-150 hover:text-green-400' /> : <FaCheckCircle className='cursor-pointer text-neutral-800 active:scale-95 transition duration-150 hover:text-neutral-600' />}
                                    </div>
                                </td>
                                <td className="border h-20 px-2 p-1 flex flex-row items-center justify-start">
                                    {p.productLabel}
                                    <div className='flex flex-row items-center justify-center m-1 p-1 px-2 bg-gray-900 text-white rounded-full font-bold'><FaHome className='mr-1' />
                                        {p.oldAmount - p.dischargedAmount}
                                    </div>
                                    <div className='flex flex-row items-center justify-center m-1 p-1 px-2 bg-yellow-600 text-black rounded-full font-bold'><FaTruck className='mr-1' />
                                        {p.dischargedAmount}
                                    </div>
                                </td>
                                <td className="border pr-2 p-1">{p.oldAmount}</td>
                                <td className="border pr-2 p-1"><RknNumericInput width="128px" value={p.newAmount} onChange={(v) => handleNewAmountChange(p.id, v)} readOnly={!p.included} /></td>
                                <td className="border pr-2 p-1"> <RknDateInput value={p.expiryDate} onChange={(v) => handleExpiryDateChange(p.id, v)} /></td>
                                <td className="border pr-2 p-1"><input value={p.reason} className={InputFieldStyle} onChange={(e) => handleReasonChange(p.id, e.target.value)} /></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>}

            {finalized && <Table className='text-gray-100 m-1 mb-20' columns={columns} data={products} rowKey="id" />}

            {/* Bottom Tool Bar */}
            <div className='fixed z-20 bottom-0 right-0 left-0 bg-gray-900 text-white h-16 border-t-2 border-gray-500 flex flex-row items-center justify-center space-x-2'>
                {!errorMessage && !finalized && <RknButton className="w-40" label={isSaving ? <PulseLoader color='#AAAAAA' /> : "Enregistrer"} before={<FaSave />} onPress={() => Save(false)} disabled={!changesAvailable} />}
                {!isSaving && !errorMessage && !finalized && <RknButton className="w-40" label={isSaving ? <PulseLoader color='#AAAAAA' /> : "Finalizer"} before={<FaCheckCircle />} onPress={handleFinalizeOnClick} disabled={!targetID} />}
                {<RknButton className="w-44" label="Imprimer" before={<FaPrint />} onPress={PrintPDF} />}
                {<RknButton className="w-44" label="Télécharger" before={<FaDownload />} onPress={DownloadPDF} />}
                {/* {finalized && !isSaving && targetID && <RknButton className="w-44" label="Déverrouiller" before={<FaKey />} onPress={unlock} />} */}
            </div>

        </div>
    );
}

export default InventoryEditor;