import React, { useState, useEffect } from "react";
import { SyncLoader } from "react-spinners";
import FileSelectAndDrop from "../FileSelectAndDrop";
import { PerformSecurePostRequestWithFormData } from "../../Reaknotron/Libs/RknQueryTools";

const RknImageSelectAndUpload = (props) => {

    useEffect(() => {

        setURL(props.src);

        if (props && props.src) {
            setimgAvailable(true);
        }
    }, [props.src])

    const [selectedFile, setSelectedFile] = useState("");
    const [url, setURL] = useState();
    const [imgAvailable, setimgAvailable] = useState(false);
    const [isUploading, setIsUploading] = useState(false);

    const handleWideImgSelect = (event) => {

        const file = event.target.files[0];

        setSelectedFile(file);
        setURL(URL.createObjectURL(file));
        setimgAvailable(true);

        if (props.onChange) {
            props.onChange();
        }

        if (props.uploadURL) {

            setIsUploading(true);

            // Build form
            const formData = new FormData();

            // ID
            if (props.id) {
                formData.append("id", props.id);
            }

            formData.append("picture", file);

            if (props.version)
                formData.append("version", props.version);

            PerformSecurePostRequestWithFormData(props.uploadURL, formData, (res) => {

                setIsUploading(false);
                // setImageURL(await PerformImageGetRequest("/api/get-product-image?id=" + targetID));

                if (props.onUploadFinished) {
                    props.onUploadFinished();
                }
            });
        }

    }

    const handleWideImgClear = () => {
        setSelectedFile("");
        setimgAvailable(false);

        if (props.onChange) {
            props.onChange();
        }
    }

    return (
        <div className='flex flex-col items-center justify-center' >
            <label className="mb-1 text-sm font-medium text-gray-100">{props.label ? props.label : "???"}</label>

            {isUploading ?
                <div>
                    <SyncLoader color="#AAAAAA" />
                </div>
                :
                <div>
                    {!imgAvailable && <FileSelectAndDrop name="blackLogo" onChange={handleWideImgSelect} />}
                    {imgAvailable && <img src={url} alt="preview" className="object-cover h-64 w-64 m-auto border-2 border-gray-300 rounded-2xl" />}
                    {imgAvailable && <div className='text-xl text-gray-500 font-bold border-2 border-gray-500 rounded-2xl w-64 m-auto mt-1 hover:bg-gray-500 hover:text-gray-100' onClick={handleWideImgClear}>X</div>}
                </div>}

        </div>
    )
}

export default RknImageSelectAndUpload