import { React, useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { FaTimesCircle, FaCheckCircle } from 'react-icons/fa';
import RknDateInput from '../components/RknUI/RknDateInput';
import RknNumericInput from '../components/RknUI/RknNumericInput';
import { useTranslation } from 'react-i18next';
import RknButton from '../components/RknUI/RknButton';
import { InputFieldStyle } from '../Styles';

const GenerateInvoicePopup = (props) => {

    const { t } = useTranslation();

    // const probeRef = useRef(null);

    useEffect(() => {
        // setTimeout(() => { probeRef.current.focus(); }, 400);
    }, []);

    const [date, setDate] = useState(null);
    const [selectedPaymentMethod, setSelectedPaymentMethod] = useState('CASH');
    const [ref, setRef] = useState(0);
    const [checkIdNumber, setCheckIdNumber] = useState("");
    const [busy, setBusy] = useState(false);

    const TriggerPropsOnConfirm = () => {

        if (props.onConfirm) {
            props.onConfirm({ date: date, paymentMethod: selectedPaymentMethod, ref: ref, checkIdNumber: checkIdNumber });
        }
    }

    const OnSubmit = (e) => {
        setBusy(true);
        e.preventDefault();
        TriggerPropsOnConfirm();
    }

    const TriggerPropsOnCancel = () => {
        if (props.onCancel)
            props.onCancel();
    }

    const handlePaymentMethodChange = (event) => {
        setSelectedPaymentMethod(event.target.value);
    };

    return (
        <motion.div
            className='fixed top-0 left-0 right-0 z-10 flex flex-col items-center justify-center w-screen h-screen bg-black bg-opacity-60 backdrop-blur-lg'
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.3 }}
        >
            <motion.div
                className='flex flex-col items-center justify-center p-8 m-auto text-gray-100 bg-gray-900 border-4 border-gray-500 rounded-3xl w-96'
                initial={{ opacity: 0, y: "-50%" }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.3 }}
            >
                <h3 className='mb-4 text-xl font-bold text-gray-100'>{t("pos.toolbar.invoice.generateInvoice")}</h3>

                <form onSubmit={OnSubmit} className='flex flex-col items-center justify-center w-80'>

                    <label className='text-sm'>{t("pos.toolbar.invoice.date")} :</label>
                    <RknDateInput onChange={setDate} />

                    <label className='mt-4 text-sm'>Référence :</label>
                    <RknNumericInput value={ref} onChange={(v) => setRef(v)} placeholder="Référence..." />

                    {/* Payment Method */}
                    <label className='mt-4 text-sm'>{t("pos.toolbar.quote.paymentTerms")} :</label>
                    <select name="state" className="py-1 mx-4 text-sm text-gray-900 border border-gray-300 rounded-lg bg-gray-50 focus:ring-blue-500 focus:border-blue-500 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500"
                        defaultValue="CASH"
                        onChange={handlePaymentMethodChange}
                    >
                        <option value="CASH">💰  {t("pos.toolbar.quote.paymentMethods.cash")}</option>
                        <option value="CHECK">💶  {t("pos.toolbar.quote.paymentMethods.check")}</option>
                        <option value="BANK_TRANSFER">💹  {t("pos.toolbar.quote.paymentMethods.bankTransfer")}</option>
                        <option value="BANK_CARD">💳  {t("pos.toolbar.quote.paymentMethods.creditCard")}</option>
                        <option value="MOBILE_PAYMENT">📱  {t("pos.toolbar.quote.paymentMethods.mobilePayment")}</option>
                        <option value="ELECTRONIC_WALLET">🛄  {t("pos.toolbar.quote.paymentMethods.eWallet")}</option>
                        <option value="VIRTUAL_CURRENCY">✨ {t("pos.toolbar.quote.paymentMethods.cryptocurrency")}</option>
                    </select>

                    {/* <label className='mt-4 text-sm'>{t("pos.toolbar.invoice.ref")} :</label>
                    <RknNumericInput value={ref} onChange={(v) => setRef(v)} placeholder="..." /> */}

                    {selectedPaymentMethod === "CHECK" &&
                        <motion.div
                            className='flex flex-col items-center justify-center mb-2'
                            initial={{ opacity: 0, y: "-15%" }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ duration: 0.3 }}
                        >
                            <label>N° de Chèque : </label>
                            <input type='text' value={checkIdNumber} className={InputFieldStyle} placeholder="Numéro de Chèque..." onChange={(e) => { setCheckIdNumber(e.target.value); }} />
                        </motion.div>
                    }

                    <div className='flex flex-row items-center justify-center mt-4'>
                        {/* <button type='submit' className="px-4 py-2 font-bold text-white bg-blue-500 border-b-4 border-blue-700 rounded hover:bg-blue-400 hover:border-blue-500">  { }</button> */}
                        <RknButton label={t("button.confirm")} before={<FaCheckCircle className='inline mb-1' size={20} />} submit busy={busy} />
                        <span className='mx-2'></span>
                        <button type='button' onClick={TriggerPropsOnCancel} className="px-4 py-2 font-bold text-white bg-blue-500 border-b-4 border-blue-700 rounded hover:bg-blue-400 hover:border-blue-500"><FaTimesCircle className='inline mb-1' size={20} />  {t("button.cancel")}</button>
                    </div>

                </form>
                <br />

            </motion.div>
        </motion.div>
    )
}

export default GenerateInvoicePopup