import { React, useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { FaTimesCircle, FaCheckCircle, FaTrash } from 'react-icons/fa';
import hotkeys from 'hotkeys-js';
import { PulseLoader } from 'react-spinners';
import AppData from '../App.json';
import { PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import RknNumericInput from './RknUI/RknNumericInput';
import RknDateInput from './RknUI/RknDateInput';
import { IsIsoDate } from '../Reaknotron/Libs/RknTimeTools';
import { ConvertDateToISO } from '../Reaknotron/Libs/RknTimeTools';

const UpdateClockingEventPopup = (props) => {

    const hourRef = useRef(null);

    useEffect(() => {

        console.log("USE EFFECT : E = " + JSON.stringify(props.ece));

        if (props.ece && IsIsoDate(props.ece.time)) {
            setTime(props.ece.time);
            const d = new Date(props.ece.time);
            setHour(d.getHours());
            setMinute(d.getMinutes());
        }

        setTimeout(() => { hourRef.current.focus(); }, 150);
    }, []);

    useEffect(() => {

        hotkeys.filter = function (event) {
            var tagName = (event.target || event.srcElement).tagName;
            hotkeys.setScope(/^(INPUT|TEXTAREA|SELECT)$/.test(tagName) ? 'input' : 'other');
            return true;
        }

        hotkeys('escape', event => {
            event.preventDefault();
            TriggerPropsOnCancel();
        });

        return () => {
            hotkeys.unbind('escape');
        }

    }, []);

    // Basic
    const [time, setTime] = useState(null);
    const [hour, setHour] = useState("");
    const [minute, setMinute] = useState("");
    const [timestamp, setTimestamp] = useState(null);
    const [type, setType] = useState('');
    const [saving, setSaving] = useState(false);

    useEffect(() => {
        if (time && IsIsoDate(time) && hour && minute) {
            let d = new Date(time);
            d.setHours(hour);
            d.setMinutes(minute);
            // const iso = ConvertDateToISO(d);
            // console.log("ISO = " + iso);
            setTimestamp(d);
        }
    }, [time, hour, minute]);

    const TriggerPropsOnConfirm = (ParamNewVersion) => {

        if (props.onConfirm) {
            props.onConfirm(ParamNewVersion);
        }

    }

    const OnSubmit = (e) => {
        e.preventDefault();
        // TriggerPropsOnConfirm();
        UpdateClockingEventInDB();
    }

    const TriggerPropsOnCancel = () => {
        if (props.onCancel)
            props.onCancel();
    }

    const UpdateClockingEventInDB = async () => {

        setSaving(true);

        try {

            const eceToPost = { id: props.ece._id, time: timestamp, type: type };

            PerformSecurePostRequest("/api/update-ece", eceToPost, (res) => {
                TriggerPropsOnConfirm(eceToPost);
                setSaving(false);
            });

        } catch (error) {
            console.log("ERROR : " + error);

            if (error.response && error.response.status >= 400 && error.response.status <= 500) {
                console.log(error.response.data);
            }

            setSaving(false);
        }
    }

    const handleChange = (event) => {
        setType(event.target.value);
    }

    return (
        <motion.div
            className='fixed top-0 right-0 left-0 w-screen h-screen bg-black bg-opacity-60 z-10 flex flex-col items-center justify-center backdrop-blur-lg'
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.3 }}
        >
            <motion.div
                className='bg-gray-900 border-4 border-gray-500 rounded-3xl m-auto w-1/2 p-4 pb-0 flex flex-col items-center justify-center'
                initial={{ opacity: 0, y: "-50%" }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.3 }}
            >
                <h1 className='mb-0.5 font-bold text-gray-100 text-lg'>Edition Pointage</h1>
                <h2 className='mb-2 font-bold text-gray-500 text-xs'>Employé : {props.ece.employee}</h2>

                <form onSubmit={OnSubmit} className='flex flex-col items-center justify-center'>

                    <select className='bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-0.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 h-8 my-3 w-48' value={type} onChange={handleChange}>
                        <option value="">Selectionnez une Action...</option>
                        <option value="ENTRY">Entrée</option>
                        <option value="EXIT">Sortie</option>
                    </select>

                    <div className='bg-gray-800 p-4 pt-2 rounded-xl'>
                        <div className='flex flex-row items-center justify-start my-3'>
                            <label className="mr-2 text-sm font-medium text-gray-900 dark:text-white">Date</label>
                            <RknDateInput value={time} onChange={setTime} />
                        </div>

                        <div className='flex flex-row items-center justify-start my-1'>
                            <label className="mr-2 text-sm font-medium text-gray-900 dark:text-white">Heure</label>
                            <RknNumericInput width={65} value={hour} ref={hourRef} onChange={(v) => setHour(v)} placeholder='Heure...' />
                            <label className="mx-1 mr-1.5 text-sm font-medium text-gray-900 dark:text-white">:</label>
                            <RknNumericInput width={65} value={minute} onChange={(v) => setMinute(v)} placeholder='Minute...' />
                        </div>

                        <div className='text-xs text-gray-600 mt-4'>{timestamp ? JSON.stringify(timestamp) : "-"}</div>
                    </div>

                    <div className='flex flex-row items-center justify-center mt-6'>
                        {type && <div>
                            <button type='submit' className="bg-blue-500 hover:bg-blue-400 text-white font-bold py-2 px-4 border-b-4 border-blue-700 hover:border-blue-500 rounded">{saving ? <PulseLoader color='#AAAAAA' /> : <div><FaCheckCircle className='inline mb-1' size={20} /> Confirmer</div>}</button>
                            <span className='mx-2'></span>
                        </div>}
                        <button type='button' onClick={TriggerPropsOnCancel} className="bg-blue-500 hover:bg-blue-400 text-white font-bold py-2 px-4 border-b-4 border-blue-700 hover:border-blue-500 rounded"><FaTimesCircle className='inline mb-1' size={20} /> Annuler</button>
                    </div>
                </form>
                <br />

            </motion.div>
        </motion.div>
    )
}

export default UpdateClockingEventPopup