import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import { AwesomeButton } from 'react-awesome-button';
import { FaEdit, FaPlus, FaTrash } from 'react-icons/fa';
import { Link } from 'react-router-dom';
import useDocumentTitle from '@tanem/use-document-title';
import { PerformGetRequest, PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import RknPageSelector from '../components/RknUI/RknPageSelector';
import { StringToNumber_2DecAtMost } from '../Reaknotron/Libs/RknStringTools';

const ReceptionList = () => {

    // Title
    useDocumentTitle("Gestion des Réceptions");

    const [receptionList, setReceptionList] = useState();
    const [currentPage, setCurrentPage] = useState(1);
    const [maxPage, setMaxPage] = useState(1);

    const GetReceptionList = () => {
        PerformGetRequest(`/api/get-reception-list-ready?size=10&page=${currentPage}`, (res) => {
            if (res) {
                setMaxPage(res.data.totalPages);
                setReceptionList(res.data.paginatedResults);
                // UpdateTableData(res.data.paginatedResults);
            }
        });
    }

    useEffect(() => {

        GetReceptionList();

    }, [currentPage]);

    const DeleteReceptionInDb = (ParamID) => {
        PerformSecurePostRequest("/api/delete-reception", { id: ParamID }, (res) => {
            GetReceptionList();
        });
    }

    const GenerateOperationButtons = (ParamItem) => {

        const buttonStyle = 'bg-gray-900 text-gray-100 rounded-lg p-2 my-2 mx-1 text-sm hover:bg-gray-700 inline';

        if (ParamItem) {
            return (
                <div className='flex flex-row'>
                    {<button className={buttonStyle}> <Link to={"/reception-editor?id=" + ParamItem.id}> <FaEdit size={20} /></Link> </button>}
                    {!ParamItem.stockageDone && <button className={buttonStyle} onClick={() => { DeleteReceptionInDb(ParamItem.id) }}> <FaTrash size={20} /> </button>}
                </div>
            )
        }

        return "N/A";
    }

    const columns = [
        {
            title: 'Opérations',
            dataIndex: '',
            key: 'operations',
            width: 128,
            className: 'border border-gray-500',
            render: r => GenerateOperationButtons(r)
        },
        {
            title: 'Date',
            dataIndex: 'time',
            key: 'time',
            className: 'border border-gray-500',
            width: 128,
            render: d => <div className='inline text-sm'>{(new Date(d)).toLocaleDateString('fr-FR', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' })}</div>
        },
        {
            title: 'Fournisseur',
            dataIndex: 'provider',
            key: 'provider',
            width: 256,
            className: 'border border-gray-500'
        },
        {
            title: 'Produits',
            dataIndex: 'products',
            key: 'products',
            width: 96,
            className: 'border border-gray-500'
        },
        {
            title: 'Total',
            dataIndex: 'total',
            key: 'total',
            width: 128,
            className: 'border border-gray-500',
            render: t => StringToNumber_2DecAtMost(t)
        },
        {
            title: 'Etat',
            key: 'stockageDone',
            width: 128,
            className: 'border border-gray-500',
            render: i => i.stockageDone ?
                <Link to={'/reception-editor?id=' + i.id}
                    // onClick={() => { console.log(i.id); }}
                    className='p-1 m-1 text-sm font-bold bg-green-800 border-2 border-green-500 rounded-xl cursor-pointer'>Stockée</Link>
                :
                <Link to={'/reception-editor?id=' + i.id}
                    // onClick={() => { console.log(i.id); }}
                    className='p-1 m-1 text-sm border-2 border-neutral-500 text-gray-300 rounded-xl cursor-pointer'>En attente...</Link>
        }
    ];

    const handlePageChange = (ParamPage) => {
        setCurrentPage(ParamPage);
    }

    return (
        <div className='text-gray-100 flex flex-col items-center justify-center'>
            <br />
            <h3 className='text-xl font-bold'>Liste des Réception</h3>
            <br />
            <AwesomeButton before={<FaPlus />}><a href='/reception-editor'>Ajouter Une Réception</a></AwesomeButton>
            <br />
            <br />
            <div className='flex flex-col items-center'>
                <Table columns={columns} data={receptionList} rowKey="id" />
            </div>
            <br />
            <RknPageSelector max={maxPage} onChange={handlePageChange} />
            <br />
        </div>
    )
}

export default ReceptionList