import React, { useState, useEffect } from 'react';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import { BarChart, Bar, XAxis, YAxis, ResponsiveContainer } from 'recharts';
import Table from 'rc-table';

const DashboardStatistics = () => {

    useEffect(() => {

        PerformGetRequest("/api/statistics", (res) => {
            setStats(res.data);

            let tmpSnrData = [
                { label: "Réc. (Total)", value: res.data.reception.total },
                { label: "Réc. (Payé)", value: res.data.reception.fullfilled },
                { label: "Ventes (Total)", value: res.data.sales.total },
                { label: "Ventes (Final)", value: res.data.sales.totalToPay },
                { label: "Bénéfice", value: res.data.sales.profit },
                { label: "R.D.C.", value: res.data.returnSlips.returnFromCustomer },
                { label: "R.V.F.", value: res.data.returnSlips.returnToProvider }
            ];

            setSnrData(tmpSnrData);

            const income = Number(res.data.sales.total) + Number(res.data.returnSlips.returnToProvider);
            const expense = Number(res.data.reception.total) + Number(res.data.returnSlips.returnFromCustomer);
            const netIncome = income - expense;

            let tmpTableData = [
                { label: "Revenus", value: income },
                { label: "Dépenses", value: expense },
                { label: "Revenus Net", value: netIncome }
            ];

            setTableData(tmpTableData);
        });

    }, []);

    const columns = [
        {
            title: '',
            dataIndex: 'label',
            key: 'label',
            className: 'border-4 border-gray-500 p-2 font-bold',
            width: 196
        },
        {
            title: 'Montant',
            dataIndex: 'value',
            key: 'value',
            className: 'border-4 border-gray-500 p-2',
            width: 512
        }
    ];

    const columns_final = [
        {
            title: '',
            dataIndex: 'label',
            key: 'label',
            className: 'border-4 border-gray-500 p-2 font-bold',
            width: 256
        },
        {
            title: 'Montant',
            dataIndex: 'value',
            key: 'value',
            className: 'border-4 border-gray-500 p-2',
            width: 512
        }
    ];

    const [stats, setStats] = useState(null);
    const [snrData, setSnrData] = useState(null);
    const [tableData, setTableData] = useState(null);
    // const [snrData, setSnrData] = useState([
    //     { label: "Réc. (Total)", value: "100000" },
    //     { label: "Réc. (Payé)", value: "80000" },
    //     { label: "Ventes (Total)", value: "60000" },
    //     { label: "Bénéfice (Total)", value: "15000" },
    //     { label: "R.D.C.", value: "4500" },
    //     { label: "R.V.F.", value: "8000" }
    // ]);

    return (
        <div className='text-gray-100 flex flex-col items-center justify-center'>
            <div className='mt-4 text-3xl font-bold'>Statistiques</div>
            {/* {stats && <div>{JSON.stringify(stats)}</div>} */}
            {/* {snrData && <div>{JSON.stringify(snrData)}</div>} */}

            {snrData &&
                <div className='flex flex-row h-96 mt-4 space-x-4'>
                    {/* <ResponsiveContainer width={"100%"} height={"100%"}> */}
                    <BarChart
                        width={768}
                        height={384}
                        data={snrData}
                        className=''
                    // layout="vertical"
                    // layout="horizontal"
                    // margin={{ top: 1, right: 1, bottom: 1, left: 1 }}  // Ajustez la marge gauche pour les étiquettes
                    >
                        <YAxis type="number" tick={{ fill: '#CCCCCC' }} tickLine={{ stroke: '#CCCCCC' }} />
                        <XAxis dataKey="label" type="category" fontSize={14} tick={{ fill: '#CCCCCC' }} tickLine={{ stroke: '#CCCCCC' }} />
                        <Bar
                            dataKey="value"
                            fill='#CCCCCC'
                        // label={{ position: "left" }}  // Positionne l'étiquette à gauche de la barre
                        />
                    </BarChart>
                    {/* </ResponsiveContainer> */}
                    <div className='mt-4 h-64'>
                        <Table className='text-gray-100' columns={columns} data={snrData} rowKey="label" />
                    </div>
                </div>
            }

            {tableData && <Table className='text-gray-100 text-3xl' columns={columns_final} data={tableData} rowKey="label" />}
        </div>
    )
}

export default DashboardStatistics