import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import { FaDollarSign, FaEdit, FaPlus } from 'react-icons/fa';
import RknButton from '../components/RknUI/RknButton';
import { Link } from 'react-router-dom';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import BalancePaymentPopup from '../components/BalancePaymentPopup';
import { CheckPrivilege } from '../LoginManager';

const EstablishmentManager = () => {

    useEffect(() => {

        GetEstablishmentListFromDb();

    }, []);

    const [estList, setEstList] = useState();
    const [currentPaymentEstID, setCurrentPaymentEstID] = useState(null);

    const columns = [
        {
            title: 'Opérations',
            dataIndex: '',
            key: 'operation',
            className: 'border border-gray-500',
            width: 64,
            render: e =>
                <div className='flex flex-row items-center justify-center'>
                    {CheckPrivilege("ESTABLISHMENT_MANAGEMENT") && <Link className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' to={"/establishment-editor?id=" + e._id} ><FaEdit /></Link>}
                    {CheckPrivilege("ESTABLISHMENT_MANAGEMENT") && <div className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' onClick={() => { setCurrentPaymentEstID(e._id); }}><FaDollarSign /></div>}
                </div>
        },
        {
            title: 'Designation',
            dataIndex: '',
            key: 'designation',
            className: 'border border-gray-500',
            width: 256,
            render: (e) => <Link to={"/establishment-editor?id=" + e._id}>{e.designation}</Link>
        },
        {
            title: 'Catégorie',
            dataIndex: 'category',
            key: 'category',
            className: 'border border-gray-500',
            width: 256,
            render: c => c && <div>{c.icon || ""} {c.name || "?"}</div>
        },
        {
            title: 'Solde',
            dataIndex: 'balance',
            key: 'balance',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Client',
            dataIndex: 'isCustomer',
            key: 'isCustomer',
            className: 'border border-gray-500',
            width: 256,
            render: (c) => c ? <div className='text-gray-100 font-bold'>Oui</div> : <div className='text-neutral-600'>Non</div>
        },
        {
            title: 'Fournisseur',
            dataIndex: 'isProvider',
            key: 'isProvider',
            className: 'border border-gray-500',
            width: 256,
            render: (p) => p ? <div className='text-gray-100 font-bold'>Oui</div> : <div className='text-neutral-600'>Non</div>
        }
    ];

    const GetEstablishmentListFromDb = async () => {

        PerformGetRequest("/api/get-establishment-list", (res) => {
            console.log("RESULT = " + JSON.stringify(res.data));
            setEstList(res.data);
        });

    }

    const handleOnConfirmPayment = (ParamValue) => {
        GetEstablishmentListFromDb();
        setCurrentPaymentEstID(null);
    }

    return (
        <div className='text-gray-100 flex flex-col items-center'>
            <br />
            <h3 className='text-xl font-bold'>Liste des Etablissements</h3>
            <br />
            <Link to='/establishment-editor'><RknButton label="Ajouter Un Etablissement" before={<FaPlus />} /></Link>
            <br />
            <br />
            <div className='flex flex-col items-center'>
                <Table columns={columns} data={estList} rowKey="_id" />
            </div>
            {currentPaymentEstID && <BalancePaymentPopup onCancel={() => { setCurrentPaymentEstID(null); }} onConfirm={handleOnConfirmPayment} establishmentID={currentPaymentEstID} />}
            <br />
            <br />
        </div>
    )
}

export default EstablishmentManager