import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import { PerformGetRequest, PerformSecurePostRequest, PerformImageGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import RknInputDialog from '../components/RknUI/RknInputDialog';
import { FaIdCard, FaLocationArrow, FaMailBulk, FaUser, FaCheckCircle, FaHourglass, FaEdit, FaTrash, FaDollarSign } from 'react-icons/fa';
import RknButton from '../components/RknUI/RknButton';
import { GenerateInvoice } from '../Reaknotron/PDF/Invoice';
import AppData from '../App.json';
import { StringToNumber_2DecAtMost } from '../Reaknotron/Libs/RknStringTools';
import { Link } from 'react-router-dom';
import RknConfirmationPopup from '../components/RknUI/RknConfirmationPopup';

import { useTranslation } from 'react-i18next';

const SalesList = () => {

    const { t } = useTranslation();

    const GetSalesListFromDB = (ParamCustomer, ParamChecksOnly) => {

        let url = "/api/get-sales-list?dummy=1";

        if (ParamCustomer)
            url += "&customer=" + ParamCustomer;

        if (ParamChecksOnly)
            url += "&checks=true";

        PerformGetRequest(url, (res) => { setSalesList(res.data); });
    }

    useEffect(() => {
        GetSalesListFromDB(null, null);

        PerformGetRequest("/api/get-establishment-list", (res) => {
            // console.log(JSON.stringify(res.data));
            setCustomers(res.data);
        });
    }, []);

    const [salesList, setSalesList] = useState();
    const [eComSalesList, setEComSalesList] = useState();
    const [currentPaymentSale, setCurrentPaymentSale] = useState(null);
    const [displayType, setDisplayType] = useState("POS");
    const [customers, setCustomers] = useState(null);
    const [selectedCustomer, setSelectedCustomer] = useState(null);
    const [deleteSalePopupTarget, setDeleteSalePopupTarget] = useState(null);
    const [redeemCheckPopupTarget, setRedeemCheckPopupTarget] = useState(null);

    const GeneratePricingAndPaymentInfo = (ParamTotal, ParamAmountToPay, ParamFullfilledPayment, i) => {

        try {

            return (
                <div className='flex flex-col items-start p-1 text-xs font-bold bg-gray-900 justify-items-start '>
                    <div>{"Prix Total : " + ParamTotal + " DA"}</div>
                    <div>{"Prix Final : " + ParamAmountToPay + " DA"}</div>
                    <div>{"Remise : " + Number(Number(ParamTotal) - Number(ParamAmountToPay)) + " DA"}</div>
                    <div>{"Montant Payé : " + ParamFullfilledPayment + " DA"}</div>
                    <div>{"Reste à Payé : " + Number(Number(ParamAmountToPay) - Number(ParamFullfilledPayment)) + " DA"}</div>
                </div>
            )

        } catch (error) {
            return "?";
        }
    }

    const columns_2 = [
        {
            title: t('salesList.table.cols2.state'),
            dataIndex: 'finalized',
            key: 'finalized',
            className: 'border border-gray-500',
            width: 32,
            render: f => f ? <FaCheckCircle size={16} className='ml-1 text-green-500' /> : <FaHourglass size={16} className='ml-1 text-neutral-700' />
        },
        {
            title: t('salesList.table.cols2.action'),
            dataIndex: '',
            key: 'action',
            className: 'border border-gray-500',
            width: 32,
            render: s =>
                <div className='flex flex-row items-center justify-center'>
                    <Link className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' to={"/sales-point?id=" + s._id}><FaEdit /></Link>
                    {/* {s.finalized === false && <div className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' onClick={() => { handleDeleteOnClick(s._id); }} ><FaTrash /></div>} */}
                    <div className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' onClick={() => { setDeleteSalePopupTarget(s._id); }} ><FaTrash /></div>
                    {/* <div className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' onClick={() => { setCurrentPaymentSale(s._id); }}><FaDollarSign /></div>
                    <div className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' onClick={() => { DownloadInvoicePDF(s.customerID, s.products, s.paymentMethod); }}><FaDownload /></div> */}
                </div>
        },
        {
            title: t('salesList.table.cols2.date'),
            dataIndex: 'time',
            key: 'time',
            className: 'border border-gray-500',
            width: 256,
            render: d => <p className='inline text-sm'>{d ? (new Date(d)).toLocaleDateString('fr-FR', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' }) : "-"}</p>
        },
        {
            title: t('salesList.table.cols2.product'),
            dataIndex: 'products',
            key: 'products',
            className: 'border border-gray-500',
            width: 96,
            render: p => <p className='inline'>{(p && Object.keys(p)) ? Object.keys(p).length : "-"}</p>
        },
        // {
        //     title: 'Prix & Paiement',
        //     dataIndex: '',
        //     key: 'pnp',
        //     className: 'border border-gray-500',
        //     width: 256,
        //     render: i => <div>{GeneratePricingAndPaymentInfo(i.totalPrice, i.amountToPay, i.fulfilledPaiement, i)}</div>
        // },
        {
            title: t('salesList.table.cols2.totalPrice'),
            dataIndex: '',
            key: 'pt',
            className: 'border border-gray-500',
            width: 196,
            render: i => <div>{i.totalPrice}</div>
        },
        {
            title: t('salesList.table.cols2.finalPrice'),
            dataIndex: '',
            key: 'pf',
            className: 'border border-gray-500',
            width: 196,
            render: i => <div>{i.amountToPay}</div>
        },
        {
            title: t('salesList.table.cols2.discount'),
            dataIndex: '',
            key: 'r',
            className: 'border border-gray-500',
            width: 128,
            render: i => <div>{Number(Number(i.totalPrice) - Number(i.amountToPay))} ({100 - Math.round((Number(i.amountToPay) / Number(i.totalPrice) * 100))} %)</div>
        },
        {
            title: t('salesList.table.cols2.profit'),
            dataIndex: 'profit',
            key: 'profit',
            className: 'border border-gray-500',
            width: 128,
            render: i => <div>{StringToNumber_2DecAtMost(i)}</div>
        },
        {
            title: t('salesList.table.cols2.client'),
            dataIndex: '',
            key: 'establishment',
            className: AppData.CUSTOMER_NAME_IN_SALES_POINT ? 'border border-gray-500' : 'hidden',
            width: 256,
            render: s => <div>{(s.establishment && s.establishment.designation) ? s.establishment.designation : "?"}</div>
        },
        {
            title: t('salesList.table.cols2.paid'),
            dataIndex: '',
            key: 'fulfilledPaiement',
            className: AppData.CUSTOMER_NAME_IN_SALES_POINT ? 'border border-gray-500' : 'hidden',
            width: 196,
            render: i => <div>{Number(i.fulfilledPaiement)} ({Math.round((Number(i.fulfilledPaiement) / Number(i.amountToPay) * 100))} %)</div>
        },
        {
            title: t('salesList.table.cols2.remaining'),
            dataIndex: '',
            key: 'remaining',
            className: AppData.CUSTOMER_NAME_IN_SALES_POINT ? 'border border-gray-500' : 'hidden',
            width: 196,
            render: i => <div className={(Number(i.amountToPay) - Number(i.fulfilledPaiement)) > 0 ? 'text-red-600 font-bold' : 'text-green-500'}>{Number(i.amountToPay) - Number(i.fulfilledPaiement)} ({100 - Math.round((Number(i.fulfilledPaiement) / Number(i.amountToPay) * 100))} %)</div>
        }
    ];

    const columns_mobile = [
        {
            title: t('salesList.table.colsMobile.state'),
            dataIndex: 'finalized',
            key: 'finalized',
            className: 'border border-gray-500',
            width: 32,
            render: f => f ? <FaCheckCircle size={16} className='ml-1 text-green-500' /> : <FaHourglass size={16} className='ml-1 text-neutral-700' />
        },
        {
            title: t('salesList.table.colsMobile.action'),
            dataIndex: '',
            key: 'action',
            className: 'border border-gray-500',
            width: 32,
            render: s =>
                <div className='flex flex-row items-center justify-center'>
                    <Link className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' to={"/sales-point?id=" + s._id}><FaEdit /></Link>
                    {s.finalized === false && <div className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' onClick={() => { handleDeleteOnClick(s._id); }} ><FaTrash /></div>}
                    {/* <div className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' onClick={() => { setCurrentPaymentSale(s._id); }}><FaDollarSign /></div>
                    <div className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' onClick={() => { DownloadInvoicePDF(s.customerID, s.products, s.paymentMethod); }}><FaDownload /></div> */}
                </div>
        },
        {
            title: t('salesList.table.colsMobile.client'),
            dataIndex: 'customer',
            key: 'customer',
            className: AppData.CUSTOMER_NAME_IN_SALES_POINT ? 'border border-gray-500' : 'hidden',
            width: 256,
            render: c => <div>{c ? c.firstName + " " + c.familyName : "?"}</div>
        },
        {
            title: t('salesList.table.colsMobile.detail'),
            dataIndex: '',
            key: 'details',
            className: 'border border-gray-500',
            width: 320,
            render: i =>
                <div className='pl- 1 py-0.5 flex flex-col items-start justify-center'>
                    <div>Prix Final : {i.amountToPay} DA</div>
                    <div>Bénéfice : {i.profit} DA</div>
                    <div className={(Number(i.amountToPay) - Number(i.fulfilledPaiement)) > 0 ? 'text-red-600 font-bold' : 'text-green-500'}>Restant : {Number(i.amountToPay) - Number(i.fulfilledPaiement)} ({100 - Math.round((Number(i.fulfilledPaiement) / Number(i.amountToPay) * 100))} %)</div>
                </div>
        }
    ];

    const columns_check = [
        {
            title: t('salesList.table.colsMobile.state'),
            dataIndex: 'checkRedeemed',
            key: 'checkRedeemed',
            className: 'border border-gray-500',
            width: 32,
            render: f => f ? <FaCheckCircle size={16} className='ml-1 text-green-500' /> : <FaHourglass size={16} className='ml-1 text-neutral-700' />
        },
        {
            title: t('salesList.table.cols2.action'),
            dataIndex: '',
            key: 'action',
            className: 'border border-gray-500',
            width: 32,
            render: s =>
                <div className='flex flex-row items-center justify-center'>
                    <Link className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' to={"/sales-point?id=" + s._id}><FaEdit /></Link>
                    <div className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' onClick={() => { setDeleteSalePopupTarget(s._id); }} ><FaTrash /></div>
                    {!s.checkRedeemed && <div className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' onClick={() => { setRedeemCheckPopupTarget(s._id); }} ><FaDollarSign /></div>}
                </div>
        },
        {
            title: t('salesList.table.cols2.date'),
            dataIndex: 'time',
            key: 'time',
            className: 'border border-gray-500',
            width: 256,
            render: d => <p className='inline text-sm'>{d ? (new Date(d)).toLocaleDateString('fr-FR', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' }) : "-"}</p>
        },
        {
            title: t('salesList.table.cols2.product'),
            dataIndex: 'products',
            key: 'products',
            className: 'border border-gray-500',
            width: 96,
            render: p => <p className='inline'>{(p && Object.keys(p)) ? Object.keys(p).length : "-"}</p>
        },
        {
            title: t('salesList.table.cols2.totalPrice'),
            dataIndex: '',
            key: 'pt',
            className: 'border border-gray-500',
            width: 196,
            render: i => <div>{i.totalPrice}</div>
        },
        {
            title: t('salesList.table.cols2.finalPrice'),
            dataIndex: '',
            key: 'pf',
            className: 'border border-gray-500',
            width: 196,
            render: i => <div>{i.amountToPay}</div>
        },
        {
            title: t('salesList.table.cols2.client'),
            dataIndex: 'customer',
            key: 'customer',
            className: AppData.CUSTOMER_NAME_IN_SALES_POINT ? 'border border-gray-500' : 'hidden',
            width: 256,
            render: c => <div>{c ? c.firstName + " " + c.familyName : "?"}</div>
        },
        {
            title: "N° de Chèque",
            dataIndex: 'checkIdNumber',
            key: 'checkIdNumber',
            className: 'border border-gray-500',
            width: 256
        }
    ];

    const handleOnConfirmPayment = (ParamValue) => {
        PerformSecurePostRequest("/api/perform-sale-payment", { id: currentPaymentSale, amount: Number(ParamValue) }, (res) => {
            PerformGetRequest("/api/get-sales-list", (res) => { setSalesList(res.data); console.log(JSON.stringify(res.data)); });
            setCurrentPaymentSale(null);
        });
    }

    const handleDisplayTypeChange = (e) => {
        // console.log(e.target.value);
        setDisplayType(e.target.value);

        if (e.target.value == "POS")
            GetSalesListFromDB(null, null);
        else if (e.target.value == "CHECK")
            GetSalesListFromDB(null, true);
        else
            PerformGetRequest("/api/get-ecom-sales", (res) => { setEComSalesList(res.data); });
    }

    // const DownloadInvoicePDF = async (ParamCustomer, ParamProducts, ParamPaymentMethod) => {

    //     let items = [];

    //     Object.keys(ParamProducts).forEach((k) => {
    //         // tmpTotal += tmp[k].price * tmp[k].amount;
    //         const p = ParamProducts[k];

    //         let unit = "Pcs";
    //         if (p.unit && p.unit != "undefined") {
    //             unit = p.unit;
    //         }

    //         items.push({ name: p.name, quantity: p.amount, price: p.price, total: p.price * p.amount, unit: unit });
    //     });

    //     console.log("ITEMS = " + JSON.stringify(items));

    //     PerformGetRequest("/api/get-self-establishment", async (establishmentResponse) => {

    //         let tmpCustomer = {
    //             fullName: "-",
    //             activity: "-",
    //             address: "-",
    //             phoneNumber: "-",
    //             commercialRegisterNumber: "-",
    //             taxationArticle: "-",
    //             fiscalIdentificationNumber: "-",
    //             statisticalIdentificationNumber: "-"
    //         };

    //         PerformGetRequest("/api/get-customer?id=" + ParamCustomer, async (customerResponse) => {

    //             tmpCustomer.fullName = customerResponse.data.firstName + " " + customerResponse.data.familyName;

    //             const logo = await PerformImageGetRequest("/api/get-self-logo?version=black");
    //             const doc = await GenerateInvoice("0000001", establishmentResponse.data, tmpCustomer, items, logo, ParamPaymentMethod);
    //             doc.save("Facture.pdf");

    //         });

    //     });

    // }

    const DownloadInvoicePDF_eCom = async (ParamSale) => {

        let customer = {
            fullName: ParamSale.card_owner_fullname,
            activity: "-",
            address: "-",
            phoneNumber: "-",
            commercialRegisterNumber: "-",
            taxationArticle: "-",
            fiscalIdentificationNumber: "-",
            statisticalIdentificationNumber: "-"
        };

        let items = [];
        if (ParamSale.sold_items) {
            for (const item of ParamSale.sold_items) {
                items.push({ name: item.name, quantity: item.quantity, price: item.price, total: item.total });
            }
        }

        console.log("ITEMS = " + JSON.stringify(items));

        PerformGetRequest("/api/get-self-establishment", async (res) => {
            const doc = await GenerateInvoice(ParamSale.id, res.data, customer, items);
            doc.save("Facture ECommerce.pdf");
        });

    }

    const handleDeleteOnClick = (ParamID) => {

        let saleToPost = { id: ParamID };

        PerformSecurePostRequest("/api/delete-sale", saleToPost, (res) => {
            if (res.data.code === "OK") {
                GetSalesListFromDB(null, null);
            }
        });

        setDeleteSalePopupTarget(null);

    }

    const handleRedeemCheckOnClick = (ParamID) => {

        let saleToPost = { id: ParamID };

        PerformSecurePostRequest("/api/redeem-check", saleToPost, (res) => {
            if (res.data.code === "OK") {
                GetSalesListFromDB(null, true);
            }
        });

        setRedeemCheckPopupTarget(null);

    }

    const handleCustomerChange = (e) => {
        setSelectedCustomer(customers.find(c => c._id === e.target.value));
        GetSalesListFromDB(e.target.value);
    }

    return (
        <div className='text-gray-900 dark:text-gray-100'>

            <div className='flex flex-col items-center justify-center'>
                <br />
                <h3 className='text-xl font-bold'>{t('salesList.title')}</h3>
                <br />
                <select name="state" className="w-64 py-1 m-4 text-sm text-gray-900 border border-gray-300 rounded-lg bg-gray-50 focus:ring-blue-500 focus:border-blue-500 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500" defaultValue="POS" onChange={handleDisplayTypeChange}>
                    <option value="POS">🛒 {t('salesList.selectType.pos')}</option>
                    <option value="CHECK">💶 Vente par Chèque</option>
                    <option value="ECOMMERCE">🌎 {t('salesList.selectType.eCommerce')}</option>
                </select>
                {customers && <select value={selectedCustomer?._id || ''} onChange={handleCustomerChange} className="py-1 mx-2 my-0 text-xs text-gray-900 border border-gray-300 rounded-lg bg-gray-50 focus:ring-blue-500 focus:border-blue-500 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500" >
                    <option value="">{t('salesList.selectClient')}</option>
                    {customers.map(customer => (
                        <option key={customer._id} value={customer._id}>{customer.designation}</option>
                    ))}
                </select>}
                <br />

                {/* POS */}
                {displayType === "POS" && <Table className='hidden text-xs md:inline' columns={columns_2} data={salesList} rowKey="_id" />}
                {displayType === "POS" && <Table className='inline text-xs md:hidden' columns={columns_mobile} data={salesList} rowKey="_id" />}

                {/* Check */}
                {displayType === "CHECK" && <Table className='text-xs inline' columns={columns_check} data={salesList} rowKey="_id" />}

                {/* eCom */}
                {displayType === "ECOMMERCE" &&
                    <div>
                        {eComSalesList && eComSalesList.map((s) => {
                            return (
                                <div key={s.id} className='flex flex-col items-center justify-center mx-2'>
                                    <div className='w-full mx-2 font-bold text-gray-100 bg-gray-700 rounded-t-lg'>Vente N° {s.id}</div>
                                    <div className='w-full p-2 m-2 mt-0 bg-gray-900 border-2 border-gray-500 rounded-b-lg'>

                                        {/* ID */}
                                        <div className='flex flex-row items-center justify-center my-2'>
                                            <FaIdCard className='mr-2' />
                                            <div>{s.card_owner_fullname}</div>
                                            <span className='mx-4' />
                                            <FaUser className='mr-2' />
                                            <div>{s.user ? s.user.fullname : "Invité"}</div>
                                            <span className='mx-4' />
                                            <FaMailBulk className='mr-2' />
                                            <div>{s.user ? s.user.email : "Invité"}</div>
                                            <span className='mx-4' />
                                            <FaLocationArrow className='mr-2' />
                                            <div>{s.shipping_address}</div>
                                        </div>

                                        {/* Items */}
                                        <div className='flex flex-col items-center justify-center mt-4'>
                                            {s.sold_items && s.sold_items.map((item) => {
                                                return (
                                                    <div className='flex flex-row items-center justify-center text-sm font-bold'>
                                                        <div className='bg-gray-800 w-96 p-0.5 m-0.5 rounded-full px-2'>{item.name}</div>
                                                        <div className='bg-gray-800 w-12 p-0.5 m-0.5 rounded-full px-2'>{item.quantity}</div>
                                                        <div className='bg-gray-800 w-24 p-0.5 m-0.5 rounded-full px-2'>{item.total} DA</div>
                                                    </div>
                                                )
                                            })}
                                            <div className='p-2 mt-4 text-xl font-bold text-gray-900 bg-gray-100 rounded-full w-96'>Total : {s.total_cost} DA</div>
                                            <RknButton label="Télécharger La Facture" className="my-2" onPress={() => DownloadInvoicePDF_eCom(s)} />
                                        </div>

                                    </div>
                                </div>
                            )
                        })}
                    </div>
                }
            </div>

            <br />
            <br />

            <RknInputDialog isOpen={currentPaymentSale ? true : false} onConfirm={handleOnConfirmPayment} onClose={() => { setCurrentPaymentSale(null); }} />
            {deleteSalePopupTarget && <RknConfirmationPopup danger={false} onConfirm={() => { handleDeleteOnClick(deleteSalePopupTarget); }} onCancel={() => { setDeleteSalePopupTarget(null); }} />}
            {redeemCheckPopupTarget && <RknConfirmationPopup danger={false} onConfirm={() => { handleRedeemCheckOnClick(redeemCheckPopupTarget); }} onCancel={() => { setRedeemCheckPopupTarget(null); }} />}

        </div>
    )
}

export default SalesList