import { React, useState, useEffect, useRef } from 'react';
import { FaLayerGroup } from 'react-icons/fa';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';

const BatchIdInputField = (props) => {

    const timeoutRef = useRef(null);

    const [batchId, setBatchId] = useState('');
    const [status, setStatus] = useState("PENDING"); // PENDING, FOUND, NOT_FOUND

    useEffect(() => {
        if (batchId) {
            // Clear the existing timeout
            if (timeoutRef.current) {
                clearTimeout(timeoutRef.current);
            }

            // Set a new timeout
            timeoutRef.current = setTimeout(() => {
                CheckBatch();
            }, 500);
        } else {
            setStatus("PENDING");
        }

        return () => {
            if (timeoutRef.current) {
                clearTimeout(timeoutRef.current);
            }
        };
    }, [batchId]);

    useEffect(() => {
        
        if (props.value)
            setBatchId(props.value);
        else if (props.productID) {
            PerformGetRequest("/api/best-batch-to-sell?productID=" + props.productID, (res)=>{
                if (res.data && res.data.code === "OK") {
                    setBatchId(res.data.batch.batchID);
                }
            });
        }

    }, [props.value])

    // useEffect(() => {
    //     console.log('Status changed to: ' + status);
    //     if (props.onValidBatch) {
    //         if (status === "FOUND") {
    //             props.onValidBatch(true);
    //         } else {
    //             props.onValidBatch(false);
    //         }
    //     }
    // }, [status]);

    const handlebatchValidityChange = (ParamValidity, ParamBatchIdString) => {
        if (props.onValidBatch) {
            props.onValidBatch(ParamValidity, ParamBatchIdString);
        }
    }

    const handleBatchIdChange = (e) => {
        setBatchId(e.target.value);
    };

    const CheckBatch = () => {
        console.log('Checking batch ID: ' + batchId);
        PerformGetRequest("/api/get-batch?productID=" + props.productID + "&batchID=" + batchId, (res) => {

            if (res.data && res.data._id) {
                setStatus("FOUND");
                handlebatchValidityChange(true, batchId);
            } else {
                setStatus("NOT_FOUND");
                handlebatchValidityChange(false, batchId);
            }

        }, (err) => {
            setStatus("NOT_FOUND");
            handlebatchValidityChange(false, batchId);
        });
    }

    return (
        <div className={`flex flex-row text-gray-100 text-sm font-bold opacity-80`} >
            <div className={`${status === "PENDING" ? "bg-gray-900" : status === "FOUND" ? "bg-green-700" : "bg-red-700"} rounded-l-full p-0.5 pl-2 pr-3 flex flex-row select-none`}><FaLayerGroup className='ml-1 mr-2 mt-0.5' /> Lot N° </div>
            <input className={`${status === "PENDING" ? "bg-gray-900" : status === "FOUND" ? "bg-green-700" : "bg-red-700"} rounded-r-full p-0.5 pl-2 pr-3 w-32`} type='text' value={batchId} onChange={handleBatchIdChange} />
        </div>
    )
}

export default BatchIdInputField