import React, { useState, useEffect } from 'react';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';

const CounterManager = () => {
    const [saleCounter, setSaleCounter] = useState(0);
    const [proformaInvoiceCounter, setProformaInvoiceCounter] = useState(0);
    const [deliveryNoteCounter, setDeliveryNoteCounter] = useState(0);
    const [invoiceCounter, setInvoiceCounter] = useState(0);
    const [barcodeCounter, setBarcodeCounter] = useState(0);

    useEffect(() => {

        PerformGetRequest("/api/counters", (res) => {
            const sale = res.data.SALE;
            const proformaInvoice = res.data.PROFORMA_INVOICE;
            const deliveryNote = res.data.DELIVERY_NOTE;
            const invoice = res.data.INVOICE;
            const barcode = res.data.BARCODE;

            setSaleCounter(sale);
            setProformaInvoiceCounter(proformaInvoice);
            setDeliveryNoteCounter(deliveryNote);
            setInvoiceCounter(invoice);
            setBarcodeCounter(barcode);
        });

    }, []);

    return (
        <div className='flex flex-col items-center justify-center text-gray-100'>
            <h1 className='text-3xl font-bold my-2'>Gestion des Compteurs</h1>
            <div>Vente : {saleCounter}</div>
            <div>Proforma : {proformaInvoiceCounter}</div>
            <div>Bon de Livraison : {deliveryNoteCounter}</div>
            <div>Facture : {invoiceCounter}</div>
            <div>Code Barre : {barcodeCounter}</div>
        </div>
    );
};

export default CounterManager;