import React, { useState } from 'react';
import { FaArrowAltCircleRight, FaArrowAltCircleLeft } from 'react-icons/fa';

const RknPageSelector = (props) => {

    const [page, setPage] = useState(1);

    const handleLeftClick = () => {
        if (page <= 1) {
            setPage(1);
            return;
        }

        setPage(page - 1);

        if (props.onChange)
            props.onChange(page - 1);
    }

    const handleRightClick = () => {
        if (page >= props.max) {
            setPage(props.max);
            return;
        }

        setPage(page + 1);

        if (props.onChange)
            props.onChange(page + 1);
    }

    return (
        <div className='flex flex-row items-center justify-center h-12 bg-gray-900 text-gray-100 border-2 border-gray-500 rounded-lg select-none w-64'>

            <div onClick={handleLeftClick}
                className='bg-gray-900 rounded-full mx-2 text-gray-500 hover:text-gray-100 transition duration-150 cursor-pointer active:scale-90'>
                <FaArrowAltCircleLeft size={24} />
            </div>

            <div className='mx-2 select-none font-bold'>
                {Number(page) + " / " + Number(props.max)}
            </div>

            <div onClick={handleRightClick}
                className='bg-gray-900 rounded-full mx-2 text-gray-500 hover:text-gray-100 transition duration-150 cursor-pointer active:scale-90'>
                <FaArrowAltCircleRight size={24} />
            </div>
        </div>
    )
}

export default RknPageSelector