import i18n from "i18next";
import { initReactI18next } from "react-i18next";

import global_ar from "./translations/ar/translation.json";
import global_fr from "./translations/fr/translation.json";
import global_en from "./translations/en/translation.json";

const resources = {
  ar: {
    translation: global_ar,
  },
  fr: {
    translation: global_fr,
  },
  en: {
    translation: global_en,
  },
};

i18n
  .use(initReactI18next) // passes i18n down to react-i18next
  .init({
    resources,
    // if you're using a language detector, do not define the lng option
    lng: "en", // language to use.
    fallbackLng: "fr", // fallback language.

    interpolation: {
      escapeValue: false, // react already safes from xss
    },
  });

// Function to change the direction based on the selected language
const changeDirection = (lang) => {
  const direction = lang === "ar" ? "rtl" : "ltr";
  document.documentElement.setAttribute("dir", direction); // Update the direction
};

// Listen to language changes
i18n.on("languageChanged", (lng) => {
  changeDirection(lng);
});

// Set the initial direction when the page loads based on the default language
changeDirection(i18n.language);

export const switchLanguage = (newLang) => {
  return new Promise((resolve) => {
    i18n.changeLanguage(newLang).then(() => {
      changeDirection(newLang);
      resolve();
    });
  });
};

export const isRTL = () => {
  const isRTL = document.documentElement.getAttribute('dir') === 'rtl';
  return isRTL;
}

export default i18n;