const GetImageDimensions = async (ParamImage) => {

    return new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => {
            resolve({ width: img.width, height: img.height });
        };
        
        img.onerror = (err) => {
            reject(err);
            console.log("Get Image Dimensions : Image load error.");
        };
        
        img.src = ParamImage;
    });
};

module.exports = { GetImageDimensions };