import { React, useState, useEffect, useRef } from 'react';
import axios from "axios";
import { GetBackEndUrl } from '../const';
import { BarLoader } from 'react-spinners';
import { FaCog } from 'react-icons/fa';
import { AwesomeButton } from 'react-awesome-button';
import 'react-awesome-button/dist/styles.css';
import { Login } from '../LoginManager';
import AppData from '../App.json';
// import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import RknSubmitButton from '../components/RknUI/RknSubmitButton';
// import Webcam from 'react-webcam';
import { useTranslation } from 'react-i18next';
// import RknButton from '../components/RknUI/RknButton';

const LoginForm = () => {

    const qrCodeRef = useRef(null);
    const { t } = useTranslation();

    useEffect(() => {

        if (AppData.QRCODE_LOGIN_FLAG) {
            setQrMode(true);
            setTimeout(() => { qrCodeRef.current.focus(); }, 150);
        }

    }, []);

    const [loginInfo, setLoginInfo] = useState({ username: "", password: "" });
    const [uiMessage, setUIMessage] = useState("");
    const [isBusy, setIsBusy] = useState(false);
    const [qrMode, setQrMode] = useState(false);
    const [qrCode, setQrCode] = useState(""); // machine-readable optical label

    const handleChange = ({ currentTarget: input }) => {
        setLoginInfo({ ...loginInfo, [input.name]: input.value });
    }

    useEffect(() => {
        if (qrCode && qrCode.length > 0) {
            const timeOutId = setTimeout(() => LoginOnClick(null), 400);
            return () => clearTimeout(timeOutId);
        }
    }, [qrCode]);

    const LoginOnClick = async (event) => {

        setIsBusy(true);

        if (event)
            event.preventDefault();

        var loginInfoToPost = {};

        if (qrMode) {
            if (qrCode.includes("[sep]")) {
                let parts = qrCode.split("[sep]");
                loginInfoToPost.username = parts[0];
                loginInfoToPost.password = parts[1];
            } else {
                setUIMessage(t("uiMessages.qrCodeError"));
                setIsBusy(false);
                return;
            }
        } else {
            loginInfoToPost.username = loginInfo.username;
            loginInfoToPost.password = loginInfo.password;
        }

        setUIMessage(t("uiMessages.connectionPending"));

        try {

            // Build Req/Res
            const url = GetBackEndUrl() + "/api/login";
            console.log("Login URL = " + url);
            const res = await axios.post(url, loginInfoToPost);

            // console.log("LOGIN DATA = " + JSON.stringify(res.data));

            if (res.data["token"]) {
                // localStorage.setItem("token", res.data["token"]);
                Login(res.data["token"], res.data["name"], res.data["privileges"], res.data["forensics"]);
                setUIMessage(t("uiMessages.welcomeMessage"));
                window.location = "/dashboard";
            }

        } catch (error) {
            console.log("ERROR : " + error);
            setIsBusy(false);

            if (error.response && error.response.status >= 400 && error.response.status <= 500) {

                console.log(error.response.data);

                if (error.response.data["code"] === "USER_NOT_FOUND")
                    setUIMessage(t("uiMessages.userNotFoundError"));
                else if (error.response.data["code"] === "INCORRECT_PASSWORD")
                    setUIMessage(t("uiMessages.incorrectPasswordError"));
                else
                    setUIMessage(t("uiMessages.connectionFailure"));
            }
            else {
                // window.postMessage('{"code":"ERROR", "message":"Impossible de ce connecter au serveur."}', '*');
                setUIMessage(t("uiMessages.connectionFailure"));
            }
        }

    }

    const awsBtnStyle = {
        '--button-primary-color': "#111111", // BG
        '--button-primary-color-dark': "#333333", // Shadow
        '--button-primary-color-light': "#CCCCCC", // Text
        '--button-primary-color-hover': "#333333", // Hover BG
        // '--button-secondary-color-active': "#ff0505",
    };

    return (
        <div className='flex flex-col items-center'>
            <br />
            <form onSubmit={LoginOnClick} className='flex flex-col items-center justify-center'>
                {!qrMode && <input type="text" name="username" placeholder={t("login.username")} value={loginInfo.username} onChange={handleChange} required className='bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 my-2' readOnly={isBusy} />}
                {!qrMode && <input type="password" name="password" placeholder={t("login.password")} value={loginInfo.password} onChange={handleChange} required className='bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 my-2' readOnly={isBusy} />}
                {qrMode && <input ref={qrCodeRef} type="password" name="qrcode" placeholder={t("login.qr")} value={loginInfo.qrcode} onChange={(e) => { setQrCode(e.target.value); }} className='bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 my-2' />}
                <RknSubmitButton label={t("login.login")} />
            </form>
            <br />
            {qrMode && <div className='my-1 text-xs text-gray-800 cursor-pointer dark:text-gray-400 hover:text-gray-400 dark:hover:text-white' onClick={() => setQrMode(false)}>Se connecter sans Code QR ?</div>}
            <br />
            <p className='text-gray-100'>{uiMessage}</p>
            <br />
            {/* <a className='p-1 bg-gray-900 text-gray-100 font-bold' href="print://escpos.org/escpos/usb/print?srcTp=uri&srcObj=pdf&numCopies=1&src='https://funny-custard-76cd16.netlify.app/voucher.pdf''">Print Me !</a> */}
            <br />
            {isBusy && <BarLoader color='#AAAAAA' />}
            <br />
            <br />
            <AwesomeButton type="primary" style={awsBtnStyle} before={<FaCog />}><a href='/connexion-settings'>{t("login.option.title")}</a></AwesomeButton>
        </div >
    )
}

export default LoginForm