import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import { PerformGetRequest } from '../../Reaknotron/Libs/RknQueryTools';
import { GetDateTimeDMYHM } from '../../Reaknotron/Libs/RknTimeTools';
import { FaCartArrowDown, FaOutdent, FaCartPlus } from 'react-icons/fa';
import { render } from '@testing-library/react';
import { SubjectToIconAndLabel, ActionToIconAndLabel, BoolToIconAndLabel } from '../../Reaknotron/Libs/RknIconsAndLabels';

const Archive = () => {

    useEffect(() => {

        PerformGetRequest("/api/ds-domain-log", (res) => {
            setEntries(res.data);
        });

    }, []);

    const [entries, setEntries] = useState(null);

    const columns = [
        {
            title: 'Date',
            dataIndex: 'time',
            key: 'time',
            className: 'border border-gray-500',
            width: 224,
            render: t => <div>{GetDateTimeDMYHM(t)}</div>
        },
        {
            title: 'Sujet',
            dataIndex: 'subjectModelName',
            key: 'subjectModelName',
            className: 'border border-gray-500',
            width: 256,
            render: s => SubjectToIconAndLabel(s)
        },
        {
            title: 'Action',
            dataIndex: 'action',
            key: 'action',
            className: 'border border-gray-500',
            width: 160,
            render: a => ActionToIconAndLabel(a)
        },
        {
            title: 'Présence',
            dataIndex: 'found',
            key: 'found',
            className: 'border border-gray-500',
            width: 120,
            render: f => BoolToIconAndLabel(f)
        }
    ];

    return (
        <div className='text-gray-100 flex flex-col items-center justify-center'>
            <br />
            <h1 className='text-xl font-bold'>Journal</h1>
            <br />
            <Table columns={columns} data={entries} rowKey="_id" />
            <br />
            <br />
        </div>
    )
}

export default Archive