import { useState, useEffect } from 'react';
import AppData from '../App.json';

const useReaktor = (ParamContext, ParamOnUpdate) => {

    const [reaktorSocket, setReaktorSocket] = useState(null);

    // Connect to Reaktor
    useEffect(() => {

        // Connect to Reaktor
        if (AppData.USE_REAKTOR && AppData.FORCED_REAKTOR_URL) {
            const sock = new WebSocket(AppData.FORCED_REAKTOR_URL);

            sock.addEventListener('open', () => {
                console.log('REAKTOR : Ready for Context : ' + ParamContext);

                // Declare Context
                // sock.send(ParamContext);
            });

            sock.addEventListener('message', (event) => {

                console.log("Reaktor Message (RAW) = " + event.data);
                // console.log("Reaktor Message (JSON) = " + JSON.stringify(event.data));

                let obj;

                try {
                    obj = JSON.parse(event.data);
                } catch (error) {
                    console.log("REAKTOR : Invalid Command.");
                }

                if (obj == null || obj == {}) {
                    console.log("REAKTOR : Invalid Object.");
                    return;
                }

                if (obj.command === "UPDATE") {
                    if (obj.context === ParamContext && ParamOnUpdate) {
                        ParamOnUpdate(obj.content);
                    }
                } else if (obj.command === "INPUT") {
                    if (obj.context === ParamContext && ParamOnUpdate) {
                        ParamOnUpdate(obj.content);
                    }
                } else if (obj.command === "NEW") {
                    if (obj.context === ParamContext && ParamOnUpdate) {
                        ParamOnUpdate(obj.content);
                    }
                }

                sock.addEventListener('error', (error) => {
                    console.log("REAKTOR ERROR : " + error);
                    sock.close();
                });
            });

            setReaktorSocket(sock);
        }

    }, []);

    return { reaktorSocket };
};

export default useReaktor;