import { React, useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { FaTimesCircle, FaCheckCircle } from 'react-icons/fa';
import hotkeys from 'hotkeys-js';
import { PulseLoader } from 'react-spinners';
import { PerformGetRequest, PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import RknNumericInput from './RknUI/RknNumericInput';
import { GetCashReg } from '../const';
import CountUp from 'react-countup';

const BalancePaymentPopup = (props) => {

    const amountOneRef = useRef(null);

    // Basic
    const [amountOne, setAmountOne] = useState("");
    const [amountTwo, setAmountTwo] = useState("");
    const [customerName, setCustomerName] = useState(null);
    const [customerBalance, setCustomerBalance] = useState(null);
    const [finalBalance, setFinalBalance] = useState(0);
    const [type, setType] = useState('DEPOSIT');
    const [saving, setSaving] = useState(false);

    useEffect(() => {

        console.log("USE EFFECT : EST ID = " + props.establishmentID);

        setTimeout(() => { amountOneRef.current.focus(); }, 150);

        if (props.establishmentID) {
            PerformGetRequest("/api/get-establishment?id=" + props.establishmentID, (res) => {
                setCustomerName(res.data.designation);
                setCustomerBalance(res.data.balance);
            });
        }

        if (props.type && props.type == "WITHDRAWAL") {
            setType("WITHDRAWAL");
        }

    }, []);

    useEffect(() => {

        hotkeys.filter = function (event) {
            var tagName = (event.target || event.srcElement).tagName;
            hotkeys.setScope(/^(INPUT|TEXTAREA|SELECT)$/.test(tagName) ? 'input' : 'other');
            return true;
        }

        hotkeys('escape', event => {
            event.preventDefault();
            TriggerPropsOnCancel();
        });

        return () => {
            hotkeys.unbind('escape');
        }

    }, []);

    useEffect(() => {
        if (type == "DEPOSIT") {
            setFinalBalance(Number(customerBalance) + Number(amountOne));
        }
        else if (type == "WITHDRAWAL") {
            setFinalBalance(Number(customerBalance) - Number(amountOne));
        }
    }, [amountOne, amountTwo, type]);

    const TriggerPropsOnConfirm = () => {

        if (props.onConfirm) {
            props.onConfirm();
        }

    }

    const OnSubmit = (e) => {
        e.preventDefault();
        // TriggerPropsOnConfirm();
        PerformPayment();
    }

    const TriggerPropsOnCancel = () => {
        if (props.onCancel)
            props.onCancel();
    }

    const PerformPayment = async () => {

        setSaving(true);

        try {

            if (props.establishmentID) {
                PerformSecurePostRequest("/api/perform-establishment-payment", { id: props.establishmentID, amount: Number(amountOne), cashRegID: GetCashReg(), type: type }, (res) => {
                    setSaving(false);
                    TriggerPropsOnConfirm();
                });
            }

        } catch (error) {
            console.log("ERROR : " + error);

            if (error.response && error.response.status >= 400 && error.response.status <= 500) {
                console.log(error.response.data);
            }

            setSaving(false);
        }
    }

    const handleTypeChange = (event) => {
        setType(event.target.value);
    };

    return (
        <motion.div
            className='fixed top-0 right-0 left-0 w-screen h-screen bg-black bg-opacity-60 z-10 flex flex-col items-center justify-center backdrop-blur-lg'
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.3 }}
        >
            <motion.div
                className='bg-gray-900 border-4 border-gray-500 rounded-3xl m-auto w-5/6 md:w-1/2 p2 md:p-4 pb-0 flex flex-col items-center justify-center'
                initial={{ opacity: 0, y: "-50%" }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.3 }}
            >
                <div className='flex flex-col items-center justify-center mb-2'>
                    <h1 className='mb-1 mt-2 md:mt-1 font-bold text-gray-100 text-base md:text-xl'>Effectuer une Transaction</h1>
                    <h3 className='mb-1 font-bold text-gray-400 text-base'>Établissement : {customerName}</h3>
                    <h4 className='mb-1 text-xs text-gray-500'>Balance Actuelle : {customerBalance} DA</h4>
                </div>

                <label className='text-sm mt-4 mb-1'>Type</label>
                <select
                    name="state"
                    className="py-1 mx-4 mb-6 text-sm text-gray-900 border border-gray-300 rounded-lg bg-gray-50 focus:ring-blue-500 focus:border-blue-500 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500"
                    defaultValue="DEPOSIT"
                    onChange={handleTypeChange}
                    value={type}
                >
                    <option value="DEPOSIT">💰 Versement</option>
                    <option value="WITHDRAWAL">📤 Retrait</option>
                </select>

                <form onSubmit={OnSubmit} className='flex flex-col items-center justify-center'>
                    {/* <input type="number" value={removalAmount} ref={productPriceRef} onChange={(e) => { setRemovalAmount(e.target.value); }} className={'bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 mb-1 w-64 mx-auto md:w-64'} placeholder='Quantité...' /> */}
                    <RknNumericInput value={amountOne} ref={amountOneRef} onChange={(v) => setAmountOne(v)} placeholder='Montant...' />
                    <RknNumericInput value={amountTwo} onChange={(v) => setAmountTwo(v)} placeholder='Vérification...' />

                    {amountOne > 0 && amountOne === amountTwo && <div className={`bg-gray-800 rounded px-4 p-2 my-3 font-bold text-3xl ${type == "DEPOSIT" ? "text-green-400" : "text-red-400"}`}>{customerBalance} {type == "DEPOSIT" ? "+" : "-"} {amountOne} = <CountUp end={finalBalance} useEasing={false} preserveValue={true} duration='0.4' separator='' /> DA</div>}

                    <div className='flex flex-row items-center justify-center mt-4'>
                        {amountOne > 0 && amountOne === amountTwo && <div>
                            <button type='submit' className="bg-blue-500 hover:bg-blue-400 text-white font-bold py-2 px-4 border-b-4 border-blue-700 hover:border-blue-500 rounded">{saving ? <PulseLoader color='#AAAAAA' /> : <div><FaCheckCircle className='inline mb-1' size={20} /> Confirmer</div>}</button>
                            <span className='mx-2'></span>
                        </div>}
                        <button type='button' onClick={TriggerPropsOnCancel} className="bg-blue-500 hover:bg-blue-400 text-white font-bold py-2 px-4 border-b-4 border-blue-700 hover:border-blue-500 rounded"><FaTimesCircle className='inline mb-1' size={20} /> Annuler</button>
                    </div>
                </form>
                <br />

            </motion.div>
        </motion.div>
    )
}

export default BalancePaymentPopup