import React from 'react';

const RknIconButton = (props) => {
    return (
        <div className='h-8 w-8 p-1 m-1 bg-gray-900 border border-gray-500 rounded-lg hover:bg-gray-500 active:scale-90 transition duration-150 flex flex-col items-center justify-start cursor-pointer'
            onClick={props.onPress}
        >
            {props.icon}
        </div>
    )
}

export default RknIconButton