import { React, useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { FaTimesCircle, FaCheckCircle } from 'react-icons/fa';
import hotkeys from 'hotkeys-js';
import { PulseLoader } from 'react-spinners';
import AppData from '../App.json';
import InitialStockEditor from './InitialStockEditor';
import { PerformSecurePostRequestWithFormData } from '../Reaknotron/Libs/RknQueryTools';

const SalesPointQuickProductAdder = (props) => {

    const productNameRef = useRef(null);
    const productPriceRef = useRef(null);

    useEffect(() => {
        setTimeout(() => { productNameRef.current.focus(); }, 400);

        if (!AppData.STORAGE_MANAGEMENT_FLAG || props.ignoreInitialStock) {
            setBatches({});
        }
    }, []);

    useEffect(() => {

        hotkeys.filter = function (event) {
            var tagName = (event.target || event.srcElement).tagName;
            hotkeys.setScope(/^(INPUT|TEXTAREA|SELECT)$/.test(tagName) ? 'input' : 'other');
            return true;
        }

        hotkeys('escape', event => {
            event.preventDefault();
            TriggerPropsOnCancel();
        });

        return () => {
            hotkeys.unbind('escape');
        }

    }, []);

    // Basic
    const [productName, setProductName] = useState("");
    const [productNameEdited, setProductNameEdited] = useState(false);
    const [productPrice, setProductPrice] = useState(0);
    const [productPriceEdited, setProductPriceEdited] = useState(false);
    const [saving, setSaving] = useState(false);

    // Stock Management
    const [batches, setBatches] = useState(null);

    const TriggerPropsOnConfirm = () => {

        if (props.onConfirm) {
            if (productNameEdited && productPriceEdited)
                props.onConfirm(productName, productPrice, props.barcode);
        } else {
            if (productNameEdited && productPriceEdited)
                QuickAddProductToDB();
        }

    }

    const OnSubmit = (e) => {
        e.preventDefault();
        TriggerPropsOnConfirm();
    }

    const TriggerPropsOnCancel = () => {
        if (props.onCancel)
            props.onCancel();
    }

    const handleProductNameChange = (e) => {

        var v = e.target.value;
        setProductName(v);
        setProductNameEdited(true);
    }

    const QuickAddProductToDB = async () => {

        setSaving(true);

        try {

            // Build form
            const formData = new FormData();
            formData.append("name", productName);
            formData.append("price", productPrice);
            formData.append("halfWholesalePrice", productPrice);
            formData.append("wholesalePrice", productPrice);
            formData.append("barcode", props.barcode);

            // Batches with their amounts and expiration dates
            if (batches) {
                let batchesArray = [];
                Object.keys(batches).forEach((bk) => {
                    batchesArray.push({
                        batchID: batches[bk].batchID,
                        expiryDate: batches[bk].expiryDate,
                        amount: batches[bk].amount,
                        price: batches[bk].price
                    });
                });
                // console.log("BA = " + JSON.stringify(batchesArray));
                formData.append("batches", JSON.stringify(batchesArray));
            }

            PerformSecurePostRequestWithFormData("/api/new-product", formData, (res) => {
                TriggerPropsOnCancel();
                setSaving(false);
            });

        } catch (error) {
            console.log("ERROR : " + error);

            if (error.response && error.response.status >= 400 && error.response.status <= 500) {
                console.log(error.response.data);
            }

            setSaving(false);
        }
    }

    return (
        <motion.div
            className='fixed top-0 right-0 left-0 w-screen h-screen bg-black bg-opacity-60 z-10 flex flex-col items-center justify-center backdrop-blur-lg'
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.3 }}
        >
            <motion.div
                className='bg-gray-900 border-4 border-gray-500 rounded-3xl m-auto w-1/2 p-4 pb-0 flex flex-col items-center justify-center'
                initial={{ opacity: 0, y: "-50%" }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.3 }}
            >
                <div className='border border-gray-500 bg-gray-800 rounded-xl p-4 pt-2 text-red-500 mb-4'>
                    <div style={{ fontSize: "48px" }}>🤷‍♀️</div>
                    <div>Produit introuvable...</div>
                </div>

                <h3 className='mb-1 font-bold text-gray-100 text-xl'>Ajouter un Produit Rapidement</h3>
                <h4 className='mb-4 text-xs text-gray-500'>Code-Barres : {props.barcode}</h4>

                <form onSubmit={OnSubmit} className='flex flex-col items-center justify-center'>
                    <input type="text" value={productName} ref={productNameRef} onChange={handleProductNameChange} className={'bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 mb-1 w-64 mx-auto md:w-64'} placeholder='Nom du Produit...' />
                    <input type="number" value={productPrice} ref={productPriceRef} onChange={(e) => { setProductPrice(e.target.value); setProductPriceEdited(true); }} className={'bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 mb-1 w-64 mx-auto md:w-64'} placeholder='Prix du Produit...' />

                    {AppData.STORAGE_MANAGEMENT_FLAG && !props.ignoreInitialStock &&
                        <InitialStockEditor className='w-64' onChange={(v) => { setBatches(v); }} />
                    }

                    <div className='flex flex-row items-center justify-center mt-4'>
                        <button type='submit' className="bg-blue-500 hover:bg-blue-400 text-white font-bold py-2 px-4 border-b-4 border-blue-700 hover:border-blue-500 rounded">{saving ? <PulseLoader color='#AAAAAA' /> : <div><FaCheckCircle className='inline mb-1' size={20} /> Confirmer</div>}</button>
                        <span className='mx-2'></span>
                        <button type='button' onClick={TriggerPropsOnCancel} className="bg-blue-500 hover:bg-blue-400 text-white font-bold py-2 px-4 border-b-4 border-blue-700 hover:border-blue-500 rounded"><FaTimesCircle className='inline mb-1' size={20} /> Annuler</button>
                    </div>
                </form>
                <br />

            </motion.div>
        </motion.div>
    )
}

export default SalesPointQuickProductAdder