const AppData = require('./App.json');

const GetBackEndUrl = () => {

    if (AppData.FORCED_BACKEND_URL)
        return AppData.FORCED_BACKEND_URL;

    let result = "http://localhost:4000";

    const storedValue = localStorage.getItem("serverAddress");

    if (storedValue && storedValue != "")
        result = storedValue;

    return result;
}

const GetPrintServerAddress = () => {
    let result = "http://localhost:5000/print";

    const storedValue = localStorage.getItem("printServerAddress");

    if (storedValue && storedValue != "")
        result = storedValue;

    return result;
}

const GetPrinterName = () => {

    if (AppData.FORCED_PRINTER_NAME)
        return AppData.FORCED_PRINTER_NAME;

    let result = "Default Printer";

    const storedValue = localStorage.getItem("printerName");

    if (storedValue && storedValue != "")
        result = storedValue;

    return result;
}

const GetIfReducedPerformance = () => {
    let result = false;

    const storedValue = localStorage.getItem("reducedPerformance");

    if (storedValue && storedValue != "")
        result = storedValue;

    return result;
}

const GetIfPrintWaitingReceipt = () => {
    let result = false;

    const storedValue = localStorage.getItem("printWaitingReceipt");

    if (storedValue && storedValue != "" && storedValue === "true") {
        result = true;
    }

    return result;
}

const GetIfShowProductsOutOfStock = () => {
    let result = false;

    const storedValue = localStorage.getItem("showProductsOutOfStock");

    if (storedValue && storedValue != "" && storedValue === "true") {
        result = true;
    }

    return result;
}

const GetInfoLineOne = () => {

    let result = "";

    if (localStorage.getItem("infoLineOne"))
        result = localStorage.getItem("infoLineOne");

    return result;
}

const GetInfoLineTwo = () => {

    let result = "";

    if (localStorage.getItem("infoLineTwo"))
        result = localStorage.getItem("infoLineTwo");

    return result;
}

const GetCurrencyDesignation = () => {

    let result = "Dinars";

    if (localStorage.getItem("currencyDesignation"))
        result = localStorage.getItem("currencyDesignation");

    return result;
}

// Get currency symbol
const GetCurrencySymbol = (language = "fr") => {
    let result = language === "fr" || language === "en" ? "DA" : "دج";

    if (localStorage.getItem("currencySymbol"))
        result = localStorage.getItem("currencySymbol");

    return result;
}

// Get currency symbol
const GetCashReg = () => {
    let result = null;

    if (localStorage.getItem("cashReg"))
        result = localStorage.getItem("cashReg");

    return result;
}

module.exports = { GetBackEndUrl, GetPrintServerAddress, GetPrinterName, GetIfReducedPerformance, GetIfPrintWaitingReceipt, GetInfoLineOne, GetInfoLineTwo, GetIfShowProductsOutOfStock, GetCurrencyDesignation, GetCurrencySymbol, GetCashReg };