import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import useDocumentTitle from '@tanem/use-document-title';
import { useSearchParams } from 'react-router-dom';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';

const ReceptionByProductViewer = () => {

    const columns = [
        {
            title: 'Date & Heure',
            dataIndex: 'time',
            key: 'time',
            className: 'border border-gray-500',
            width: 256,
            render: d => <div className='inline text-sm'>{(new Date(d)).toLocaleDateString('fr-FR', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' })}</div>
        },
        {
            title: 'Fournisseur',
            dataIndex: 'provider',
            key: 'provider',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Qte.',
            dataIndex: 'amount',
            key: 'amount',
            width: 128,
            className: 'border border-gray-500'
        },
        {
            title: 'Prix',
            dataIndex: 'price',
            key: 'price',
            width: 128,
            className: 'border border-gray-500'
        }
    ];

    useDocumentTitle("Receptions par Produit");
    const [searchParams, setSearchParams] = useSearchParams();

    // Effect
    useEffect(() => {

        if (searchParams.get("id")) {
            PerformGetRequest("/api/receptions-by-product?id=" + searchParams.get("id"), (res) => {
                // console.log("MOVES = " + JSON.stringify(res.data.moves));
                // setName(res.data.name);
                setName("-");
                setMoves(res.data);
                // setCalculatedAmount(res.data.result);
                // setRegistredAmount(res.data.amount);
            });
        }

    }, []);

    const [name, setName] = useState("");
    const [moves, setMoves] = useState(null);

    return (
        <div className='flex flex-col items-center justify-center text-gray-100'>
            <h1 className='my-2 font-bold text-x'>Receptions par Produit : {name}</h1>
            {moves && <Table columns={columns} data={moves} rowKey="id" tableLayout='auto' />}
        </div>
    )
}

export default ReceptionByProductViewer