import { React, useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import axios from 'axios';
import { InputFieldStyle } from '../Styles';
import { GetBackEndUrl } from '../const';
import RknSubmitButton from '../components/RknUI/RknSubmitButton';
import RknDateInput from '../components/RknUI/RknDateInput';

const StudentEditor = () => {

    useEffect(() => {

        if (searchParams.get("cat")) {
            setCategory(searchParams.get("cat"));
        }

    }, []);

    const [firstName, setFirstName] = useState("");
    const [familyName, setFamilyName] = useState("");
    const [phoneNumber, setPhoneNumber] = useState("");
    const [category, setCategory] = useState("");

    // Navigation
    const navigate = useNavigate();
    const [searchParams, setSearchParams] = useSearchParams();

    const handleFirstNameChange = (e) => {
        setFirstName(e.target.value);
    }

    const handleFamilyNameChange = (e) => {
        setFamilyName(e.target.value);
    }

    const handlePhoneNumberChange = (e) => {
        setPhoneNumber(e.target.value);
    }

    const AddStudentToDB = async () => {
        try {

            let studentToPost = {
                firstName: firstName,
                familyName: familyName,
                phoneNumber: phoneNumber,
                category: category
            };

            // Add token
            // const token = localStorage.getItem("token");
            // const config = {
            //     headers: { Authorization: `Bearer ${token}` }
            // };

            const url = GetBackEndUrl() + "/api/new-student";
            console.log("POST : " + url);

            let res = await axios.post(url, studentToPost);

            if (res) {
                setFirstName("");
                setFamilyName("");
                setPhoneNumber("");
            }

        } catch (error) {
            console.log("ERROR : " + error);
        }
    }

    return (
        <div className='m-4 p-2 flex flex-col items-center text-gray-100'>
            <h3 className='text-xl font-bold mt-2'>Inscrire un étudiant</h3>
            <br />
            <label className="block text-sm font-medium text-gray-900 dark:text-white">Prénom :</label>
            <input type='text' className={InputFieldStyle} placeholder="Prénom..." onChange={handleFirstNameChange} value={firstName} />
            <br />

            <label className="block text-sm font-medium text-gray-900 dark:text-white">Nom :</label>
            <input type='text' className={InputFieldStyle} placeholder="Nom..." onChange={handleFamilyNameChange} value={familyName} />
            <br />

            <label className="block text-sm font-medium text-gray-900 dark:text-white">N° de Téléphone :</label>
            <input type='text' className={InputFieldStyle} placeholder="N° de Téléphone..." onChange={handlePhoneNumberChange} value={phoneNumber} />
            <br />

            <label className="block text-sm font-medium text-gray-900 dark:text-white">Date de naissance :</label>
            <RknDateInput onChange={null} value={null} />
            <br />
            {/* {firstName && familyName && phoneNumber && <AwesomeButton onPress={AddStudentToDB} >Confirmer</AwesomeButton>} */}
            {firstName && familyName && phoneNumber && <RknSubmitButton onPress={AddStudentToDB} label="Confirmer" />}
            <br />
        </div>
    )
}

export default StudentEditor