import React from 'react';
import Popup from 'reactjs-popup';
import { FaTimesCircle } from 'react-icons/fa';
import CategorizedProductSelector from './CategorizedProductSelector';

import { useTranslation } from 'react-i18next';

const CategorizedProductSelectorPopup = (props) => {

    const { t } = useTranslation();

    const CloseModal = () => {
        props.onClose();
    }

    const handleProductOnClick = (paramProduct) => {
        if (props.onProductClick) {
            props.onProductClick(paramProduct);
        }
    }

    const contentStyle = { background: '#172439', width: "90%", height: "75%", borderRadius: "16px" };

    return (
        <div>
            <Popup
                open={props.isOpen}
                modal
                closeOnDocumentClick
                onClose={CloseModal}
                onOpen={() => { }}
                {...{ contentStyle }}
            >
                <div className="p-2 text-gray-100 bg-gray-900 modal rounded-xl">
                    <button className="close" onClick={CloseModal}>
                        <FaTimesCircle />
                    </button>
                    <div className="header">{t("pos.toolbar.products.select")}</div>
                    <br />
                    <CategorizedProductSelector onProductClick={handleProductOnClick} />
                </div>
            </Popup>
        </div>
    );
};

export default CategorizedProductSelectorPopup;