import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';

const TransactionManager = () => {

    useEffect(() => {

        GetDepositListFromDb();
        GetWithdrawalsListFromDb();

    }, []);

    const [deposits, setDeposits] = useState(null);
    const [withdrawals, setWithdrawals] = useState(null);
    const [customers, setCustomers] = useState(null);
    const [selectedCustomer, setSelectedCustomer] = useState(null);

    useEffect(() => {

        PerformGetRequest("/api/get-establishment-list", (res) => {
            // console.log(JSON.stringify(res.data));
            setCustomers(res.data);
        });

    }, []);

    const columns_deposits = [
        {
            title: 'Date',
            dataIndex: 'time',
            key: 'time',
            className: 'border border-gray-500',
            width: 256,
            render: d => <div className='inline text-sm'>{(new Date(d)).toLocaleDateString('fr-FR', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' })}</div>
        },
        {
            title: 'Etablisement',
            dataIndex: 'estLabel',
            key: 'estLabel',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Montant',
            dataIndex: 'amount',
            key: 'amount',
            className: 'border border-gray-500',
            width: 256
        }
    ];

    const columns_withdrawals = [
        {
            title: 'Date',
            dataIndex: 'time',
            key: 'time',
            className: 'border border-gray-500',
            width: 256,
            render: d => <div className='inline text-sm'>{(new Date(d)).toLocaleDateString('fr-FR', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' })}</div>
        },
        {
            title: 'Etablisement',
            dataIndex: 'estLabel',
            key: 'estLabel',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Montant',
            dataIndex: 'amount',
            key: 'amount',
            className: 'border border-gray-500',
            width: 256
        }
    ];

    const GetDepositListFromDb = async (customerId) => {

        PerformGetRequest(`/api/deposits?customerId=${customerId}`, (res) => {
            // console.log(JSON.stringify(res.data));
            setDeposits(res.data);
        });

    }

    const GetWithdrawalsListFromDb = async (customerId) => {

        PerformGetRequest(`/api/withdrawals?customerId=${customerId}`, (res) => {
            // console.log(JSON.stringify(res.data));
            setWithdrawals(res.data);
        });

    }

    const handleCustomerChange = (e) => {
        setSelectedCustomer(customers.find(c => c._id === e.target.value));
        GetDepositListFromDb(e.target.value);
        GetWithdrawalsListFromDb(e.target.value);
    }

    return (
        <div className='text-gray-100 flex flex-col items-center'>
            <br />
            <h3 className='text-xl font-bold'>Versements</h3>
            <br />
            {customers && <select value={selectedCustomer?._id || ''} onChange={handleCustomerChange} className="py-1 mx-2 my-0 text-xs text-gray-900 border border-gray-300 rounded-lg bg-gray-50 focus:ring-blue-500 focus:border-blue-500 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500" >
                <option value="">Établissement...</option>
                {customers.map(customer => (
                    <option key={customer._id} value={customer._id}>{customer.designation}</option>
                ))}
            </select>}
            <br />
            {deposits && <Table columns={columns_deposits} data={deposits} rowKey="_id" />}
            <br />
            <br />
            <h3 className='text-xl font-bold'>Retraits</h3>
            <br />
            {withdrawals && <Table columns={columns_withdrawals} data={withdrawals} rowKey="_id" />}
            <br />
        </div>
    )
}

export default TransactionManager