import React, { useState, useEffect, useRef } from 'react';
import Popup from 'reactjs-popup';
import { FaTimesCircle, FaCheckCircle } from 'react-icons/fa';
import RknNumericInput from '../components/RknUI/RknNumericInput';
import RknDateInput from './RknUI/RknDateInput';
import RknButton from './RknUI/RknButton';
// import CountUp from 'react-countup';

const FinalizeProductionPopup = (props) => {

    const ref = useRef(null);

    useEffect(() => {
        if (ref && ref.current) {
            ref.current.focus();
        }

        // if (props.initialValue) {
        //     setAmountToPay(props.initialValue);
        //     setTotal(props.initialValue);
        // }
    }, []);

    const [batchNumber, setBatchNumber] = useState(0);
    const [expiryDate, setExpiryDate] = useState(null);

    const CloseModal = () => {
        props.onClose();
    }

    const handleBatchNumberChange = (ParamValue) => {
        setBatchNumber(ParamValue);
    }

    const handleOnConfirm = () => {
        if (props.onConfirm) {
            props.onConfirm(batchNumber, expiryDate);
            CloseModal();
        }
    }

    return (
        <div>
            <Popup
                open={props.isOpen}
                modal
                closeOnDocumentClick
                onClose={() => { CloseModal(); }}
            >
                <div className="modal bg-gray-900 text-gray-100 p-2">
                    <button className="close" onClick={() => { CloseModal(); }}>
                        <FaTimesCircle />
                    </button>
                    <div className="header">Paiement</div>
                    <br />
                    <div className="content flex flex-col items-center">

                        <label className='text-sm'>N° du Lot :</label>
                        <RknNumericInput value={batchNumber} onChange={handleBatchNumberChange} placeholder="N° du lot..." ref={ref} />
                        <span className='my-2' />

                        <label className='text-sm'>Paiement Initiale :</label>
                        {/* <RknNumericInput value={initialPayment} onChange={(v) => { setInitialPayment(v) }} placeholder="Paiement Initiale..." /> */}
                        <RknDateInput onChange={setExpiryDate} />
                        <span className='my-2' />

                        {/* <button type='submit' className="bg-blue-500 hover:bg-blue-400 text-white font-bold py-2 px-4 border-b-4 border-blue-700 hover:border-blue-500 rounded mt-2"><FaCheckCircle className='inline mb-1' size={20} /> Confirmer</button> */}
                        <RknButton onPress={handleOnConfirm} label="Finalizer" />
                        <br />

                    </div>
                </div>
            </Popup>
        </div>
    )
}

export default FinalizeProductionPopup;