import React, { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import Table from 'rc-table';
import axios from 'axios';
import { GetBackEndUrl } from '../const';
import { InputFieldStyle } from '../Styles';
import { AwesomeButton } from 'react-awesome-button';
import { FaEnvelope, FaPlus } from 'react-icons/fa';
import RknButton from '../components/RknUI/RknButton';
import { Link } from 'react-router-dom';

const StudentManager = () => {

    useEffect(() => {

        if (searchParams.get("cat")) {
            setCategory(searchParams.get("cat"));
            GetStudentListFromDB(searchParams.get("cat"));
        } else {
            GetStudentListFromDB();
        }

    }, []);

    const [tableData, setTableData] = useState();
    const [groupMessage, setGroupMessage] = useState("");
    const [category, setCategory] = useState("");

    // Navigation
    const navigate = useNavigate();
    const [searchParams, setSearchParams] = useSearchParams();

    const columns = [
        {
            title: "Prénom",
            dataIndex: 'firstName',
            key: 'firstName',
            width: 256,
            className: 'border border-gray-500'
        },
        {
            title: 'Nom',
            dataIndex: 'familyName',
            key: 'familyName',
            width: 256,
            className: 'border border-gray-500'
        },
        {
            title: 'N° de Téléphone',
            dataIndex: 'phoneNumber',
            key: 'phoneNumber',
            width: 256,
            className: 'border border-gray-500'
        }
    ];

    const GetStudentListFromDB = async (ParamCategory) => {
        let res;

        try {

            // Build Req/Res
            let url;

            if (ParamCategory)
                url = GetBackEndUrl() + "/api/student-list?cat=" + ParamCategory;
            else
                url = GetBackEndUrl() + "/api/student-list";

            console.log("GET : " + url);
            res = await axios.get(url);

            if (res) {
                // console.log(res.data);
                UpdateTableData(res.data);
            }

        } catch (error) {
            console.log("ERROR : " + error);

            if (error.response && error.response.status >= 400 && error.response.status <= 500) {

                console.log(error.response.data);

            }
        }
    }

    const UpdateTableData = (ParamQueryResult) => {
        let result = [];
        ParamQueryResult.forEach(student => {
            result.push({
                id: student._id,
                firstName: student.firstName,
                familyName: student.familyName,
                phoneNumber: student.phoneNumber
            });
            setTableData(result);
        });
    }

    const handleGroupMessageChange = (e) => {
        setGroupMessage(e.target.value);
    }

    const SendGroupMessage = () => {
        const socket = new WebSocket('ws://localhost:9999');

        socket.addEventListener('open', () => {
            console.log('connected!');
            socket.send('{"code":"ME_CONSUMER"}');

            tableData.forEach((student) => {
                let msg = "Mr. ";
                msg += student.firstName;
                msg += " ";
                msg += student.familyName;
                msg += ", ";
                msg += groupMessage;

                let command = { code: "SEND", phone: student.phoneNumber, message: msg };

                socket.send(JSON.stringify(command));
            });
        });

        socket.addEventListener('message', (event) => {
            console.log("WS MSG : " + event.data);
        });

        socket.addEventListener('error', (error) => {
            console.log("WS ERROR : " + error);
            socket.close();
        });
    }

    return (
        <div>
            <br />
            <h3 className='text-3xl font-bold text-gray-100'>Gestion des Etudiants</h3>
            <br />
            <div className='flex flex-col items-center text-gray-100 m-4'>

                {/* Student List */}
                <div className='w-full m-4 p-2 flex flex-col items-center'>
                    {/* <h3 className='text-xl font-bold mt-2'>Liste des Etudiants</h3>
                    <br /> */}
                    <RknButton label={<Link to={"/student-editor?cat=" + category}>Ajouter un Etudiant</Link>} before={<FaPlus />} />
                    <br />
                    <Table columns={columns} data={tableData} rowKey="id" className='mx-4' />
                    <br />
                </div>

                {/* Batch Notification Sender */}
                {/* <div className='border-4 border-gray-500 rounded-3xl w-full m-4 p-2 flex flex-col items-center'>
                    <h3 className='text-xl font-bold mt-2'>Notification en Vrac</h3>
                    <br />
                    <input type='text' className={InputFieldStyle} placeholder="Message..." onChange={handleGroupMessageChange} value={groupMessage} />
                    <br />
                    {groupMessage && <AwesomeButton onPress={SendGroupMessage} before={<FaEnvelope size={24} />}> Envoyer</AwesomeButton>}
                    <br />
                </div> */}

            </div>
        </div>
    )
}

export default StudentManager