import React, { useState, useEffect } from 'react';
import WilayaData from '../../assets/Cities/Wilaya_Of_Algeria.json';
import CommuneData from '../../assets/Cities/Algerian_Cities.json';
import { InputFieldStyle } from '../../Styles';

const RknWilayaCommuneSelector = (props) => {

    const [wilayaList, setWilayaList] = useState(null);
    const [selectedWilaya, setSelectedWilaya] = useState(null);
    const [selectedWilayaID, setSelectedWilayaID] = useState(null);
    const [communeList, setCommuneList] = useState(null);
    const [selectedCommune, setSelectedCommune] = useState(null);
    const [selectedCommuneID, setSelectedCommuneID] = useState(null);

    useEffect(() => {
        // console.log('Loaded Wilaya Resp :' + JSON.stringify(WilayaData));
        setWilayaList(WilayaData);
        // console.log('Loaded Commune Resp :' + JSON.stringify(CommuneData));
        const tmp = CommuneData.filter((c) => {
            // console.log("c.wilaya_code = " + c.wilaya_code);
            return Number(c.wilaya_code) == 1;
        });
        setCommuneList(tmp);

        setSelectedWilaya(WilayaData[0]);
        setSelectedWilayaID(WilayaData[0].id);
    }, []);

    const handleWilayaChange = (e) => {
        const selectedId = Number(e.target.value);
        const selectedWilaya = WilayaData.find(w => Number(w.id) === selectedId);
        // console.log("SW = " + JSON.stringify(selectedWilaya));

        setSelectedWilaya(selectedWilaya);
        setSelectedWilayaID(selectedId);

        const tmp = CommuneData.filter((c) => Number(c.wilaya_code) === selectedId);
        setCommuneList(tmp);

        // Select the first commune
        const firstCommune = tmp[0];
        setSelectedCommune(firstCommune);
        setSelectedCommuneID(firstCommune.id);

        if (props.onChange) {
            props.onChange({
                wilaya: { id: selectedWilaya.id, name: selectedWilaya.name },
                commune: firstCommune ? { id: firstCommune.id, name: firstCommune.commune_name_ascii } : null
            });
        }
    }

    const handleCommuneChange = (e) => {
        const selectedId = Number(e.target.value);
        const selectedCommune = CommuneData.find(c => c.id === selectedId);
        // console.log("SELECTED COMMUNE = " + JSON.stringify(selectedCommune));

        setSelectedCommune(selectedCommune);
        setSelectedCommuneID(selectedId);

        if (props.onChange) {
            props.onChange({
                wilaya: { id: selectedWilaya.id, name: selectedWilaya.name },
                commune: { id: selectedCommune.id, name: selectedCommune.commune_name_ascii }
            });
        }
    }

    return (
        <div className='text-gray-100 flex flex-row items-center justify-start'>
            <label className='mr-2'>Wilaya : </label>
            <select value={selectedWilayaID} onChange={handleWilayaChange} className={InputFieldStyle} >
                {wilayaList && wilayaList.map((w, i) => {
                    return (
                        <option key={w.id} value={w.id}>{w.name}</option>
                    )
                })}
            </select>
            <label className='ml-4 mr-2'>Commune : </label>
            <select value={selectedCommuneID} onChange={handleCommuneChange} className={InputFieldStyle} >
                {communeList && communeList.map((c, i) => {
                    return (
                        <option key={c.id} value={c.id}>{c.commune_name_ascii}</option>
                    )
                })}
            </select>
        </div>
    );
};

export default RknWilayaCommuneSelector;