import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import { PerformGetRequest } from '../../Reaknotron/Libs/RknQueryTools';

const Archive = () => {

    useEffect(() => {

        GetArchivesFromDb();

    }, []);

    const [products, setProducts] = useState(null);
    const [receptions, setReceptions] = useState(null);
    const [sales, setSales] = useState(null);
    const [dischargeSheets, setDischargeSheets] = useState(null);

    const columns_products = [
        {
            title: 'Designation',
            dataIndex: 'name',
            key: 'name',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Quantité',
            dataIndex: 'availableAmount',
            key: 'availableAmount',
            className: 'border border-gray-500',
            width: 256
        }
    ];

    const columns_receptions = [
        {
            title: 'Designation',
            dataIndex: 'time',
            key: 'time',
            className: 'border border-gray-500',
            width: 256
        }
    ];

    const GetArchivesFromDb = async () => {

        PerformGetRequest("/api/archive", (res) => {
            setProducts(res.data.products);
            setReceptions(res.data.receptions);
        });

    }

    return (
        <div className='text-gray-100'>
            <br />
            <h1 className='text-xl font-bold'>Archives</h1>
            <br />
            <div className='flex flex-col items-center'>
                <h1 className='text-lg font-bold my-2'>Produits</h1>
                <Table columns={columns_products} data={products} rowKey="_id" />
                <br />
                <h1 className='text-lg font-bold mt-4 mb-2'>Réceptions</h1>
                <Table columns={columns_receptions} data={receptions} rowKey="_id" />
            </div>
            <br />
            <br />
        </div>
    )
}

export default Archive