import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import axios from 'axios';
import { GetBackEndUrl } from '../const';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import { FaPlus, FaEdit } from 'react-icons/fa';
import { Link } from 'react-router-dom';
import RknButton from '../components/RknUI/RknButton';

const EmployeeManager = () => {

    useEffect(() => {

        // GetEmployeeListFromDB();
        PerformGetRequest("/api/get-employee-list", (res) => { setTableData(res.data); });

    }, []);

    const [tableData, setTableData] = useState();
    const [firstName, setFirstName] = useState("");
    const [familyName, setFamilyName] = useState("");

    const columns = [
        {
            title: 'Opérations',
            dataIndex: '',
            key: 'operations',
            width: 128,
            className: 'border border-gray-500',
            render: i => GenerateOperationButtons(i)
        },
        {
            title: "Prénom",
            dataIndex: 'firstName',
            key: 'firstName',
            width: 256,
            className: 'border border-gray-500'
        },
        {
            title: 'Nom',
            dataIndex: 'familyName',
            key: 'familyName',
            width: 256,
            className: 'border border-gray-500'
        }
    ];

    const GetEmployeeListFromDB = async () => {
        let res;

        try {

            // Build Req/Res
            var url = GetBackEndUrl() + "/api/get-employee-list";

            console.log("GET : " + url);
            res = await axios.get(url);

            if (res) {
                // console.log(res.data);
                UpdateTableData(res.data);
            }

        } catch (error) {
            console.log("ERROR : " + error);

            if (error.response && error.response.status >= 400 && error.response.status <= 500) {

                console.log(error.response.data);

            }
        }
    }

    const UpdateTableData = (ParamQueryResult) => {
        let result = [];
        ParamQueryResult.forEach(employee => {
            result.push({
                id: employee._id,
                firstName: employee.firstName,
                familyName: employee.familyName
            });
            setTableData(result);
        });
    }

    const GenerateOperationButtons = (ParamItem) => {

        const buttonStyle = 'bg-gray-900 text-gray-100 rounded-lg p-2 my-2 mx-1 text-sm hover:bg-gray-700 inline';

        if (ParamItem) {
            return (
                <div className='flex flex-row'>
                    <button className={buttonStyle}> <Link to={"/employee-editor?id=" + ParamItem._id}> <FaEdit size={20} /></Link> </button>
                </div>
            )
        }

        return "N/A";
    }

    return (
        <div className='flex flex-col items-center justify-center text-gray-100 m-4'>
            <br />
            <h3 className='text-3xl font-bold text-gray-100'>Gestion des Employés</h3>
            <br />
            <Link to='/employee-editor'><RknButton before={<FaPlus />} label="Ajouter Un Employé" /></Link>
            <br />

            {/* Employee List */}
            <Table columns={columns} data={tableData} rowKey="_id" className='mx-4' />
        </div>
    )
}

export default EmployeeManager