import React, { useState, useEffect } from 'react';
import { InputFieldStyle } from '../../Styles';
import { FaEdit } from 'react-icons/fa';
import { useTranslation } from 'react-i18next';

const RknPaymentSelector = (props) => {

    const { t } = useTranslation();

    const [paymentOptions, setPaymentOptions] = useState([
        { id: 'CASH', name: `💰  ${t("pos.toolbar.quote.paymentMethods.cash")}` },
        { id: 'CHECK', name: `💶  ${t("pos.toolbar.quote.paymentMethods.check")}` },
        { id: 'BANK_TRANSFER', name: `💹  ${t("pos.toolbar.quote.paymentMethods.bankTransfer")}` },
        { id: 'BANK_CARD', name: `💳  ${t("pos.toolbar.quote.paymentMethods.creditCard")}` },
        { id: 'MOBILE_PAYMENT', name: `📱  ${t("pos.toolbar.quote.paymentMethods.mobilePayment")}` },
        { id: 'ELECTRONIC_WALLET', name: `🛄  ${t("pos.toolbar.quote.paymentMethods.eWallet")}` },
        { id: 'VIRTUAL_CURRENCY', name: `✨  ${t("pos.toolbar.quote.paymentMethods.cryptocurrency")}` }
    ]);

    const [selectedPayment, setSelectedPayment] = useState(null);
    const [editMode, setEditMode] = useState(false);
    const [editValue, setEditValue] = useState("");

    useEffect(() => {
        // Initialize selected payment if provided in props
        if (props.initialValue) {
            setSelectedPayment(props.initialValue);
        } else {
            setSelectedPayment('CASH'); // Default to cash if no initial value
        }
    }, []);

    const handlePaymentChange = (e) => {
        const selectedId = e.target.value;
        console.log('Selected Payment : ' + selectedId);
        setSelectedPayment(selectedId);
        if (props.onChange) {
            const selectedPaymentObject = paymentOptions.find(payment => payment.id === selectedId);
            // props.onChange({ id: selectedId, name: selectedPaymentObject.name });
            props.onChange(selectedId);
        }
    }

    const handleEditValueChange = (e) => {
        const v = e.target.value;
        setEditValue(v);
        if (props.onChange) {
            // props.onChange({ id: v, name: v });
            console.log('Selected Payment (Edited) : ' + v);
            props.onChange(v);
        }
    }

    return (
        <div className='text-gray-100 flex flex-col items-center justify-center mt-2'>
            <label className="ml-1 text-sm font-medium text-gray-900 dark:text-white">Modalité du Paiement : </label>
            <div className='flex flex-row items-center justify-center'>
                {/* Input or Selector */}
                {editMode ?
                    <input
                        value={editValue}
                        onChange={handleEditValueChange}
                        className={InputFieldStyle + " w-64"}
                    />
                    :
                    <select
                        value={selectedPayment}
                        onChange={handlePaymentChange}
                        className={InputFieldStyle}
                    >
                        {paymentOptions.map((option) => (
                            <option key={option.id} value={option.id}>
                                {option.name}
                            </option>
                        ))}
                    </select>
                }

                {/* Edit Button */}
                <div
                    className='h-10 w-10 pt-2 pl-0.5 ml-1 mt-2 bg-gray-900 border border-gray-500 rounded-lg hover:bg-gray-500 active:scale-90 transition duration-150 flex flex-col items-center justify-start cursor-pointer'
                    onClick={() => setEditMode(!editMode)}
                >
                    <FaEdit size={20} />
                </div>
            </div>
        </div>
    );
};

export default RknPaymentSelector;