import { React, useState, useEffect, useRef } from 'react';
import RknNumericInput from '../components/RknUI/RknNumericInput';
import { useTranslation } from 'react-i18next';
import RknAnimatedPopup from '../components/RknUI/RknAnimatedPopup'
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import { motion } from 'framer-motion';
import { BarLoader } from 'react-spinners';
import RknButton from '../components/RknUI/RknButton';

const EditPricePopup = (props) => {

    const { t } = useTranslation();
    const ref = useRef(null);

    const [price, setPrice] = useState(0);
    const [product, setProduct] = useState(null);
    const [changesAvailable, setChangesAvailable] = useState(null);

    useEffect(() => {

        setTimeout(() => {

            ref.current.select();

        }, 150);

        PerformGetRequest("/api/get-product?id=" + props.id, (res) => {
            setProduct(res.data);
        });
    }, [])

    const handlePriceOnClick = (ParamPriceType, ParamPrice) => {

        if (props.onConfirm)
            props.onConfirm(ParamPriceType, ParamPrice);

        if (props.onClose)
            props.onClose();
    }

    const handleConfirm = () => {
        if (props.onConfirm)
            props.onConfirm("CUSTOM", price);
    }

    const handleCancel = () => {
        if (props.onClose)
            props.onClose();
    }

    const handleEnterPress = (event) => {
        if (event.key === "Enter") {
            event.preventDefault();
            handleConfirm();
        }
    }

    return (
        <RknAnimatedPopup className="flex flex-col items-center justify-center text-gray-100" onClose={handleCancel} >
            <h1 className='text-xl font-bold mb-4'>{props.label}</h1>
            <RknNumericInput placeholder='Prix...' ref={ref} value={price} onChange={(v) => setPrice(v)} onKeyDown={handleEnterPress} />
            {/* <div>{props.id}</div> */}
            {/* <div>{product && JSON.stringify(product)}</div> */}

            {!product &&
                <div className='w-80 h-32 bg-gray-800 rounded flex flex-col items-center justify-center my-4'>
                    <BarLoader size={24} color='#AAAAAA' />
                </div>
            }

            {product &&
                <motion.div
                    className='grid grid-cols-2 items-center justify-center my-4'
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ duration: 0.25 }}
                >
                    <div className='w-40 h-8 bg-gray-700 text-gray-100 rounded-l-full p-1 my-0.5 opacity-60'>Prix Promotionnel</div>
                    <div className='w-40 h-8 cursor-pointer hover:brightness-125 active:scale-95 transition duration-150 bg-yellow-300 text-black font-bold rounded-r-full p-1 my-0.5' onClick={() => handlePriceOnClick("PROMOTION", product.promotionPrice)} >{product.promotionPrice} DA</div>
                    <div className='w-40 h-8 bg-gray-700 text-gray-100 rounded-l-full p-1 my-0.5 opacity-60'>Prix de Gros</div>
                    <div className='w-40 h-8 cursor-pointer hover:brightness-125 active:scale-95 transition duration-150 bg-purple-700 text-gray-100 font-bold rounded-r-full p-1 my-0.5' onClick={() => handlePriceOnClick("WHOLESALE", product.wholesalePrice)} >{product.wholesalePrice} DA</div>
                    <div className='w-40 h-8 bg-gray-700 text-gray-100 rounded-l-full p-1 my-0.5 opacity-60'>Prix Demi-Gros</div>
                    <div className='w-40 h-8 cursor-pointer hover:brightness-125 active:scale-95 transition duration-150 bg-orange-700 text-gray-100 font-bold rounded-r-full p-1 my-0.5' onClick={() => handlePriceOnClick("HALF_WHOLESALE", product.halfWholesalePrice)} >{product.halfWholesalePrice} DA</div>
                    <div className='w-40 h-8 bg-gray-700 text-gray-100 rounded-l-full p-1 my-0.5 opacity-60'>Prix de Détail</div>
                    <div className='w-40 h-8 cursor-pointer hover:brightness-125 active:scale-95 transition duration-150 bg-green-700 text-gray-100 font-bold rounded-r-full p-1 my-0.5' onClick={() => handlePriceOnClick("RETAIL", product.price)} >{product.price} DA</div>
                </motion.div>
            }

            <div className='flex flex-row items-center justify-center space-x-2' >
                <RknButton label="Confirmer" before={null} onPress={handleConfirm} />
                <RknButton label="Annuler" before={null} onPress={handleCancel} />
            </div>

        </RknAnimatedPopup>
    )
}

export default EditPricePopup