import { React, useState, useRef, useEffect } from 'react';
import { motion } from 'framer-motion';
import { FaBoxes, FaDollarSign, FaCalculator, FaCalendarAlt, FaHistory, FaList, FaTimesCircle } from 'react-icons/fa';
import RknDateInput from './RknUI/RknDateInput';
import { StringToNumber_2DecAtMost } from '../Reaknotron/Libs/RknStringTools';
import AppData from '../App.json';

const ReceptionItem = (props) => {

    // Refs
    const amountRef = useRef(null);

    const [amount, setAmount] = useState(1);
    const [PUHT, setPUHT] = useState(1);
    const [TVA, setTVA] = useState(19);
    const [PUTTC, setPUTTC] = useState(1);
    const [batchID, setBatchID] = useState("");
    const [expiryDate, setExpiryDate] = useState(null);

    useEffect(() => {
        setTimeout(() => { amountRef.current.focus(); amountRef.current.select(); }, 100);

        if (props.value) {
            setAmount(props.value.amount);

            if (AppData.PRODUCT_SPECIFIC_TVA) {

                let puht = 1;
                if (props.value.PUHT)
                    puht = props.value.PUHT;

                let tva = 19;
                if (props.value.TVA)
                    tva = props.value.TVA;

                setPUHT(puht);
                setTVA(tva);
            } else {
                setTVA(0);
            }

            setPUTTC(props.value.price);
            setBatchID(props.value.batchID);
            setExpiryDate(props.value.expirationDate);
        }
    }, []);

    useEffect(() => {

        if (props.onChange) {
            props.onChange
                (
                    props.value.id,
                    amount,
                    PUHT,
                    TVA,
                    PUTTC,
                    amount * PUTTC,
                    batchID,
                    expiryDate
                );
        }

    }, [amount, PUTTC, TVA, PUTTC, batchID, expiryDate]);

    const handleAmountOnChange = (e) => {
        setAmount(e.target.value);

        // console.log("V: " + e.target.value);
        // console.log("PUHT: " + PUHT);
        // console.log("TVA: " + TVA);

        if (AppData.PRODUCT_SPECIFIC_TVA) {
            setPUTTC(PUHT * (1 + TVA / 100));
        }
    }

    const handlePUHTOnChange = (e) => {
        setPUHT(e.target.value);
        setPUTTC(e.target.value * (1 + TVA / 100));
    }

    const handleTVAOnChange = (e) => {
        setTVA(e.target.value);
        setPUTTC(PUHT * (1 + e.target.value / 100));
    }

    const handlePriceOnChange = (e) => {
        setPUTTC(e.target.value);
    }

    const handleBatchIDOnChange = (e) => {
        setBatchID(e.target.value);
    }

    const handleExpDateOnChange = (d) => {
        setExpiryDate(d);
    }

    const handleProductDelete = () => {
        // console.log("Delete : " + props.value.id);

        if (props.onDelete)
            props.onDelete(props.value.id);
    }

    return (
        <motion.div
            className='text-gray-100 flex flex-col items-center justify-center'
            initial={{ opacity: 0, x: "-25%" }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.3 }}
        >
            <div className='w-full flex flex-col items-center justify-center'>

                <div className='flex flex-row items-center justify-center text-xs'>

                    <FaTimesCircle size={20} className='text-gray-500 mr-1 cursor-pointer hover:text-gray-300 active:scale-90 transition duration-150' onClick={handleProductDelete} />

                    {/* Old Price */}
                    <div className="flex border border-gray-700 p-0.5 w-32 text-gray-600 rounded-l-xl">
                        <span className="flex items-center justify-center m-1.5">
                            <FaHistory size={20} />
                        </span>
                        <div className='h-8 pt-2 text-xs font-bold'>{StringToNumber_2DecAtMost(props.value.lastReceptionPrice)} DA</div>
                    </div>

                    {/* Designation */}
                    <div className="flex border border-gray-700 p-0.5 w-96">
                        <span className='text-xs bg-gray-700 text-gray-400 font-bold w-6 h-6 mx-2 mt-0.5 px-1.5 py-0.5 pt-1 rounded'>
                            {props.index}
                        </span>
                        <div className='h-8 pt-1.5'>{props.value.name}</div>
                    </div>

                    {/* Amount */}
                    <div className="flex border border-gray-700 p-0.5 w-36">
                        <span className="flex items-center justify-center p-1">
                            <FaBoxes size={22} />
                        </span>
                        <input ref={amountRef} className="text-gray-100 bg-gray-700 rounded-lg w-full p-2 mx-0.5" type='number' value={amount} placeholder='Quantité...' onChange={handleAmountOnChange} />
                    </div>

                    {/* PUHT */}
                    <div className="flex border border-gray-700 p-0.5 w-40">
                        <span className="flex items-center justify-center p-1 font-bold text-xs">
                            {AppData.PRODUCT_SPECIFIC_TVA ? "P.U.H.T." : <FaDollarSign size={22} />}
                        </span>
                        <input className="text-gray-100 bg-gray-700 rounded-lg w-full p-2 mx-0.5" type='number' value={PUHT} placeholder='PUHT...' onChange={handlePUHTOnChange} />
                    </div>

                    {/* TVA */}
                    {AppData.PRODUCT_SPECIFIC_TVA && <div className="flex border border-gray-700 p-0.5 w-28">
                        <span className="flex items-center justify-center p-1 font-bold">
                            TVA
                        </span>
                        <input className="text-gray-100 bg-gray-700 rounded-lg w-full p-2 mx-0.5" type='number' value={TVA} placeholder='TVA...' onChange={handleTVAOnChange} />
                        <div className='pt-1 text-gray-500 text-base'>%</div>
                    </div>}

                    {/* Unit Price TTC */}
                    {AppData.PRODUCT_SPECIFIC_TVA && <div className="flex border border-gray-700 p-0.5 w-40">
                        <span className="flex items-center justify-center p-1">
                            {"P.U.T.T.C."}
                        </span>
                        <input className="text-gray-100 bg-gray-700 rounded-lg w-full p-2 mx-0.5" type='number' value={PUTTC} placeholder='Prix...' onChange={handlePriceOnChange} readOnly={AppData.PRODUCT_SPECIFIC_TVA} />
                    </div>}

                    {/* Total Price */}
                    <div className="flex border border-gray-700 p-0.5 w-40">
                        <span className="flex items-center justify-center p-1">
                            <FaCalculator size={22} />
                        </span>
                        <div className="text-gray-700 bg-gray-200 font-bold rounded-lg w-full p-2 mx-0.5" >{StringToNumber_2DecAtMost(amount * PUTTC)} DA</div>
                    </div>

                    {/* Batch Number */}
                    {AppData.BATCH_ID_FLAG &&
                        <div className="flex border border-gray-700 p-0.5 w-32">
                            <span className="flex items-center justify-center p-1">
                                <FaList size={22} />
                            </span>
                            <input className="text-gray-100 bg-gray-700 rounded-lg w-full p-2 mx-0.5" type='text' name='batchID' value={batchID} placeholder='Lot N°...' onChange={handleBatchIDOnChange} />
                        </div>
                    }

                    {/* Expiry Date */}
                    {AppData.EXPIRATION_DATE_MANAGEMENT_FLAG &&
                        <div className="flex border border-gray-700 p-0.5 w-60">
                            <span className="flex items-center justify-center p-1">
                                <FaCalendarAlt size={22} />
                            </span>
                            <RknDateInput onChange={handleExpDateOnChange} value={expiryDate} />
                        </div>
                    }

                </div>

            </div>
        </motion.div>
    )
}

export default ReceptionItem