import React, { useState, useEffect } from 'react';
import RknButton from '../components/RknUI/RknButton';
import { PerformGetRequest, PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import { PulseLoader } from 'react-spinners';

function HourlyStatusEditor() {

    // Initialize an array of length 24 with the initial state value (e.g., 1)
    const [boxStates, setBoxStates] = useState(new Array(24).fill(1));
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);

    useEffect(() => {
        PerformGetRequest("/api/get-default-attendance-events", (res) => {

            if (res.data && res.data.defaultEventsPerHour) {
                console.log("SET");
                setBoxStates(res.data.defaultEventsPerHour);
            }

            setIsLoading(false);

            // console.log("STATUS = " + res.status);
            // console.log("DATA = " + JSON.stringify(res.data));
            // console.log("EVENTS = " + JSON.stringify(res.data.defaultEventsPerHour));
            // if (response.status === 404) {

            // }
        }, (err) => {
            setIsLoading(false);
        });
    }, []);

    // Function to toggle the state of a specific box
    const toggleSpecificState = (index) => {

        // Cycle through 1, 2, 3, then back to 1
        let newState = (boxStates[index] + 1);

        if (newState > 3)
            newState = 1;

        // Update the state of the specific box
        const updatedStates = [...boxStates]; // Create a copy of the current state array
        updatedStates[index] = newState; // Update the state at the specific index
        setBoxStates(updatedStates); // Set the updated state array

        console.log(JSON.stringify(updatedStates));
    };

    const handleSaveOnClick = () => {
        setIsSaving(true);
        const configToPost = { defaultEventsPerHour: boxStates };
        PerformSecurePostRequest("/api/update-default-attendance-events", configToPost, (res) => {
            setIsSaving(false);
        });
    }

    if (isLoading)
        return <PulseLoader color='#AAAAAA' />

    return (
        <div className='flex flex-col items-center justify-center'>
            <div className="grid grid-cols-8 grid-rows-3 justify-center items-center p-2">
                {/* Render boxes based on the boxStates array */}
                {boxStates.map((state, index) => (
                    <div
                        key={index}
                        className={`flex flex-vcol items-center justify-center font-bold w-16 text-xs h-16 select-none m-1 rounded border-2 ${state === 1 ? 'bg-neutral-500' : state === 2 ? 'bg-green-500' : 'bg-red-500'
                            } cursor-pointer`}
                        onClick={() => toggleSpecificState(index)} // Pass the index to toggle the specific state
                    >
                        {index + 1} : 00
                    </div>
                ))}
            </div>
            <div className='text-gray-100 text-xs flex flex-row items-center justify-center space-x-4 mb-4'>
                
                <div className='flex flex-row'>
                    <div className='w-4 h-4 bg-neutral-500 mr-1 rounded' />
                    <div>Indéfinie</div>
                </div>

                <div className='flex flex-row'>
                    <div className='w-4 h-4 bg-green-500 mr-1 rounded' />
                    <div>Entrée</div>
                </div>

                <div className='flex flex-row'>
                    <div className='w-4 h-4 bg-red-500 mr-1 rounded' />
                    <div>Sortie</div>
                </div>

            </div>
            {isSaving ? <PulseLoader color='#AAAAAA' /> : <RknButton label="Enregistrer" className="w-32" onPress={handleSaveOnClick} />}
        </div>
    );
}

export default HourlyStatusEditor;