import { React, useState, useEffect } from 'react';
import Popup from 'reactjs-popup';
import { FaTimesCircle, FaExchangeAlt, FaRandom } from 'react-icons/fa';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import { GridLoader } from 'react-spinners';

const CstSwapPopup = (props) => {

    // useEffect(()=>{
    //     PerformGetRequest("/api/get-customer-sitting-tables-list", (res) => { setTables(res.data); });
    // });

    const handleOnOpen = () => {
        PerformGetRequest("/api/get-customer-sitting-tables-list", (res) => { setTables(res.data); });
    }

    const [tables, setTables] = useState(null);

    const CloseModal = () => {
        props.onClose();
    }

    const handleTableSelection = (ParamTableID) => {
        if (props.onSelection)
            props.onSelection(ParamTableID);
    }

    const contentStyle = { background: '#172439', width: "80%", height: "60%", borderRadius: "16px" };

    return (
        <div>
            <Popup
                open={props.isOpen}
                modal
                closeOnDocumentClick
                onClose={() => { CloseModal(); }}
                onOpen={handleOnOpen}
                {...{ contentStyle }}
            >
                <div className="modal bg-gray-900 text-gray-100 p-2 rounded-xl">
                    <button className="close" onClick={() => { CloseModal(); }}>
                        <FaTimesCircle />
                    </button>
                    <div className="header">Transfert de Table</div>
                    <br />
                    <div className='flex flex-row items-center justify-center flex-wrap'>
                        {
                            tables ? tables.map((cst) => {
                                return (
                                    <div key={cst._id}
                                        className='h-8 w-28 m-0.5 p-1 text-sm rounded-lg border-2 border-gray-900 hover:border-gray-100 transition duration-300 flex flex-col items-center justify-center cursor-pointer select-none text-gray-100 font-bold'
                                        style={{ backgroundColor: cst.color ? cst.color : '#555555' }}
                                        onClick={() => { handleTableSelection(cst._id) }}>
                                        {cst.occupied ? '🔴' : '🟢'} Table {cst.name}
                                    </div>
                                )
                            }) : <GridLoader color='#AAAAAA' />
                        }
                    </div>
                </div>
            </Popup>
        </div>
    )
}

export default CstSwapPopup