import React, { useState } from 'react';
import RknSubmitButton from '../RknUI/RknSubmitButton';
import { InputFieldStyle, LabelStyle } from '../../Styles';
import RknNumericInput from '../RknUI/RknNumericInput';
import { PerformSecurePostRequest } from '../../Reaknotron/Libs/RknQueryTools';

const PTForm = () => {

    const [name, setName] = useState("");
    const [baseSalary, setBaseSalary] = useState(0);
    const [targetID, setTargetID] = useState(null);
    const [changesAvailable, setChangesAvailable] = useState(false);

    const handleNameChange = (e) => {
        setName(e.target.value);
        setChangesAvailable(true);
    }

    const handleBaseSalaryChange = (ParamValue) => {
        setBaseSalary(ParamValue);
        setChangesAvailable(true);
    }

    const OnSubmit = async (event) => {

        event.preventDefault();

        let pt = { name: name, baseSalary: baseSalary };

        if (targetID) {

            pt.id = targetID;
            PerformSecurePostRequest("/api/update-pt", pt, (res) => {
                if (res.data && res.data.message && res.data.message == "OK") {
                    setChangesAvailable(false);
                }
            });

        } else {

            PerformSecurePostRequest("/api/new-pt", pt, (res) => {
                if (res.data && res.data.id) {
                    setTargetID(res.data.id);
                    setChangesAvailable(false);
                }
            });

        }

    }

    return (
        <div className='flex flex-col items-center justify-center text-gray-900 dark:text-gray-100'>
            <br />
            <h3 className='font-bold text-xl'>Editeur de Titre Professionel</h3>
            <br />
            <form onSubmit={OnSubmit}>
                <label className={LabelStyle}>Designation</label>
                <input type="text" className={InputFieldStyle} placeholder="Designation..." value={name} onChange={handleNameChange} required />
                <br />
                <br />

                <label className={LabelStyle}>Salaire de Base</label>
                <RknNumericInput value={baseSalary} onChange={handleBaseSalaryChange} placeholder="Salaire de Base..." />
                <br />
                <br />

                <RknSubmitButton label={targetID ? "Enregistrer" : "Ajouter"} onPress={OnSubmit} disabled={!changesAvailable} />
            </form>
        </div>
    )
}

export default PTForm