import { React, useState, useEffect } from 'react';
import Table from 'rc-table';
import { PerformGetRequest, PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import BalancePaymentPopup from '../components/BalancePaymentPopup';
import { FaDollarSign } from 'react-icons/fa';
import RknInputDialog from '../components/RknUI/RknInputDialog';

const CashRegManager = () => {

    const columns = [
        {
            title: 'Opérations',
            dataIndex: '',
            key: 'operation',
            className: 'border border-gray-500',
            width: 64,
            render: cr =>
                <div className='flex flex-row items-center justify-center'>
                    {/* {CheckPrivilege("CUSTOMER_MANAGEMENT") && <Link className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' to={"/customer-editor?id=" + cr._id} ><FaEdit /></Link>} */}
                    {<div className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' onClick={() => { setCurrentCashRegID(cr._id); }}><FaDollarSign /></div>}
                </div>
        },
        {
            title: "Designation",
            dataIndex: 'designation',
            key: 'designation',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: "Contenu",
            dataIndex: 'content',
            key: 'content',
            className: 'border border-gray-500',
            width: 256
        }
    ];

    const columns_moves = [
        {
            title: "Utilisateur",
            dataIndex: 'user',
            key: 'user',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: "Date",
            dataIndex: 'time',
            key: 'time',
            className: 'border border-gray-500',
            width: 256,
            render: d => <div className='inline text-sm'>{d ? (new Date(d)).toLocaleDateString('fr-FR', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' }) : "-"}</div>
        },
        {
            title: "Caisse",
            dataIndex: 'cashReg',
            key: 'cashReg',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: "Contenu Initiale",
            dataIndex: 'oldContent',
            key: 'oldContent',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: "Nouveau Contenu",
            dataIndex: 'amount',
            key: 'amount',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: "Changement",
            dataIndex: 'change',
            key: 'change',
            className: 'border border-gray-500',
            width: 256,
            render: c => <div className={`p-1 px-2 m-1 rounded-full font-bold ${c ? (c < 0 ? "bg-red-800" : "bg-green-800") : "bg-neutral-700"}`} >{c}</div>
        }
    ];

    const [cashRegList, setCashRegList] = useState(null);
    const [cashRegMoves, setCashRegMoves] = useState(null);
    const [currentCashRegID, setCurrentCashRegID] = useState(null);

    const getCashRegListFromDb = () => {
        PerformGetRequest("/api/cash-registers", (res) => {
            // console.log(res.data);
            setCashRegList(res.data);
        });
    }

    const getMoveListFromDb = () => {
        PerformGetRequest("/api/cash-reg-moves", (res) => {
            setCashRegMoves(res.data);
        });
    }

    useEffect(() => {

        getCashRegListFromDb();
        getMoveListFromDb();
        
    }, []);
    
    const handleOnConfirmContentupdate = (ParamValue) => {
        
        PerformSecurePostRequest("/api/update-cash-register", { content: ParamValue, id: currentCashRegID }, (res) => {
            getCashRegListFromDb();
            getMoveListFromDb();
            setCurrentCashRegID(null);
        });

    }

    return (
        <div className='flex flex-col items-center justify-center text-gray-100'>
            <br />
            <h1 className='text-3xl font-bold'>Gestion des Caisses</h1>
            <br />
            <Table columns={columns} data={cashRegList} rowKey="_id" />
            <br />
            <br />
            <h1 className='text-3xl font-bold'>Mouvements</h1>
            <br />
            <Table columns={columns_moves} data={cashRegMoves} rowKey="_id" />
            <br />
            <br />
            <RknInputDialog isOpen={currentCashRegID ? true : false} onConfirm={handleOnConfirmContentupdate} onClose={() => { setCurrentCashRegID(null); }} />
            <br />
            <br />
        </div>
    )
}

export default CashRegManager