import { React, useState, useEffect } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { InForensicsMode, IsLoggedIn } from '../LoginManager';
import { FaExpand, FaArrowLeft, FaUser, FaEnvelope, FaDatabase, FaSearchPlus, FaFire, FaArrowRight } from 'react-icons/fa';
import AppData from '../App.json';
import UserProfileMenu from './UserProfileMenu';
import { isRTL } from '../i18n';

const NavBar = () => {

    // const isArabic = i18n.language === 'ar';
    // const isRTL = document.documentElement.getAttribute('dir') === 'rtl';

    const logo = require(`../${AppData.LOGO}`); // TODO : Get logo from Logo folder (assets/logo)

    const [prevRoutes, setPrevRoutes] = useState({});
    const [open, setOpen] = useState(false);
    const [fs, setFs] = useState(false);

    useEffect(() => {

        let tmpRoutes = {};

        tmpRoutes["product-editor"] = "product-list";
        tmpRoutes["inventory-movement"] = "product-list";
        tmpRoutes["employee-editor"] = "employee-manager";
        tmpRoutes["inventory-sheet-editor"] = "inventory-manager";
        tmpRoutes["sales-point"] = "sales-list";
        tmpRoutes["customer-editor"] = "customer-manager";
        tmpRoutes["reception-editor"] = "reception-list";

        setPrevRoutes(tmpRoutes);

    }, []);

    const handleFullScreenOnClick = () => {

        const element = document.documentElement;

        if (!fs) {
            if (element.requestFullscreen) {
                element.requestFullscreen();
            } else if (element.mozRequestFullScreen) {
                element.mozRequestFullScreen();
            } else if (element.webkitRequestFullscreen) {
                element.webkitRequestFullscreen();
            } else if (element.msRequestFullscreen) {
                element.msRequestFullscreen();
            }

            setFs(true);
        } else {
            if (document.exitFullscreen) {
                document.exitFullscreen();
            } else if (document.mozCancelFullScreen) {
                document.mozCancelFullScreen();
            } else if (document.webkitExitFullscreen) {
                document.webkitExitFullscreen();
            } else if (document.msExitFullscreen) {
                document.msExitFullscreen();
            }

            setFs(false);
        }

    }

    const navigate = useNavigate();
    const location = useLocation();

    // Function to go back to the previous page
    const goBack = () => {
        // navigate(-1);

        let previousRoute = "/dashboard";
        const noSlashLocation = location.pathname.startsWith('/') ? location.pathname.slice(1) : location.pathname;
        console.log(noSlashLocation);

        if (prevRoutes[noSlashLocation]) {
            previousRoute = '/' + prevRoutes[noSlashLocation];
        }

        navigate(previousRoute);
    };

    return (
        <nav className='flex flex-row items-center justify-between px-2 sm:px-4 py-2.5 bg-gray-900 fixed w-full z-50 top-0 left-0 border-b border-gray-600 h-16' >

            <div className='grid grid-cols-2 gap-2' style={{ zIndex: 60 }}>
                {/* Back Arrow */}
                {location.pathname.length >= 2 && <button className='flex flex-col items-center justify-center w-10 h-10 p-2 text-gray-500 transition duration-300 border-2 border-gray-700 cursor-pointer select-none left-4 top-3 hover:text-gray-100 rounded-3xl hover:border-gray-200 active:border-4' onClick={goBack}>
                    {isRTL() ? <FaArrowRight size={22} /> : <FaArrowLeft size={22} />}
                </button>}
            </div>

            <div style={{ top: AppData.LOGO_TOP_DISTANCE }} className='fixed right-0 left-0 flex flex-row items-center justify-center'>

                {/* Logo */}
                {
                    AppData.LOGO_AND_LABEL && (AppData.LOGO_AND_LABEL == "BOTH" || AppData.LOGO_AND_LABEL == "LOGO") &&
                    <Link to='/dashboard'>
                        <span className='text-3xl font-bold text-gray-100 duration-300 scale-75 opacity-50 hover:opacity-90 sm:scale-100'>
                            <img src={logo} className={`h-${AppData.LOGO_HEIGHT ? AppData.LOGO_HEIGHT : "10"} antialiased transition duration-300`} alt='logo' />
                        </span>
                    </Link>
                }

                {(AppData.LOGO_AND_LABEL && AppData.LOGO_AND_LABEL == "BOTH") && <span className='mx-0.5 sm:mx-2' />}

                {/* Label */}
                {
                    AppData.LOGO_AND_LABEL && (AppData.LOGO_AND_LABEL == "BOTH" || AppData.LOGO_AND_LABEL == "LABEL") &&
                    <Link to='/dashboard'>
                        <span className='text-2xl font-medium text-gray-100 duration-300 opacity-50 hover:opacity-90 sm:font-bold sm:text-3xl'>
                            {AppData.COMPANY_LABEL}
                        </span>
                    </Link>
                }

            </div>

            <div className='relative flex flex-row items-center justify-center gap-x-2'>

                {/* Sress Testing Mode */}
                {AppData.STRESS_TESTING && <button className='flex flex-col items-center justify-center w-10 h-10 p-2 text-gray-300 border-2 border-red-900 cursor-not-allowed rounded-3xl bg-gradient-to-b from-red-500 to-orange-500'>
                    <FaFire className='' size={22} />
                </button>}

                {/* Forensics Mode */}
                {InForensicsMode() && <button className='flex flex-col items-center justify-center w-10 h-10 p-2 text-gray-300 border-2 border-red-900 cursor-not-allowed rounded-3xl bg-gradient-to-b from-red-700 to-indigo-700'>
                    <FaSearchPlus className='' size={22} />
                </button>}

                {/* Fullscreen Button */}
                {AppData.FULLSCREEN_BUTTON && <button className='flex flex-col items-center justify-center w-10 h-10 p-2 text-gray-500 transition duration-300 border-2 border-gray-700 cursor-pointer select-none hover:text-gray-100 rounded-3xl hover:border-gray-200 active:border-4' onClick={handleFullScreenOnClick}>
                    <FaExpand className='' size={22} />
                </button>}

                {/* {IsLoggedIn() && <button className='flex flex-col items-center justify-center w-10 h-10 p-2 text-gray-500 transition duration-300 border-2 border-gray-700 cursor-pointer select-none hover:text-gray-100 rounded-3xl hover:border-gray-200 active:border-4' onClick={() => { setOpen(!open); }}>
                    <FaDatabase size={22} />
                </button>} */}

                {/* {IsLoggedIn() && <button className='flex flex-col items-center justify-center w-10 h-10 p-2 text-gray-500 transition duration-300 border-2 border-gray-700 cursor-pointer select-none hover:text-gray-100 rounded-3xl hover:border-gray-200 active:border-4' onClick={() => { setOpen(!open); }}>
                    <FaEnvelope size={22} />
                </button>} */}

                {IsLoggedIn() && <button className='flex flex-col items-center justify-center w-10 h-10 p-2 text-gray-500 transition duration-300 border-2 border-gray-700 cursor-pointer select-none hover:text-gray-100 rounded-3xl hover:border-gray-200 active:border-4' onClick={() => { setOpen(!open); }}>
                    <FaUser size={22} />
                </button>}

                {open && <UserProfileMenu onBlur={() => setOpen(false)} />}

            </div>

        </nav >
    )
}

export default NavBar