import React, { useState, useEffect } from 'react';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import { StringToNumber_2DecAlways } from '../Reaknotron/Libs/RknStringTools';
import Table from 'rc-table';

const ReceptionTotalCounter = (props) => {

    const leftCellStyle = 'mt-2';
    const rightCellStyle = 'font-bold bg-gray-700 p-2 rounded-xl';

    const columns = [
        {
            title: 'Fournisseur',
            dataIndex: 'label',
            key: 'label',
            className: 'border border-gray-500',
            width: 320
        },
        {
            title: "Total",
            dataIndex: 'total',
            key: 'total',
            width: 256,
            className: 'border border-gray-500'
        }
    ];

    // Effects
    useEffect(() => {

        GetReceptionTotal();

    }, [props]);

    // States
    const [total, setTotal] = useState(0);
    const [fullfilled, setFullfilled] = useState(0);
    const [establishmentsTotals, setEstablishmentsTotals] = useState(null);

    const GetReceptionTotal = async () => {

        // Build Req/Res
        let url;

        if (props.start && props.end)
            url = "/api/get-reception-total?start=" + props.start.toISOString() + "&end=" + props.end.toISOString();
        else
            url = "/api/get-reception-total";

        PerformGetRequest(url, (res) => {
            setTotal(res.data.total);
            setFullfilled(res.data.fullfilled);
            setEstablishmentsTotals(res.data.establishmentsTotal);
        });

    }

    return (
        <div className='bg-gray-800 border-4 border-gray-500 rounded-xl text-gray-100 text-3xl p-4 m-4 font-bold'>
            <div className='flex flex-col items-center'>
                <div className='grid grid-cols-2 gap-2 text-gray-300 text-left'>
                    <div className={leftCellStyle}>Montant Total des Réceptions</div><div className={rightCellStyle + ' border-2 border-orange-600'} >{total || "0"} DA</div>
                    <div className={leftCellStyle}>Montant Total Payé</div><div className={rightCellStyle + ' border-4 border-green-500'} >{fullfilled || "0"} DA</div>
                    <div className={leftCellStyle}>Pourcentage Payé</div><div className={rightCellStyle + ' border-4 border-green-300'} >{total ? StringToNumber_2DecAlways(fullfilled / total * 100) : "-"} %</div>
                </div>
                {establishmentsTotals && <div className='mt-4 text-lg'>
                    <Table columns={columns} data={establishmentsTotals} rowKey="id" tableLayout='auto' className='m-auto text-gray-100' />
                </div>}
            </div>
        </div>
    )
}

export default ReceptionTotalCounter