import React, { useState, useEffect } from 'react';
import { GetPrintServerAddress, GetPrinterName, GetIfReducedPerformance, GetIfPrintWaitingReceipt, GetInfoLineOne, GetInfoLineTwo, GetIfShowProductsOutOfStock, GetCurrencyDesignation, GetCurrencySymbol, GetCashReg } from '../const';
import RknContainer from '../components/RknUI/RknContainer';
import { AwesomeButton } from 'react-awesome-button';
import { InputFieldStyle } from '../Styles';
import AppData from '../App.json';
import ProductSearchPopup from '../components/ProductSearchPopup';
import ProductImage from '../components/ProductImage';
import HourlyStatusEditor from '../components/HourlyStatusEditor';
import SilverPriceEditor from '../components/SilverPriceEditor';
import RknButton from '../components/RknUI/RknButton';
import { switchLanguage } from '../i18n';
import RknSmartSelector from '../components/RknUI/RknSmartSelector';

const Config = () => {

    // Effect
    useEffect(() => {

        setPrintServerAddress(GetPrintServerAddress());
        setPrinterName(GetPrinterName());
        setReducedPerformance(GetIfReducedPerformance());
        setPrintWaitingReceipt(GetIfPrintWaitingReceipt());
        setShowProductsOutOfStock(GetIfShowProductsOutOfStock());
        setInfoLineOne(GetInfoLineOne());
        setInfoLineTwo(GetInfoLineTwo());
        setCurrencyDesignation(GetCurrencyDesignation());
        setCurrencySymbol(GetCurrencySymbol());
        setCashReg(GetCashReg());

        // if (localStorage.getItem("infoLineOne")) {
        //     setInfoLineOne(localStorage.getItem("infoLineOne"));
        // }

        // if (localStorage.getItem("infoLineTwo")) {
        //     setInfoLineTwo(localStorage.getItem("infoLineTwo"));
        // }

        if (localStorage.getItem("footerNote")) {
            setFooterNote(localStorage.getItem("footerNote"));
        }

        if (localStorage.getItem("receiptWidth")) {
            setReceiptWidth(localStorage.getItem("receiptWidth"));
        } else {
            setReceiptWidth("72.1");
        }

        if (localStorage.getItem("sameProdPrepTimeModifier")) {
            setSameProdPrepTimeModifier(localStorage.getItem("sameProdPrepTimeModifier"));
            // console.log(localStorage.getItem("sameProdPrepTimeModifier"));
        }

        if (localStorage.getItem("sameCatPrepTimeModifier")) {
            setSameCatPrepTimeModifier(localStorage.getItem("sameCatPrepTimeModifier"));
            // console.log(localStorage.getItem("sameCatPrepTimeModifier"));
        }

        if (localStorage.getItem("cashReg")) {
            setCashReg(localStorage.getItem("cashReg"));
        }

    }, []);

    const [printServerAddress, setPrintServerAddress] = useState("");
    const [printerName, setPrinterName] = useState("");
    const [infoLineOne, setInfoLineOne] = useState("");
    const [infoLineTwo, setInfoLineTwo] = useState("");
    const [footerNote, setFooterNote] = useState("");
    const [receiptWidth, setReceiptWidth] = useState("");

    const [reducedPerformance, setReducedPerformance] = useState(false);

    const [sameProdPrepTimeModifier, setSameProdPrepTimeModifier] = useState(0.2);
    const [sameCatPrepTimeModifier, setSameCatPrepTimeModifier] = useState(0.5);
    const [printWaitingReceipt, setPrintWaitingReceipt] = useState(false);
    const [showProductsOutOfStock, setShowProductsOutOfStock] = useState(false);

    const [sokkifyInfo, setSokkifyInfo] = useState({ shopID: "", apiToken: "" });

    const [quickServiceItems, setQuickServiceItems] = useState([7, 8, 9, 4, 5, 6, 1, 2, 3]);
    const [searchProductWindowOpen, setSearchProductWindowOpen] = useState(false);
    const [currentQuickServiceSlot, setCurrentQuickServiceSlot] = useState(null);

    const [currencyDesignation, setCurrencyDesignation] = useState("Dinars");
    const [currencySymbol, setCurrencySymbol] = useState("DA");

    const [cashReg, setCashReg] = useState(null);

    const [changesAvailable, setChangesAvailable] = useState(false);

    const handlePrintServerAddressChange = (e) => {
        setPrintServerAddress(e.target.value);
        setChangesAvailable(true);
    }

    const handlePrinterNameChange = (e) => {
        setPrinterName(e.target.value);
        setChangesAvailable(true);
    }

    const handleInfoLineOneChange = (e) => {
        setInfoLineOne(e.target.value);
        setChangesAvailable(true);
    }

    const handleInfoLineTwoChange = (e) => {
        setInfoLineTwo(e.target.value);
        setChangesAvailable(true);
    }

    const handleFooterNoteChange = (e) => {
        setFooterNote(e.target.value);
        setChangesAvailable(true);
    }

    const handleReceiptWidthChange = (e) => {
        setReceiptWidth(e.target.value);
        setChangesAvailable(true);
    }

    const handleReducedPerformanceChange = () => {
        setReducedPerformance(!reducedPerformance);
        setChangesAvailable(true);
    };

    const handleSameProdPrepTimeModifierChange = (e) => {
        setSameProdPrepTimeModifier(e.target.value);
        setChangesAvailable(true);
    }

    const handleSameCatPrepTimeModifierChange = (e) => {
        setSameCatPrepTimeModifier(e.target.value);
        setChangesAvailable(true);
    }

    const handlePrintWaitingReceiptChange = () => {
        setPrintWaitingReceipt(!printWaitingReceipt);
        setChangesAvailable(true);
    };

    const handleShowProductsOutOfStockChange = () => {
        setShowProductsOutOfStock(!showProductsOutOfStock);
        setChangesAvailable(true);
    };

    const handleCurrencyDesignationChange = (e) => {
        setCurrencyDesignation(e.target.value);
        setChangesAvailable(true);
    };

    const handleCurrencySymbolChange = (e) => {
        setCurrencySymbol(e.target.value);
        setChangesAvailable(true);
    };

    const handleCashRegChange = (ParamItem) => {
        setCashReg(ParamItem._id);
        setChangesAvailable(true);
    };

    const saveBtnOnClick = () => {
        localStorage.setItem("printServerAddress", printServerAddress);
        localStorage.setItem("printerName", printerName);
        localStorage.setItem("infoLineOne", infoLineOne);
        localStorage.setItem("infoLineTwo", infoLineTwo);
        localStorage.setItem("footerNote", footerNote);
        localStorage.setItem("receiptWidth", receiptWidth);
        localStorage.setItem("reducedPerformance", reducedPerformance);
        localStorage.setItem("sameProdPrepTimeModifier", sameProdPrepTimeModifier);
        localStorage.setItem("sameCatPrepTimeModifier", sameCatPrepTimeModifier);
        localStorage.setItem("printWaitingReceipt", printWaitingReceipt.toString());
        localStorage.setItem("showProductsOutOfStock", showProductsOutOfStock.toString());
        localStorage.setItem("currencyDesignation", currencyDesignation);
        localStorage.setItem("currencySymbol", currencySymbol);
        localStorage.setItem("cashReg", cashReg);
        setChangesAvailable(false);
    }

    const SearchProductOnConfirm = (ParamBarcode) => {

        if (!currentQuickServiceSlot)
            return;

        console.log(currentQuickServiceSlot + " : " + ParamBarcode);
        localStorage.setItem("quick-service-slot-" + currentQuickServiceSlot, ParamBarcode);
        // PerformGetRequest("/api/get-product?id=" + ParamBarcode, OnProductFound);
        setSearchProductWindowOpen(false);
    }

    const handleClearQuickServiceItems = () => {
        for (let i = 1; i <= 9; i++) {
            if (localStorage.getItem("quick-service-slot-" + i)) {
                localStorage.removeItem("quick-service-slot-" + i);
            }
        }
    }

    return (
        <div className='flex flex-col items-center justify-center pt-4'>

            {true &&
                <RknContainer title="Configuration de la Devise">
                    <br />
                    <label className='text-gray-100 text-sm'>Designation : </label>
                    <br />
                    <input type='text' name='currencyDesignation' value={currencyDesignation} onChange={handleCurrencyDesignationChange} placeholder="Designation de la devise..." className={InputFieldStyle} />
                    <br />
                    <br />
                    <label className='text-gray-100 text-sm'>Symbole : </label>
                    <br />
                    <input type='text' name='currencySymbol' value={currencySymbol} onChange={handleCurrencySymbolChange} placeholder="Symbole de la devise..." className={InputFieldStyle} />
                    <br />
                    <br />
                </RknContainer>
            }

            <RknContainer title="💬 Langue">
                <RknButton label="Arabe" onPress={() => switchLanguage("ar")} />
                <RknButton label="Français" onPress={() => switchLanguage("fr")} />
            </RknContainer>

            {AppData.PRINTER_MANAGEMENT_FLAG &&
                <RknContainer title="Configuration de l'Imprimante">
                    <label className='text-gray-100 text-sm'>Adresse du Serveur d'Impression : </label>
                    <br />
                    <input type='text' name='printServerAddress' value={printServerAddress} onChange={handlePrintServerAddressChange} placeholder="Adresse du Serveur d'Impression..." className={InputFieldStyle} />
                    <br />
                    <br />
                    <label className='text-gray-100 text-sm'>Nom de l'Imprimante : </label>
                    <br />
                    <input type='text' name='printerName' value={printerName} onChange={handlePrinterNameChange} placeholder="Nom de l'Imprimante..." className={InputFieldStyle} />
                    <br />
                    <br />
                    <label className='text-gray-100 text-sm'>Information sur le Bon (Ligne 1) : </label>
                    <br />
                    <input type='text' name='infoLineOne' value={infoLineOne} onChange={handleInfoLineOneChange} placeholder="Ligne N° 1..." className={InputFieldStyle} />
                    <br />
                    <br />
                    <label className='text-gray-100 text-sm'>Information sur le Bon (Ligne 2) : </label>
                    <br />
                    <input type='text' name='infoLineTwo' value={infoLineTwo} onChange={handleInfoLineTwoChange} placeholder="Ligne N° 2..." className={InputFieldStyle} />
                    <br />
                    <br />
                    <label className='text-gray-100 text-sm'>Note en bas du Bon : </label>
                    <br />
                    <input type='text' name='footerNote' value={footerNote} onChange={handleFooterNoteChange} placeholder="Note en bas du Ticket de Caisse..." className={InputFieldStyle} />
                    <br />
                    <br />
                    <label className='text-gray-100 text-sm'>Largeur du Ticket de Caisse : </label>
                    <br />
                    <input type='number' name='receiptWidth' value={receiptWidth} onChange={handleReceiptWidthChange} placeholder="Largeur du Ticket de Caisse..." className={InputFieldStyle} />
                    <br />
                </RknContainer>
            }

            {true &&
                <RknContainer title="Configuration du Graphisme">
                    <br />
                    <label>
                        <input type="checkbox" checked={reducedPerformance} onChange={handleReducedPerformanceChange} className='mr-1 w-4 h-4' />
                        <p className='ml-1 text-gray-100 font-bold inline text-lg'>Performance Réduite</p>
                    </label>
                    <br />
                    <br />
                </RknContainer>
            }

            {AppData.CATERING_FLAG &&
                <RknContainer title="Configuration de la Restauration">
                    <br />
                    <label className='text-gray-100 text-sm'>Pourcentage de Temps de préparation du même produit : </label>
                    <br />
                    <input type='number' step='0.1' name='sameProdPrepTimeModifier' value={sameProdPrepTimeModifier} onChange={handleSameProdPrepTimeModifierChange} placeholder="Pourcentage de Temps de préparation du même produit..." className={InputFieldStyle} />
                    <br />
                    <br />
                    <label className='text-gray-100 text-sm'>Pourcentage de Temps de préparation de même catégorie : </label>
                    <br />
                    <input type='number' step='0.1' name='sameCatPrepTimeModifier' value={sameCatPrepTimeModifier} onChange={handleSameCatPrepTimeModifierChange} placeholder="Pourcentage de Temps de préparation de même categorie..." className={InputFieldStyle} />
                    <br />
                    <br />
                    <label>
                        <input type="checkbox" checked={printWaitingReceipt} onChange={handlePrintWaitingReceiptChange} className='mr-1 w-4 h-4' />
                        <p className='ml-1 text-gray-100 font-bold inline text-lg'>Imprimer le bon d'attente</p>
                    </label>
                    <br />
                    <br />
                    <label>
                        <input type="checkbox" checked={showProductsOutOfStock} onChange={handleShowProductsOutOfStockChange} className='mr-1 w-4 h-4' />
                        <p className='ml-1 text-gray-100 font-bold inline text-lg'>Afficher les produits en rupture de stock</p>
                    </label>
                    <br />
                    <br />
                </RknContainer>
            }

            {AppData.CATERING_FLAG &&
                <RknContainer title="⚡ Service Rapide">
                    <div className='grid grid-rows-3 grid-cols-3'>
                        {quickServiceItems.map((item) => {
                            return (localStorage.getItem("quick-service-slot-" + item) ? <ProductImage id={localStorage.getItem("quick-service-slot-" + item)} size={64} /> : <div onClick={() => { setSearchProductWindowOpen(true); setCurrentQuickServiceSlot(item); }}
                                className='bg-gray-700 text-gray-100 font-bold text-3xl p-1 m-1 rounded-xl w-16 h-16 cursor-pointer hover:bg-gray-500 transition duration-300'
                            >
                                {item}
                            </div>);
                        })}
                    </div>
                    <div
                        onClick={handleClearQuickServiceItems}
                        className='text-gray-100 font-bold text-sm bg-gray-900 p-1 cursor-pointer hover:bg-gray-700 m-2 rounded-full active:scale-90 transition duration-150'
                    >
                        Clear
                    </div>
                </RknContainer>
            }

            {AppData.EMPLOYEE_MANAGEMENT_FLAG &&
                <RknContainer title="⏱ Pointage par défaut">
                    <HourlyStatusEditor />
                </RknContainer>
            }

            {AppData.SILVER_SHOP &&
                <RknContainer title="💍 Prix d'Un Gramme d'Argent">
                    <SilverPriceEditor />
                </RknContainer>
            }

            {AppData.SALES_POINT_FLAG &&
                <RknContainer title="📠 Caisse">
                    <RknSmartSelector url={"/api/cash-registers"} idKey="_id" value={cashReg} labelKey="designation" reaktorContext="CASH_REGISTER" onChange={handleCashRegChange} quickAddRoute="/cash-reg-editor" />
                </RknContainer>
            }

            <br />
            {changesAvailable && <AwesomeButton type='primary' onPress={saveBtnOnClick} >Enregistrer</AwesomeButton>}

            {searchProductWindowOpen && <ProductSearchPopup onConfirm={SearchProductOnConfirm} onCancel={() => { setSearchProductWindowOpen(false); }} />}
        </div>
    )
}

export default Config