import React from 'react';

const RknCompactButton = (props) => {

  const handleOnPress = () => {
    if (props.disabled) {
      // Do Nothing
    } else {
      if (props.onPress)
        props.onPress();
    }
  }

  return (
    <div className={props.className ? props.className : ''}>
      <button
        className={`w-full border-b-2 ${props.disabled ? "border-neutral-700 hover:border-neutral-500 bg-neutral-400 hover:bg-neutral-400 text-neutral-500" : "border-blue-700 hover:border-blue-500 bg-blue-500 hover:bg-blue-400 text-gray-100"} font-bold py-1 px-2 rounded my-0.5 flex flex-row items-center justify-center transition duration-150 active:translate-y-0.5 h-8`}
        onClick={handleOnPress}
      >
        {props.before && <div className='me-1 pt-0.5'>{props.before}</div>}
        {props.responsive ? <div className='hidden text-sm font-medium sm:block'>{props.label ? props.label : "???"}</div> : <div>{props.label ? props.label : "???"}</div>}
      </button>
    </div>
  )
}

export default RknCompactButton