import React from 'react';
import { useState, useEffect } from 'react';
import { PerformGetRequest, PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import { Stage, Layer, Rect, Text, Group, Circle } from 'react-konva';

function CstMap(props) {

    // const MAX_X = 768 - (16 * 4);
    // const MAX_Y = 512 - (16 * 4);
    const TABLE_SIZE = 64;

    useEffect(() => {

        if (props.width) {
            setWidth(props.width);
            set_MAX_X(props.width - TABLE_SIZE);
        }

        if (props.length) {
            setLength(props.length);
            set_MAX_Y(props.length - TABLE_SIZE);
        }

    }, [props.width, props.length]);

    const [tables, setTables] = useState({});
    const [width, setWidth] = useState(null);
    const [length, setLength] = useState(null);
    const [MAX_X, set_MAX_X] = useState(null);
    const [MAX_Y, set_MAX_Y] = useState(null);

    useEffect(() => {
        PerformGetRequest("/api/get-customer-sitting-tables-list", (ParamResult) => {
            // console.log(JSON.stringify(ParamResult.data));
            // setCstList(ParamResult.data);
            let tmpTables = {};

            for (let i = 0; i < ParamResult.data.length; i++) {
                // console.log(ParamResult.data[i]);
                // result[i].order = c;
                // tmpTables[ParamResult.data[i]._id] = ParamResult.data[i];
                tmpTables[ParamResult.data[i]._id] = {
                    name: ParamResult.data[i].name,
                    color: ParamResult.data[i].color,
                    pos: { x: ParamResult.data[i].xPos, y: ParamResult.data[i].yPos },
                    occupied: ParamResult.data[i].occupied
                }
            }

            console.log(JSON.stringify(tmpTables));
            setTables(tmpTables);
        });
    }, []);

    const handleDragEnd = (e, tableId) => {

        if (!props.editMode) {
            return;
        }

        // console.log("DRAG END : " + e.target.x() + " /// " + e.target.y());

        // Calculate the nearest grid point
        const gridSize = TABLE_SIZE / 4;
        const newPos = {
            x: Math.round(e.target.x() / gridSize) * gridSize,
            y: Math.round(e.target.y() / gridSize) * gridSize
        };

        // Clamp the position within the bounds
        if (newPos.x > MAX_X) {
            newPos.x = MAX_X;
        }

        if (newPos.y > MAX_Y) {
            newPos.y = MAX_Y;
        }

        if (newPos.x < 0) {
            newPos.x = 0;
        }

        if (newPos.y < 0) {
            newPos.y = 0;
        }

        if (newPos && newPos.x && newPos.y) {

            // Update the position in the state
            setTables(prevTables => {
                const newTables = { ...prevTables };
                newTables[tableId].pos = newPos;
                return newTables;
            });

            // Update the position in the database
            PerformSecurePostRequest("/api/update-cst", { id: tableId, xPos: newPos.x, yPos: newPos.y }, (res) => {

            });

        }

    };

    const handleTableClick = (e, ParamTableID) => {

        if (props.editMode)
            return;

        // console.log("TABLE ID = " + ParamTableID);

        if (props.onClick)
            props.onClick(ParamTableID);
    }

    return (
        // <Stage width={window.innerWidth} height={window.innerHeight}>
        // <div className='fixed z-50 bg-black opacity-95 top-0 bottom-0 right-0 left-0 flex flex-col items-center justify-center'>
        <div>
            {width && length &&
                <div className='flex flex-col items-center justify-center'>
                    <div className='bg-black bg-opacity-80 backdrop-blur-xl rounded-t-lg text-gray-100 font-bold text-sm p-2 px-4 border-t-4 border-x-4 border-gray-100'>
                        {props.editMode ? "Plan des Tables (Mode Editeur)" : "Plan des Tables"}
                    </div>
                    <div className='bg-black bg-opacity-80 backdrop-blur-xl border-8 border-gray-100 rounded-xl' style={{ width: MAX_X, height: MAX_Y }}>
                        <Stage width={width} height={length}>
                            <Layer fill="red">
                                {tables && Object.keys(tables).map((tableId) => {
                                    const table = tables[tableId];
                                    return (
                                        <Group
                                            key={tableId}
                                            draggable={props.editMode}
                                            onDragEnd={(e) => { handleDragEnd(e, tableId); document.body.style.cursor = 'grab'; }}
                                            x={table.pos.x}
                                            y={table.pos.y}
                                            onDragStart={() => { document.body.style.cursor = 'grabbing'; }}
                                            onMouseEnter={() => { props.editMode ? document.body.style.cursor = 'grab' : document.body.style.cursor = 'pointer'; }}
                                            onMouseLeave={() => { document.body.style.cursor = 'default'; }}
                                            onClick={(e) => { handleTableClick(e, tableId); }}
                                        >
                                            <Rect
                                                width={TABLE_SIZE}
                                                height={TABLE_SIZE}
                                                fill={table.color ? table.color : "#333333"}
                                                cornerRadius={16}
                                            />
                                            <Text
                                                text={table.occupied ? "🔴 " + table.name : "🟢 " + table.name}
                                                fill='white'
                                                width={TABLE_SIZE} // Set the width to the width of the Rect
                                                height={TABLE_SIZE} // Set the height to the height of the Rect
                                                align='center'
                                                verticalAlign='middle'
                                                fontStyle='bold'
                                            />
                                        </Group>
                                    );
                                })}
                            </Layer>
                        </Stage>
                    </div>
                </div>
            }
        </div>

    );
}

export default CstMap;