import React, { useState, useEffect, useRef } from 'react';
import Popup from 'reactjs-popup';
import { FaTimesCircle, FaCheckCircle, FaHandHoldingUsd, FaMobile, FaHourglass } from 'react-icons/fa';
import RknNumericInput from '../components/RknUI/RknNumericInput';
import CountUp from 'react-countup';
import AppData from '../App.json';
import { motion } from "framer-motion";
import { PerformGetRequest, PerformRawGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import useReaktor from '../Hooks/useReaktor';

import { useTranslation } from 'react-i18next';
import { GetCurrencySymbol } from '../const';
import RknButton from './RknUI/RknButton';
import { InputFieldStyle } from '../Styles';

const PaymentPopup = (props) => {

    const { t, i18n } = useTranslation();

    const ref_step1 = useRef(null);
    const ref_step2 = useRef(null);

    useEffect(() => {

        // console.log("PROPS.CUSTOMER = " + JSON.stringify(props.customer));
        console.log("PROPS.EST = " + JSON.stringify(props.establishment));

        if (props.customer) {
            PerformGetRequest("/api/get-customer?id=" + props.customer, (res) => {
                setCustomerBalance(res.data.balance);
                setCustomerFullname(res.data.firstName + " " + res.data.familyName);
            });
        } else if (props.establishment) {
            PerformGetRequest("/api/get-establishment?id=" + props.establishment, (res) => {
                setCustomerBalance(res.data.balance);
                setCustomerFullname(res.data.designation);
            });
        }

        if (ref_step1 && ref_step1.current) {
            ref_step1.current.focus();
        }

        if (props.initialValue) {
            setAmountToPay(props.initialValue);
            setTotal(props.initialValue);
        }

    }, []);

    useReaktor("CHARGILY", (ParamContent) => {
        console.log("REAKTOR CONTENT = " + JSON.stringify(ParamContent));

        if (ParamContent) {
            if (ParamContent.type === "checkout.paid") {
                setEPaymentStatus("PAID");
            } else {
                setEPaymentStatus("FAILED");
            }
        }
    });

    const [total, setTotal] = useState(0);
    const [amountToPay, setAmountToPay] = useState(0);
    const [finalized, setFinalized] = useState(true);
    const [initialPayment, setInitialPayment] = useState(0);
    const [selectedPaymentMethod, setSelectedPaymentMethod] = useState('CASH');
    const [step, setStep] = useState(1);
    const [receivedCash, setReceivedCash] = useState("");
    const [giveBackCash, setGiveBackCash] = useState(0);
    const [ePaymentButtonBusy, setEPaymentButtonBusy] = useState(false);
    const [ePaymentStatus, setEPaymentStatus] = useState("NULL");
    const [discountPercentage, setDiscountPercentage] = useState(0);
    const [checkIdNumber, setCheckIdNumber] = useState("");
    const [customerFullname, setCustomerFullname] = useState("");
    const [customerBalance, setCustomerBalance] = useState(0);

    const CloseModal = () => {
        props.onClose();
    }

    const handleAmountChange = (ParamValue) => {
        setAmountToPay(ParamValue);
        const normalized = 1 - (ParamValue / total);
        setDiscountPercentage(normalized * 100);
    }

    const handleDiscountPercentageChange = (ParamValue) => {
        setDiscountPercentage(ParamValue);
        const discount = total * ParamValue / 100;
        setAmountToPay(total - discount);
    }

    const OnSubmit_StepOne = () => {

        if (AppData.GIVEBACK_CASH_CALCULATOR_FLAG) {

            setStep("GIVEBACK_CASH_CALCULATOR");
            setTimeout(() => {
                if (ref_step2 && ref_step2.current) {
                    ref_step2.current.focus();
                }
            }, 150);

        } else {

            if (props.onConfirm) {

                let initialPaymentToPost = initialPayment;

                if (!AppData.CUSTOMER_NAME_IN_SALES_POINT || (!props.customer && !props.establishment)) {
                    initialPaymentToPost = amountToPay;
                }

                props.onConfirm(finalized, amountToPay, initialPaymentToPost, selectedPaymentMethod, initialPaymentToPost, 0, checkIdNumber);
                CloseModal();
            }

        }

        // PerformGetRequest("/api/open-cash-drawer", (res) => { }); // TODO : Cash drawer flag
        PerformRawGetRequest("http://localhost:4000/api/open-cash-drawer", (res) => { }); // TODO : Cash drawer flag

    }

    const OnSubmit_GiveBackCashCalculator = () => {
        if (props.onConfirm) {

            let initialPaymentToPost = initialPayment;

            if (!AppData.CUSTOMER_NAME_IN_SALES_POINT || (!props.customer && !props.establishment)) {
                initialPaymentToPost = amountToPay;
            }

            props.onConfirm(finalized, amountToPay, initialPaymentToPost, selectedPaymentMethod, receivedCash, giveBackCash);
            CloseModal();
        }
    }

    const OnSubmit_AwaitingMobilePayment = () => {
        if (props.onConfirm) {

            let initialPaymentToPost = initialPayment;

            if (!AppData.CUSTOMER_NAME_IN_SALES_POINT || (!props.customer && !props.establishment)) {
                initialPaymentToPost = amountToPay;
            }

            props.onConfirm(finalized, amountToPay, initialPaymentToPost, selectedPaymentMethod, receivedCash, giveBackCash);
            CloseModal();
        }
    }

    const StressOnPress = () => {
        if (props.onStress) {

            let initialPaymentToPost = initialPayment;

            if (!AppData.CUSTOMER_NAME_IN_SALES_POINT || (!props.customer && !props.establishment)) {
                initialPaymentToPost = amountToPay;
            }

            props.onStress(finalized, amountToPay, initialPaymentToPost, selectedPaymentMethod, receivedCash, giveBackCash);
            CloseModal();
        }
    }

    // const handleFinalizedChange = () => {
    //     setFinalized(!finalized);
    // };

    const handlePaymentMethodChange = (event) => {
        setSelectedPaymentMethod(event.target.value);
    };

    const handleMobilePaymentOnClick = () => {

        setEPaymentButtonBusy(true);

        PerformGetRequest("/api/get-payment-link?amount=" + amountToPay, (res => {
            if (res && res.data) {
                setStep("AWAITING_MOBILE_PAYMENT");
                setEPaymentStatus("PENDING");
                window.open(res.data.url, '_blank');
                setEPaymentButtonBusy(false);
            }
        }))
    }

    const handleInialPaymentOnChange = (ParamValue) => {
        if (ParamValue > amountToPay)
            ParamValue = amountToPay; // Prevent over payment due to balance bug // TODO : Fix this bug

        setInitialPayment(ParamValue);
    }

    return (
        <div>
            <Popup
                open={props.isOpen}
                modal
                closeOnDocumentClick
                onClose={() => { CloseModal(); }}
            >
                <div className="p-2 text-gray-100 bg-gray-900 modal">
                    <button className="close" onClick={() => { CloseModal(); }}>
                        <FaTimesCircle />
                    </button>
                    <div className="header">{t("pos.toolbar.payment.pay")}</div>
                    <br />

                    {/* Step 1 */}
                    {step === 1 && <motion.form
                        onSubmit={OnSubmit_StepOne}
                        className="flex flex-col items-center content"
                        initial={{ opacity: 0, y: "-15%" }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ duration: 0.3 }}
                    >

                        {/* Total */}
                        <label className='text-sm'>{t("pos.toolbar.payment.total")} :</label>
                        <div className={'text-gray-100 font-bold rounded-lg flex flex-row items-center justify-center'}>
                            <CountUp end={total} useEasing={false} preserveValue={true} duration='0.4' style={{ fontSize: 48 }} separator='' />
                            <div style={{ fontSize: 48 }} className='mx-2 font-light text-neutral-500'>{GetCurrencySymbol(i18n.language)}</div>
                        </div>
                        <span className='my-4' />

                        {/* Amount to Pay */}
                        <label className='text-sm'>{t("pos.toolbar.payment.payAmount")} :</label>
                        <div className='flex flex-row items-center justify-center space-x-1'>
                            <RknNumericInput value={amountToPay} onChange={handleAmountChange} placeholder="Montant à payer..." ref={ref_step1} />
                            <RknNumericInput value={discountPercentage} onChange={handleDiscountPercentageChange} placeholder="%..." unit="%" width="64px" />
                        </div>
                        <span className='my-2' />

                        {
                            AppData.CUSTOMER_NAME_IN_SALES_POINT && (props.customer || props.establishment) &&
                            <div className='flex flex-col items-center justify-center p-2 pb-1 mt-2 bg-gray-800 rounded-xl'>
                                <label className='text-sm'>Paiement Initiale :</label>
                                <RknNumericInput value={initialPayment} onChange={handleInialPaymentOnChange} placeholder="Paiement Initiale..." />
                                <span className='my-2' />
                                {customerFullname &&
                                    <div className='flex flex-col items-center justify-center text-sm text-gray-200 bg-gray-900 border-gray-600 border p-1 mb-1 rounded-lg border-dashed'>
                                        <div>Client : {customerFullname}</div>
                                        <div>Balance : {customerBalance}</div>
                                    </div>
                                }
                            </div>
                        }

                        {/* Payment Method */}
                        <label className='text-sm mt-4 mb-1'>Modalité du Paiement :</label>
                        <select
                            name="state"
                            className="py-1 mx-4 mb-6 text-sm text-gray-900 border border-gray-300 rounded-lg bg-gray-50 focus:ring-blue-500 focus:border-blue-500 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500"
                            defaultValue="CASH"
                            onChange={handlePaymentMethodChange}
                        >
                            <option value="CASH">💰  {t("pos.toolbar.payment.paymentMethods.cash")}</option>
                            <option value="CHECK">💶  {t("pos.toolbar.payment.paymentMethods.check")}</option>
                            <option value="BANK_TRANSFER">💹  {t("pos.toolbar.payment.paymentMethods.bankTransfer")}</option>
                            <option value="BANK_CARD">💳  {t("pos.toolbar.payment.paymentMethods.creditCard")}</option>
                            <option value="MOBILE_PAYMENT">📱  {t("pos.toolbar.payment.paymentMethods.mobilePayment")}</option>
                            <option value="ELECTRONIC_WALLET">🛄  {t("pos.toolbar.payment.paymentMethods.eWallet")}</option>
                            <option value="VIRTUAL_CURRENCY">✨  {t("pos.toolbar.payment.paymentMethods.cryptocurrency")}</option>
                        </select>

                        {(selectedPaymentMethod === "BANK_CARD" || selectedPaymentMethod === "MOBILE_PAYMENT") && <RknButton label="Paiement Mobile" before={<FaMobile />} onPress={handleMobilePaymentOnClick} busy={ePaymentButtonBusy} />}

                        {selectedPaymentMethod === "CHECK" &&
                            <motion.div
                                className='flex flex-col items-center justify-center mb-2'
                                initial={{ opacity: 0, y: "-15%" }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ duration: 0.3 }}
                            >
                                <label>N° de Chèque : </label>
                                <input type='text' value={checkIdNumber} className={InputFieldStyle} placeholder="Numéro de Chèque..." onChange={(e) => { setCheckIdNumber(e.target.value); }} />
                            </motion.div>
                        }

                        <div className='flex flex-row items-center justify-center space-x-2 mt-2'>

                            {!(selectedPaymentMethod === "BANK_CARD" || selectedPaymentMethod === "MOBILE_PAYMENT") && <button type='submit' className="px-4 py-2 font-bold text-white bg-blue-500 border-b-4 border-blue-700 rounded hover:bg-blue-400 hover:border-blue-500"><FaCheckCircle className='inline mb-1' size={20} />  {t("button.confirm")}</button>}

                            {AppData.STRESS_TESTING && <button type='button' className='flex flex-col items-center justify-center w-20 h-10 p-2 font-bold text-gray-300 border-2 border-red-900 cursor-pointer rounded-3xl bg-gradient-to-b from-red-500 to-orange-500 active:scale-95'
                                onClick={StressOnPress}
                            >
                                Stress
                            </button>}

                        </div>
                        <br />

                    </motion.form>}

                    {/* Step : GIVEBACK_CASH_CALCULATOR */}
                    {step === "GIVEBACK_CASH_CALCULATOR" && <motion.form onSubmit={OnSubmit_GiveBackCashCalculator} className="flex flex-col items-center content"
                        initial={{ opacity: 0, y: "-15%" }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ duration: 0.3 }}
                    >

                        <FaHandHoldingUsd size={48} />
                        <label className='text-sm'>Monnaie Reçu :</label>
                        <RknNumericInput value={receivedCash} onChange={(v) => { setReceivedCash(v); setGiveBackCash(v - amountToPay); }} placeholder="Monnaie Reçu..." ref={ref_step2} />
                        <span className='my-4' />

                        <label className='text-sm'>Monnaie à Rendre au Client :</label>
                        <div className={'text-gray-100 font-bold rounded-lg flex flex-row items-center justify-center'}>
                            <CountUp end={giveBackCash} useEasing={false} preserveValue={true} duration='0.2' style={{ fontSize: 48 }} separator='' />
                            <div style={{ fontSize: 48 }} className='mx-2 font-light text-neutral-500'>DA</div>
                        </div>
                        <span className='my-4' />

                        {receivedCash >= amountToPay
                            ?
                            <button type='submit' className="px-4 py-2 mt-2 font-bold text-white bg-blue-500 border-b-4 border-blue-700 rounded hover:bg-blue-400 hover:border-blue-500"><FaCheckCircle className='inline mb-1' size={20} /> Confirmer</button>
                            :
                            <div className='flex flex-col items-center justify-center text-red-500'><FaTimesCircle size={20} />Montant Insuffisant</div>
                        }
                        <br />

                    </motion.form>}

                    {/* Step : AWAITING_MOBILE_PAYMENT */}
                    {step === "AWAITING_MOBILE_PAYMENT" && <motion.form onSubmit={OnSubmit_AwaitingMobilePayment} className="flex flex-col items-center content"
                        initial={{ opacity: 0, y: "-15%" }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ duration: 0.3 }}
                    >

                        {ePaymentStatus === "PAID" &&
                            <div className='flex flex-col items-center justify-center text-green-500'>
                                <FaCheckCircle size={48} />
                                <div className='mt-2'>Paiement effectué avec succés.</div>
                            </div>
                        }

                        {ePaymentStatus === "PENDING" &&
                            <div className='flex flex-col items-center justify-center text-yellow-500'>
                                <FaHourglass size={48} className='animate-spin' />
                                <div className='mt-2'>En attente du paiement mobile...</div>
                            </div>
                        }

                        {ePaymentStatus === "FAILED" &&
                            <div className='flex flex-col items-center justify-center text-red-500'>
                                <FaTimesCircle size={48} />
                                <div className='mt-2'>Le paiement mobile a echoué...</div>
                            </div>
                        }

                        {ePaymentStatus === "PAID" && <button type='submit' className="px-4 py-2 mt-2 font-bold text-white bg-blue-500 border-b-4 border-blue-700 rounded hover:bg-blue-400 hover:border-blue-500"><FaCheckCircle className='inline mb-1' size={20} /> Confirmer</button>}
                        <br />

                    </motion.form>}

                </div>
            </Popup>
        </div>
    )
}

export default PaymentPopup;