import { React, useState, useEffect } from 'react';
import RknDateInput from './RknUI/RknDateInput';
import RknNumericInput from './RknUI/RknNumericInput';
import AppData from '../App.json';

const InitialStockEditor = (props) => {

    const [batches, setBatches] = useState({}); // A batch is a group of products that has the same expiration dates and/or same batch ID
    const [count, setCount] = useState(0);

    useEffect(() => {
        if (props.value) {
            // TODO : Load Value
        } else {
            let tmp = {};
            tmp[count] = { expiryDate: null, amount: 0 }
            setBatches(tmp);
            setCount(count + 1);
        }
    }, []);

    const handleOnAdd = () => {
        let tmp = batches;
        tmp[count] = { batchID: "", expiryDate: null, amount: 0, price: 0 }
        setBatches(tmp);
        setCount(count + 1);
    }

    const handleBatchIDChange = (ParamID, ParamValue) => {
        let tmp = batches;
        tmp[ParamID].batchID = ParamValue;
        setBatches(tmp);
        TriggerOnChange(tmp);
    }

    const handleExpDateOnChange = (ParamID, ParamDate) => {
        let tmp = batches;
        tmp[ParamID].expiryDate = ParamDate;
        setBatches(tmp);
        TriggerOnChange(tmp);
    }

    const handlePriceOnChange = (ParamID, ParamValue) => {
        let tmp = batches;
        tmp[ParamID].price = ParamValue;
        setBatches(tmp);
        TriggerOnChange(tmp);
    }

    const handleAmountOnChange = (ParamID, ParamValue) => {
        let tmp = batches;
        tmp[ParamID].amount = ParamValue;
        setBatches(tmp);
        TriggerOnChange(tmp);
    }

    const TriggerOnChange = (ParamValue) => {
        if (props.onChange)
            props.onChange(ParamValue);
    }

    return (
        <div className={props.className ? props.className : ''}>
            <div className='flex flex-col items-center justify-center p-1 my-2 rounded-lg'>
                <label className='text-sm font-bold mb-2'>Stock Initiale</label>
                {Object.keys(batches).map((bk) => {
                    return (
                        <div className='flex flex-row items-center justify-center bg-gray-300 p-1 rounded-xl bg-opacity-20 mb-2' key={bk}>
                            {AppData.BATCH_ID_FLAG && <RknNumericInput onChange={(v) => handleBatchIDChange(bk, v)} width="72px" placeholder="Lot N°..." />}
                            {AppData.EXPIRATION_DATE_MANAGEMENT_FLAG && <RknDateInput onChange={(d) => handleExpDateOnChange(bk, d)} />}
                            <RknNumericInput onChange={(v) => handleAmountOnChange(bk, v)} width="64px" placeholder="Qte..." />
                            <RknNumericInput onChange={(v) => handlePriceOnChange(bk, v)} width="128px" placeholder="Prix D'achat..." />
                        </div>
                    )
                })}
                <div className='bg-gray-800 text-gray-100 font-bold border border-gray-500 w-16 rounded-xl pb-1 text-3xl hover:bg-gray-100 hover:text-gray-800 cursor-pointer' onClick={handleOnAdd}>+</div>
            </div>
        </div>
    )
}

export default InitialStockEditor