import { React, useState, useEffect } from 'react';
import useDocumentTitle from '@tanem/use-document-title';
import ProductSearchPopup from '../components/ProductSearchPopup';
import { PerformGetRequest, PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import ProductImage from '../components/ProductImage';
import { InputFieldStyle } from '../Styles';
import RknButton from '../components/RknUI/RknButton';
import { FaPlus } from 'react-icons/fa';
import RknNumericInput from '../components/RknUI/RknNumericInput';

const ProductPackEditor = () => {

    useDocumentTitle("Editeur de Pack");

    const [designation, setDesignation] = useState("");
    const [products, setProducts] = useState({});
    const [price, setPrice] = useState(0);
    const [dummy, setDummy] = useState(0);
    const [searchPopupOpen, setSearchPopupOpen] = useState(false);

    const handleSearchOnCancel = () => {
        // console.log("Search on Cancel");
        setSearchPopupOpen(false);
    }

    const SearchProductOnConfirm = (ParamID) => {
        PerformGetRequest("/api/get-product?id=" + ParamID, (res) => {
            // console.log("RES = " + JSON.stringify(res.data));

            let tmpProducts = products;
            tmpProducts[res.data._id] = { name: res.data.name, amount: 1 };
            setProducts(tmpProducts);

            setDummy(dummy + 1);
        });
        setSearchPopupOpen(false);
    }

    const handleSave = () => {
        // console.log("SAVE");

        const packToPost = { name: designation, price: price, products: products };

        PerformSecurePostRequest("/api/new-product-pack", packToPost, (res) => {
            console.log("RES = " + JSON.stringify(res.data));
        });
    }

    return (
        <div className='text-gray-100 flex flex-col items-center justify-center'>
            <h1 className='text-xl font-bold mt-4'>Editeur de Pack</h1>
            {searchPopupOpen && <ProductSearchPopup onConfirm={SearchProductOnConfirm} onCancel={handleSearchOnCancel} />}

            <div className='flex flex-col items-center justify-center m-4 mb-2'>
                <label>Designation</label>
                <input type='text' value={designation} onChange={(e) => setDesignation(e.target.value)} className={InputFieldStyle + " w-64"} />
            </div>

            <div className='flex flex-col items-center justify-center m-2 mb-2'>
                <label>Prix</label>
                <RknNumericInput value={price} onChange={(v) => setPrice(v)} className={InputFieldStyle + " w-64"} />
            </div>

            <div className='flex flex-col items-center justify-center m-1 my-4 p-1 bg-gray-800 rounded-xl'>
                <h2>Liste des Produits</h2>
                <div>{products && Object.keys(products).map((pk) => {
                    return (
                        <div key={pk} className='flex flex-row items-center justify-start bg-gray-700 m-1 rounded-xl'>
                            <ProductImage id={pk} size={64} width={64} height={64} />
                            <div>{products[pk].name}</div>
                            <div className='bg-gray-800 p-1 px-2 m-1 rounded-full'> X {products[pk].amount}</div>
                        </div>
                    )
                })}</div>
                <div className='bg-gray-800 text-gray-100 font-bold border border-gray-500 w-16 rounded-xl pb-1 text-3xl hover:bg-gray-100 hover:text-gray-800 cursor-pointer my-2' onClick={() => setSearchPopupOpen(true)}>+</div>
            </div>

            <RknButton label="Enregistrer" before={<FaPlus />} onPress={handleSave} />

            <div className='hidden'>{dummy}</div>

        </div >
    )
}

export default ProductPackEditor