import { React, useState } from 'react';
import RknFileUploadPopup from '../components/RknUI/RknFileUploadPopup';
import RknButton from '../components/RknUI/RknButton';
import Table from 'rc-table';
import RknNumericInput from '../components/RknUI/RknNumericInput';
import { PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import RknSmartSelector from '../components/RknUI/RknSmartSelector';

// JSPDF
import autoTable from 'jspdf-autotable';
import { DrawLine } from '../Reaknotron/Libs/RknJsPdfTools';
const jspdf = require('jspdf');

const AmountImportWizard = () => {

    const [uploadCsvPopupOpen, setUploadCsvPopupOpen] = useState(false);
    const [records, setRecords] = useState(null);
    const [unitPrice, setUnitPrice] = useState(0);
    const [fee, setFee] = useState(650);
    const [month, setMonth] = useState(null);
    const [year, setYear] = useState(null);
    const [monthString, setMonthString] = useState(null);
    const [maxDDO, setMaxDDO] = useState(null);
    const [curDDO, setCurDDO] = useState(null);
    const [dupliacteDDO, setDupliacteDDO] = useState(0);
    const [category, setCategory] = useState(null);
    const [createDDOBusy, setCreateDDOBusy] = useState(false);

    const renderAmount = (r) => {

        if (!unitPrice)
            return <div>0</div>;

        const amount = ((Number(unitPrice) * Number(r.milkAmount)) - fee);
        let cn = 'text-gray-100 font-bold';

        if (amount < 0)
            cn = 'text-red-600 font-bold';

        return <div className={cn}>{amount} DA</div>
    }

    const columns = [
        {
            title: 'Collecteur',
            dataIndex: 'collector',
            key: 'collector',
            className: 'border border-gray-500 text-gray-500',
            width: 320
        },
        {
            title: 'Designation',
            dataIndex: 'name',
            key: 'name',
            className: 'border border-gray-500',
            width: 320
        },
        {
            title: 'Quantité',
            dataIndex: 'milkAmount',
            key: 'milkAmount',
            width: 128,
            className: 'border border-gray-500'
        },
        {
            title: 'Prix Unitaire',
            dataIndex: '',
            key: 'unitPrice',
            width: 128,
            className: 'border border-gray-500',
            render: r => <div>{unitPrice ? unitPrice : "0"} DA</div>
        },
        {
            title: 'Frais',
            dataIndex: '',
            key: 'fee',
            width: 128,
            className: 'border border-gray-500',
            render: r => <div>{fee ? fee : "0"} DA</div>
        },
        {
            title: 'Montant',
            dataIndex: '',
            key: 'amount',
            width: 128,
            className: 'border border-gray-500',
            render: renderAmount
        }
    ];

    const ParseCSV = (ParamCSV) => {

        let result = {};

        console.log("Parsing CSV...");

        const lines = ParamCSV.split('\n');
        console.log("Line count : " + lines.length);

        const firstLineParts = lines[0].split(';');
        const lastSixDigits = firstLineParts[0].slice(-6);
        const year = lastSixDigits.slice(0, 4);
        // const month = GetFrenchMonthFromNumber(lastSixDigits.slice(-2));
        const month = lastSixDigits.slice(-2);
        // setMonthString(month + " " + year);
        result.Month = month;
        result.Year = year;
        result.MonthString = month + " " + year;

        let tmpRecords = [];
        let tmpBanks = {};

        if (lines.length >= 3) {
            // console.log([lines[1], lines[2]]);
            const columns = lines[1].split(';');

            let sri = 1;
            for (let index = 2; index < lines.length - 2; index++) {
                const element = lines[index];

                const values = element.split(';');

                let record = {};
                let i = 0;
                columns.forEach(c => {
                    // console.log("COL = " + c);
                    record[c] = values[i];
                    i++;
                });

                if (!tmpBanks[record["Banque Eleveur"]]) {
                    tmpBanks[record["Banque Eleveur"]] = [];
                }

                // Fix raw rib
                let rawRib = record["RIB Eleveur"];
                if (rawRib && rawRib.endsWith('_')) {
                    rawRib = rawRib.slice(0, -1);
                }

                // Fix raw rib
                let sanitaryID = record["Identification Sanitaire"];
                if (sanitaryID && sanitaryID.endsWith('_')) {
                    sanitaryID = sanitaryID.slice(0, -1);
                }

                let ddoRecord = {};
                ddoRecord["index"] = sri;
                // console.log("NPC = " + record["Nom Pr�nom Collecteur"]);
                ddoRecord["name"] = record["Nom Pr�nom Eleveur"];
                ddoRecord["wilaya"] = record["Wilaya Eleveur"];
                ddoRecord["commune"] = record["Commune Eleveur"];
                ddoRecord["bankName"] = record["Banque Eleveur"];
                ddoRecord["bankAccount"] = rawRib;
                ddoRecord["amount"] = record["Prime Total Production"];
                // console.log("QTE = " + record["Qt� Collect�es"]);
                ddoRecord["milkAmount"] = record["Qt� Collect�es"];
                ddoRecord["collector"] = record["Nom Pr�nom Collecteur"];
                ddoRecord["sanitaryID"] = sanitaryID;
                sri++;

                tmpRecords.push(ddoRecord);
                tmpBanks[record["Banque Eleveur"]].push(ddoRecord);

                // console.log("RECORD = " + JSON.stringify(record));
                // console.log("RECORD S = " + JSON.stringify(recordSimplified));

            }

            tmpRecords.sort((a, b) => a.collector.localeCompare(b.collector));

            result.Records = tmpRecords;
            result.Banks = tmpBanks;


        } else {

            console.log("Not enough lines...");

        }

        return result;

    }

    const handleImport = async (selectedFile) => {

        console.log(selectedFile.name);

        const reader = new FileReader();

        reader.onload = (event) => {
            // console.log(event.target.result);
            const result = ParseCSV(event.target.result);
            setRecords(result.Records);
            setMonth(result.Month);
            setYear(result.Year);
            setMonthString(new Date(result.Year, result.Month - 1).toLocaleString('fr-FR', { month: 'long' }) + " " + result.Year);
            // setFileContent(event.target.result);
            setUploadCsvPopupOpen(false);
        };

        reader.onerror = (error) => {
            console.error('Error reading file:', error);
            setUploadCsvPopupOpen(false);
        };

        reader.readAsText(selectedFile);

    }

    const handleMakeDdoOnClick = () => {

        setCreateDDOBusy(true);

        let i = 0;
        let d = 0;
        setMaxDDO(records.length);
        setDupliacteDDO(0);

        for (const r of records) {

            let amount = unitPrice ? ((Number(unitPrice) * Number(r.milkAmount)) - fee) : 0;
            let status = "PENDING";

            if (amount < 0) {
                amount = 0;
                status = "IGNORED";
            }


            let ddoToPost = {
                month: month,
                year: year,
                targetType: "OTHER",
                targetID: r.name,
                targetWilaya: r.wilaya,
                targetCommune: r.commune,
                bankName: r.bankName,
                accountNumber: r.bankAccount,
                baseAmount: amount,
                finalAmount: amount,
                status: status,
                categoryID: category,
                extraFieldOne: r.collector,
                extraFieldTwo: r.sanitaryID
            }

            // console.log("DDO = " + JSON.stringify(ddoToPost));

            PerformSecurePostRequest("/api/new-ddo", ddoToPost, (res) => {

                if (res.data.code == "OK") {
                    i++;
                    setCurDDO(i);
                } else if (res.data.code == "DUPLICATE") {
                    // console.log("Duplicate DDO !");
                    i++;
                    d++;
                    setCurDDO(i);
                    setDupliacteDDO(d);
                }

                if (i == records.length) {
                    setCreateDDOBusy(false);
                }

            });

        }
    }

    const GeneratePDF = async () => {

        const width = 210;
        const thirdOfReceiptWidth = width / 3;
        const ticketLength = 70;
        const halfReceiptWidth = thirdOfReceiptWidth / 2;
        const doc = new jspdf.jsPDF('p', 'mm', [270 * 2, width]); // Portrait, Milimeter, Height, Width

        const DEFAULT_FAT_PER_LITER = 28;
        const DEFAULT_SUBVENTIONED_UNIT_PRICE = 12;
        const DEFAULT_MILK_ANALYZE_COST = 500;
        const DEFAULT_RET_CORR = 150;

        let i = 1;
        let cursorY = 6;
        let col = 1;
        let row = 1;

        let lastCollector = "";
        let collectorOffset = 0;
        let first = true;
        // let newPage = true;

        for (const r of records) {

            if (lastCollector != r.collector && !first) {
                doc.addPage();
                col = 1;
                row = 1;
            }

            first = false;

            if (lastCollector != r.collector) {
                lastCollector = r.collector;
                doc.setFont(undefined, 'bold');
                doc.setFontSize(12);
                doc.text("Collecteur : " + r.collector, width / 2, 6, 'center');
                DrawLine(doc, 4, 8, width - 4, 8, 0.5, { r: 0, g: 0, b: 0 });
                collectorOffset = 10;
            }

            const COL_X = thirdOfReceiptWidth * (col - 1);
            const ROW_Y = ticketLength * (row - 1);
            // console.log("ROW_Y = " + ROW_Y);

            // Reset
            cursorY = 4 + ROW_Y + collectorOffset;

            // Label 1 Text
            doc.setFont(undefined, 'bold');
            doc.setTextColor(0, 0, 0);
            doc.setFontSize(8);
            doc.text("SARL Halib Farah", halfReceiptWidth + COL_X, cursorY, 'center');
            cursorY += 4;

            doc.setFontSize(12);
            doc.text("Bulletin de Paie N° " + i.toString().padStart(4, '0'), halfReceiptWidth + COL_X, cursorY, 'center');
            cursorY += 3.5;

            doc.setFont(undefined, 'normal');
            doc.setFontSize(8);
            doc.text("Mois de " + monthString, halfReceiptWidth + COL_X, cursorY, 'center');
            cursorY += 3;

            let amount = unitPrice ? (Number(unitPrice) * Number(r.milkAmount)) : 0;
            let subvention = Number(r.milkAmount) * DEFAULT_SUBVENTIONED_UNIT_PRICE;
            let net = amount - DEFAULT_MILK_ANALYZE_COST - DEFAULT_RET_CORR;

            let body = [];
            body.push(["Eleveur", r.name]);
            // body.push(["Collecteur", r.collector]);
            body.push(["RIB", r.bankAccount]);
            body.push(["Quantité", r.milkAmount]);
            body.push(["M.G (g/L)", DEFAULT_FAT_PER_LITER]);
            body.push(["P.U.", unitPrice]);
            body.push(["Ret. Corr.", DEFAULT_RET_CORR]);
            body.push(["Subvention", subvention]);
            body.push(["Analyze", DEFAULT_MILK_ANALYZE_COST]);
            body.push(["Net. Paie", net]);

            autoTable(doc, {
                body: body,
                startY: cursorY,
                margin: 3 + COL_X,
                theme: 'grid',
                tableWidth: thirdOfReceiptWidth - 6,
                styles: {
                    fontSize: 8,
                    cellPadding: 1,
                    fontStyle: 'bold',
                    textColor: 'black'
                }
            });

            // doc.addPage();
            i++;

            col++;

            if (col > 3) {

                col = 1;
                row++;
                if (row > 3) {
                    row = 1;
                    collectorOffset = 0;
                    doc.addPage();
                }

            }

        }

        return doc;
    }

    const handleConfirmDownloadPdfOnClick = async (ParamRef) => {
        // setDownloadPdfPopupOpen(false);
        const doc = await GeneratePDF();
        doc.save("Fiche de Paie.pdf");
    }

    const handleCategoryChange = (ParamItem) => {
        setCategory(ParamItem._id);
    }

    return (
        <div className='text-gray-100 flex flex-col items-center justify-center'>
            <h1 className='text-xl font-bold my-2'>Importation des Quantités...</h1>
            <RknButton label="Importer" onPress={() => setUploadCsvPopupOpen(true)} className="w-32" />
            <span className="my-2" />

            <label className="text-sm font-medium text-gray-900 dark:text-white mt-2 mx-2">Prix Unitaire</label>
            <RknNumericInput value={unitPrice} onChange={(v) => setUnitPrice(v)} />
            <span className="my-2" />
            <label className="text-sm font-medium text-gray-900 dark:text-white mt-2 mx-2">Frais</label>
            <RknNumericInput value={fee} onChange={(v) => setFee(v)} />
            <span className="my-2" />

            {/* {records && <div>{JSON.stringify(records)}</div>} */}

            {records && <h2 className='mt-4 mb-2 text-gray-500'>Quantités pour le mois de <span className='font-bold text-gray-100'>{monthString}</span></h2>}
            {records && <Table columns={columns} data={records} rowKey="_id" tableLayout='auto' />}

            {records &&
                <div className='flex flex-col items-center justify-center my-2'>
                    <label className="text-sm font-medium text-gray-900 dark:text-white mt-2 mx-2">Catégorie des ordres de virement</label>
                    <RknSmartSelector url={"/api/ddo-category-list"} idKey="_id" value={category} labelKey="name" reaktorContext="CATEGORY" onChange={handleCategoryChange} quickAddRoute="/category-manager" />
                </div>
            }

            {maxDDO && <div className='font-bold text-sm my-2'>{curDDO} sur {maxDDO} effectué</div>}
            {dupliacteDDO > 0 && <div className='font-bold text-sm my-2 text-red-600'>{dupliacteDDO} Dupliqué !</div>}

            {records && unitPrice > 0 && category && <RknButton label="Créer les ordres de virement" onPress={handleMakeDdoOnClick} className="w-64" busy={createDDOBusy} />}
            <span className="my-2" />
            {records && <RknButton label="PDF" onPress={handleConfirmDownloadPdfOnClick} className="w-64" />}
            <span className="my-2" />


            <RknFileUploadPopup
                isOpen={uploadCsvPopupOpen}
                onClose={() => setUploadCsvPopupOpen(false)}
                onConfirm={handleImport}
                defaultValue={null}
                fileLabel="CSV"
                fileType=".csv"
            />
        </div>
    )
}

export default AmountImportWizard