import { React, useState, useEffect } from 'react';
import { FaFileAlt, FaTimesCircle } from 'react-icons/fa';
import Popup from 'reactjs-popup';
import RknButton from '../components/RknUI/RknButton';
import RknNumericInput from './RknUI/RknNumericInput';
import RknDateInput from './RknUI/RknDateInput';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';

const jspdf = require('jspdf');

const GeneratePayslipPopup = (props) => {

    const [start, setStart] = useState(null);
    const [end, setEnd] = useState(null);
    const [holidays, setHolidays] = useState(0);
    const [PRI, setPRI] = useState(10);

    const handleOnConfirm = () => {
        if (props.onConfirm)
            props.onConfirm();
    }

    const CloseModal = () => {
        props.onClose();
    }

    const Generate = () => {
        if (start && end && (holidays || holidays === 0) && PRI && props.employeeID) {

            // console.log("START = " + start);
            // console.log("END = " + end);

            const url = `/api/generate-payslip?id=${props.employeeID}&start=`
                + new Date(start).toISOString()
                + "&end="
                + new Date(end).toISOString()
                + "&holidays="
                + holidays
                + "&PRI="
                + PRI

            PerformGetRequest(url, (res) => {
                // console.log("Payslip = " + JSON.stringify(res.data));
                handleOnConfirm();
            });
        }
    }

    return (
        <div>
            <Popup
                open={props.isOpen}
                modal
                closeOnDocumentClick
                onClose={() => { CloseModal(); }}
            >
                <div className="modal bg-gray-900 text-gray-100 p-2">
                    <button className="close" onClick={() => { CloseModal(); }}>
                        <FaTimesCircle />
                    </button>
                    <div className="header">Générer un Bulletin de Paie</div>
                    <div className="content flex flex-col items-center">

                        <label className="block text-sm font-medium text-gray-900 dark:text-white">Du</label>
                        <RknDateInput value={start} onChange={setStart} />
                        <span className='mb-4' />

                        <label className="block text-sm font-medium text-gray-900 dark:text-white">Au</label>
                        <RknDateInput value={end} onChange={setEnd} />
                        <span className='mb-4' />

                        <label className="block text-sm font-medium text-gray-900 dark:text-white">Jour(s) de Congé</label>
                        <RknNumericInput value={holidays} onChange={setHolidays} />
                        <span className='mb-4' />

                        <label className="block text-sm font-medium text-gray-900 dark:text-white">Prime de Rendement Individuelle</label>
                        <RknNumericInput value={PRI} onChange={setPRI} unit="%" />
                        <span className='mb-4' />

                        <RknButton label="Générer" className="w-48 mx-auto" before={<FaFileAlt />} onPress={Generate} />
                    </div>
                </div>
            </Popup>
        </div>
    )
}

export default GeneratePayslipPopup