import { React, useState, useEffect, useRef } from 'react';
import Popup from 'reactjs-popup';
import { FaTimesCircle } from 'react-icons/fa';
import RknButton from './RknButton';

const RknFileUploadPopup = (props) => {

    const [selectedFile, setSelectedFile] = useState(null);

    const CloseModal = () => {
        if (props.onClose)
            props.onClose();
    }

    const handleConfirmOnClick = (event) => {

        // event.preventDefault();

        if (props.onConfirm)
            props.onConfirm(selectedFile);
    }

    const handleFileChange = (event) => {
        setSelectedFile(event.target.files[0]);
    };

    return (
        <div>
            <Popup
                open={props.isOpen}
                modal
                closeOnDocumentClick
                onClose={() => { CloseModal(); }}
            // onOpen={handleOnOpen}
            >
                <div className="modal bg-gray-900 text-gray-100 p-2">
                    <button className="close" onClick={() => { CloseModal(); }}>
                        <FaTimesCircle />
                    </button>
                    <div className="header">Séléctionner un Fichier {props.fileLabel || "..."}</div>
                    <form onSubmit={handleConfirmOnClick} className="content flex flex-col items-center">
                        <br />
                        <input
                            id="fileInput"
                            type="file"
                            accept={props.fileType || "*"}
                            onChange={handleFileChange}
                            className='bg-gray-800 text-gray-200 p-1 rounded-r-xl'
                        />
                        <br />
                        <RknButton label="Valider" onPress={handleConfirmOnClick} />
                    </form>
                </div>

            </Popup>
        </div>
    )
}

export default RknFileUploadPopup