import { React, useState, useEffect, useRef } from 'react';
import Popup from 'reactjs-popup';
import { FaTimesCircle, FaCheckCircle } from 'react-icons/fa';
import RknNumericInput from './RknUI/RknNumericInput';

import { useTranslation } from 'react-i18next';

const EditAmountPopup = (props) => {

    const { t } = useTranslation();

    const ref = useRef(null);

    useEffect(() => {
        setTimeout(() => {

            // if (ref & ref.current)
                ref.current.select();

        }, 150);
    }, []);

    const [amount, setAmount] = useState(1);

    const CloseModal = () => {
        props.onClose();
    }

    const OnSubmit = () => {
        if (props.onConfirm) {
            props.onConfirm(amount);
            CloseModal();
        }
    }

    const handleSetAmount = (ParamValue) => {
        
        if (props.max && ParamValue > props.max)
            ParamValue = props.max;
        
        setAmount(ParamValue);
    }

    return (
        <div>
            <Popup
                open={props.isOpen}
                modal
                closeOnDocumentClick
                onClose={() => { CloseModal(); }}
            >
                <div className="p-2 text-gray-100 bg-gray-900 modal">
                    <button className="close" onClick={() => { CloseModal(); }}>
                        <FaTimesCircle />
                    </button>
                    <div className="header">{props.label ? props.label : `${t("pos.table.content.itemQuantity.title")}`}</div>
                    <br />
                    <form onSubmit={OnSubmit} className="flex flex-col items-center content">
                        <label className='text-sm'>{props.label ? props.label : `${t("pos.table.content.itemQuantity.count")}`} :</label>
                        <RknNumericInput placeholder='Quantité...' ref={ref} value={amount} onChange={handleSetAmount} />
                        <button type='submit' className="px-4 py-2 mt-2 font-bold text-white bg-blue-500 border-b-4 border-blue-700 rounded hover:bg-blue-400 hover:border-blue-500"><FaCheckCircle className='inline mb-1' size={20} />  {t("button.confirm")}</button>
                        <br />
                    </form>
                </div>

            </Popup>
        </div>
    )
}

export default EditAmountPopup