import { React, useState, useEffect } from 'react';
import axios from 'axios';
import { AwesomeButtonProgress } from 'react-awesome-button';
import { FaTimesCircle } from 'react-icons/fa';
import Popup from 'reactjs-popup';
import { GetBackEndUrl } from '../const';
import RknButton from '../components/RknUI/RknButton';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';

const PostToFacebookPopup = (props) => {

    const textAreaStyle = 'bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 w-full';

    const [postContent, setPostContent] = useState("");

    useEffect(() => {

        // setPostContent(JSON.stringify(props.value));

        var result = "";

        const v = props.value;
        const s = props.specs;

        if (s) {
            result = "💻 " + s.brand + " " + s.model + " " + s.screenSizeInInch + " Pouces" + '\n' + '\n';
            result += s.cpu + " 🌬" + '\n';
            result += s.coreCount + " Core 😎 / " + s.threadCount + " Thread 🚀🚀🚀🚀" + '\n';
            result += CacheInKbToReadable(s.cpuCacheInKb) + " Cache" + '\n';
            result += "📏📏 " + RamInMbToReadable(s.ramInMb) + " " + s.ramType + '\n';
            result += "💽 " + Math.round(s.storageCapacityInGb) + " Gb " + s.storageType + '\n';
            result += "🎮 " + s.gpu + '\n';
            result += '\n';
            result += "Etat " + s.stateScore + "/10 👌" + '\n';
            result += "💰Prix : " + s.price + " DA💰" + '\n';
        } else {
            result += v.name + " (" + v.price + " DA)";
        }

        setPostContent(result);
    }, []);

    const CacheInKbToReadable = (ParamCacheInKb) => {
        let cacheInKb = Number(ParamCacheInKb);

        if (cacheInKb >= 1024)
            return (cacheInKb / 1024) + " Mb";
        else
            return cacheInKb + " Kb";
    }

    const RamInMbToReadable = (ParamRamInMb) => {
        let ramInMb = Number(ParamRamInMb);

        if (ramInMb >= 1024)
            return Math.round(ramInMb / 1024) + " Gb";
        else
            return ramInMb + " Mb";
    }

    const CloseModal = () => {
        props.onClose();
    }

    const PostToFacebook = async (ParamPostContent) => {

        try {

            PerformGetRequest("/api/host-product-image?id=" + props.productID, (res) => {
                console.log("HOST RESULT = " + JSON.stringify(res.data));

                if (res.data.success) {
                    const imageLink = "https://occipital-resonant-bandicoot.glitch.me/download?file=" + res.data.file;
                    window.open('https://kompleta-share.netlify.app/?content=' + ParamPostContent + '&image=' + btoa(imageLink), '_blank');
                }
            });

        } catch (error) {
            console.log("ERROR : " + error);
        }

    }

    return (
        <div>
            <Popup
                open={props.isOpen}
                modal
                closeOnDocumentClick
                onClose={() => { CloseModal(); }}
            >
                <div className="modal bg-gray-900 text-gray-100 p-2">
                    <button className="close" onClick={() => { CloseModal(); }}>
                        <FaTimesCircle />
                    </button>
                    <div className="header"> Partagé sur Facebook </div>
                    <div className="content flex flex-col items-center">
                        <br />

                        <div className='mt-2 w-full flex flex-col items-center justify-center'>
                            <textarea name="note" className={textAreaStyle} value={postContent} rows="16" placeholder="Publication..." onChange={(e) => { setPostContent(e.target.value) }} />
                            <br />
                            <RknButton before={"💬"} label="Partager" onPress={() => { PostToFacebook(postContent); }} />
                        </div>

                    </div>
                </div>
            </Popup>
        </div>
    )
}

export default PostToFacebookPopup