import React, { useState } from 'react';
import RknButton from '../components/RknUI/RknButton';
import { FaShopify } from 'react-icons/fa';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import RknContainer from '../components/RknUI/RknContainer';
import AppData from '../App.json';
import { SyncLoader } from 'react-spinners';

const SokkifyManager = () => {

    const [sokkifyPassword, setSokkifyPassword] = useState("");
    const [syncResults, setSyncResults] = useState([]);
    const [counter, setCounter] = useState(0);
    const [max, setMax] = useState(0);
    const [counter_eCom, setCounter_eCom] = useState(0);
    const [max_eCom, setMax_eCom] = useState(0);
    const [eComSync, setEComSync] = useState(false);

    const StartSokkifySync = () => {
        PerformGetRequest("/api/get-product-list", (res) => {
            setMax(res.data.length);
            SyncNextItem(res.data, 1);
        });
    }

    const SyncNextItem = (ParamItems, ParamCounter) => {
        if (ParamItems && ParamItems.length > 0) {
            // console.log("LEN 1 = " + ParamItems.length);
            const p = ParamItems.shift();
            // console.log("LEN 2 = " + ParamItems.length);

            if (p) {
                PerformGetRequest("/api/add-product-on-sokkify?id=" + p._id + "&password=" + sokkifyPassword, (res) => {
                    // console.log("P RES = " + JSON.stringify(res.data));

                    let tmpArray;

                    // This does not seem to work i.e it does not clean the array
                    if (ParamCounter == 1) {
                        tmpArray = [];
                    }
                    else {
                        tmpArray = syncResults;
                    }

                    tmpArray.push(res.data);
                    setSyncResults(tmpArray);

                    setCounter(ParamCounter);

                    SyncNextItem(ParamItems, ParamCounter + 1);
                });
            }
        }
    }

    const SyncNextItem_eCom = (ParamItems, ParamCounter) => {
        if (ParamItems && ParamItems.length > 0) {
            // console.log("LEN 1 = " + ParamItems.length);
            const p = ParamItems.shift();
            // console.log("LEN 2 = " + ParamItems.length);

            if (p) {
                PerformGetRequest("/api/send-product-to-shop?id=" + p._id, (res) => {
                    // console.log("P RES = " + JSON.stringify(res.data));

                    // setCounter_eCom(ParamCounter);

                    let tmpArray;

                    // This does not seem to work i.e it does not clean the array
                    if (ParamCounter == 1) {
                        tmpArray = [];
                    }
                    else {
                        tmpArray = syncResults;
                    }

                    tmpArray.push(res.data);
                    setSyncResults(tmpArray);

                    setCounter_eCom(ParamCounter);
                    SyncNextItem_eCom(ParamItems, ParamCounter + 1);
                });
            }
        } else {
            setEComSync(false);
        }
    }

    const StartEComWebsiteSync = () => {

        setEComSync(true);

        PerformGetRequest("/api/clear-products-on-shop", (res_1) => {
            if (res_1.data == "OK") {
                PerformGetRequest("/api/get-product-list", (res_2) => {
                    setMax(res_2.data.length);
                    SyncNextItem_eCom(res_2.data, 1);
                });
            }
        });
    }

    return (
        <div className='flex flex-col items-center justify-center'>

            <span className="mt-24" />

            {AppData.SOKKIFY_FLAG && !AppData.CUSTOM_ONLINE_SHOP && <RknContainer title="Sokkify">

                <RknButton
                    label="Synchroniser avec Sokkify"
                    className="w-64 text-base font-base m-auto my-2"
                    before={<FaShopify size={20} />}
                    onPress={StartSokkifySync}
                />

                <div className='flex flex-row items-center justify-center my-2'>
                    <label htmlFor="password" className='text-gray-100 mr-2'>Mot de Passe :</label>
                    <input name='password' type='text' className='py-0.5 px-2 rounded-3xl' value={sokkifyPassword} onChange={(e) => { setSokkifyPassword(e.target.value); }} />
                </div>

                {syncResults && syncResults.length > 0 &&
                    <div className='border border-gray-500 m-2 rounded-xl p-4'>

                        {max > 0 && <div className='text-gray-100 font-bold'>{counter} / {max}</div>}

                        {syncResults && <div className='mt-4 text-gray-100 flex flex-col items-center justify-center'>
                            {syncResults.map((r) => {
                                return (
                                    <div className='flex flex-row w-96' key={r.id}>
                                        <div className='w-10/12 bg-gray-900 text-gray-100 p-1 m-1 rounded-lg overflow-hidden' >
                                            {r.message == "IGNORE" ? "(Produit Supprimé)" : r.name}
                                        </div>
                                        {r.message == "OK" ?
                                            <div className='w-2/12 bg-green-700 text-gray-100 p-1 m-1 rounded-lg overflow-clip' >
                                                OK
                                            </div>
                                            :
                                            <div className='w-2/12 bg-red-700 text-gray-100 p-1 m-1 rounded-lg overflow-clip' >
                                                {/* Erreur */}
                                                {r.message}
                                            </div>
                                        }

                                    </div>
                                )
                            })}

                        </div>}

                    </div>}

            </RknContainer>}

            {AppData.CUSTOM_ONLINE_SHOP && <RknContainer title="Siteweb E-Commerce">

                <RknButton
                    label="Synchroniser avec le Siteweb E-Commerce"
                    className="w-64 text-base font-base m-auto mt-2 mb-6"
                    before={<FaShopify size={20} />}
                    onPress={StartEComWebsiteSync}
                />

                {eComSync && <SyncLoader color='#AAAAAA' />}

                {false && syncResults && syncResults.length > 0 &&
                    <div className='border border-gray-500 m-2 rounded-xl p-4'>

                        {max_eCom > 0 && <div className='text-gray-100 font-bold'>{counter_eCom} / {max_eCom}</div>}

                        {syncResults && <div className='mt-4 text-gray-100 flex flex-col items-center justify-center'>
                            {syncResults.map((r) => {
                                return (
                                    <div className='flex flex-row w-96' key={r.id}>
                                        <div className='w-10/12 bg-gray-900 text-gray-100 p-1 m-1 rounded-lg overflow-hidden' >
                                            {r.message == "IGNORE" ? "(Produit Supprimé)" : r.name}
                                        </div>
                                        {r.message == "OK" ?
                                            <div className='w-2/12 bg-green-700 text-gray-100 p-1 m-1 rounded-lg overflow-clip' >
                                                OK
                                            </div>
                                            :
                                            <div className='w-2/12 bg-red-700 text-gray-100 p-1 m-1 rounded-lg overflow-clip' >
                                                {/* Erreur */}
                                                {r.message}
                                            </div>
                                        }

                                    </div>
                                )
                            })}

                        </div>}

                    </div>
                }

            </RknContainer>}
        </div>
    )

}

export default SokkifyManager