import { React, useState, useEffect } from 'react';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import { motion } from 'framer-motion';
import { FaCheckCircle, FaEdit, FaLongArrowAltLeft, FaPlusCircle, FaPlusSquare, FaTimesCircle } from 'react-icons/fa';
import ProductImage from '../components/ProductImage';
import RknButton from '../components/RknUI/RknButton';
import RknCompactButton from '../components/RknUI/RknCompactButton';

const MobileSalesPoint = (props) => {

    const [categories, setCategories] = useState(null);
    const [products, setProducts] = useState(null);
    const [currentCategory, setCurrentCategory] = useState(null);
    const [categoryCounters, setCategoryCounters] = useState({});
    const [itemCounters, setItemCounters] = useState({});
    const [dummy, setDummy] = useState(0);
    const [total, setTotal] = useState(0);

    useEffect(() => {

        PerformGetRequest("/api/get-category-list", (res) => {
            console.log(JSON.stringify(res.data));
            setCategories(res.data);
        });

    }, []);

    useEffect(() => {

        if (currentCategory) {
            PerformGetRequest("/api/product-by-category?id=" + currentCategory, (res) => {
                setProducts(res.data);
                console.log("BY CAT : " + JSON.stringify(res.data));
            });
        }

    }, [currentCategory]);

    const handleItemOnClick = (ParamProduct) => {

        // let id;
        // if (ParamID) {
        //     id = ParamID;
        // } else {
        //     id = localStorage.getItem("quick-service-slot-" + ParamSlotID);
        // }

        let cat = ParamProduct.category;
        let tmpCats = categoryCounters;
        if (tmpCats[cat]) {
            tmpCats[cat].amount = tmpCats[cat].amount + 1;
        } else {
            tmpCats[cat] = { amount: 1 };
        }

        let id = ParamProduct._id;
        let tmpItems = itemCounters;
        if (tmpItems[id]) {
            tmpItems[id].amount = tmpItems[id].amount + 1;
        } else {
            // tmpItems[id] = { amount: 1, price: ParamProduct.price };
            tmpItems[id] = { amount: 1, price: GetAppropriatePrice(ParamProduct) };
        }

        setItemCounters(tmpItems);

        UpdateTotal(tmpItems);

        setDummy(prevDummy => prevDummy + 1);
    }

    const handlePackageOnClick = (ParamProduct) => {

        let cat = ParamProduct.category;
        let tmpCats = categoryCounters;
        if (tmpCats[cat]) {
            tmpCats[cat].amount = tmpCats[cat].amount + ParamProduct.packaging;
        } else {
            tmpCats[cat] = { amount: ParamProduct.packaging };
        }

        let id = ParamProduct._id;
        let tmpItems = itemCounters;
        if (tmpItems[id]) {
            tmpItems[id].amount = tmpItems[id].amount + ParamProduct.packaging;
        } else {
            // tmpItems[id] = { amount: ParamProduct.packaging, price: ParamProduct.price };
            tmpItems[id] = { amount: ParamProduct.packaging, price: GetAppropriatePrice(ParamProduct) };
        }

        setItemCounters(tmpItems);

        UpdateTotal(tmpItems);

        setDummy(prevDummy => prevDummy + 1);
    }

    const UpdateTotal = (ParamItems) => {

        // console.log("PARAM ITEMS = " + JSON.stringify(ParamItems));

        let total = 0;
        for (const k of Object.keys(ParamItems)) {
            // const price = Number(quickServiceItemsInfo[k].price);
            const price = 1;
            total += (price * Number(ParamItems[k].amount));
        }
        setTotal(total);
    }

    const handleConfirmOnPress = () => {
        if (props.onConfirm) {
            props.onConfirm(itemCounters)
        }
    }

    const GetAppropriatePrice = (ParamProduct) => {
        if (props.defaultPrice) {

            if (props.defaultPrice == "HALF_WHOLESALE")
                return ParamProduct.halfWholesalePrice;
            else if (props.defaultPrice == "WHOLESALE")
                return ParamProduct.wholesalePrice;
            else
                return ParamProduct.price;
        }

        return ParamProduct.price;
    }

    return (
        <div>

            {!currentCategory &&
                <div className='flex flex-col items-center justify-center text-gray-100'>
                    {categories && categories.map((c, i) => {
                        return (
                            <motion.div
                                key={c._id}
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                transition={{ duration: 0.15 * i }}
                                className='bg-gray-900 p-1 w-screen active:scale-95 hover:bg-gray-700 transition duration-300 cursor-pointer select-none'
                                onClick={() => { setCurrentCategory(c._id); }}
                            >
                                {c.icon + " " + c.name + (categoryCounters[c._id] ? " (" + categoryCounters[c._id].amount + ")" : "")}
                            </motion.div>
                        )
                    })}
                </div>}

            {currentCategory &&
                <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ duration: 0.15 }}
                    className='bg-gray-900 p-1 w-screen active:scale-95 hover:bg-gray-700 transition duration-300 text-gray-100 flex flex-col items-center justify-center cursor-pointer select-none'
                    onClick={() => { setCurrentCategory(null); }}
                >
                    <FaLongArrowAltLeft />
                </motion.div>}

            {currentCategory &&
                <div className='flex flex-col items-center justify-center text-gray-100'>
                    {products && products.map((p, i) => {
                        return (
                            <motion.div
                                key={p._id}
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                transition={{ duration: 0.15 * i }}
                                className='bg-gray-900 p-1 w-screen flex flex-row items-center justify-center h-24 select-none cursor-pointer'
                                onClick={null}
                            >
                                <ProductImage
                                    amount={(itemCounters[p._id] && itemCounters[p._id].amount) ? itemCounters[p._id].amount : ""}
                                    id={p._id}
                                    size={80}
                                    onClick={() => { handleItemOnClick(p); }}
                                />

                                <div className='flex-grow bg-gray-800 m-1 pb-1 h-20 rounded-xl flex flex-col items-start justify-center'>
                                    <div className='h-6 rounded-t-xl bg-gray-700 w-full font-bold'>{p.name}</div>

                                    <div className='flex-grow flex flex-row items-center justify-cente'>
                                        <div className='w-20 h-full p-0.5 pl-2 m-0.5 flex flex-col items-center justify-center'>{GetAppropriatePrice(p)} DA</div>
                                        <div className='flex-grow p-0.5 pl-2 m-0.5 flex flex-row items-center justify-center'>
                                            <FaPlusCircle size={32} className='m-1 active:scale-95 transition duration-150' onClick={() => { handleItemOnClick(p); }} />

                                            <div className='flex flex-row items-center justify-center mx-1 rounded-lg border-2 border-gray-100 active:scale-95 transition duration-150'>
                                                <FaPlusSquare size={30} className='p-0.5 m-1' onClick={() => { handlePackageOnClick(p); }} />
                                                <div className='mr-2'>{p.packaging}</div>
                                            </div>

                                            {/* <FaEdit size={32} className='m-1 active:scale-95 transition duration-150' /> */}
                                        </div>
                                    </div>
                                </div>

                            </motion.div>
                        )
                    })}
                </div>}

            <div className='h-12 bg-gray-900 fixed z-20 bottom-0 right-0 left-0 flex flex-row items-center justify-center space-x-2 border-t-2 border-gray-300'>
                {/* <RknCompactButton label="Paiement" before={<FaCheckCircle />} /> */}
                <RknCompactButton label="Valider" before={<FaCheckCircle />} onPress={handleConfirmOnPress} />
                <RknCompactButton label="Annuler" before={<FaTimesCircle />} onPress={handleConfirmOnPress} />
            </div>

        </div>
    )
}

export default MobileSalesPoint