            {AppData.STORAGE_MANAGEMENT_FLAG && AppData.AMOUNT_IMPORT_WIZARD && CheckPrivilege("ALL") && <MainMenuCard label="Importation des Quantités" before={<FaMagic size={48} />} href='/qty-import' />}
