            {AppData.STORAGE_MANAGEMENT_FLAG && CheckPrivilege("RECEPTION_MANAGEMENT") && <MainMenuCard label={t("receptionMgmt.cardTitle")} before={<FaCartPlus size={48} />} href='/reception-list' />}
            {AppData.STORAGE_MANAGEMENT_FLAG && AppData.BATCH_MANAGEMENT_FLAG && CheckPrivilege("PRODUCT_MANAGEMENT") && <MainMenuCard label="Gestion Des Lots" before={<FaLayerGroup size={48} />} href='/batch-manager' />}
            {AppData.INVENTORY_SHEETS_FLAG && CheckPrivilege("PRODUCT_MANAGEMENT") && <MainMenuCard label="Fiche(s) d'Invetaire" before={<FaListOl size={48} />} href='/inventory-manager' />}
