            {AppData.EMPLOYEE_MANAGEMENT_FLAG && CheckPrivilege("EMPLOYEE_MANAGEMENT") && <MainMenuCard label={t("clocking.cardTitle")} before={<FaRegClock size={48} />} href='/employee-clocking-board' />}
            {AppData.EMPLOYEE_MANAGEMENT_FLAG && CheckPrivilege("EMPLOYEE_MANAGEMENT") && <MainMenuCard label={t("pointeuse.cardTitle")} before={<FaCalculator size={48} />} href='/tas-manager' />}
            {AppData.EMPLOYEE_MANAGEMENT_FLAG && CheckPrivilege("EMPLOYEE_MANAGEMENT") && <MainMenuCard label={t("profTitles.cardTitle")} before={<FaBriefcase size={48} />} href='/pt-manager' />}
            {AppData.EMPLOYEE_MANAGEMENT_FLAG && CheckPrivilege("EMPLOYEE_MANAGEMENT") && <MainMenuCard label="Absences" before={<FaBan size={48} />} href='/absence-manager' />}
            {AppData.EMPLOYEE_MANAGEMENT_FLAG && CheckPrivilege("EMPLOYEE_MANAGEMENT") && <MainMenuCard label="Horaires de travail" before={<FaArrowsAltH size={48} />} href='/shift-manager' />}

            {AppData.STUDENT_MANAGEMENT_FLAG && <MainMenuCard label="Etudiants (Catégorie A)" before={<FaUserGraduate size={48} />} href='/student-manager?cat=a' />}
