            {AppData.CUSTOMER_MANAGEMENT_FLAG && CheckPrivilege("ESTABLISHMENT_MANAGEMENT") && <MainMenuCard label="Transactions" before={<FaCreditCard size={48} />} href='/transaction-manager' />}

