import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import { FaDollarSign, FaEdit, FaPlus } from 'react-icons/fa';
import RknButton from '../components/RknUI/RknButton';
import { Link } from 'react-router-dom';
import { PerformGetRequest, PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import RknInputDialog from '../components/RknUI/RknInputDialog';
import BalancePaymentPopup from '../components/BalancePaymentPopup';
import DefaultPriceLabel from '../components/DefaultPriceLabel';
import { CheckPrivilege } from '../LoginManager';

const CustomerManager = () => {

    useEffect(() => {

        GetCustomerListFromDb();

    }, []);

    const [customerList, setCustomerList] = useState();
    const [currentPaymentCustomerID, setCurrentPaymentCustomerID] = useState(null);

    const columns = [
        {
            title: 'Opérations',
            dataIndex: '',
            key: 'operation',
            className: 'border border-gray-500',
            width: 64,
            render: c =>
                <div className='flex flex-row items-center justify-center'>
                    {CheckPrivilege("CUSTOMER_MANAGEMENT") && <Link className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' to={"/establishment-editor?id=" + c._id} ><FaEdit /></Link>}
                    {CheckPrivilege("CUSTOMER_MANAGEMENT") && <div className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' onClick={() => { setCurrentPaymentCustomerID(c._id); }}><FaDollarSign /></div>}
                </div>
        },
        {
            title: 'Désignation',
            dataIndex: 'designation',
            key: 'designation',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Prénom',
            dataIndex: 'firstName',
            key: 'firstName',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Nom',
            dataIndex: 'lastName',
            key: 'familyName',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Catégorie',
            dataIndex: 'category',
            key: 'category',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Balance',
            dataIndex: 'balance',
            key: 'balance',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Prix par défaut',
            dataIndex: 'defaultPrice',
            key: 'defaultPrice',
            className: 'border border-gray-500',
            width: 256,
            render: p => <div className='m-1'><DefaultPriceLabel defaultPrice={p} /></div>
        }
    ];

    const columns_mobile = [
        {
            title: 'Operations',
            dataIndex: '',
            key: 'operation',
            className: 'border border-gray-500',
            width: 64,
            render: c =>
                <div className='flex flex-row items-center justify-center'>
                    <div className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' onClick={() => { setCurrentPaymentCustomerID(c._id); }}><FaDollarSign /></div>
                </div>
        },
        {
            title: 'Designation',
            dataIndex: '',
            key: 'name',
            className: 'border border-gray-500',
            width: 256,
            render: c => <div>{c.firstName + " " + c.familyName}</div>
        },
        {
            title: 'Balance',
            dataIndex: 'balance',
            key: 'balance',
            className: 'border border-gray-500',
            width: 256
        }
    ];

    const GetCustomerListFromDb = async () => {

        PerformGetRequest("/api/get-customer-list", (res) => {
            setCustomerList(res.data);
        });

    }

    const handleOnConfirmPayment = (ParamValue) => {
        GetCustomerListFromDb();
        setCurrentPaymentCustomerID(null);
    }

    return (
        <div className='text-gray-100 flex flex-col items-center'>
            <br />
            <h3 className='text-xl font-bold'>Liste des Clients</h3>
            <br />
            {/* {CheckPrivilege("CUSTOMER_MANAGEMENT") && <Link to='/customer-editor'><RknButton label="Ajouter Un Client" before={<FaPlus />} /></Link>} */}
            <br />
            <br />
            <div className='flex flex-col items-center'>
                <Table columns={columns} data={customerList} rowKey="_id" className='hidden md:inline' />
                <Table columns={columns_mobile} data={customerList} rowKey="_id" className='inline md:hidden' />
            </div>
            <br />
            <br />
            {/* <RknInputDialog isOpen={currentPaymentCustomerID ? true : false} onConfirm={handleOnConfirmPayment} onClose={() => { setCurrentPaymentCustomerID(null); }} /> */}
            {currentPaymentCustomerID && <BalancePaymentPopup onCancel={() => { setCurrentPaymentCustomerID(null); }} onConfirm={handleOnConfirmPayment} establishmentID={currentPaymentCustomerID} />}
        </div>
    )
}

export default CustomerManager