import { React, useState, useEffect } from 'react';
import { HashLoader } from 'react-spinners';
import { PerformImageGetRequest } from '../Reaknotron/Libs/RknQueryTools';
// import { PackImg } from '../assets/Features/commandes-rapides-num-pad.jfif';
// require(`../assets/Features/${imageName}`);

const ProductImage = (props) => {

  useEffect(() => {

    const fetchImage = async () => {
      try {
        if (props.pack) {
          const packImg = require('../assets/Props/Cube.jpg');
          setImage(packImg);
        }
        else if (props.image) {
          setImage(props.image);
        }
        else if (props.size == 64)
          setImage(await PerformImageGetRequest("/api/get-product-image?id=" + props.id + "&size=64"));
        else
          setImage(await PerformImageGetRequest("/api/get-product-image?id=" + props.id));
      } catch (error) {
        console.log('ERROR : ' + error.message);
      }
    };

    fetchImage();
  }, []);

  const [image, setImage] = useState(null);
  const [loaded, setLoaded] = useState(false);

  const handleOnClick = () => {
    if (props.onClick)
      props.onClick();
  }

  return (
    <div className='flex flex-col items-center justify-center m-0.5 select-none'>
      <div style={{ width: props.size, height: props.size }} className={image ? 'grid place-items-center' : `grid place-items-center border-2 border-gray-300 ${props.showLabel ? "rounded-t-2xl" : "rounded-2xl"} transition duration-150`}>
        {image && <img src={image} className={props.showLabel ? 'object-cover border-2 border-gray-300 rounded-t-2xl shadow-[0_15px_16px_-5px_rgba(0,0,0,0.9)] cursor-pointer hover:brightness-200 transition duration-150' : 'object-cover border-2 border-gray-300 rounded-2xl shadow-[0_15px_16px_-5px_rgba(0,0,0,0.9)] cursor-pointer hover:brightness-200 transition duration-150'} onLoad={() => setLoaded(true)} style={{ width: props.size, height: props.size }} onClick={handleOnClick} draggable={false} onContextMenu={props.onContextMenu} />}
        {!image && <HashLoader color='#AAAAAA' />}
        {props.amount && <div className='absolute bg-red-700 text-gray-100 text-sm font-bold w-7 h-7 rounded-full p-0.5 border-2 border-gray-100 select-none cursor-pointer active:scale-125 transition duration-150 flex flex-col items-center justify-center' onClick={handleOnClick}>{props.amount}</div>}
      </div>
      {props.showLabel &&
        <div style={{ width: props.size }} className='h-8 text-xs text-gray-100 bg-gradient-to-b from-gray-900 to-gray-800 rounded-b-2xl border border-gray-500 grid place-items-center text-ellipsis overflow-hidden whitespace-nowrap'>
          {props.showLabel}
        </div>
      }
    </div>
  )
}

export default ProductImage