import React, { useState, useEffect, forwardRef, useImperativeHandle } from "react";
import AppData from '../../App.json';

const RknDebouncedInput = forwardRef((props, ref) => {

    const [query, setQuery] = useState("");

    useEffect(() => {

        let delay = 400;
        if (props.delay) {
            delay = Number(props.delay);
        }

        if (query && query.length > 0) {

            const timeOutId = setTimeout(() => {
                if (props.onSignal) {
                    props.onSignal(query);
                }
            }, delay);

            return () => clearTimeout(timeOutId);
        }

    }, [query]);

    useImperativeHandle(ref, () => ({
        
        clear() {
            // console.log("Child function called");
            setQuery("");
        }

    }));

    return (
        <div className="w-full m-1">
            <div className='text-sm font-bold bg-gray-900 p-1 border-gray-500 border rounded-t-xl w-full mx-auto'>{props.label ? props.label : "..."}</div>
            <div className={AppData.REDUCE_FROSTED_GLASS ? 'bg-black bg-opacity-40 h-24 flex flex-col items-center justify-center border border-gray-500 rounded-b-xl px-2' : 'bg-gray-500 backdrop-blur-xl bg-opacity-20 h-24 flex flex-col items-center justify-center border border-gray-500 rounded-b-xl px-2'}>
                <input
                    type="text"
                    value={query}
                    // ref={searchRef}
                    onChange={(e) => setQuery(e.target.value)}
                    className={
                        props.errorMode ?
                            'bg-red-800 border-8 border-gray-500 focus:border-cyan-500 text-gray-100 text-lg rounded-3xl p-2.5 w-full'
                            : 'bg-gray-800 border-8 border-gray-500 focus:border-cyan-500 text-gray-100 text-lg rounded-3xl p-2.5 w-full'
                    }
                    placeholder={props.placeholder ? props.placeholder : '...'} />

            </div>
        </div>
    )
});

export default RknDebouncedInput