import React, { useState, useEffect, useRef } from 'react';
import Popup from 'reactjs-popup';
import { FaTimesCircle, FaCheckCircle } from 'react-icons/fa';
import { PerformGetRequest, PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import ProductImage from '../components/ProductImage';
import hotkeys from 'hotkeys-js';
import { GridLoader } from 'react-spinners';
import { Checkmark } from 'react-checkmark';

const QuickServicePopup = (props) => {

    const [itemCounters, setItemCounters] = useState({});
    const [dummy, setDummy] = useState(0);
    const [quickServiceItems, setQuickServiceItems] = useState([7, 8, 9, 4, 5, 6, 1, 2, 3]);
    const [quickServiceItemsInfo, setQuickServiceItemsInfo] = useState({});
    const [COID, setCOID] = useState(null);
    const [cateringOrderIDinDB, setCateringOrderIDinDB] = useState(null);
    const [total, setTotal] = useState(0);
    const [isLoading, setIsLoading] = useState(true);
    const [finalized, setFinalized] = useState(false);

    // const popupRef = useRef(null);

    useEffect(() => {
        const handleKeyDown = (event) => {

            if (event.key >= '1' && event.key <= '9') {
                // console.log('A numpad number from 1 to 9 was pressed');
                handleItemOnClick(event.key);
            }

            if (event.key === 'Enter') {
                event.preventDefault();
                console.log("Enter");
                OnSubmit(event);
            }
        };

        window.addEventListener('keydown', handleKeyDown);

        // Clean up function
        return () => {
            window.removeEventListener('keydown', handleKeyDown);
        };
    }, [itemCounters, cateringOrderIDinDB]);

    const handleOpen = () => {

        setFinalized(false);

        let c = 0;
        PerformGetRequest("/api/generate-empty-catering-order", (res) => {
            setCOID(res.data.coid);
            setCateringOrderIDinDB(res.data._id);
        });

        setItemCounters({});
        setDummy(0);

        quickServiceItems.forEach((item) => {
            if (localStorage.getItem("quick-service-slot-" + item)) {
                const id = localStorage.getItem("quick-service-slot-" + item);
                c++;
                PerformGetRequest("/api/get-product?id=" + id, (res) => {
                    // console.log("QP = " + JSON.stringify(res.data));
                    let tmpItems = quickServiceItemsInfo;
                    tmpItems[id] = res.data;
                    setQuickServiceItemsInfo(tmpItems);
                    c--;
                    if (c === 0) {
                        setIsLoading(false);
                    }
                });
            }
        });
    }

    const CloseModal = () => {
        props.onClose();
        console.log("CloseModal");
    }

    const OnSubmit = (e) => {

        if (props.isOpen && !finalized) {
            console.log("OnSubmit");

            e.preventDefault();

            // Build consumed products list with amount and price and some other info
            let consumedProducts = {};
            for (const k of Object.keys(quickServiceItemsInfo)) {
                const p = quickServiceItemsInfo[k];

                if (itemCounters[k]) {
                    let productInfo = { id: p.id, name: p.name, category: p.category, price: p.price, altLangName: p.altLangName, amount: itemCounters[k].amount, preparationDuration: p.preparationDuration };
                    
                    if (p.buyable && p.sellable) {
                        productInfo.wap = p.wap;
                    }

                    consumedProducts[k] = productInfo;
                }

            }

            // Calculate total
            var total = 0;
            for (const k of Object.keys(consumedProducts)) {
                total += (Number(consumedProducts[k].price) * Number(consumedProducts[k].amount));
            };

            // Prepare data to post
            let cateringOrderToPost = { id: cateringOrderIDinDB, totalPrice: total, fulfilledPaiement: total, consumedProducts: consumedProducts };

            // Post
            setIsLoading(true);
            PerformSecurePostRequest("/api/finalize-catering-order", cateringOrderToPost, (res) => {
                setIsLoading(false);
                setFinalized(true);
                setTimeout(() => { CloseModal(); }, 1500);
            });
        }
    }

    const handleItemOnClick = (ParamSlotID, ParamID) => {

        let id;
        if (ParamID) {
            id = ParamID;
        } else {
            id = localStorage.getItem("quick-service-slot-" + ParamSlotID);
        }

        let tmpItems = itemCounters;
        if (tmpItems[id]) {
            tmpItems[id].amount = tmpItems[id].amount + 1;
        } else {
            tmpItems[id] = { slot: ParamSlotID, amount: 1 };
        }

        setItemCounters(tmpItems);

        UpdateTotal(tmpItems);

        setDummy(prevDummy => prevDummy + 1);
    }

    const UpdateTotal = (ParamItems) => {

        // console.log("PARAM ITEMS = " + JSON.stringify(ParamItems));

        let total = 0;
        for (const k of Object.keys(ParamItems)) {
            const price = Number(quickServiceItemsInfo[k].price);
            total += (price * Number(ParamItems[k].amount));
        }
        setTotal(total);
    }

    return (
        <div>
            <Popup
                open={props.isOpen}
                modal
                closeOnDocumentClick
                onClose={() => { CloseModal(); }}
                onOpen={handleOpen}
            >
                <div className="modal bg-gray-900 text-gray-100 p-2 flex flex-col items-center">
                    <button className="close" onClick={() => { CloseModal(); }}>
                        <FaTimesCircle />
                    </button>
                    <div className="header">Service Rapide</div>
                    <div className='bg-gray-800 text-gray-500 rounded-xl mt-2 text-xs sm:text-sm font-bold pt-0.5 w-64 flex flex-col items-center justify-center'>Commande N° : {COID}</div>
                    <div className='bg-gray-800 text-gray-100 rounded-xl mt-0.5 text-xs sm:text-base font-bold pt-0.5 w-64 flex flex-col items-center justify-center'>Total : {total} DA</div>

                    {!isLoading && !finalized && <form onSubmit={OnSubmit} className="content flex flex-col items-center">

                        <div className='grid grid-rows-3 grid-cols-3'>
                            {quickServiceItems.map((item) => {
                                const id = localStorage.getItem("quick-service-slot-" + item);
                                return (id ?
                                    <ProductImage
                                        amount={(itemCounters[id] && itemCounters[id].amount) ? itemCounters[id].amount : ""}
                                        id={id}
                                        size={64}
                                        onClick={() => { handleItemOnClick(item, id); }}
                                    />
                                    :
                                    <div className='bg-gray-700 text-gray-100 font-bold text-3xl p-1 m-1 rounded-xl w-16 h-16 cursor-pointer hover:bg-gray-500 transition duration-300'>
                                        {item}
                                    </div>);
                            })}
                        </div>

                        <button type='submit' className="bg-blue-500 hover:bg-blue-400 text-white font-bold py-2 px-4 border-b-4 border-blue-700 hover:border-blue-500 rounded mt-2"><FaCheckCircle className='inline mb-1' size={20} /> Confirmer</button>
                        <br />

                    </form>}

                    {finalized && !isLoading && <div className="m-4">
                        <Checkmark color="#223344" size="72px" />
                    </div>}

                    {isLoading && <GridLoader size={24} color={"#AAA"} />}

                </div>
            </Popup>
        </div>
    )
}

export default QuickServicePopup;