    const Save = (ParamFinalized, ParamAmountToPay, ParamInitialPayment, ParamPaymentMethod, ParamReceivedCash, ParamGiveBackCash, ParamCheckIdNumber) => {

        return new Promise(async (resolve) => {

            if (!changesAvailable)
                resolve(false);
            // return;

            setIsSaving(true);

            let res;

            try {

                const saleToPost = {
                    products: products,
                    totalPrice: total,
                    amountToPay: ParamAmountToPay,
                    initialPayment: ParamInitialPayment,
                    establishmentID: establishmentID,
                    finalized: ParamFinalized,
                    paymentMethod: ParamPaymentMethod,
                    receivedCash: ParamReceivedCash,
                    giveBackCash: ParamGiveBackCash,
                    checkIdNumber: ParamCheckIdNumber,
                    cashRegID: cashRegID
                }

                PerformSecurePostRequest("/api/new-sale", saleToPost, (res) => {
                    if (res) {
                        // console.log("ID =  " + res.data.id);
                        navigate('/sales-point?id=' + res.data.id);
                        setSaleID(res.data.id);
                        setChangesAvailable(false);
                        setIsSaving(false);
                        setFinalized(ParamFinalized);
                        resolve(res.data.id);
                    } else {
                        resolve(false);
                    }
                });

            } catch (error) {
                setOnError(true);
                setErrorMessage("Impossible d'effectuer la sauvegarde, Veuillez contacter votre support technique si le problème persiste.")
                console.log("ERROR : " + error);

                if (error.response && error.response.status >= 400 && error.response.status <= 500) {
                    console.log(error.response.data);
                }

                setIsSaving(false);
                resolve(false);
            }
        });

    }

    const Update = (ParamFinalized, ParamAmountToPay, ParamInitialPayment, ParamPaymentMethod, ParamReceivedCash, ParamGiveBackCash, ParamCheckIdNumber) => {

        return new Promise(async (resolve) => {

            setIsSaving(true);

            try {

                const saleToPost = {
                    id: saleID,
                    products: products,
                    totalPrice: total,
                    amountToPay: ParamAmountToPay,
                    initialPayment: ParamInitialPayment,
                    establishmentID: establishmentID,
                    finalized: ParamFinalized,
                    paymentMethod: ParamPaymentMethod,
                    receivedCash: ParamReceivedCash,
                    giveBackCash: ParamGiveBackCash,
                    checkIdNumber: ParamCheckIdNumber,
                    cashRegID: cashRegID
                }

                PerformSecurePostRequest("/api/update-sale", saleToPost, (res) => {
                    if (res) {
                        setChangesAvailable(false);
                        setIsSaving(false);
                        setFinalized(ParamFinalized);
                        resolve(true);
                    } else {
                        resolve(false);
                    }
                });

            } catch (error) {
                setOnError(true);
                setErrorMessage("Impossible d'effectuer la sauvegarde, Veuillez contacter votre support technique si le problème persiste.")
                console.log("ERROR : " + error);

                if (error.response && error.response.status >= 400 && error.response.status <= 500) {
                    console.log(error.response.data);
                }

                setIsSaving(false);
                resolve(false);
            }

        });
    }

