import { React, useState, useEffect, useRef } from 'react';
import { FaTimesCircle } from 'react-icons/fa';
import Popup from 'reactjs-popup';
import RknButton from '../components/RknUI/RknButton';
import RknNumericInput from './RknUI/RknNumericInput';
import { FaDownload } from 'react-icons/fa';
import { Impact_GetBinaryString } from "../Reaknotron/Fonts/impact-normal";
import html2canvas from 'html2canvas';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import { GetDateTimeDMYHM, GetShortDateOf, IsIsoDate, TimeStampToDMY } from '../Reaknotron/Libs/RknTimeTools';

const jspdf = require('jspdf');

const PrintMedicationStickerPopup = (props) => {

    // const textAreaStyle = 'bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 w-full';

    const pdfRef = useRef(null);

    const [width, setWidth] = useState(40);
    const [height, setHeight] = useState(20);
    const [batch, setBatch] = useState(null);
    const [product, setProduct] = useState(null);
    const [batchInfoContent, setBatchInfoContent] = useState(null);

    useEffect(() => {
        // console.log("PrintMedicationStickerPopup");
        setBatch(props.batch);

        PerformGetRequest("/api/get-product?id=" + props.batch.productID, (res) => {
            console.log("PROD = " + JSON.stringify(res.data));
            setProduct(res.data);
        });
    }, []);

    useEffect(() => {
        setBatchInfoContent(GetBatchInfoContent());
    }, [product]);

    const CloseModal = () => {
        props.onClose();
    }

    const GetBatchInfoContent = () => {

        if (batch && batch.expiryDateStatus && batch.expiryDateStatus.date && batch.entryDate && IsIsoDate(batch.entryDate) && IsIsoDate(batch.expiryDateStatus.date)) {

            // const fab = new Date(batch.entryDate);
            // const exp = new Date(batch.expiryDateStatus.date);

            const fabString = TimeStampToDMY(batch.entryDate);
            const expString = TimeStampToDMY(batch.expiryDateStatus.date);
            const idString = batch.batchID;

            const pdfContent = `
                <div style="font-family: 'Courier New'; font-size: 6pt;" class="bg-white text-black w-18 h-24 font-bold">
                    <p style="transform: rotate(270deg) translateX(-32px) translateY(-4px);">
                    FAB : ${fabString}
                    <br/>
                    EXP : ${expString}
                    <br/>
                    LOT : ${idString}
                    </p>
                </div>
            `;

            return pdfContent;
        } else {
            return "?";
        }


    }

    // <div style="font-family: Helvetica; font-size: 6pt; transform: rotate(270deg);" class="bg-black text-white p-2 pb-4 h-16 w-32">


    const BuildPDF = async () => {

        const halfReceiptWidth = width / 2;
        const x2 = width * 0.3;

        // const doc = new jspdf.jsPDF('p', 'mm', [height, width]); // Portrait, Milimeter, Height, Width
        const doc = new jspdf.jsPDF('landscape', 'mm', [height, width]); // Landscape, Milimeter, Height, Width
        var cursorY = 2;

        // // Impact
        // const impactBinary = Impact_GetBinaryString();
        // doc.addFileToVFS('impact', impactBinary);
        // doc.addFont('impact', 'impact', 'normal');

        // // Init
        // doc.setFont('impact', 'normal');
        // doc.setTextColor(0, 0, 0);
        // doc.setFontSize(36);

        // // Label
        // doc.text("VIGNETTE", halfReceiptWidth, cursorY, 'center');
        // cursorY += 1;

        // console.log(doc.getFontList());
        doc.setFont('helvetica', 'normal');
        doc.setTextColor(0, 0, 0);
        doc.setFontSize(6);

        // Company
        doc.text("Vignette Vitasource", x2, cursorY, 'left');
        cursorY += 2.5;

        // Name
        doc.text(batch.product, x2, cursorY, 'left');
        cursorY += 2.5;

        // Description
        doc.text("Complément Alimentaire", x2, cursorY, 'left');
        cursorY += 3.5;

        doc.setFontSize(5);

        // Count
        doc.text("Boite de 24 Pcs", x2, cursorY, 'left');
        cursorY += 2;

        // Price
        doc.text(`Prix : 900.50 + SHP 2.50`, x2, cursorY, 'left');
        cursorY += 3;

        // PPA
        doc.text(`PPA : ${product.price} DA`, x2, cursorY, 'left');
        cursorY += 2;

        // Ref Price
        doc.text(`Tarif Ref. De : ${product.price} DA`, x2, cursorY, 'left');
        cursorY += 2;

        // // Generate the image data URL
        // // const imageUrl = DrawRotatedText("FAB : 12/12/2024", 90, 20, 40);
        // const imageUrl = DrawRotatedMultiLineText("FAB : 12/12/2024\n FAB : 12/12/2024\n FAB : 12/12/2024", 90, 400, 200);
        // console.log("IMAGE URL = " + imageUrl);

        // Add the image to the PDF
        // doc.addImage(imageUrl, 'PNG', 10, 10, 100, 100); // Adjust these parameters as needed

        try {
            const canvas = await html2canvas(pdfRef.current, {
                quality: 1, // Adjust quality for better image quality
                scale: 4, // Use a higher scale for increased resolution
                allowCSSFilters: true, // Enable CSS filters support
            });
            const imgData = canvas.toDataURL('image/png');
            console.log("CANVAS IMG DATA = " + imgData); // Do something with the image data
            doc.addImage(imgData, 'PNG', -2, -2, 12, 20); // Adjust these parameters as needed
        } catch (error) {
            console.error('Error capturing PDF as image:', error);
        }

        doc.setFont(undefined, 'normal');

        return doc;
    }

    const DownloadPDF = async () => {
        console.log("DownloadPDF()");
        const doc = await BuildPDF();
        doc.save("Vignette.pdf");
    }

    return (
        <div>
            <Popup
                open={props.isOpen}
                modal
                closeOnDocumentClick
                onClose={() => { CloseModal(); }}
            >
                <div className="modal bg-gray-900 text-gray-100 p-2">
                    <button className="close" onClick={() => { CloseModal(); }}>
                        <FaTimesCircle />
                    </button>
                    <div className="header"> Impression de Vignette pour Médicaments </div>
                    <div className="content flex flex-col items-center">
                        <div dangerouslySetInnerHTML={{ __html: batchInfoContent }} ref={pdfRef} />
                        <RknNumericInput value={width} onChange={setWidth} />
                        <RknNumericInput value={height} onChange={setHeight} />
                        <RknButton label="Télécharger" className="w-48 mx-auto" before={<FaDownload />} onPress={DownloadPDF} />
                    </div>
                </div>
            </Popup>
        </div>
    )
}

export default PrintMedicationStickerPopup