function GetDateTimeDMYHM(ParamDate) {
    var d = new Date(ParamDate);
    var month = '' + (d.getMonth() + 1);
    var day = '' + d.getDate();
    var year = d.getFullYear();
    var hour = '' + d.getHours();
    var minute = '' + d.getMinutes();

    if (month.length < 2)
        month = '0' + month;

    if (day.length < 2)
        day = '0' + day;

    if (hour.length < 2)
        hour = '0' + hour;

    if (minute.length < 2)
        minute = '0' + minute;

    return [day, month, year].join('-') + " " + [hour, minute].join(':');
}

const GetShortDate = () => {
    return (new Date()).toLocaleDateString('fr-FR', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' });
}

const GetShortDateOf = (ParamDate) => {
    return ParamDate.toLocaleDateString('fr-FR', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' });
}

function GetTimeHM2Digits() {
    var d = new Date();
    var hour = '' + d.getHours();
    var minute = '' + d.getMinutes();

    if (hour.length < 2)
        hour = '0' + hour;

    if (minute.length < 2)
        minute = '0' + minute;

    return hour + ":" + minute;
}

function ConvertMsToDHMS(ParamMilliseconds) {

    const days = Math.floor(ParamMilliseconds / (24 * 60 * 60 * 1000));
    const daysMod = Math.floor(ParamMilliseconds % (24 * 60 * 60 * 1000));
    const hours = Math.floor(daysMod / (60 * 60 * 1000));
    const hoursMod = Math.floor(daysMod % (60 * 60 * 1000));
    const minutes = Math.floor(hoursMod / (60 * 1000));
    const minutesMod = Math.floor(hoursMod % (60 * 1000));
    const seconds = Math.floor(minutesMod / 1000);

    return days + ":" + hours + ":" + minutes + ":" + seconds;
}

function ConvertMsToHMS(ParamMilliseconds) {

    const hours = Math.floor(ParamMilliseconds / (60 * 60 * 1000));
    const hoursMod = Math.floor(ParamMilliseconds % (60 * 60 * 1000));
    const minutes = Math.floor(hoursMod / (60 * 1000));
    const minutesMod = Math.floor(hoursMod % (60 * 1000));
    const seconds = Math.floor(minutesMod / 1000);

    return hours + ":" + minutes + ":" + seconds;
}

function IsIsoDate(ParamStr) {
    const timestamp = Date.parse(ParamStr);
    return !isNaN(timestamp) && new Date(timestamp).toISOString() === ParamStr;
}

function TimeStampToDMY(ParamTimeStamp) {
    const date = new Date(ParamTimeStamp); // Convert to milliseconds
    const day = ('0' + date.getDate()).slice(-2); // Get the day and ensure it's two digits
    const month = ('0' + (date.getMonth() + 1)).slice(-2); // Get the month and ensure it's two digits
    const year = date.getFullYear(); // Get the year

    return `${day}-${month}-${year}`;
}

const GetBatchExpirationStatus = (ParamBatches) => {

    console.log("BAT = " + JSON.stringify(ParamBatches));

    const batchKeys = Object.keys(ParamBatches);

    console.log("BAT KEY 0 = " + batchKeys[0]);

    if (ParamBatches && batchKeys && batchKeys[0]) {

        console.log("MARK 1");
        var d = new Date(ParamBatches[batchKeys[0]].expiryDate);

        if (batchKeys.length > 1) {
            let min = new Date(ParamBatches[batchKeys[0]].expiryDate);

            batchKeys.forEach((bk) => {
                if (ParamBatches[bk].expiryDate && IsIsoDate(ParamBatches[bk].expiryDate) && new Date(ParamBatches[bk].expiryDate) < min)
                    min = new Date(ParamBatches[bk].expiryDate);
            });

            d = min;
        }

        if (new Date() >= d) {
            console.log("MARK 2");
            return { status: "EXPIRED", remaining: 0, date: d };
        } else {
            console.log("MARK 3");
            const daysUntilExpiration = GetDaysLeftUntil(d);
            if (daysUntilExpiration <= 3) {
                return { status: "DANGER", remaining: daysUntilExpiration, date: d };
            } else if (daysUntilExpiration <= 15) {
                return { status: "WARNING", remaining: daysUntilExpiration, date: d };
            } else {
                return { status: "SAFE", remaining: daysUntilExpiration, date: d };
            }
        }

    } else {
        console.log("MARK 4");
        return { status: "UNKNOWN", remaining: 0, date: d };
    }
}

const GetDaysLeftUntil = (ParamTargetDate) => {
    const oneDay = 24 * 60 * 60 * 1000; // hours*minutes*seconds*milliseconds
    return Math.round((ParamTargetDate - new Date()) / oneDay);
}

const ConvertDateToISO = (input) => {
    // Step 1 & 2: Split the input string by '/' and reorder the parts
    const parts = input.split("/");
    const reordered = `${parts[2]}-${parts[1]}-${parts[0]}`;

    // Step 3: Use the Date object to create a new date
    const date = new Date(reordered);

    // Step 4: Convert the date to an ISO 8601 extended format string
    const isoString = date.toISOString();

    // Step 5: Split the ISO 8601 date string by 'T' and return the date
    // return isoString.split("T")[0];
    return isoString;
}

const GetFrenchMonthFromNumber = (ParamNumber) => {
    const frenchMonths = ['Janvier', 'Février', 'Mars', 'Avril', 'Mai', 'Juin', 'Juillet', 'Août', 'Septembre', 'Octobre', 'Novembre', 'Décembre'];

    const n = Number(ParamNumber);
    if (n > 0 && n < 13) {
        return frenchMonths[n-1];
    }
}

