import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import { PerformGetRequest } from '../../Reaknotron/Libs/RknQueryTools';
import InventoryMovementCell from '../../components/InventoryMovementCell';

const InventoryMovementSummary = () => {

    useEffect(() => {

        GetProductsFromDb();

    }, []);

    const [products, setProducts] = useState(null);

    const columns = [
        {
            title: 'Designation',
            dataIndex: 'name',
            key: 'name',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Sommaire',
            dataIndex: '',
            key: 'summary',
            className: 'border border-gray-500',
            width: 320,
            render: p => <InventoryMovementCell id={p._id} />
        }
    ];

    const GetProductsFromDb = async () => {

        PerformGetRequest("/api/get-product-list?resolveCategoryID=false&ignoreDeleted=true", (ParamResult) => {
            setProducts(ParamResult.data);
        });

    }

    return (
        <div className='text-gray-100'>
            <br />
            <h3 className='text-xl font-bold'>Sommaire des Movements de Stock</h3>
            <br />
            <div className='flex flex-col items-center'>
                <Table columns={columns} data={products} rowKey="_id" />
            </div>
            <br />
            <br />
        </div>
    )
}

export default InventoryMovementSummary