function StringToJson(ParamJson) {
    try {
        // Attempt to parse the string as JSON
        const jsonObject = JSON.parse(ParamJson);

        // Check if the parsed result is an object (not array)
        if (typeof jsonObject === 'object' && jsonObject !== null) {
            return jsonObject;
        } else {
            throw new Error('The parsed result is not an object');
        }
    } catch (error) {
        // If there's any error during parsing, return null
        return null;
    }
}

module.exports = {
    StringToJson
}