import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';

const SalesTotalCounter = (props) => {

    const leftCellStyle = 'mt-2';
    const rightCellStyle = 'font-bold bg-gray-700 p-2 rounded-xl';

    const columns = [
        {
            title: 'Designation',
            dataIndex: 'label',
            key: 'label',
            className: 'border border-gray-500',
            width: 320
        },
        {
            title: "Nombre de Ventes",
            dataIndex: 'count',
            key: 'count',
            width: 256,
            className: 'border border-gray-500'
        },
        {
            title: "Montant Total",
            dataIndex: 'total',
            key: 'total',
            width: 256,
            className: 'border border-gray-500'
        },
        {
            title: "Bénéfice",
            dataIndex: 'profit',
            key: 'profit',
            width: 256,
            className: 'border border-gray-500'
        }
    ];

    const customer_columns = [
        {
            title: 'Client',
            dataIndex: 'label',
            key: 'label',
            className: 'border border-gray-500',
            width: 320
        },
        {
            title: "Total",
            dataIndex: 'total',
            key: 'total',
            width: 256,
            className: 'border border-gray-500'
        }
    ];

    // Effects
    useEffect(() => {

        GetSalesTotal();

    }, [props]);

    // States
    const [total, setTotal] = useState(0);
    const [profit, setProfit] = useState(0);
    const [miscCustomerCount, setMiscCustomerCount] = useState(0);
    const [regularCustomerCount, setRegularCustomerCount] = useState(0);
    const [tableData, setTableData] = useState(null);
    const [customerTableData, setCustomerTableData] = useState(null);

    const GetSalesTotal = async () => {

        // Build Req/Res
        let url;

        if (props.start && props.end)
            url = "/api/get-sales-total?start=" + props.start.toISOString() + "&end=" + props.end.toISOString();
        else
            url = "/api/get-sales-total";

        PerformGetRequest(url, (res) => {
            setTotal(res.data.total);
            setProfit(res.data.profit);
            setMiscCustomerCount(res.data.misc);
            setRegularCustomerCount(res.data.regular);
            setTableData(res.data.categories);
            setCustomerTableData(res.data.totalsByCustomer);
        });
    }

    return (
        <div className='p-4 m-4'>

            <div className='flex flex-col items-center'>
                <div className='grid grid-cols-2 gap-2 text-gray-300 text-left m-2 border-2 border-gray-500 p-2 rounded-xl'>
                    <div className={leftCellStyle}>Montant Total des Ventes</div><div className={rightCellStyle + ' border-2 border-green-800'} >{total || "0"} DA</div>
                    <div className={leftCellStyle}>Bénéfice</div><div className={rightCellStyle + ' border-4 border-green-500'} >{profit || "0"} DA</div>
                    <div className={leftCellStyle}>Nombre de Clients Divers</div><div className={rightCellStyle + ' border-4 border-green-300'} >{miscCustomerCount || "0"}</div>
                    <div className={leftCellStyle}>Clients Réguliers</div><div className={rightCellStyle + ' border-4 border-green-300'} >{regularCustomerCount || "0"}</div>
                </div>
            </div>

            <p className='mt-4 mb-2 text-lg text-gray-100'>Ventes Par Catégorie de Clients</p>
            <div className='flex flex-col items-center justify-center text-base'>
                <Table columns={columns} data={tableData} rowKey="id" tableLayout='auto' className='m-auto text-gray-100' />
                <span className='my-4' />
                <Table columns={customer_columns} data={customerTableData} rowKey="id" tableLayout='auto' className='m-auto text-gray-100' />
            </div>
        </div>
    )
}

export default SalesTotalCounter