const PerformFileGetRequestAndDownload = async (ParamRoute, ParamFileName) => {
  // Parameters
  // ParamRoute Example : "/api/get-catering-orders-list"
  // ParamFileName Example : "contract.docx"

  // Build Request
  var url = GetBackEndUrl() + ParamRoute;

  // Log Request
  console.log("GET : " + url);

  // Perform Request
  try {
    const token = localStorage.getItem("token");
    const res = await axios.get(url, {
      headers: {
        Authorization: token,
        'ngrok-skip-browser-warning': '1'
      },
      responseType: 'arraybuffer' // Set the response type to arraybuffer
    });

    // Create a Blob from the response data
    // TODO : Adapt to all file types not just open xml formats
    const blob = new Blob([res.data], { type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' });

    // Create a URL for the Blob
    const blobUrl = URL.createObjectURL(blob);

    // Create a temporary anchor element
    const a = document.createElement('a');

    // Set the href and download attributes of the anchor element
    a.href = blobUrl;
    a.download = ParamFileName;

    // Click the anchor element to start the download
    a.click();

  } catch (error) {
    console.log("GET ERROR : " + error);
  }
}

const PerformImageGetRequest = (ParamRoute) => {

  return new Promise(async (resolve, reject) => {

    // Build Request
    const url = GetBackEndUrl() + ParamRoute;
    const token = localStorage.getItem("token");
    const config = {
      responseType: 'arraybuffer',
      headers: { Authorization: token, 'ngrok-skip-browser-warning': '1' }
    }

    // Log Request
    // console.log("GET : " + url);

    // Perform Request
    try {
      const response = await axios.get(url, config);
      let binary = '';
      const bytes = new Uint8Array(response.data);
      bytes.forEach((byte) => binary += String.fromCharCode(byte));
      const imageSrc = `data:${response.headers['content-type'].toLowerCase()};base64,${window.btoa(binary)}`;
      resolve(imageSrc);
    } catch (error) {
      console.log("GET ERROR : " + error);
      reject(error);
    }
  });

}

// For Src attributes like image and audio
const PerformFileGetRequest = (ParamRoute) => {

  return new Promise(async (resolve, reject) => {

    // Build Request
    const url = GetBackEndUrl() + ParamRoute;
    const token = localStorage.getItem("token");
    const config = {
      responseType: 'arraybuffer',
      headers: { Authorization: token, 'ngrok-skip-browser-warning': '1' }
    }

    // Log Request
    // console.log("GET : " + url);

    // Perform Request
    try {
      const response = await axios.get(url, config);

      // console.log("H = " + response.headers['content-type']);

      if (response && response.headers['content-type'] && response.headers['content-type'].startsWith("audio")) {
        let binary = '';
        const bytes = new Uint8Array(response.data);
        bytes.forEach((byte) => binary += String.fromCharCode(byte));
        const src = `data:${response.headers['content-type'].toLowerCase()};base64,${window.btoa(binary)}`;
        resolve(src);
      } else {
        resolve(null);
      }

    } catch (error) {
      console.log("GET ERROR : " + error);
      reject(error);
    }
  });

}

const PerformSecurePostRequest = async (ParamRoute, ParamObjToPost, ParamCallBack) => {
  // Parameters
  // ParamRoute Example : "/api/new-catering-order"

  // Build Request
  var url = GetBackEndUrl() + ParamRoute;

  // Log Request
  console.log("POST : " + url);

  // Perform Request
  try {

    // Add token
    const token = localStorage.getItem("token");

    if (token) {
      const config = {
        // headers: { Authorization: `Bearer ${token}` }
        headers: { Authorization: token }
      };
      let res = await axios.post(url, ParamObjToPost, config);
      if (res && ParamCallBack) {
        ParamCallBack(res);
      }
    }
  } catch (error) {
    console.log("SECURE POST ERROR : " + error);
  }
}

const PerformSecurePostRequestWithFormData = async (ParamRoute, ParamFormData, ParamCallBack) => {
  // Parameters
  // ParamRoute Example : "/api/new-catering-order"

  // Build Request
  var url = GetBackEndUrl() + ParamRoute;

  // Log Request
  console.log("POST : " + url);

  // Perform Request
  try {

    // Add token
    const token = localStorage.getItem("token");

    if (token) {
      const response = await axios({
        method: "post",
        url: GetBackEndUrl() + ParamRoute,
        data: ParamFormData,
        headers: { "Content-Type": "multipart/form-data", Authorization: token }
      });

      if (response && ParamCallBack) {
        ParamCallBack(response);
      }
    }

  } catch (error) {
    console.log("SECURE POST WITH FORMDATA ERROR : " + error);
  }
}

