import React, { useState, useEffect, useRef } from 'react';
import { Navigate, useSearchParams } from 'react-router-dom';
import useDocumentTitle from '@tanem/use-document-title';
import axios from 'axios';
import { GetBackEndUrl } from '../const';
import { FaPrint, FaDownload, FaCheckCircle, FaSave, FaUser, FaTimesCircle, FaQuestionCircle, FaSearch, FaSearchDollar, FaUserPlus, FaStar } from 'react-icons/fa';
import { AnimatePresence, motion } from "framer-motion";
import AppData from '../App.json';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import { CircleLoader } from 'react-spinners';
import { GetDateTimeDMYHM, GetShortDate, GetTimeHM2Digits } from '../Reaknotron/Libs/RknTimeTools';
// import BgVideo from "../assets/Daily Shopping Sales Point BG.mp4";
import '../VFX.css';
import NetImage from '../components/NetImage';
import ProductImage from '../components/ProductImage';

const AdScreen = () => {

    // ...
    useDocumentTitle("Pub");

    // Refs
    const pRef = useRef(null);

    // Navigation
    const [searchParams, setSearchParams] = useSearchParams();

    const [counter, setCounter] = useState(0);
    const [products, setProducts] = useState({});
    const [current, setCurrent] = useState(null);

    const [videoSource, setVideoSource] = useState(null);

    useEffect(() => {

        setVideoSource(require(`../assets/${AppData.SALES_POINT_BG_VIDEO}`));

        PerformGetRequest("/api/promoted-products", (res) => OnProductsLoaded(res.data));

    }, []);

    const OnProductsLoaded = (ParamProducts) => {
        console.log(ParamProducts);
        setProducts(ParamProducts);

        if (ParamProducts && ParamProducts[0]) {
            setCurrent(ParamProducts[0]);

            setTimeout(() => {
                LoadNextProduct(ParamProducts, 0);
            }, 5000);
        }
    }

    const LoadNextProduct = (ParamProducts, ParamIndex) => {
        const nextIndex = ParamIndex + 1;
        console.log("NEXT = " + nextIndex);
        console.log("LENGTH = " + ParamProducts.length);

        // Remove the class
        pRef.current.classList.remove("fade-5");

        // Trigger a reflow to restart the animation
        void pRef.current.offsetWidth;

        // Add the class back
        pRef.current.classList.add("fade-5");

        if (nextIndex > ParamProducts.length - 1) {
            setCurrent(ParamProducts[0]);

            setTimeout(() => {
                LoadNextProduct(ParamProducts, -1);
            }, 5000);
        } else {
            setCurrent(ParamProducts[nextIndex]);

            setTimeout(() => {
                LoadNextProduct(ParamProducts, nextIndex);
            }, 5000);
        }
    }

    return (
        <div className='text-gray-100 bg-black'>

            <video src={videoSource} className='fixed h-screen w-full object-cover opacity-100' autoPlay loop muted />

            <div className='fixed top-16 right-2 left-2 h-16 bg-gradient-to-b from-yellow-700 to-yellow-300 m-1 p-1 rounded-xl'>
                <div className='text-yellow-900 font-bold flex flex-row items-center justify-center space-x-2 animate-pulse'>
                    <FaStar size={32} /><p style={{ fontSize: 32 }}>PROMOTION</p><FaStar size={32} />
                </div>
            </div>

            <div className='fixed top-36 right-2 left-2 bottom-4 mx-1 p-1 bg-black bg-opacity-10 rounded-xl flex flex-col items-center justify-center'>

                {/* <AnimatePresence>
                    <motion.div
                        key={current?._id}
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        transition={{ duration: 1, delay: 1 }}
                    > */}

                <div className='fade-5 bg-black px-24 rounded-3xl bg-opacity-20 backdrop-blur-sm border border-neutral-400' ref={pRef}>

                    {/* Name */}
                    <div
                        className='font-bold mt-4'>
                        {current && <p style={{ fontSize: 36 }}>{current.name}</p>}
                    </div>

                    {/* Picture */}
                    <div>
                        {current && <ProductImage id={current._id} size={256} />}
                    </div>

                    {/* Price */}
                    <div>
                        {current && <p style={{ fontSize: 48 }} className='text-red-700 font-bold line-through'>{current.price} DA</p>}
                    </div>

                    {/* Promotion Price */}
                    <div
                        className='text-gray-100 font-bold animate-bounce mb-4' style={{ fontSize: 72 }}>
                        {current && <p>{current.promotionPrice} DA</p>}
                    </div>

                </div>

                {/* </motion.div>
                </AnimatePresence> */}

            </div>
        </div>
    )
}

export default AdScreen