import React from 'react';
import { motion } from 'framer-motion';

const RknAnimatedPopup = (props) => {

    const handleOnClose = () => {
        if (props.onClose)
            props.onClose();
    }

    return (
        <div>
            <motion.div
                className='fixed top-0 right-0 left-0 w-screen h-screen bg-black bg-opacity-60 z-10 flex flex-col items-center justify-center backdrop-blur-lg'
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ duration: 0.3 }}
                onClick={handleOnClose}
            >
                <motion.div
                    className='bg-gray-900 border-4 border-gray-500 rounded-3xl m-auto w-5/6 md:w-1/2 p2 md:p-4 pb-0 flex flex-col items-center justify-center'
                    initial={{ opacity: 0, y: "-50%" }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.3 }}
                >
                    {props.children}
                </motion.div>
            </motion.div>
        </div>
    )
}

export default RknAnimatedPopup