import React, { useState } from 'react';
import { FaDatabase, FaImages } from 'react-icons/fa';
import FileUpload from '../components/FileUpload';
import { GetBackEndUrl } from '../const';
import { AwesomeButton } from 'react-awesome-button';
import RknButton from '../components/RknUI/RknButton';
import { PerformFileGetRequest, PerformFileGetRequestAndDownload, PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import RknContainer from '../components/RknUI/RknContainer';
import AppData from '../App.json';
import { SyncLoader } from 'react-spinners';

const DatabaseManager = () => {

    const [counter_Img64, setCounter_Img64] = useState(0);
    const [max_Img64, setMax_Img64] = useState(0);

    const StartImg64Generation = () => {
        PerformGetRequest("/api/get-product-list", (res) => {
            setMax_Img64(res.data.length);
            GenerateNextItem_Img64(res.data, 1);
        });
    }

    const GenerateNextItem_Img64 = (ParamItems, ParamCounter) => {
        if (ParamItems && ParamItems.length > 0) {
            // console.log("LEN 1 = " + ParamItems.length);
            const p = ParamItems.shift();
            // console.log("LEN 2 = " + ParamItems.length);

            if (p) {
                PerformGetRequest("/api/generate-64pix?id=" + p._id, (res) => {
                    // console.log("P RES = " + JSON.stringify(res.data));

                    setCounter_Img64(ParamCounter);
                    GenerateNextItem_Img64(ParamItems, ParamCounter + 1);
                });
            }
        }
    }

    return (
        <div className='flex flex-col items-center justify-center'>
            <span className="mt-24" />

            <RknContainer title="Base de Données">
                <div className='p-2'>
                    {/* <AwesomeButton className='m-8' before={<FaDatabase />}><a href={GetBackEndUrl() + "/api/get-database"} target='_blank'>Télécharger la Base de Données</a></AwesomeButton> */}
                    <AwesomeButton className='m-8' before={<FaDatabase />} onPress={() => { PerformFileGetRequestAndDownload("/api/get-database", "Base de Données.json"); }}>Télécharger la Base de Données</AwesomeButton>
                </div>
                {/* <RknButton label="" */}
            </RknContainer>

            <RknContainer title="Optimizations">
                <div className='p-2'>
                    <AwesomeButton className='m-8' before={<FaImages />} onPress={StartImg64Generation} >Générer les images 64x64</AwesomeButton>
                </div>
                {max_Img64 > 0 && counter_Img64 > 0 && max_Img64 && counter_Img64 &&
                    <div className='text-gray-100 text-xs font-bold bg-gray-900 p-1 rounded-full'>
                        {counter_Img64 + "/" + max_Img64}
                    </div>
                }
            </RknContainer>

        </div>
    )
}

export default DatabaseManager