import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import { FaPlus } from 'react-icons/fa';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';

const PTManager = () => {

    useEffect(() => {

        GetPTListFromDb();

    }, []);

    const [PTList, setPTList] = useState();

    const columns = [
        {
            title: 'Designation',
            dataIndex: 'name',
            key: 'name',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Salaire de Base',
            dataIndex: 'baseSalary',
            key: 'baseSalary',
            className: 'border border-gray-500',
            width: 256
        }
    ];

    const GetPTListFromDb = async () => {

        PerformGetRequest("/api/pt-list", (res) => setPTList(res.data));
    }

    return (
        <div className='text-gray-100'>
            <br />
            <h3 className='text-xl font-bold'>Liste des Titres professionnels</h3>
            {/* <br />
            <AwesomeButton before={<FaPlus />}><a href='/provider-editor'>Ajouter Un Fournisseur</a></AwesomeButton>
            <br /> */}
            <br />
            <div className='flex flex-col items-center'>
                <Table columns={columns} data={PTList} rowKey="_id" />
            </div>
            <br />
            <br />
        </div>
    )
}

export default PTManager