    const BuildPDF = async () => {

        var receiptWidth = 60;

        if (localStorage.getItem("receiptWidth")) {
            receiptWidth = Number(localStorage.getItem("receiptWidth"));
            console.log("RECEIPT WIDTH = " + receiptWidth);
        }

        const halfReceiptWidth = receiptWidth / 2;

        const doc = new jspdf.jsPDF('p', 'mm', [192, receiptWidth]); // Portrait, Milimeter, Height, Width
        var cursorY = 10;

        // Label
        doc.setFont(undefined, 'bold');
        doc.setTextColor(0, 0, 0);
        doc.setFontSize(11);
        doc.text("Facturation de la Réception", halfReceiptWidth, cursorY, 'center');
        cursorY += 4;
        doc.setFont(undefined, 'normal');

        // Provider
        doc.setFont(undefined, 'bold');
        doc.setTextColor(0, 0, 0);
        doc.setFontSize(9);
        doc.text("Fournisseur : " + "???", halfReceiptWidth, cursorY, 'center');
        cursorY += 4;
        doc.setFont(undefined, 'normal');

        // Date
        doc.setFontSize(8);
        doc.text(GetShortDate() + " à " + GetTimeHM2Digits(), halfReceiptWidth, cursorY, 'center');
        cursorY += 4;

        // Sold Products Table
        const tableData = buildSoldProductsTableDataForPDF();

        let cellTextFontSize = 9;
        autoTable(doc, {
            head: [tableData.head],
            body: tableData.body,
            startY: cursorY,
            margin: 1,
            theme: 'grid',
            tableWidth: receiptWidth - 2,
            styles: {
                fontSize: cellTextFontSize,
                cellPadding: 1,
                fontStyle: 'bold',
                textColor: 'black'
            },
            headStyles: { fillColor: [0, 0, 0], textColor: [255, 255, 255] },
            didDrawPage: (d) => { cursorY = d.cursor.y },
        });
        cursorY += 9;

        // Total
        doc.setFontSize(12);
        doc.text("Total : " + StringToNumber_2DecAtMost(total) + " DA", halfReceiptWidth, cursorY, 'center');
        cursorY += 8;

        return doc;
    }

