import autoTable from 'jspdf-autotable';
import { StringToNumber_2DecAtMost, StringToNumber_2DecAlways } from '../Libs/RknStringTools';
const AppData = require('../../App.json');
const { GetShortDate } = require('../Libs/RknTimeTools');
const jspdf = require('jspdf');

const BuildProductsTableData = (ParamItems, ParamFinalized) => {

    var head = ['N°', 'Produit', 'Base', 'Recharge', 'Départ', 'Final', 'Vendu', 'P.U.', 'Montant'];

    let body = [];
    let c = 0;

    // for (let index = 0; index < 15; index++) {

    for (const item of ParamItems) {

        let tableLine = [];

        c++;
        tableLine.push(c);

        console.log("ITEM = " + JSON.stringify(item));

        if (Number(item.baseAmount) === 0 && Number(item.loadedAmount) === 0 && Number(item.finalAmount) === 0) {
            // Ignore
        } else {
            tableLine.push(item.productLabel);
            tableLine.push(item.baseAmount);
            tableLine.push(item.loadedAmount);
            tableLine.push(item.departureAmount);
            tableLine.push(ParamFinalized ? item.finalAmount : "");
            tableLine.push(ParamFinalized ? item.soldAmount : "");
            tableLine.push(item.price);
            tableLine.push(ParamFinalized ? item.total : "");
            body.push(tableLine);
        }

    }

    // }

    let result = { head: head, body: body };
    return result;
}

export async function GenerateDischargeSheet(ParamCustomerLabel, ParamItemsList, ParamTotal, ParamFinalized) {

    var receiptWidth = 210;

    const doc = new jspdf.jsPDF('p', 'mm', [270, receiptWidth]); // Portrait, Milimeter, Height, Width
    var cursorY = 16;

    // Title
    let title = "Fiche de Décharge";
    let titleFontSize = 28;

    // Title
    doc.setFont(undefined, 'bold');
    doc.setTextColor(0, 0, 0);
    doc.setFontSize(titleFontSize);
    doc.text(title, 5, cursorY, 'left');
    cursorY += 5;

    // Date
    doc.setFont(undefined, 'normal');
    doc.setFontSize(10);
    doc.text("Date : " + GetShortDate(), 5.1, cursorY, 'left');
    cursorY += 5;

    // Customer
    doc.setFont(undefined, 'normal');
    doc.setFontSize(10);
    doc.text("Client : " + ParamCustomerLabel, 5.1, cursorY, 'left');
    cursorY += 5;

    // Total
    doc.setFont(undefined, 'normal');
    doc.setFontSize(10);
    doc.text("Montant Total : " + StringToNumber_2DecAlways(ParamTotal) + " DA", 5.1, cursorY, 'left');
    cursorY += 10;

    // Products table
    const tableData = BuildProductsTableData(ParamItemsList, ParamFinalized);

    let cellTextFontSize = 10;
    autoTable(doc, {
        head: [tableData.head],
        body: tableData.body,
        startY: cursorY,
        margin: 6,
        theme: 'grid',
        tableWidth: receiptWidth - 16,
        styles: {
            fontSize: cellTextFontSize,
            cellPadding: 1,
            fontStyle: 'bold',
            textColor: 'black',
            lineWidth: 0.25,
            lineColor: [72, 72, 72]
        },
        headStyles: { fillColor: [0, 0, 0], textColor: [255, 255, 255] },
        didDrawPage: (d) => { cursorY = d.cursor.y },
    });
    cursorY += 5;

    return doc;
}