import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import useDocumentTitle from '@tanem/use-document-title';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import { StringToNumber_2DecAlways, StringToNumber_2DecAtMost } from '../Reaknotron/Libs/RknStringTools';

const StockValue = () => {

    useDocumentTitle("Valeur du Stock");

    const GetProductListFromDb = async () => {
        PerformGetRequest("/api/get-product-value-list", (res) => {
            setPositiveProductList(res.data.positive);
            setPositiveProductsTotal(res.data.positiveSum);
            setNegativeProductList(res.data.negative);
            setNegativeProductsTotal(res.data.negativeSum);
        });
    }

    useEffect(() => {

        GetProductListFromDb();

    }, []);

    const columns = [
        {
            title: 'N°',
            dataIndex: '', // Empty string as we're not mapping to a data field
            key: 'rowNumber', // Unique key for this column
            width: 80, // Adjust width as needed
            className: 'border border-gray-500',
            render: (text, record, index) => index + 1, // Display index+1 as row numbers start at 1
        },
        {
            title: 'Designation',
            dataIndex: 'name',
            key: 'name',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Qte. Disponible',
            dataIndex: 'availableAmount',
            key: 'availableAmount',
            width: 128,
            className: 'border border-gray-500'
        },
        {
            title: 'P.U.M.P.',
            dataIndex: 'wap',
            key: 'wap',
            width: 128,
            className: 'border border-gray-500',
            render: wap => <div>{StringToNumber_2DecAtMost(wap)}</div>
        },
        {
            title: 'Total',
            dataIndex: '',
            key: 'total',
            width: 128,
            className: 'border border-gray-500',
            render: i => <div>{StringToNumber_2DecAtMost(i.availableAmount * i.wap)}</div>
        }
    ];

    const [positiveProductList, setPositiveProductList] = useState(null);
    const [positiveProductsTotal, setPositiveProductsTotal] = useState(null);
    const [negativeProductList, setNegativeProductList] = useState(null);
    const [negativeProductsTotal, setNegativeProductsTotal] = useState(null);

    return (
        <div className='flex flex-col items-center justify-center text-gray-100'>
            <h1 className='text-2xl font-bold my-2'>Valeur du Stock</h1>
            {positiveProductList && <div className='p-1 px-2 bg-gray-900 mt-2 font-bold text-xl border-4 border-neutral-300 rounded-t-xl'>Total  :  {StringToNumber_2DecAlways(positiveProductsTotal, false, true)} DA</div>}
            {positiveProductList && <Table columns={columns} data={positiveProductList} rowKey="id" tableLayout='auto' className='bg-gray-900 p-4 rounded-xl border border-neutral-500' />}
            <span className='my-2' />
            {negativeProductList && <div className='p-1 px-2 bg-red-900 mt-2 font-bold text-xl border-4 border-neutral-300 rounded-t-xl'>Total (Négatif)  :  {StringToNumber_2DecAlways(negativeProductsTotal, false, true)} DA</div>}
            {negativeProductList && <Table columns={columns} data={negativeProductList} rowKey="id" tableLayout='auto' className='bg-red-900 p-4 rounded-xl border border-neutral-500' />}
            <span className='my-4' />
        </div>
    )
}

export default StockValue