// Outputs and ISO date String when the date is valid, otherwise outputs an empty string.
import { React, useState, useEffect } from 'react';
import { IsIsoDate } from '../../Reaknotron/Libs/RknTimeTools';

import { useTranslation } from 'react-i18next';

const RknDateInput = (props) => {

    const { t } = useTranslation();

    function formatDate(date) {
        let day = date.getDate().toString().padStart(2, '0');
        let month = (date.getMonth() + 1).toString().padStart(2, '0'); // add 1 because months are zero-indexed
        let year = date.getFullYear();

        return `${day}/${month}/${year}`;
    }

    useEffect(() => {
        if (props.value && IsIsoDate(props.value)) {
            const d = new Date(props.value);
            const f = formatDate(d);

            if (f == input) {

            } else {
                setInput(f);
                setIsDateValid(true);
            }
            // setInput(props.value);
        }
    }, [props.value]);

    const [input, setInput] = useState("");
    const [isDateValid, setIsDateValid] = useState(false);
    const [_ISO_expirationDate, set_ISO_ExpirationDate] = useState(null);

    function isValidDate(input) {
        let slashes = input.match(/\//g);

        if (slashes && slashes.length >= 2 && input.length == 10) {
            return true;
        } else {
            return false;
        }
    }

    function convertDateToISO(input) {
        // Step 1 & 2: Split the input string by '/' and reorder the parts
        const parts = input.split("/");
        const reordered = `${parts[2]}-${parts[1]}-${parts[0]}`;

        // Step 3: Use the Date object to create a new date
        const date = new Date(reordered);

        // Step 4: Convert the date to an ISO 8601 extended format string
        const isoString = date.toISOString();

        // Step 5: Split the ISO 8601 date string by 'T' and return the date
        // return isoString.split("T")[0];
        return isoString;
    }

    function handleExpDateOnChange(e) {

        let i = e.target.value;
        let valid = isValidDate(i);
        let tmpISODate = null;

        if (valid) {
            setIsDateValid(true);
            tmpISODate = convertDateToISO(i);
        } else {
            setIsDateValid(false);
        }

        setInput(i);
        set_ISO_ExpirationDate(tmpISODate);
        TriggerPropsOnChange(tmpISODate);
    }

    const TriggerPropsOnChange = (ParamIsoDate) => {
        if (props.onChange)
            props.onChange(ParamIsoDate);
    }

    return (
        <div className={props.className ? props.className : ''}>
            <input className={isDateValid ? "text-gray-100 bg-gray-700 rounded-lg p-1 m-1 border border-gray-500" : "text-gray-100 bg-red-700 rounded-lg p-1 m-1 bg-opacity-40 border border-gray-500"} type='text' name='expirationDate' value={input} placeholder={t("pos.toolbar.quote.dateFormat")} onChange={handleExpDateOnChange} />
        </div>
    )
}

export default RknDateInput