import { FaCartArrowDown, FaOutdent, FaCartPlus, FaBox } from 'react-icons/fa';

export const SubjectToIconAndLabel = (ParamSubject) => {
    if (ParamSubject === "sale") {
        return <div className='flex flex-row items-center justify-center text-blue-500'>
            <FaCartArrowDown className='mr-1' /> Vente
        </div>;
    } else if (ParamSubject === "dischargeSheet") {
        return <div className='flex flex-row items-center justify-center text-yellow-500'>
            <FaOutdent className='mr-1' /> Fiche de Décharge
        </div>;
    } else if (ParamSubject === "reception") {
        return <div className='flex flex-row items-center justify-center text-green-500'>
            <FaCartPlus className='mr-1' /> Réception
        </div>;
    } else if (ParamSubject === "product") {
        return <div className='flex flex-row items-center justify-center text-gray-300'>
            <FaBox className='mr-1' /> Produit
        </div>;
    }
};

export const ActionToIconAndLabel = (ParamAction) => {
    if (ParamAction === "CREATE") {
        return <div className='flex flex-row items-center justify-center p-1 m-1 mx-auto text-xs w-20 rounded font-bold text-gray-100 bg-green-800'>
            Création
        </div>;
    } else if (ParamAction === "UPDATE") {
        return <div className='flex flex-row items-center justify-center p-1 m-1 mx-auto text-xs w-20 rounded font-bold text-gray-100 bg-orange-600'>
            Modification
        </div>;
    } else if (ParamAction === "DELETE") {
        return <div className='flex flex-row items-center justify-center p-1 m-1 mx-auto text-xs w-20 rounded font-bold text-gray-100 bg-red-800'>
            Suppression
        </div>;
    }
};

export const BoolToIconAndLabel = (ParamBool) => {
    if (ParamBool === null) {
        return <div className='flex flex-row items-center justify-center p-1 m-1 mx-auto text-xs w-20 rounded font-bold text-gray-100 bg-neutral-800'>
            ?
        </div>;
    } else if (ParamBool === true) {
        return <div className='flex flex-row items-center justify-center p-1 m-1 mx-auto text-xs w-20 rounded font-bold text-gray-100 bg-green-800'>
            Oui
        </div>;
    } else if (ParamBool === false) {
        return <div className='flex flex-row items-center justify-center p-1 m-1 mx-auto text-xs w-20 rounded font-bold text-gray-100 bg-red-800'>
            Non
        </div>;
    }
};