import React, { useState } from 'react';
import { FaQuestionCircle } from 'react-icons/fa';
import { motion } from 'framer-motion';

const RknEmojiSelector = (props) => {

    const emojis = ['', '❓', '⭐', '☕', '🥤', '🍹', '💧', '🧃', '🍲', '🥗', '🥪', '🍕', '🍔', '🌮', '🥩', '🍖', '🍗', '🥚', '🍜', '🍛', '🍝', '🥘', '🍪', '🎂', '🍰', '🍬', '🍫', '🍨', '🍦', '🍧', '🥧', '🧁', '🍩', '🧴', '🏺', '🥫', '💊', '🍊', '🌿', '🥦', '🥕', '🍅', '🌾', '🛠️', '⚙️', '🔩', '🪓', '🧰', '🥽', '⚡', '🏠', '💍', '💎', '🔗', '⛓', '📿', '🎀', '🌷͙֒', '✨', '🧷', '🔮', '👑', '🧪', '⚛', '🗣', '📖', '👜', '🦻', '👨', '👩', '🥇', '🥈', '🥉', '🗿', '🎇', '💉', '🦷', '👄', '😷', '⚕', '🏥', '🩺', '🩸'];

    const [showSelector, setShowSelector] = useState(false);
    const [selectedEmoji, setSelectedEmoji] = useState('');

    const handleEmojiOnClick = (ParamEmoji) => {
        setSelectedEmoji(ParamEmoji);
        setShowSelector(false);

        if (props.onChange)
            props.onChange(ParamEmoji);
    }

    return (
        <div className='flex flex-col items-center justify-center'>

            <div className='border-4 border-gray-500 flex flex-row w-48 h-12 rounded-3xl m-1'>
                <div className='w-9/12 bg-gray-800 p-2 rounded-l-3xl text-xs flex flex-col items-center justify-center'>
                    Séléctionner un Emoji
                </div>
                <div onClick={() => setShowSelector(true)} className='w-3/12 bg-gray-600 p-2 rounded-r-3xl text-lg cursor-pointer hover:bg-slate-300 hover:text-gray-700 transition duration-150 flex flex-col items-center justify-center'>
                    {selectedEmoji ? selectedEmoji : <FaQuestionCircle className='scale-125' />}
                </div>
            </div>

            {showSelector && <motion.div
                initial={{ opacity: 0, scale: "20%" }}
                animate={{ opacity: 1, scale: "100%" }}
                transition={{ duration: 0.3 }}
                className='absolute flex flex-row flex-wrap items-center justify-center bg-gray-700 bg-opacity-20 backdrop-blur-xl border-4 border-gray-500 rounded-3xl p-2 sm:w-5/6 w-11/12'
            >
                {emojis.map((e, i) => {
                    return (
                        <div onClick={() => handleEmojiOnClick(e)} key={i} className='w-10 h-10 text-xl rounded-lg border border-gray-500 bg-gray-900 hover:bg-gray-500 cursor-pointer transition duration-300 p-1 m-0.5'>
                            {e}
                        </div>
                    )
                })}
            </motion.div>}
        </div>
    )
}

export default RknEmojiSelector