import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import RenderExpirationStatus from '../Reaknotron/Libs/RknDataRenderingUtils';
import RknIconButton from '../components/RknUI/RknIconButton';
import { Link } from 'react-router-dom';
import { FaEye } from 'react-icons/fa';

const Notifications = () => {

    useEffect(() => {

        GetProductNotifications();
        GetSaleNotifications();
        GetReceptionNotifications();

    }, []);

    const [p_notifications, set_p_Notifications] = useState(null);
    const [s_notifications, set_s_Notifications] = useState(null);
    const [r_notifications, set_r_Notifications] = useState(null);

    const renderNotification = (ParamNotif) => {

        if (ParamNotif.reason === "STORAGE") {

            if (ParamNotif.availableAmount < ParamNotif.minimumAmount)
                return <div className='text-red-500'>Stock Dangereusement Faible</div>
            else if (ParamNotif.availableAmount < ParamNotif.alertAmount)
                return <div className='text-yellow-500'>Stock Faible</div>

        } else if (ParamNotif.reason === "EXPIRATION") {
            return RenderExpirationStatus(ParamNotif.expiryStatus);
        }

        return <div>?</div>

    }

    const p_columns = [
        {
            title: 'Produit',
            dataIndex: 'name',
            key: 'name',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Notification',
            dataIndex: '',
            key: 'notification',
            className: 'border border-gray-500',
            width: 256,
            render: p => renderNotification(p)
        }
    ];

    const s_columns = [
        {
            title: 'Client',
            dataIndex: 'customerLabel',
            key: 'customerLabel',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Reste à Payer',
            dataIndex: 'sale',
            key: 'remainingAmount',
            className: 'border border-gray-500',
            width: 256,
            render: s => <div className={(Number(s.amountToPay) - Number(s.fulfilledPaiement)) > 0 ? 'text-red-600 font-bold' : 'text-green-500'}>{Number(s.amountToPay) - Number(s.fulfilledPaiement)} ({100 - Math.round((Number(s.fulfilledPaiement) / Number(s.amountToPay) * 100))} %)</div>
        },
        {
            title: 'Vente',
            dataIndex: 'sale',
            key: 'sale',
            className: 'border border-gray-500',
            width: 64,
            render: s => <Link to={`/sales-point?id=${s._id}`} className='flex flex-row items-center justify-center' ><RknIconButton icon={<FaEye />} /></Link>
        }

    ];

    const r_columns = [
        {
            title: 'Fournisseur',
            dataIndex: 'label',
            key: 'label',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Reste à Payer',
            dataIndex: 'reception',
            key: 'remainingAmount',
            className: 'border border-gray-500',
            width: 256,
            render: r => <div className={(Number(r.totalPrice) - Number(r.fulfilledPaiement)) > 0 ? 'text-red-600 font-bold' : 'text-green-500'}>{Number(r.totalPrice) - Number(r.fulfilledPaiement)} ({100 - Math.round((Number(r.fulfilledPaiement) / Number(r.totalPrice) * 100))} %)</div>
        },
        {
            title: 'Reception',
            dataIndex: 'reception',
            key: 'reception',
            className: 'border border-gray-500',
            width: 64,
            render: s => <Link to={`/reception-editor?id=${s._id}`} className='flex flex-row items-center justify-center' ><RknIconButton icon={<FaEye />} /></Link>
        }

    ];

    const GetProductNotifications = async () => {

        PerformGetRequest("/api/product-notifications", (res) => set_p_Notifications(res.data));
    }

    const GetSaleNotifications = async () => {

        PerformGetRequest("/api/sale-notifications", (res) => set_s_Notifications(res.data));
    }

    const GetReceptionNotifications = async () => {

        PerformGetRequest("/api/reception-notifications", (res) => set_r_Notifications(res.data));
    }

    return (
        <div className='text-gray-100 flex flex-col items-center'>
            <br />
            <h3 className='text-xl font-bold mb-2'>Notifications sur les produits</h3>
            {p_notifications && <Table columns={p_columns} data={p_notifications} rowKey="_id" />}

            <h3 className='text-xl font-bold mt-4 mb-2'>Notifications sur les crédits</h3>
            {s_notifications && <Table columns={s_columns} data={s_notifications} rowKey="_id" />}
            <br />

            <h3 className='text-xl font-bold mt-4 mb-2'>Notifications sur les réceptions</h3>
            {r_notifications && <Table columns={r_columns} data={r_notifications} rowKey="_id" />}
            <br />
            <br />
        </div>
    )
}

export default Notifications