import React, { useState, useEffect, forwardRef } from 'react';

const RknNumericInput = forwardRef((props, ref) => {

    const [value, setValue] = useState("");

    useEffect(() => {

        if (props.value)
            setValue(props.value);
        else if (props.value === 0)
            setValue(0);

    }, [props.value])

    const handleChange = (event) => {

        if (event.target.value === '') {
            setValue("");

            if (props.onChange)
                props.onChange('');

            return;
        }

        var regex = /^\d*\.?\d*$/;
        if (props.allowNegative) {
            var regex = /^(-?\d*\.?\d*)$/;
        }


        if (regex.test(event.target.value)) {
            setValue(event.target.value);

            if (props.onChange)
                props.onChange(event.target.value);
        }
    }

    return (
        <div className='flex flex-col items-start justify-center'>
            {props.label && <label className="ml-1 text-sm font-medium text-gray-900 dark:text-white">{props.label}</label>}
            <div className='flex flex-row items-center justify-center'>
                <input
                    value={value}
                    onChange={handleChange}
                    placeholder={props.placeholder}
                    className={'bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 mt-1 h-9'}
                    ref={ref}
                    style={{ height: props.height ? props.height : "", width: props.width ? props.width : "" }}
                    readOnly={props.readOnly ? props.readOnly : false}
                    onKeyDown={(e) => { if (props.onKeyDown) props.onKeyDown(e) }}
                />
                <div className='ml-1 font-bold text-gray-900 dark:text-gray-100'>{props.unit}</div>
            </div>
        </div>
    )
})

export default RknNumericInput