import { React, useState, useEffect, useRef } from 'react';
import Popup from 'reactjs-popup';
import { FaTimesCircle } from 'react-icons/fa';
import RknSubmitButton from './RknSubmitButton';
import RknDateInput from './RknDateInput';

const RknDateRangeDialog = (props) => { // TODO : Add regex prop

    // const inputFieldStyle = 'bg-gray-50 border border-gray-300 text-gray-900 text-lg font-bold rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 mt-2';

    const ref = useRef(null);

    // const [userInput, setUserInput] = useState("");
    const [start, setStart] = useState(null);
    const [end, setEnd] = useState(null);

    const handleOnOpen = () => {
        if (props.defaultValue) {
            // setUserInput(props.defaultValue);
            // ref.current.focus();
        }

        setTimeout(() => {
            ref.current.focus();
        }, 150);
    }

    const CloseModal = () => {
        if (props.onClose)
            props.onClose();
    }

    // const handleUserInputChange = (event) => {
    //     setUserInput(event.target.value);
    // }

    const handleConfirmOnClick = (event) => {

        event.preventDefault();

        // if (props.onConfirm) {
        //     props.onConfirm({ start: start, end: end });
        // }

        if (props.onConfirm) {
            const confirmedStart = new Date(start).setHours(0, 0, 0, 0);
            const confirmedEnd = new Date(end).setHours(23, 59, 59, 999);

            const isoStart = (new Date(confirmedStart)).toISOString();
            const isoEnd = (new Date(confirmedEnd)).toISOString();

            props.onConfirm({ start: isoStart, end: isoEnd });
        }
    }

    return (
        <div>
            <Popup
                open={props.isOpen}
                modal
                closeOnDocumentClick
                onClose={() => { CloseModal(); }}
                onOpen={handleOnOpen}
            >
                <div className="modal bg-gray-900 text-gray-100 p-2">
                    <button className="close" onClick={() => { CloseModal(); }}>
                        <FaTimesCircle />
                    </button>
                    <div className="header">Saisissez votre texte</div>
                    <form onSubmit={handleConfirmOnClick} className="content flex flex-col items-center">
                        <br />
                        {/* <input ref={ref} type="text" name='userInput' placeholder='...' value={userInput} className={inputFieldStyle} onChange={handleUserInputChange} autocomplete="off" /> */}
                        <label className="block text-sm font-medium text-gray-900 dark:text-white">Début</label>
                        <RknDateInput ref={ref} value={start} onChange={(v) => { setStart(v); }} placeholder={"Date de début..."} />
                        <span className='block mb-2' />
                        <label className="block text-sm font-medium text-gray-900 dark:text-white">Fin</label>
                        <RknDateInput value={end} onChange={(v) => { setEnd(v); }} placeholder={"Date de fin..."} />
                        <span className='block mb-2' />
                        <br />
                        <RknSubmitButton label="Valider" onClick={handleConfirmOnClick} />
                    </form>
                </div>
            </Popup>
        </div>
    )
}

export default RknDateRangeDialog