import { React, useState, useEffect } from 'react';
import RknButton from './RknUI/RknButton';
import { PerformGetRequest, PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import RknNumericInput from '../components/RknUI/RknNumericInput';

const SilverPriceEditor = () => {

    useEffect(() => {
        PerformGetRequest("/api/get-silver-price", (res) => {
            setSilverPrice(res.data.silverPrice);
        });
    }, []);

    const [silverPrice, setSilverPrice] = useState(0);
    const [isSaving, setIsSaving] = useState(false);

    const handleSilverPriceChange = (ParamValue) => {
        console.log("V = " + ParamValue);
        setSilverPrice(ParamValue);
    }

    const handleSaveOnClick = () => {

        setIsSaving(true);

        console.log("SP = " + silverPrice);
        PerformSecurePostRequest("/api/update-silver-price", { price: silverPrice }, (res) => {
            setIsSaving(false);
        });
    }

    return (
        <div className='flex flex-col items-center justify-center'>
            <RknNumericInput value={silverPrice} onChange={handleSilverPriceChange} placeholder="Prix d'Un Gramme d'Argent" unit="DA" />
            <RknButton label="Enregistrer" onPress={handleSaveOnClick} disabled={isSaving} />
        </div>
    )
}

export default SilverPriceEditor