// Bon d'Achat PDF Generator (Not a delivery note, but a purchase note)
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import i18n from 'i18next';
import { GetCurrencySymbol } from '../../const';
import { GetShortDate, GetTimeHM2Digits } from '../Libs/RknTimeTools';
import { StringToNumber_2DecAlways } from '../Libs/RknStringTools';
const AppData = require('../../App.json');

const buildSoldProductsTableDataForPDFTicket = (ParamProducts) => {

    var head = ['Qte', 'Designation', 'P.U', 'Montant'];

    let body = [];

    Object.keys(ParamProducts).forEach((pk) => {
        let tableLine = [];
        let p = ParamProducts[pk];
        tableLine.push(p.amount);
        tableLine.push(p.name);
        tableLine.push(p.price);
        tableLine.push(p.price * p.amount);
        body.push(tableLine);
    });

    let result = { head: head, body: body };
    return result;
}

const buildSoldProductsTableDataForPDFA4 = (ParamProducts) => {

    let head = ['N°', 'Designation', 'Qte', 'P.U', 'Montant'];

    let body = [];
    let c = 0;

    Object.keys(ParamProducts).forEach((pk) => {

        // console.log("P = " + JSON.stringify(ParamProducts[pk]));

        let tableLine = [];
        let p = ParamProducts[pk];

        c++;
        tableLine.push(c);

        tableLine.push(p.name);
        tableLine.push(p.amount);

        if (AppData.PRODUCT_SPECIFIC_TVA) {
            const puttc = Number(p.price) + Number(p.price * p.tva / 100);
            tableLine.push(puttc);
            tableLine.push(puttc * p.amount);
        } else {
            tableLine.push(p.price);
            tableLine.push(p.price * p.amount);
        }

        body.push(tableLine);
    });

    let result = { head: head, body: body };
    return result;
}

const buildTotalInfoDataForPDFA4 = (ParamTotal, ParamAmountToPay, ParamFullfilledPayment, ParamUsedBalance) => {

    const total = Number(ParamTotal);
    const fullfilled = Number(ParamFullfilledPayment);

    let body = [];
    body.push(["Total : " + StringToNumber_2DecAlways(total)]);

    if (ParamTotal != ParamAmountToPay) {
        let remise = total - ParamAmountToPay;
        body.push(["Remise : " + StringToNumber_2DecAlways(remise) + " (" + StringToNumber_2DecAlways((remise / total) * 100) + "%)"]);
        body.push(["Montant à Payer : " + StringToNumber_2DecAlways(ParamAmountToPay)]);
    }

    body.push(["Montant Versé : " + StringToNumber_2DecAlways(fullfilled)]);

    if (ParamUsedBalance)
        body.push(["Solde Utilisé : " + StringToNumber_2DecAlways(ParamUsedBalance)]);

    body.push(["Reste à Payer : " + StringToNumber_2DecAlways(ParamAmountToPay - fullfilled - (ParamUsedBalance || 0))]);

    return body;
}

const BuildVoucher_A4 = async (ParamRef, ParamEstablishmentInfo, ParamInitialPayment, ParamTotal, ParamAmountToPay, ParamProducts, ParamCustomerInfo, ParamUsedBalance) => {

    var receiptWidth = 210;

    const halfReceiptWidth = receiptWidth / 2;
    const rightBlockXCoord = receiptWidth * 0.7;

    const doc = new jsPDF('p', 'mm', [270, receiptWidth]); // Portrait, Milimeter, Height, Width 
    var cursorY = 11;

    // Bon D'Achat
    doc.setFont(undefined, 'bold');
    doc.setTextColor(0, 0, 0);
    doc.setFontSize(26);
    doc.text("Bon d'Achat", rightBlockXCoord, cursorY, 'left');

    if (!AppData.HIDE_CONTACTS_ON_DELIVERY_NOTE) {
        // Address
        doc.setFont(undefined, 'normal');
        doc.setFontSize(12);
        doc.text((ParamEstablishmentInfo.address || "-"), 8, cursorY, 'left');
        cursorY += 4;

        // Tel
        doc.text("N° Tel : " + (ParamEstablishmentInfo.phoneNumber || "-"), 8, cursorY, 'left');
        cursorY += 4;
    } else {
        doc.setFont(undefined, 'normal');
        doc.setFontSize(12);
        cursorY += 8;
    }

    // ID
    doc.text("Vente N° " + ParamRef, rightBlockXCoord, cursorY, 'left');
    cursorY += 4;

    // Date
    doc.text("Date : " + GetShortDate(), rightBlockXCoord, cursorY, 'left');
    cursorY += 4;

    if (AppData.HIDE_CONTACTS_ON_DELIVERY_NOTE) {
        cursorY -= 16;
    }

    // Label
    doc.setFont(undefined, 'bold');
    doc.setFontSize(26);
    doc.text((ParamEstablishmentInfo.commercialDesignation || "-"), 8, cursorY, 'left');
    cursorY += 4;

    // Text under label / Activity
    doc.setFont(undefined, 'normal');
    doc.setFontSize(10);
    doc.text((ParamEstablishmentInfo.activity || "-"), 8, cursorY, 'left');
    cursorY += 16;

    if (!AppData.HIDE_CONTACTS_ON_DELIVERY_NOTE) {
        cursorY += 16;
    }

    // Customer name
    doc.setFontSize(12);

    autoTable(doc, {
        body: [['Client : ' + (ParamCustomerInfo?.designation || "Divers"), 'Solde : ' + (ParamCustomerInfo?.balance || "0") + " DA"]],
        startY: cursorY,
        margin: 2,
        theme: 'grid',
        tableWidth: receiptWidth - 4,
        styles: {
            fontSize: 10,
            cellPadding: 1,
            fontStyle: 'bold',
            textColor: 'black'
        },
        didDrawPage: (d) => { cursorY = d.cursor.y },
    });
    cursorY += 2;

    if (AppData.COMPACT_DELIVERY_NOTE) {

        let body = ['Total : ' + ParamTotal, 'Montant Versé : ' + ParamInitialPayment, 'Reste à Payer : ' + (Number(ParamTotal) - Number(ParamInitialPayment))];
        console.log("ParamUsedBalance = " + ParamUsedBalance);
        if (ParamUsedBalance) {
            body.push('Solde Utilisé : ' + ParamUsedBalance);
        }

        autoTable(doc, {
            body: [body],
            startY: cursorY,
            margin: 2,
            theme: 'grid',
            tableWidth: receiptWidth - 4,
            styles: {
                fontSize: 10,
                cellPadding: 1,
                fontStyle: 'bold',
                textColor: 'black'
            },
            didDrawPage: (d) => { cursorY = d.cursor.y },
        });
        cursorY += 2;
    }

    // Consumption table
    const tableData = buildSoldProductsTableDataForPDFA4(ParamProducts);

    let cellTextFontSize = 10;
    autoTable(doc, {
        head: [tableData.head],
        body: tableData.body,
        startY: cursorY,
        margin: 2,
        theme: 'grid',
        tableWidth: receiptWidth - 4,
        styles: {
            fontSize: cellTextFontSize,
            cellPadding: 1,
            fontStyle: 'bold',
            textColor: 'black'
        },
        headStyles: { fillColor: [0, 0, 0], textColor: [255, 255, 255] },
        didDrawPage: (d) => { cursorY = d.cursor.y },
    });
    cursorY += 5;

    // Amounts Total
    let c = 0;
    Object.keys(ParamProducts).forEach((pk) => {
        c += ParamProducts[pk].amount;
    });

    doc.setFontSize(10);
    doc.text("Total des Unités : " + c, 2, cursorY, 'left');
    cursorY += 8;

    // Total and Payment
    if (!AppData.COMPACT_DELIVERY_NOTE) {
        const tableData2 = buildTotalInfoDataForPDFA4(ParamTotal, ParamAmountToPay, ParamInitialPayment, ParamUsedBalance);
        autoTable(doc, {
            body: tableData2,
            startY: cursorY,
            margin: halfReceiptWidth,
            theme: 'grid',
            tableWidth: halfReceiptWidth - 10,
            styles: {
                fontSize: cellTextFontSize,
                cellPadding: 1,
                fontStyle: 'bold',
                textColor: 'black'
            },
            didDrawPage: (d) => { cursorY = d.cursor.y },
        });
        cursorY += 14;
    }

    return doc;
}

const BuildVoucher_Ticket = async (ParamProducts, ParamTotal) => {

    var receiptWidth = 60;

    if (localStorage.getItem("receiptWidth")) {
        receiptWidth = Number(localStorage.getItem("receiptWidth"));
        console.log("RECEIPT WIDTH = " + receiptWidth);
    }

    const halfReceiptWidth = receiptWidth / 2;

    const doc = new jsPDF('p', 'mm', [192, receiptWidth]); // Portrait, Milimeter, Height, Width
    var cursorY = 10;

    // Label
    doc.setFont(undefined, 'bold');
    doc.setTextColor(0, 0, 0);
    doc.setFontSize(14);
    // doc.text("Daily Shopping", halfReceiptWidth, cursorY, 'center');
    doc.text(AppData.COMPANY_LABEL, halfReceiptWidth, cursorY, 'center');
    cursorY += 4;
    doc.setFont(undefined, 'normal');

    // Date
    doc.setFontSize(8);
    doc.text(GetShortDate() + " à " + GetTimeHM2Digits(), halfReceiptWidth, cursorY, 'center');
    cursorY += 4;

    // Sold Products Table
    const tableData = buildSoldProductsTableDataForPDFTicket(ParamProducts);

    let cellTextFontSize = 9;
    autoTable(doc, {
        head: [tableData.head],
        body: tableData.body,
        startY: cursorY,
        margin: 1,
        theme: 'grid',
        tableWidth: receiptWidth - 2,
        styles: {
            fontSize: cellTextFontSize,
            cellPadding: 1,
            fontStyle: 'bold',
            textColor: 'black'
        },
        headStyles: { fillColor: [0, 0, 0], textColor: [255, 255, 255] },
        didDrawPage: (d) => { cursorY = d.cursor.y },
    });
    cursorY += 9;

    // Total
    doc.setFontSize(12);
    doc.text("Total : " + ParamTotal + " " + GetCurrencySymbol(i18n.language), halfReceiptWidth, cursorY, 'center');
    cursorY += 8;

    return doc;
}

export { BuildVoucher_A4, BuildVoucher_Ticket };