import React, { useState, useEffect } from 'react';
import { FaPlus, FaCaretDown, FaCaretLeft } from 'react-icons/fa';
import { motion } from 'framer-motion';
import { isIterable } from '../../Reaknotron/Libs/RknDataUtils';
import '../../ScrollBar.css';
import { PerformGetRequest } from '../../Reaknotron/Libs/RknQueryTools';
import useReaktor from '../../Hooks/useReaktor';

const RknSmartSelector = (props) => {

    const [selected, setSelected] = useState("");
    const [selectedLabel, setSelectedLabel] = useState("");
    const [open, setOpen] = useState(false);
    const [items, setItems] = useState(null);

    const GetListFromDB = () => {
        PerformGetRequest(props.url, (res) => {
            if (res && res.data && isIterable(res.data)) {
                // console.log("Iterable Found : " + JSON.stringify(res.data));
                setItems(res.data);
            }
        });
    }

    useEffect(() => {
        GetListFromDB();
    }, [props.url]);

    useEffect(() => {

        console.log("VALUE = " + props.value);

        if (items && props.value && props.idKey) {
            const item = items.find(item => item[props.idKey] === props.value);
            if (item) {
                setSelected(item);
                if (props.labelKey && item[props.labelKey]) {
                    setSelectedLabel(item[props.labelKey]);
                } else {
                    setSelectedLabel("?");
                }
            }
        }
    }, [props.value, items, props.idKey, props.labelKey]);

    useReaktor(props.reaktorContext, (ParamContent) => {
        // console.log("REAKTOR CONTENT = " + JSON.stringify(ParamContent));
        GetListFromDB();

        if (props.onChange && selected) {
            console.log("MARK UPDATE : " + JSON.stringify(selected));
            props.onChange(selected);
        }
    });

    const handleItemOnClick = (ParamItem) => {

        // console.log("CLICK : " + JSON.stringify(ParamItem));

        setSelected(ParamItem);

        if (props.onChange) {
            props.onChange(ParamItem);
        }

        if (props.labelKey && ParamItem[props.labelKey]) {
            setSelectedLabel(ParamItem[props.labelKey]);
        } else {
            setSelectedLabel("?");
        }

        setOpen(false);
    }

    const handlePlusOnClick = () => {

        // Open a new tab with the desired route
        if (props.quickAddRoute) {
            const url = window.location.origin + props.quickAddRoute;
            window.open(url, '_blank'); // Opens in a new tab
        }
    }


    return (
        <div className={props.className ? props.className : ''}>
            <div className='flex flex-row items-center justify-center text-gray-900 dark:text-white'>

                <input value={selectedLabel} className="bg-gray-50 border border-gray-300 text-sm rounded-l-lg focus:ring-blue-500 focus:border-blue-500 p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:focus:ring-blue-500 dark:focus:border-blue-500 h-10 w-64" />

                <div className='flex flex-col items-center justify-center bg-gray-700 w-10 h-10 m-1 border border-gray-300 dark:border-gray-600 rounded-r-lg ml-0 cursor-pointer hover:bg-gray-500 transition duration-300 active:scale-95'
                    onClick={() => { setOpen(!open); }}>
                    {!open && <FaCaretDown size={18} />}
                    {open && <FaCaretLeft size={18} />}
                </div>

                <div className='flex flex-col items-center justify-center bg-gray-700 w-10 h-10 m-1 rounded-lg cursor-pointer hover:bg-gray-500 transition duration-150 active:scale-90'
                    onClick={handlePlusOnClick}
                >
                    <FaPlus size={18} />
                </div>

            </div>

            <div className='relative'>
                {/* <motion.div className='absolute top-full left-1/2 -translate-x-44 h-64 w-72 ml-1.5 bg-gray-900 rounded-xl border-4 border-gray-500 text-xs flex flex-col items-center justify-center' */}
                {open && <motion.div className='absolute top-full left-1/2 -translate-x-44 h-64 w-72 bg-gray-900 rounded-xl border-4 border-gray-500 text-xs flex flex-col overflow-y-scroll scrollbar'
                    initial={{ opacity: 0, y: "-50%", x: "-59%", scaleY: 0 }}
                    animate={{ opacity: 1, y: 0, x: "-59%", scaleY: "100%" }}
                    transition={{ duration: 0.15 }}
                    onBlur={() => setOpen(false)}
                >
                    {items && items.map((item, index) => {
                        return (
                            <div key={item[props.idKey]}
                                className='h-6 w-64 m-0.5 p-0.5 bg-gray-800 text-gray-100 rounded-full hover:bg-gray-600 transition duration-150 cursor-pointer select-none'
                                onClick={() => { handleItemOnClick(item); }}
                            >
                                {(props.labelKey && item[props.labelKey]) ? item[props.labelKey] : "?"}
                            </div>
                        )
                    })}
                </motion.div>}
            </div>
        </div>
    )
}

export default RknSmartSelector