import { React, useState, useEffect, useRef } from 'react';
import Popup from 'reactjs-popup';
import { FaTimesCircle } from 'react-icons/fa';
import RknSubmitButton from './RknSubmitButton';
import { CirclePicker, SwatchesPicker } from 'react-color';

const RknColorDialog = (props) => {

    const [userInput, setUserInput] = useState("");

    const handleOnOpen = () => {
        if (props.defaultValue) {
            setUserInput(props.defaultValue);
        }
    }

    const CloseModal = () => {
        if (props.onClose)
            props.onClose();
    }

    const handleUserInputChange = (ParamColor, ParamEvent) => {
        // console.log("COLOR = " + JSON.stringify(ParamColor));
        console.log("HEX = " + ParamColor.hex);
        setUserInput(ParamColor.hex);
    }

    const handleConfirmOnClick = (event) => {

        event.preventDefault();

        if (props.onConfirm)
            props.onConfirm(userInput);
    }

    return (
        <div>
            <Popup
                open={props.isOpen}
                modal
                closeOnDocumentClick
                onClose={() => { CloseModal(); }}
                onOpen={handleOnOpen}
            >
                <div className="modal bg-gray-900 text-gray-100 p-2">
                    <button className="close" onClick={() => { CloseModal(); }}>
                        <FaTimesCircle />
                    </button>
                    <div className="header">Choisissez une Couleur</div>
                    <br />
                    <form onSubmit={handleConfirmOnClick} className="content flex flex-col items-center">
                        <div className='border-8 border-gray-700 rounded-3xl p-2'>
                            <CirclePicker
                                color={userInput}
                                onChangeComplete={handleUserInputChange}
                            />
                        </div>
                        <br />
                        <RknSubmitButton label="Valider" onClick={handleConfirmOnClick} />
                    </form>
                </div>
            </Popup>
        </div>
    )
}

export default RknColorDialog