import React, { useState, useEffect } from 'react';
import RknButton from '../components/RknUI/RknButton';
import { FaCheckCircle, FaPlus } from 'react-icons/fa';
import { Link } from 'react-router-dom';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import Table from 'rc-table';
import { StringToNumber_2DecAtMost } from '../Reaknotron/Libs/RknStringTools';

const ProductionManager = () => {

    const GetLabelFromStatus = (ParamStatus) => {

        if (ParamStatus === "RUNNING")
            return (<div className='p-0.5 m-0.5 text-sm font-bold bg-green-800 border-2 border-green-500 rounded-xl select-none'>Production en cours...</div>)

        if (ParamStatus === "AWAITING_LAUNCH")
            return (<div className='p-0.5 m-0.5 text-sm font-bold bg-neutral-600 border-2 border-neutral-300 rounded-xl select-none'>En attente de lancement...</div>)

        if (ParamStatus === "ON_PAUSE")
            return (<div className='p-0.5 m-0.5 text-sm font-bold bg-orange-700 border-2 border-orange-500 rounded-xl select-none'>En pause</div>)

        if (ParamStatus === "ON_HALT")
            return (<div className='p-0.5 m-0.5 text-sm font-bold bg-red-700 border-2 border-red-500 rounded-xl select-none'>En arrêt</div>)

        if (ParamStatus === "FINALIZED")
            return (<div className='p-0.5 m-0.5 text-sm font-bold bg-neutral-900 border-2 border-green-500 rounded-xl select-none text-green-500 flex flex-row items-center justify-center'><FaCheckCircle size={18} className='mr-1' />Finalizer</div>)

        // if (ParamStatus === "AWAITING_LAUNCH")
        // return (<div className='p-0.5 m-0.5 text-sm font-bold bg-neutral-600 border-2 border-neutral-100 rounded-xl select-none'>{ParamStatus}</div>)
    }

    const GetEffeciency = (ParamPC) => {

        if (ParamPC.expectedProducts && ParamPC.finalProducts) {

            let efficiency = 0;
            let prodCount = 0;

            // const expectedProdKeys = Object.keys(ParamPC.expectedProducts);
            const finalProdKeys = Object.keys(ParamPC.finalProducts);

            for (const k of finalProdKeys) {
                if (ParamPC.expectedProducts[k] && ParamPC.expectedProducts[k].amount && ParamPC.finalProducts[k].amount) {
                    const e = Number(ParamPC.finalProducts[k].amount) / Number(ParamPC.expectedProducts[k].amount);
                    efficiency += e;
                    prodCount += 1;
                }
            }

            if (prodCount > 0) {
                return StringToNumber_2DecAtMost(efficiency / prodCount * 100) + " %";
            } else {
                return "0 %";
            }

        } else {
            return "?";
        }


    }

    const GetYield = (ParamPC) => {

        if (ParamPC.ingredientsTotal && ParamPC.finalProductsTotal) {

            return StringToNumber_2DecAtMost(ParamPC.finalProductsTotal / ParamPC.ingredientsTotal * 100) + " %";

        } else {
            return "?";
        }

    }

    const columns = [
        {
            title: 'Début',
            dataIndex: 'startDate',
            key: 'startDate',
            className: 'border border-gray-500',
            width: 256,
            render: d => <p className='inline text-sm'>{d ? (new Date(d)).toLocaleDateString('fr-FR', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' }) : "-"}</p>
        },
        {
            title: 'Fin',
            dataIndex: 'finishDate',
            key: 'finishDate',
            className: 'border border-gray-500',
            width: 256,
            render: d => <p className='inline text-sm'>{d ? (new Date(d)).toLocaleDateString('fr-FR', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' }) : "-"}</p>
        },
        {
            title: 'Statut',
            dataIndex: 'status',
            key: 'status',
            className: 'border border-gray-500',
            width: 256,
            render: i => GetLabelFromStatus(i)
        },
        {
            title: 'Efficacité',
            dataIndex: '',
            key: 'efficiency',
            className: 'border border-gray-500',
            width: 256,
            render: i => GetEffeciency(i)
        },
        {
            title: 'Rendement',
            dataIndex: '',
            key: 'yield',
            className: 'border border-gray-500',
            width: 256,
            render: i => GetYield(i)
        }
    ];

    const [pcList, setPcList] = useState(null);

    useEffect(() => {
        PerformGetRequest("/api/prod-cycle-list", (res) => {
            console.log("RES = " + JSON.stringify(res.data));
            setPcList(res.data);
        });
    }, []);

    return (
        <div className='flex flex-col items-center justify-center text-gray-900 dark:text-gray-100'>
            <br />
            <h1 className='font-bold text-xl'>Gestion de la Production</h1>
            <br />
            <Link to='/production-cycle-editor'>
                <RknButton label="Lancer un Cycle de Production" before={<FaPlus />} />
            </Link>
            <br />
            {pcList && <Table columns={columns} data={pcList} rowKey="_id" tableLayout='auto' />}
        </div>
    )
}

export default ProductionManager