import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import RknButton from '../components/RknUI/RknButton';
import { FaCheckCircle, FaEdit, FaHourglass, FaPlus } from 'react-icons/fa';
import { Link } from 'react-router-dom';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import { CheckPrivilege } from '../LoginManager';

const ReturnSlipManager = () => {

    useEffect(() => {

        PerformGetRequest("/api/rs-list", (res) => {
            setRsList(res.data);
        });

    }, []);

    const [rsList, setRsList] = useState(null);

    const columns = [
        {
            title: 'Etat',
            dataIndex: 'finalized',
            key: 'finalized',
            className: 'border border-gray-500',
            width: 32,
            render: f => f ? <FaCheckCircle size={16} className='ml-1 text-green-500' /> : <FaHourglass size={16} className='ml-1 text-neutral-700' />
        },
        {
            title: 'Opérations',
            dataIndex: '',
            key: 'operation',
            className: 'border border-gray-500',
            width: 64,
            render: e =>
                <div className='flex flex-row items-center justify-center'>
                    {CheckPrivilege("ALL") && <Link className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' to={"/return-slip-editor?id=" + e._id} ><FaEdit /></Link>}
                    {/* {CheckPrivilege("ESTABLISHMENT_MANAGEMENT") && <div className='bg-gray-900 text-gray-100 text-xs p-0.5 m-0.5 rounded-lg cursor-pointer hover:bg-gray-700 active:scale-90 transition duration-150 w-6 h-6 flex flex-col items-center justify-center' onClick={() => { setCurrentPaymentEstID(e._id); }}><FaDollarSign /></div>} */}
                </div>
        },
        {
            title: 'Date & Heure',
            dataIndex: 'time',
            key: 'time',
            className: 'border border-gray-500',
            width: 256,
            render: d => <p className='inline text-sm'>{d ? (new Date(d)).toLocaleDateString('fr-FR', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' }) : "-"}</p>
        },
        {
            title: 'Direction',
            dataIndex: 'operation',
            key: 'operation',
            className: 'border border-gray-500',
            width: 128,
            render: o => <div className='inline text-sm'>{o === "FROM" ? "Depuis..." : "Vers..."}</div>
        },
        {
            title: 'Etablisement',
            dataIndex: 'estLabel',
            key: 'estLabel',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Prix Total',
            dataIndex: 'totalPrice',
            key: 'totalPrice',
            className: 'border border-gray-500',
            width: 256
        }
    ];

    return (
        <div className='flex flex-col items-center justify-center text-gray-100'>
            <h1 className='text-3xl font-bold mt-4'>Gestion des Bons de Retour</h1>
            <br />
            <Link to='/return-slip-editor'><RknButton label="Créer un bon de retour" before={<FaPlus />} /></Link>
            <br />
            {rsList && <Table columns={columns} data={rsList} rowKey="_id" />}
            <br />
        </div>
    )
}

export default ReturnSlipManager