import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import Table from 'rc-table';
import { FaPlus, FaEye, FaCheckCircle, FaHourglass, FaTrash } from 'react-icons/fa';
import { PerformGetRequest, PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import RknButton from '../components/RknUI/RknButton';
import RknIconButton from '../components/RknUI/RknIconButton';
import RknConfirmationPopup from '../components/RknUI/RknConfirmationPopup';

const DischargeSheetManager = () => {

    const columns = [
        {
            title: 'Etat',
            dataIndex: 'finalized',
            key: 'finalized',
            className: 'border border-gray-500',
            width: 32,
            render: f => f ? <FaCheckCircle size={16} className='text-green-500 ml-1' /> : <FaHourglass size={16} className='text-neutral-700 ml-1' />
        },
        {
            title: 'Opérations',
            dataIndex: '',
            key: 'operations',
            width: 128,
            className: 'border border-gray-500',
            render: ds => <div className='flex flex-row items-center justify-start'>
                <Link to={"/discharge-sheet-editor?id=" + ds._id}><RknIconButton icon={<FaEye />} /></Link>
                {!ds.finalized && <RknIconButton icon={<FaTrash />} onPress={() => setDeleteSalePopupTarget(ds._id)} />}
            </div>
            // render: ds => JSON.stringify(ds)
        },
        {
            title: 'Date',
            dataIndex: 'time',
            key: 'time',
            className: 'border border-gray-500',
            width: 256,
            render: d => <p className='inline text-sm'>{(new Date(d)).toLocaleDateString('fr-FR', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' })}</p>
        },
        {
            title: 'Client',
            dataIndex: 'customerName',
            key: 'customerName',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Produit(s)',
            dataIndex: 'products',
            key: 'products',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Montant',
            dataIndex: 'total',
            key: 'total',
            className: 'border border-gray-500',
            width: 256
        }
    ];

    useEffect(() => {

        GetDSListFromDb();

    }, []);

    const [dsList, setDSList] = useState();
    const [deleteSalePopupTarget, setDeleteSalePopupTarget] = useState(null);

    const GetDSListFromDb = async () => {

        PerformGetRequest("/api/get-ds-list", (res) => {
            // console.log(JSON.stringify(res.data));
            setDSList(res.data);
        });

    }

    const handleDeleteOnClick = (ParamID) => {

        let dsToPost = { id: ParamID };

        PerformSecurePostRequest("/api/delete-ds", dsToPost, (res) => {
            if (res.data.code === "OK") {
                GetDSListFromDb();
            }
        });

        setDeleteSalePopupTarget(null);

    }

    return (
        <div className='text-gray-100 flex flex-col items-center justify-center'>
            <br />
            <h3 className='text-xl font-bold'>Liste des Fiche(s) de décharge</h3>
            <br />
            {/* <AwesomeButton before={<FaPlus />}><a href='/provider-editor'>Ajouter Un Fournisseur</a></AwesomeButton> */}
            <RknButton className="w-80" before={<FaPlus />} label={<a className='text-sm' href='/discharge-sheet-editor'>Créer une fiche de décharge</a>} onPress={null} />
            <br />
            <br />
            <div className='flex flex-col items-center'>
                <Table
                    columns={columns}
                    data={dsList}
                    rowKey="_id"
                />
            </div>
            <br />
            <br />

            {deleteSalePopupTarget && <RknConfirmationPopup danger={false} onConfirm={() => { handleDeleteOnClick(deleteSalePopupTarget); }} onCancel={() => { console.log("On Cancel"); setDeleteSalePopupTarget(null); }} />}

        </div>
    )
}

export default DischargeSheetManager