import React, { useState, useEffect } from 'react';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import useReaktor from '../Hooks/useReaktor';

const Messenger = () => {

    const [messageList, setMessageList] = useState(null);
    const [message, setMessage] = useState("");

    const GetMessagesFromDB = () => {
        PerformGetRequest("/api/visitor-messages", (res) => {
            // console.log(JSON.stringify(res.data));
            setMessageList(res.data);
        });
    }

    useEffect(() => {

        GetMessagesFromDB();

    }, []);

    useReaktor("VISITOR_MESSAGE", (ParamContent) => {
        console.log("USE REAKTOR TRIGGER");
        GetMessagesFromDB();
    });

    const handleEnterPress = (event) => {
        if (event.key === "Enter") {
            SendMessage();
        }
    };

    const SendMessage = () => {
        setMessage("");
    }

    return (
        <div>
            <h3 className='text-xl font-bold text-gray-100 mt-4 mb-2 pt-2'>Messagerie Instantanée</h3>
            <div className='fixed right-3/4 left-2 top-28 bottom-2 p-2 bg-gray-500 m-1 rounded border-4 border-gray-300 flex flex-col items-center justify-start'>
                <div className='p-1 w-full my-0.5 text-lg font-bold text-gray-100 bg-gray-900 px-2 rounded'>Visiteur 1</div>
                <div className='p-1 w-full my-0.5 text-lg font-bold text-gray-100 bg-gray-900 px-2 rounded'>Visiteur 2</div>
                <div className='p-1 w-full my-0.5 text-lg font-bold text-gray-100 bg-gray-900 px-2 rounded'>Visiteur 3</div>
                <div className='p-1 w-full my-0.5 text-lg font-bold text-gray-100 bg-gray-900 px-2 rounded'>Visiteur 4</div>
                <div className='p-1 w-full my-0.5 text-lg font-bold text-gray-100 bg-gray-900 px-2 rounded'>Visiteur 5</div>
            </div>
            <div className='fixed right-2 left-1/4 top-28 bottom-2 bg-gray-900 m-1 rounded border-4 border-gray-300 flex flex-col items-start justify-start text-gray-100 p-2'>
                {messageList &&
                    messageList.map((m) => {
                        return (
                            <div>{m.senderName} : {m.content}</div>
                        )
                    })
                }
            </div>
            <div className='fixed z-10 right-2 left-1/4 h-14 bottom-4 bg-transparent m-1 flex flex-col items-start justify-center p-2 px-4'>

                <input
                    type='text'
                    className="w-full bg-gray-100 h-12 px-2 py-1"
                    placeholder='Rédigez votre message...'
                    value={message}
                    onChange={(e) => setMessage(e.target.value)}
                    onKeyDown={handleEnterPress}
                />

            </div>
        </div>
    )
}

export default Messenger