const buildSoldProductsTableDataForInvoice = (ParamItems) => {

    let head = ['N°', 'Designation', 'P.U. H.T.', 'Quantité', 'Total T.T.C.'];

    if (AppData.PRODUCT_SPECIFIC_TVA)
        head = ['N°', 'Designation', 'P.U. H.T.', 'TVA', 'Quantité', 'Total T.T.C.'];

    let body = [];
    let c = 0;
    let total = 0;
    let totalHT = 0;
    let tvaTotals = {};

    const GROUPINGS_OF_THREE = true;

    const keys = Object.keys(ParamItems);
    for (const k of keys) {
        let tableLine = [];
        let p = ParamItems[k];
        let pTotal = p.price * p.amount * p.tvaModifier;

        c++;
        tableLine.push(c);

        tableLine.push(p.name);
        tableLine.push(StringToNumber_2DecAlways(p.price, false, GROUPINGS_OF_THREE));

        if (AppData.PRODUCT_SPECIFIC_TVA)
            tableLine.push(StringToNumber_2DecAlways(p.tva, false, GROUPINGS_OF_THREE));

        tableLine.push(p.amount + " " + (p.unit || "Pcs"));
        tableLine.push(StringToNumber_2DecAlways(pTotal, false, GROUPINGS_OF_THREE));
        body.push(tableLine);

        totalHT += (Number(p.amount) * Number(p.price));
        total += Number(pTotal);

        // Update TVA totals
        let tvaPercentage = StringToNumber_2DecAlways(p.tva, false, GROUPINGS_OF_THREE);
        let tvaAmount = Number(pTotal) * (1 - 1 / (1 + tvaPercentage / 100));
        tvaTotals[tvaPercentage] = (tvaTotals[tvaPercentage] || 0) + tvaAmount;
    }


    let result = { head: head, body: body, totalHT: totalHT, tvaTotals: tvaTotals, total: total };
    // console.log("RESULT = " + JSON.stringify(result));
    return result;
}

const buildSoldProductsTableDataForDeliveryNote = (ParamItems) => {

    let head = ['N°', 'Designation', 'Quantité', 'Unité'];

    let body = [];
    let c = 0;

    const keys = Object.keys(ParamItems);
    for (const k of keys) {
        let tableLine = [];
        let p = ParamItems[k];

        c++;
        tableLine.push(c);

        tableLine.push(p.name);
        tableLine.push(p.amount);
        tableLine.push((p.unit || "Pcs"));

        body.push(tableLine);
    }

    let result = { head: head, body: body };
    // console.log("RESULT = " + JSON.stringify(result));
    return result;
}

const buildTotalInfoDataForPDFA4 = (ParamTotal, ParamTotalHT, ParamTVAGroups, ParamPaymentMethod) => {

    let ddt = false;
    if (ParamPaymentMethod && ParamPaymentMethod === "CASH") {
        ddt = true;
    }

    const total = Number(ParamTotal);
    const totalHT = Number(ParamTotalHT);
    let body = [];
    body.push(["Total HT : " + StringToNumber_2DecAlways(totalHT, false, true)]);

    let TTC = total;
    if (!AppData.DISABLE_TVA) {

        if (AppData.PRODUCT_SPECIFIC_TVA) {
            // body.push(["TVA (Variable) : " + StringToNumber_2DecAlways(total - totalHT)]);
            for (const [key, value] of Object.entries(ParamTVAGroups)) {
                body.push(["TVA (" + key + "%) : " + StringToNumber_2DecAlways(value, false, true)]);
                // TTC += value;
            }
        } else {
            body.push(["TVA (19%) : " + StringToNumber_2DecAlways(total * 0.19, false, true)]);
            TTC += (total * 0.19);
        }
    }

    let DDTAmount = 0;
    if (ddt && !AppData.DISABLE_DDT) {
        DDTAmount = TTC * 0.01;

        if (DDTAmount > 10000)
            DDTAmount = 10000;

        if (DDTAmount < 5)
            DDTAmount = 5;

        body.push([""]);
        body.push(["DDT : " + StringToNumber_2DecAlways(DDTAmount, false, true)]);
        TTC += DDTAmount;
    }

    // const final = TTC;
    body.push(["Total TTC : " + StringToNumber_2DecAlways(TTC, false, true)]);

    let result = { body: body, total: TTC };
    return result;
}

const BuildPFInfoTable = (ParamProformaSettings) => {

    console.log("MARK 2");

    let body = [];

    // Delivery Date
    if (ParamProformaSettings.deliveryDate)
        body.push(["Date de Livraison : " + GetShortDateOf(new Date(ParamProformaSettings.deliveryDate))]);
    else if (ParamProformaSettings.deliveryMessage)
        body.push(["Validité de l'offre : " + ParamProformaSettings.deliveryMessage]);
    else
        body.push(["(Délai de livraison non spécifié)"]);

    // Offer validity
    body.push(["Validité de l'offre : " + ParamProformaSettings.offerValidity + " Jour(s)"]);

    // Observation
    if (ParamProformaSettings.observation)
        body.push(["Observation : " + ParamProformaSettings.observation]);

    return body;
}

function DrawWrappedText(ParamDoc, ParamText, ParamWidth, ParamFontSize, ParamX, ParamY, ParamTextAlign = 'left') {

    const LINE_HEIGHT = 1; // Assuming 100% line height

    const words = ParamText.split(' ');
    let currentLine = '';
    let lineCount = 0;
    let wrappedText = '';

    for (let i = 0; i < words.length; i++) {
        const word = words[i];

        if (currentLine !== '') {
            currentLine += ' ';
        }

        const testLine = currentLine + word;
        const lineWidth = ParamDoc.getTextWidth(testLine, ParamFontSize);

        if (lineWidth > ParamWidth) {
            wrappedText += currentLine.trim() + '\n';
            currentLine = word;
            // lineCount += fontSize * LINE_HEIGHT;
            lineCount += 1;
        } else {
            currentLine += word;
        }
    }

    // Add the last line
    wrappedText += currentLine.trim();

    // Calculate the height of the last line
    // lineCount += fontSize * LINE_HEIGHT;
    lineCount += 1;

    // Draw
    ParamDoc.text(wrappedText, ParamX, ParamY, ParamTextAlign);

    return { wrappedText, lineCount };
}

