import { React, useState, useEffect } from 'react';
import RknContainer from '../components/RknUI/RknContainer';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import Table from 'rc-table';

const TASManager = () => {

    const columns = [
        {
            title: "UID",
            dataIndex: 'UID',
            key: 'UID',
            width: 64,
            className: 'border border-gray-500'
        },
        {
            title: "Nom d'Utilisateur",
            dataIndex: 'name',
            key: 'name',
            width: 256,
            className: 'border border-gray-500'
        },
        {
            title: 'RFID',
            dataIndex: 'RFID',
            key: 'RFID',
            width: 256,
            className: 'border border-gray-500'
        }
    ];

    const [users, setUsers] = useState(null);
    const [tableData, setTableData] = useState(null);

    useEffect(() => {
        PerformGetRequest("/api/tas-user-list", (res) => {
            setUsers(res.data);
            console.log(JSON.stringify(res.data));
            let tmpTableData = [];
            for (const userKey of Object.keys(res.data)) {
                // console.log(JSON.stringify(res.data[userKey]));
                tmpTableData.push({ UID: res.data[userKey]["UID"], name: res.data[userKey]["Name"], UserID: res.data[userKey]["User ID"], RFID: res.data[userKey]["card"] });
            }
            setTableData(tmpTableData);
        });
    }, []);

    return (
        <div className='text-gray-100 flex flex-col items-center justify-center'>
            <h1 className='my-4 text-xl font-bold'>Utilisateurs de la Pointeuse</h1>
            {/* {tableData && <div>{JSON.stringify(tableData)}</div>} */}
            {tableData && <Table columns={columns} data={tableData} rowKey="UID" className='mx-4' />}
        </div>
    )
}

export default TASManager