import React, { useEffect, useState } from 'react';
import { GetBackEndUrl } from '../const';

const MenukManager = () => {

    const [realTimeData, setRealTimeData] = useState([]);

    useEffect(() => {

        const url = GetBackEndUrl();
        const eventSource = new EventSource(url + "/api/menuk-sync");

        eventSource.onmessage = (event) => {
            const newData = JSON.parse(event.data);
            // Append new data to the existing array
            setRealTimeData(prevData => [...prevData, newData]);
        };

        eventSource.onerror = (error) => {
            console.error("EventSource failed:", error);
            eventSource.close();
            // Handle reconnection attempts or inform the user about the failure
        };

        return () => {
            eventSource.close();
        };

    }, []);

    return (
        <div className='text-gray-100'>
            <br />
            <h1 className='text-3xl font-bold mt-4 mb-2'>Synchronisation de votre Menu</h1>
            <ul className='text-lg mb-4'>
                {realTimeData.map((item, index) => (
                    <li key={index}>{item.message}</li>
                ))}
            </ul>
        </div>
    );
}

export default MenukManager;