import React, { useState, useEffect } from 'react';
import RknNumericInput from '../components/RknUI/RknNumericInput';
import { PerformGetRequest, PerformGetRequest_Promise, PerformSecurePostRequest, PerformSecurePostRequestWithFormData } from '../Reaknotron/Libs/RknQueryTools';
import RknButton from '../components/RknUI/RknButton';
import { PulseLoader } from 'react-spinners';
import { useSearchParams, useNavigate } from 'react-router-dom';
import Table from 'rc-table';
import { FaCheckCircle, FaDownload, FaKey, FaMagic, FaPrint, FaSave } from 'react-icons/fa';
import { GenerateDischargeSheet } from '../Reaknotron/PDF/DischargeSheet';
import { GetPrinterName } from '../const';

function DischargeSheetEditor() {

    // Navigation
    const navigate = useNavigate();
    const [searchParams, setSearchParams] = useSearchParams();

    const [products, setProducts] = useState(null);
    const [totalOfProducts, setTotalOfProducts] = useState(0);
    const [estList, setEstList] = useState(null);
    const [estLabel, setEstLabel] = useState(null);
    const [selectedEstablishment, setSelectedEstablishment] = useState(null);
    const [isSaving, setIsSaving] = useState(false);
    const [changesAvailable, setChangesAvailable] = useState(false);
    const [errorMessage, setErrorMessage] = useState(null);
    const [targetID, setTargetID] = useState(null);
    const [finalized, setFinalized] = useState(false);

    const columns = [
        {
            title: 'Produit',
            dataIndex: 'productLabel',
            key: 'productLabel',
            className: 'border border-gray-500',
            width: 256
        },
        {
            title: 'Quantité de Base',
            dataIndex: 'baseAmount',
            key: 'baseAmount',
            className: 'border border-gray-500',
            width: 128
        },
        {
            title: 'Recharge',
            dataIndex: 'loadedAmount',
            key: 'loadedAmount',
            className: 'border border-gray-500',
            width: 128
        },
        {
            title: 'Quantité de Départ',
            dataIndex: 'departureAmount',
            key: 'departureAmount',
            className: 'border border-gray-500',
            width: 128
        },
        {
            title: 'Quantité Final (Retour)',
            dataIndex: 'finalAmount',
            key: 'finalAmount',
            className: 'border border-gray-500',
            width: 128
        },
        {
            title: 'Quantité Vendu',
            dataIndex: 'soldAmount',
            key: 'soldAmount',
            className: 'border border-gray-500',
            width: 128
        },
        {
            title: 'P.U.',
            dataIndex: 'price',
            key: 'price',
            className: 'border border-gray-500',
            width: 128
        },
        {
            title: 'Montant',
            dataIndex: 'total',
            key: 'total',
            className: 'border border-gray-500',
            width: 128
        }
    ];

    const GetAppropriatePrice = (ParamProduct, ParamCustomerDefaultPrice) => {

        if (ParamProduct.dynamicUnitPrice) {
            return ParamProduct.dynamicUnitPrice;
        }

        if (ParamCustomerDefaultPrice) {

            // if (ParamCustomerDefaultPrice == "HALF_WHOLESALE")
            //     return ParamProduct.halfWholesalePrice;
            if (ParamCustomerDefaultPrice == "WHOLESALE")
                return ParamProduct.wholesalePrice;
            else
                return ParamProduct.price;
        }

        return ParamProduct.price;
    }

    const RefreshProductList = (ParamCustomerDefaultPrice) => {

        PerformGetRequest("/api/get-product-list?resolveCategoryID=true&ignoreDeleted=true&sort=alpha", async (res) => {

            // console.log("RESULT = " + JSON.stringify(ParamResult.data));

            let productInfo = {};
            let tmpProducts = [];

            for (const p of res.data) {

                let foundProd = null;
                for (const pp of products) {
                    if (pp.id === p._id)
                        foundProd = pp;
                }

                let row;
                if (foundProd) {
                    let appropriatePrice = GetAppropriatePrice(p, ParamCustomerDefaultPrice);
                    row = {
                        id: p._id,
                        productLabel: p.name,
                        baseAmount: foundProd.baseAmount,
                        loadedAmount: foundProd.loadedAmount,
                        departureAmount: foundProd.departureAmount,
                        finalAmount: foundProd.finalAmount,
                        soldAmount: foundProd.soldAmount,
                        price: appropriatePrice,
                        total: foundProd.soldAmount * appropriatePrice
                    };
                } else {
                    row = {
                        id: p._id,
                        productLabel: p.name,
                        baseAmount: 0,
                        loadedAmount: 0,
                        departureAmount: 0,
                        finalAmount: 0,
                        soldAmount: 0,
                        price: GetAppropriatePrice(p, ParamCustomerDefaultPrice),
                        total: 0
                    };
                }
                tmpProducts.push(row);
            }
            setProducts(tmpProducts);
            setChangesAvailable(true);
            // console.log("P INFOS = " + JSON.stringify(productInfo));
        });
    }

    const InitNewDS = () => {
        PerformGetRequest("/api/get-product-list?resolveCategoryID=true&ignoreDeleted=true&sort=alpha", (res) => {
            if (res) {

                let tmpProducts = [];

                res.data.forEach(p => {
                    let row = { id: p._id, productLabel: p.name, baseAmount: 0, loadedAmount: 0, departureAmount: 0, finalAmount: 0, soldAmount: 0, price: p.wholesalePrice, total: 0 };
                    tmpProducts.push(row);
                });

                setProducts(tmpProducts);
                setTotalOfProducts(0);
            }
        });

        PerformGetRequest("/api/get-customer-list", (res) => {
            setEstList(res.data);
        });
    }

    const LoadDSFromDB = (ParamID) => {
        PerformGetRequest("/api/get-ds?id=" + ParamID, (res) => {

            // console.log("DS = " + JSON.stringify(res.data));

            setProducts(res.data.products);
            setTotalOfProducts(res.data.totalPrice);
            setFinalized(res.data.finalized);

            PerformGetRequest("/api/get-customer-list", (res_2) => {
                setEstList(res_2.data);
                // setSelectedEstablishment(res.data.establishmentID);
                const establishment = res_2.data.find(est => est._id === res.data.establishmentID);
                if (establishment) {
                    setSelectedEstablishment(establishment);
                }
            });

            PerformGetRequest("/api/get-customer?id=" + res.data.establishmentID, (res_3) => {
                setEstLabel(res_3.data.designation);
            });
        });
    }

    useEffect(() => {

        if (searchParams.get("id")) {
            LoadDSFromDB(searchParams.get("id"));
            setTargetID(searchParams.get("id"));
        }
        else {
            InitNewDS();
        }

    }, []);

    useEffect(() => {

        if (products) {
            let tmpTotal = 0;
            products.forEach(p => {
                // console.log("TOTAL EFFECT ITER : " + p.total);
                tmpTotal += p.total;
            });
            setTotalOfProducts(tmpTotal);
        }
    }, [products]);

    const handleBaseAmountChange = (id, value) => {

        // console.log("handleBaseAmountChange : " + id + " : " + value);

        setProducts(products.map(row =>
            row.id === id ? {
                ...row,
                baseAmount: value,
                departureAmount: Number(value) + Number(row.loadedAmount),
                soldAmount: Number(Number(value) + Number(row.loadedAmount)) - Number(row.finalAmount),
                total: Number(Number(Number(value) + Number(row.loadedAmount)) - Number(row.finalAmount)) * row.price
            } : row
        ));
        setChangesAvailable(true);
    };

    const handleLoadedAmountChange = (id, value) => {
        setProducts(products.map(row =>
            row.id === id ? {
                ...row,
                loadedAmount: value,
                departureAmount: Number(row.baseAmount) + Number(value),
                soldAmount: Number(Number(row.baseAmount) + Number(value)) - Number(row.finalAmount),
                total: Number(Number(Number(row.baseAmount) + Number(value)) - Number(row.finalAmount)) * row.price
            } : row
        ));
        setChangesAvailable(true);
    };

    const handleFinalAmountChange = (id, value) => {
        setProducts(products.map(row =>
            row.id === id ? {
                ...row,
                finalAmount: value,
                soldAmount: Number(row.departureAmount) - Number(value),
                total: Number(Number(row.departureAmount) - Number(value)) * row.price
            } : row
        ));
        setChangesAvailable(true);
    };

    const Save = (ParamFinalize) => {

        if (finalized || isSaving)
            return;

        setIsSaving(true);

        let dsToPost = { products: products, totalPrice: totalOfProducts, establishmentID: selectedEstablishment, finalized: ParamFinalize };

        if (targetID) {

            // Update
            dsToPost.id = targetID;
            PerformSecurePostRequest("/api/update-ds", dsToPost, async (res) => {

                if (res.data.code === "OK") {

                    setChangesAvailable(false);

                    // Finalize
                    if (ParamFinalize) {

                        let productsToPost = {};
                        let productsPresent = false;

                        for (const p of products) {

                            if (p.soldAmount <= 0)
                                continue;

                            const r = await PerformGetRequest_Promise("/api/get-product?id=" + p.id);

                            if (r.result) {
                                // console.log("R = " + JSON.stringify(r.response.data));
                                productsToPost[r.response.data._id] = r.response.data;
                                productsToPost[r.response.data._id].amount = p.soldAmount;
                                productsToPost[r.response.data._id].price = p.price;
                                productsPresent = true;
                            }
                        }

                        if (productsPresent) {

                            const saleToPost = {
                                products: productsToPost,
                                totalPrice: totalOfProducts,
                                establishmentID: selectedEstablishment,
                                finalized: false
                            }

                            PerformSecurePostRequest("/api/new-sale", saleToPost, (res) => {
                                setIsSaving(false);
                                setErrorMessage(null);

                                PerformGetRequest("/api/get-customer?id=" + selectedEstablishment._id, (res_2) => {
                                    setEstLabel(res_2.data.designation);
                                });

                                setFinalized(true);
                                window.open('/sales-point?id=' + res.data.id, '_blank');
                            });
                        } else {
                            setIsSaving(false);
                            setErrorMessage(null);
                        }

                    } else {

                        setIsSaving(false);
                        setErrorMessage(null);

                    }

                } else {
                    setIsSaving(false);
                    setErrorMessage("Impossible de sauvegarder la fiche de décharge");
                }

            });

        } else {

            // Save
            PerformSecurePostRequest("/api/new-ds", dsToPost, async (res) => {

                if (res.data.code === "OK") {

                    setTargetID(res.data.id);
                    setChangesAvailable(false);
                    navigate({ pathname: '/discharge-sheet-editor', search: `?id=${res.data.id}` });

                    // Finalize
                    if (ParamFinalize) {

                        let productsToPost = {};
                        let productsPresent = false;

                        for (const p of products) {

                            if (p.soldAmount <= 0)
                                continue;

                            const r = await PerformGetRequest_Promise("/api/get-product?id=" + p.id);

                            if (r.result) {
                                // console.log("R = " + JSON.stringify(r.response.data));
                                productsToPost[r.response.data._id] = r.response.data;
                                productsToPost[r.response.data._id].amount = p.soldAmount;
                                productsToPost[r.response.data._id].price = p.price;
                                productsPresent = true;
                            }
                        }

                        if (productsPresent) {
                            const saleToPost = {
                                products: productsToPost,
                                totalPrice: totalOfProducts,
                                establishmentID: selectedEstablishment,
                                finalized: false
                            }

                            PerformSecurePostRequest("/api/new-sale", saleToPost, (res) => {
                                setIsSaving(false);
                                setErrorMessage(null);

                                PerformGetRequest("/api/get-customer?id=" + selectedEstablishment._id, (res_2) => {
                                    setEstLabel(res_2.data.designation);
                                });

                                setFinalized(true);
                                window.open('/sales-point?id=' + res.data.id, '_blank');
                            });
                        } else {
                            setIsSaving(false);
                            setErrorMessage(null);
                        }


                    } else {

                        setIsSaving(false);
                        setErrorMessage(null);

                    }

                } else {
                    setIsSaving(false);
                    setErrorMessage("Impossible de sauvegarder la fiche de décharge");
                }

            });

        }

    }

    const unlock = () => {

        if (isSaving)
            return;

        setIsSaving(true);

        let dsToPost = { id: targetID };

        PerformSecurePostRequest("/api/unlock-ds", dsToPost, async (res) => {

            if (res.data.code === "OK") {
                setFinalized(false);
                setIsSaving(false);
            }
        })

    }

    const DownloadPDF = async () => {
        const doc = await GenerateDischargeSheet(estLabel, products, totalOfProducts, finalized);
        doc.save("Fiche de Décharge.pdf");
    }

    const PrintPDF = async () => {

        const doc = await GenerateDischargeSheet(estLabel, products, totalOfProducts, finalized);

        // Build form
        const formData = new FormData();
        formData.append("pdf", doc.output('blob'));

        PerformSecurePostRequestWithFormData("/printer/print?printer=" + GetPrinterName(), formData, (res) => {

        });
    }

    const handleGetLastDS = () => {
        if (!selectedEstablishment || !selectedEstablishment._id)
            return;

        PerformGetRequest("/api/get-last-ds?id=" + selectedEstablishment._id, (res) => {
            if (res.data && res.data.products) {
                let tmpFinalAmounts = {};
                res.data.products.forEach(p => {
                    tmpFinalAmounts[p.id] = p.finalAmount;
                });

                // Create a new array with updated products
                const updatedProducts = products.map(product => {
                    const finalAmount = tmpFinalAmounts[product.id];
                    return {
                        ...product,
                        baseAmount: finalAmount || 0,
                        departureAmount: Number(finalAmount || 0) + Number(product.loadedAmount),
                        soldAmount: Number(Number(finalAmount || 0) + Number(product.loadedAmount)) - Number(product.finalAmount),
                        total: Number(Number(Number(finalAmount || 0) + Number(product.loadedAmount)) - Number(product.finalAmount)) * product.price
                    };
                });

                setProducts(updatedProducts);
                setChangesAvailable(true);
            }
        });
    }

    const handleEstChange = (e) => {

        const tmpEst = estList.find(est => est._id === e.target.value);

        if (tmpEst) {
            setSelectedEstablishment(tmpEst);
            // console.log("CUSTOMER = " + JSON.stringify(tmpEst));
            RefreshProductList(tmpEst.defaultPrice);
        }
    }

    return (
        <div className='flex flex-col items-center justify-center text-gray-900 dark:text-gray-100'>
            <br />
            <h1 className='text-xl font-bold '>Fiche de Décharge</h1>
            <br />
            {estList && !finalized &&
                <div>

                    {/* Customer Selector */}
                    {estList &&
                        <select value={selectedEstablishment?._id || ''} onChange={handleEstChange} className="bg-gray-50 border border-gray-300 text-gray-900 text-xs rounded-lg focus:ring-blue-500 focus:border-blue-500 my-0 mx-2 py-1 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500" >
                            <option value="">Séléctionner un Client</option>
                            {estList.map(c => (
                                <option key={c._id} value={c._id}>{c.designation}</option>
                            ))}
                        </select>
                    }

                    {/* Last Stock */}
                    {selectedEstablishment &&
                        <div className='flex flex-row items-center justify-center text-gray-100 bg-gray-900 p-1 m-1 text-sm font-bold rounded cursor-pointer select-none active:scale-95 hover:bg-gray-500 transition duration-150' onClick={handleGetLastDS}>
                            <FaMagic className='mr-1' />
                            <div>Dernier Stock</div>
                        </div>
                    }

                </div>

            }
            {estLabel && finalized && <div>Client : {estLabel}</div>}
            <br />
            <br />
            {!finalized && <div className="w-full overflow-x-auto">
                <table className="w-full text-left border-collapse text-sm">
                    <thead>
                        <tr>
                            <th className="border pl-2 p-1">Produit</th>
                            <th className="border pl-2 p-1">Quantité de Base</th>
                            <th className="border pl-2 p-1">Recharge</th>
                            <th className="border pl-2 p-1">Quantité de Départ</th>
                            <th className="border pl-2 p-1">Quantité Final</th>
                            <th className="border pl-2 p-1">Quantité Vendue</th>
                            <th className="border pl-2 p-1">P.U.</th>
                            <th className="border pl-2 p-1">Montant</th>
                        </tr>
                    </thead>
                    <tbody>
                        {products && products.map(p => (
                            <tr key={p.id} className={(p.baseAmount > 0 || p.loadedAmount > 0 || p.finalAmount > 0) ? 'opacity-100' : 'opacity-40'}>
                                <td className="border pr-2 p-1">{p.productLabel}</td>
                                <td className="border pr-2 p-1"><RknNumericInput width="128px" value={p.baseAmount} onChange={(v) => handleBaseAmountChange(p.id, v)} /></td>
                                <td className="border pr-2 p-1"><RknNumericInput width="128px" value={p.loadedAmount} onChange={(v) => handleLoadedAmountChange(p.id, v)} /></td>
                                <td className="border pr-2 p-1">{p.departureAmount}</td>
                                <td className="border pr-2 p-1"><RknNumericInput width="128px" value={p.finalAmount} onChange={(v) => handleFinalAmountChange(p.id, v)} /></td>
                                <td className="border pr-2 p-1">{p.soldAmount}</td>
                                <td className="border pr-2 p-1">{p.price}</td>
                                <td className="border pr-2 p-1">{Number(p.soldAmount) * Number(p.price)}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>}

            {finalized && <Table className='text-gray-100 m-1' columns={columns} data={products} rowKey="id" />}

            <div className='mt-4 mb-20'>
                <div className='font-bold text-xl'>Total : {totalOfProducts} DA</div>
                <br />
                {errorMessage && <div className='font-bold text-red-500'>{errorMessage}</div>}
            </div>

            {/* Bottom Tool Bar */}
            <div className='fixed z-20 bottom-0 right-0 left-0 bg-gray-900 text-white h-16 border-t-2 border-gray-500 flex flex-row items-center justify-center space-x-2'>
                {/* {!errorMessage && !finalized && <RknButton className="w-40" label={isSaving ? <PulseLoader color='#AAAAAA' /> : "Enregistrer"} before={<FaSave />} onPress={() => Save(false)} />} */}
                {!errorMessage && !finalized && <RknButton className="w-40" label="Enregistrer" before={<FaSave />} onPress={() => Save(false)} disabled={!changesAvailable} busy={isSaving} />}
                {(totalOfProducts >= 0) && products && selectedEstablishment && !isSaving && !errorMessage && !finalized && <RknButton className="w-40" label={isSaving ? <PulseLoader color='#AAAAAA' /> : "Finalizer"} before={<FaCheckCircle />} onPress={() => Save(true)} />}
                {<RknButton className="w-44" label="Imprimer" before={<FaPrint />} onPress={PrintPDF} />}
                {<RknButton className="w-44" label="Télécharger" before={<FaDownload />} onPress={DownloadPDF} />}
                {finalized && !isSaving && targetID && <RknButton className="w-44" label="Déverrouiller" before={<FaKey />} onPress={unlock} />}
            </div>

        </div>
    );
}

export default DischargeSheetEditor;