import CashRegEditor from './pages/CashRegEditor.jsx';
import ReceptionByProductViewer from './pages/ReceptionByProductViewer.jsx';
import ProformaInvoiceManager from './pages/ProformaInvoiceManager.jsx';
import InvoiceManager from './pages/InvoiceManager.jsx';
import TransactionManager from './pages/TransactionManager.jsx';
import Pricing from './pages/Pricing.jsx';
import DeliveryNoteManager from './pages/DeliveryNoteManager.jsx';
import CounterManager from './pages/CounterManager.jsx';
import ReturnSlipEditor from './pages/ReturnSlipEditor.jsx';
import ReturnSlipManager from './pages/ReturnSlipManager.jsx';
import StockValue from './pages/StockValue.jsx';
import RknUiDemo from './pages/RknUiDemo.jsx';

function App() {

  const [showGlobalPopup, setShowGlobalPopup] = useState(false);
  const [globalPopupMessage, setGlobalPopupMessage] = useState("");

  useEffect(() => {

    console.log("Reaknotron Online !");

    // ==========================================================================

    var light = false;
    if (localStorage.getItem('color-theme'))
      if (localStorage.getItem('color-theme') == 'dark')
        light = false;
      else
        light = true;
    else
      light = false;

    if (light) {
      document.documentElement.classList.remove('dark');
    } else {
      document.documentElement.classList.remove('dark');
      document.documentElement.classList.add('dark');
    }

    // ==========================================================================

    function handleError(ParamEvent) {
      console.log("ERROR : " + JSON.stringify(ParamEvent));
    }

    window.addEventListener("error", handleError);

    // ==========================================================================
    const handleMessages = (event) => {
      // console.log('Received message:', event.data);
      // Optional: Send a response back
      // event.source.postMessage('Message received!', '*');

      const json = StringToJson(event.data);
      if (json)
        // console.log("MESSAGE JSON = " + JSON.stringify(json));
        console.log("MESSAGE CODE = " + json.code);

      if (json && json.code === "ERROR") {
        setShowGlobalPopup(true);
        setGlobalPopupMessage(json.message);
      }
    };

    window.addEventListener('message', handleMessages);
    // ==========================================================================

    return () => {
      window.removeEventListener("error", handleError);
      window.removeEventListener('message', handleMessages);
    }

  }, []);

  return (
    // <div className="App" handle={handle}>
    <div className="App">

      {/* <div className='fixed top-0 bottom-0 left-0 right-0 backdrop-saturate-150 backdrop-brightness-110 backdrop-contrast-125 -backdrop-hue-rotate-90' style={{ zIndex:60, pointerEvents: 'none' }}></div> */}
      {/* <div className='fixed top-0 bottom-0 left-0 right-0 backdrop-blur-sm' style={{ zIndex:60, pointerEvents: 'none' }}></div> */}

      {/* <div className='container'> */}
      <div className='mt-16' id='app-module-container'>
        <BrowserRouter>

          <NavBar />

          <Routes>

            {/* Main */}
            <Route path='/' element={<LoginForm />} />
            <Route path='/connexion-settings' element={<ConnexionSettings />} />
            <Route path='/dashboard' element={IsLoggedIn() ? <Dashboard /> : <PleaseLogin />} />
            <Route path='/dashboard/stats' element={IsLoggedIn() ? <Dashboard /> : <PleaseLogin />} />

            {/* Production */}
            {AppData.PRODUCTION_MANAGEMENT && <Route path='/production-manager' element={IsLoggedIn() ? <ProductionManager /> : <PleaseLogin />} />}
            <Route path='/production-cycle-editor' element={IsLoggedIn() ? <ProductionCycleEditor /> : <PleaseLogin />} />

            {/* Sales Point */}
            {AppData.SALES_POINT_FLAG && <Route path='/sales-point' element={IsLoggedIn() ? <SalesPoint /> : <PleaseLogin />} />}
            {AppData.SALES_POINT_FLAG && <Route path='/sales-list' element={IsLoggedIn() ? <SalesList /> : <PleaseLogin />} />}

            {/* Device Maintenance */}
            {AppData.DEVICE_MAINTENANCE_FLAG && <Route path='/add-repair-order' element={IsLoggedIn() ? <RepairOrderEditor /> : <PleaseLogin />} />}
            {AppData.DEVICE_MAINTENANCE_FLAG && <Route path='/repair-orders-list' element={IsLoggedIn() ? <RepairOrdersList /> : <PleaseLogin />} />}

            {/* Products */}
            {AppData.PRODUCT_MANAGEMENT_FLAG && <Route path='/product-editor' element={IsLoggedIn() ? <ProductEditor /> : <PleaseLogin />} />}
            {AppData.PRODUCT_MANAGEMENT_FLAG && <Route path='/product-list' element={IsLoggedIn() ? <ProductList /> : <PleaseLogin />} />}
            {AppData.PRODUCT_MANAGEMENT_FLAG && CheckPrivilege("STOCK_VALUE") && <Route path='/stock-value' element={IsLoggedIn() ? <StockValue /> : <PleaseLogin />} />}
            {AppData.PRODUCT_MANAGEMENT_FLAG && <Route path='/product-pack-manager' element={IsLoggedIn() ? <ProductPackManager /> : <PleaseLogin />} />}
            {AppData.PRODUCT_MANAGEMENT_FLAG && <Route path='/product-pack-editor' element={IsLoggedIn() ? <ProductPackEditor /> : <PleaseLogin />} />}
            {AppData.PRODUCT_MANAGEMENT_FLAG && <Route path='/batch-manager' element={IsLoggedIn() ? <BatchManager /> : <PleaseLogin />} />}
            {AppData.PRODUCT_MANAGEMENT_FLAG && <Route path='/discharged-inventory' element={IsLoggedIn() ? <DischargedInventory /> : <PleaseLogin />} />}
            {AppData.PRODUCT_MANAGEMENT_FLAG && <Route path='/inventory-movement' element={IsLoggedIn() ? <InventoryMovementViewer /> : <PleaseLogin />} />}
            {AppData.PRODUCT_MANAGEMENT_FLAG && <Route path='/inventory-movement-summary' element={IsLoggedIn() ? <InventoryMovementSummary /> : <PleaseLogin />} />}
            {AppData.PRODUCT_MANAGEMENT_FLAG && <Route path='/receptions-by-product' element={IsLoggedIn() ? <ReceptionByProductViewer /> : <PleaseLogin />} />}

            {/* Inventory Sheet */}
            {AppData.INVENTORY_SHEETS_FLAG && <Route path='/inventory-sheet-editor' element={IsLoggedIn() ? <InventoryMaker /> : <PleaseLogin />} />}
            {AppData.INVENTORY_SHEETS_FLAG && <Route path='/inventory-manager' element={IsLoggedIn() ? <InventoryManager /> : <PleaseLogin />} />}

            {/* Discharge Sheet */}
            {AppData.DISCHARGE_SHEETS_FLAG && <Route path='/discharge-sheet-manager' element={IsLoggedIn() ? <DischargeSheetManager /> : <PleaseLogin />} />}
            {AppData.DISCHARGE_SHEETS_FLAG && <Route path='/discharge-sheet-editor' element={IsLoggedIn() ? <DischargeSheetEditor /> : <PleaseLogin />} />}
            {AppData.DISCHARGE_SHEETS_FLAG && <Route path='/ds-domain-log' element={IsLoggedIn() ? <DsDomainLog /> : <PleaseLogin />} />}

            {/* Computer Specs */}
            {AppData.COMPUTER_SPECS_FLAG && <Route path='/computer-specs-manager' element={IsLoggedIn() ? <ComputerSpecsManager /> : <PleaseLogin />} />}

            {/* Categories */}
            {(AppData.PRODUCT_MANAGEMENT_FLAG || AppData.CUSTOMER_MANAGEMENT_FLAG || AppData.DDO) && <Route path='/category-manager' element={IsLoggedIn() ? <CategoryManager /> : <PleaseLogin />} />}

            {/* Providers */}
            {AppData.STORAGE_MANAGEMENT_FLAG && <Route path='/provider-list' element={IsLoggedIn() ? <ProviderList /> : <PleaseLogin />} />}
            {AppData.STORAGE_MANAGEMENT_FLAG && <Route path='/provider-editor' element={IsLoggedIn() ? <ProviderEditor /> : <PleaseLogin />} />}

            {/* Ad Screen */}
            {AppData.PRODUCT_MANAGEMENT_FLAG && AppData.SALES_POINT_FLAG && <Route path='/ad-screen' element={IsLoggedIn() ? <AdScreen /> : <PleaseLogin />} />}

            {/* Reception */}
            {AppData.PRODUCT_MANAGEMENT_FLAG && AppData.STORAGE_MANAGEMENT_FLAG && <Route path='/reception-list' element={IsLoggedIn() ? <ReceptionList /> : <PleaseLogin />} />}
            {AppData.PRODUCT_MANAGEMENT_FLAG && AppData.STORAGE_MANAGEMENT_FLAG && <Route path='/reception-editor' element={IsLoggedIn() ? <ReceptionEditor /> : <PleaseLogin />} />}

            {/* Return Slip */}
            {AppData.PRODUCT_MANAGEMENT_FLAG && AppData.STORAGE_MANAGEMENT_FLAG && <Route path='/return-slip-manager' element={IsLoggedIn() ? <ReturnSlipManager /> : <PleaseLogin />} />}
            {AppData.PRODUCT_MANAGEMENT_FLAG && AppData.STORAGE_MANAGEMENT_FLAG && <Route path='/return-slip-editor' element={IsLoggedIn() ? <ReturnSlipEditor /> : <PleaseLogin />} />}

            {/* Invoicing */}
            {AppData.INVOICING_FLAG && <Route path='/proforma-invoice-manager' element={IsLoggedIn() ? <ProformaInvoiceManager /> : <PleaseLogin />} />}
            {AppData.INVOICING_FLAG && <Route path='/delivery-note-manager' element={IsLoggedIn() ? <DeliveryNoteManager /> : <PleaseLogin />} />}
            {AppData.INVOICING_FLAG && <Route path='/invoice-manager' element={IsLoggedIn() ? <InvoiceManager /> : <PleaseLogin />} />}

            {AppData.CATERING_FLAG && <Route path='/catering-sales-point' element={IsLoggedIn() ? <CateringSalesPoint /> : <PleaseLogin />} />}
            {AppData.CATERING_FLAG && <Route path='/catering-sales-list' element={IsLoggedIn() ? <CateringSalesList /> : <PleaseLogin />} />}
            {AppData.CATERING_FLAG && <Route path='/cst-list' element={IsLoggedIn() ? <TableManager /> : <PleaseLogin />} />}

            {AppData.EMPLOYEE_MANAGEMENT_FLAG && <Route path='/employee-manager' element={IsLoggedIn() ? <EmployeeManager /> : <PleaseLogin />} />}
            {AppData.EMPLOYEE_MANAGEMENT_FLAG && <Route path='/employee-clocking-board' element={IsLoggedIn() ? <EmployeeClockingBoard /> : <PleaseLogin />} />}
            {AppData.EMPLOYEE_MANAGEMENT_FLAG && <Route path='/employee-editor' element={IsLoggedIn() ? <EmployeeEditor /> : <PleaseLogin />} />}
            {AppData.EMPLOYEE_MANAGEMENT_FLAG && <Route path='/tas-manager' element={IsLoggedIn() ? <TASManager /> : <PleaseLogin />} />}
            {AppData.EMPLOYEE_MANAGEMENT_FLAG && <Route path='/payslip-editor' element={IsLoggedIn() ? <PayslipEditor /> : <PleaseLogin />} />}

            {AppData.EMPLOYEE_MANAGEMENT_FLAG && <Route path='/pt-manager' element={IsLoggedIn() ? <PTManager /> : <PleaseLogin />} />}
            {AppData.EMPLOYEE_MANAGEMENT_FLAG && <Route path='/pt-editor' element={IsLoggedIn() ? <PTForm /> : <PleaseLogin />} />}

            {AppData.EMPLOYEE_MANAGEMENT_FLAG && <Route path='/absence-manager' element={IsLoggedIn() ? <AbsenceManager /> : <PleaseLogin />} />}
            {AppData.EMPLOYEE_MANAGEMENT_FLAG && <Route path='/absence-editor' element={IsLoggedIn() ? <AbsenceEditor /> : <PleaseLogin />} />}
            {AppData.EMPLOYEE_MANAGEMENT_FLAG && <Route path='/shift-manager' element={IsLoggedIn() ? <ShiftManager /> : <PleaseLogin />} />}

            {AppData.STUDENT_MANAGEMENT_FLAG && <Route path='/student-manager' element={IsLoggedIn() ? <StudentManager /> : <PleaseLogin />} />}
            {AppData.STUDENT_MANAGEMENT_FLAG && <Route path='/student-editor' element={IsLoggedIn() ? <StudentEditor /> : <PleaseLogin />} />}

            {AppData.FEE_MANAGEMENT_FLAG && <Route path='/fee-manager' element={IsLoggedIn() ? <FeeManager /> : <PleaseLogin />} />}

            {AppData.CUSTOMER_MANAGEMENT_FLAG && <Route path='/messenger' element={IsLoggedIn() ? <Messenger /> : <PleaseLogin />} />}
            {AppData.CUSTOMER_MANAGEMENT_FLAG && <Route path='/customer-manager' element={IsLoggedIn() ? <CustomerManager /> : <PleaseLogin />} />}
            {AppData.CUSTOMER_MANAGEMENT_FLAG && <Route path='/customer-editor' element={IsLoggedIn() ? <CustomerEditor /> : <PleaseLogin />} />}

            {AppData.SALES_POINT_FLAG && <Route path='/cash-reg-manager' element={IsLoggedIn() ? <CashRegManager /> : <PleaseLogin />} />}
            {AppData.SALES_POINT_FLAG && <Route path='/cash-reg-editor' element={IsLoggedIn() ? <CashRegEditor /> : <PleaseLogin />} />}

            {AppData.MAIL_CLIENT && <Route path='/mail-manager' element={IsLoggedIn() ? <MailManager /> : <PleaseLogin />} />}

            {AppData.SOKKIFY_FLAG && <Route path='/sokkify-manager' element={IsLoggedIn() ? <SokkifyManager /> : <PleaseLogin />} />}
            {AppData.MENUK_FLAG && <Route path='/menuk-manager' element={IsLoggedIn() ? <MenukManager /> : <PleaseLogin />} />}

            {/* Users */}
            <Route path='/user-manager' element={IsLoggedIn() ? <UserManager /> : <PleaseLogin />} />
            <Route path='/role-editor' element={IsLoggedIn() ? <UserRoleEditor /> : <PleaseLogin />} />

            <Route path='/establishment-editor' element={IsLoggedIn() ? <EstablishmentCustomizer /> : <PleaseLogin />} />
            <Route path='/establishment-manager' element={IsLoggedIn() ? <EstablishmentManager /> : <PleaseLogin />} />
            <Route path='/transaction-manager' element={IsLoggedIn() ? <TransactionManager /> : <PleaseLogin />} />

            <Route path='/statistics' element={IsLoggedIn() ? <Statistics /> : <PleaseLogin />} />
            <Route path='/config' element={IsLoggedIn() ? <Config /> : <PleaseLogin />} />

            {/* Database */}
            <Route path='/counter-manager' element={IsLoggedIn() ? <CounterManager /> : <PleaseLogin />} />
            <Route path='/db-manager' element={IsLoggedIn() ? <DatabaseManager /> : <PleaseLogin />} />
            <Route path='/archive' element={IsLoggedIn() ? <Archive /> : <PleaseLogin />} />

            <Route path='/menu' element={<CateringMenu />} />
            <Route path='/menu2' element={<AnimatedCateringMenu />} />

            <Route path='/feature-manager' element={<FeatureManager />} />

            <Route path='/mobile-pos' element={IsLoggedIn() ? <MobileSalesPoint /> : <PleaseLogin />} />

            {/* Direct Debit Orders */}
            <Route path='/ddo-manager' element={IsLoggedIn() ? <DDOManager /> : <PleaseLogin />} />
            <Route path='/ddo-editor' element={IsLoggedIn() ? <DDOEditor /> : <PleaseLogin />} />

            {/* Misc */}
            <Route path='/notifications' element={IsLoggedIn() ? <Notifications /> : <PleaseLogin />} />
            <Route path='/qty-import' element={IsLoggedIn() ? <AmountImportWizard /> : <PleaseLogin />} />
            <Route path='/pricing' element={IsLoggedIn() ? <Pricing /> : <PleaseLogin />} />
            <Route path='/rkn-ui-demo' element={<RknUiDemo />} />

          </Routes>
        </BrowserRouter>
      </div>

      {showGlobalPopup &&
        <motion.div className={'fixed z-40 top-0 bottom-0 right-0 left-0 bg-opacity-25 bg-red-600 backdrop-blur-xl flex flex-col items-center justify-center'}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.5 }}
        >
          <div className='w-5/6 h-4/6 border-2 border-gray-500 bg-gray-900 rounded-xl p-2 flex flex-col items-center justify-center font-bold text-gray-100'>
            {globalPopupMessage}
            <RknButton className="mt-4 w-24" label="OK" onPress={() => setShowGlobalPopup(false)} />
          </div>
        </motion.div>
      }

    </div>
  );
}

export default App;