import React from 'react';

const RknBottomToolbar = (props) => {
    return (
        <div className='fixed z-20 bottom-0 right-0 left-0 bg-gray-900 text-white h-16 border-t-2 border-gray-500 flex flex-row items-center justify-center space-x-1'>
            {props.children}
        </div>
    )
}

export default RknBottomToolbar