import React, { useState, useEffect } from 'react';
import { InputFieldStyle } from '../Styles';
import FileSelectAndDrop from '../components/FileSelectAndDrop';
import RknButton from '../components/RknUI/RknButton';
import { PerformGetRequest, PerformSecurePostRequest, PerformSecurePostRequestWithFormData } from '../Reaknotron/Libs/RknQueryTools';
import { Formik, Field, Form, ErrorMessage } from 'formik';
import * as Yup from 'yup';
import RknSubmitButton from '../components/RknUI/RknSubmitButton';
import { useNavigate, useSearchParams } from 'react-router-dom';
import RknNumericInput from '../components/RknUI/RknNumericInput';
import RknContainer from '../components/RknUI/RknContainer';
import RknSmartSelector from '../components/RknUI/RknSmartSelector';

const EstablishmentCustomizer = () => {

    const navigate = useNavigate();
    const [searchParams, setSearchParams] = useSearchParams();

    const [targetID, setTargetID] = useState();
    const [type, setType] = useState('NATURAL');

    useEffect(() => {
        if (searchParams.get("id")) {
            setTargetID(searchParams.get("id"));

            if (searchParams.get("id") === "self") {
                GetSelfFromDb();
            } else {
                LoadEstablishmentFromDb(searchParams.get("id"));
            }
        }
        else {
            setTargetID(null);
            setLoaded(true);
        }
    }, []);

    const validationSchema = Yup.object({
        socialReason: Yup.string()
            .matches("^[A-Za-z0-9éèçà.,\\s-]+$", 'Seules les lettres, les chiffres et les tirets sont autorisés'),
        commercialDesignation: Yup.string()
            .matches("^[A-Za-z0-9éèçà.,\\s-]+$", 'Seules les lettres, les chiffres et les tirets sont autorisés'),
        activity: Yup.string()
            .matches("^[A-Za-z0-9éèçà.,()\\s-]+$", 'Seules les lettres, les chiffres, les tirets et les virgules sont autorisés'),
        address: Yup.string()
            .matches("^[A-Za-z0-9éèçà.,°\\s-]+$", 'Seules les lettres, les chiffres, les tirets et les virgules sont autorisés'),
        phoneNumber: Yup.string()
            .matches(/^\+?\d+(\s\d+)*$/, 'Doit commencer par un signe plus suivi de chiffres'),
        commercialRegisterNumber: Yup.string()
            .matches(/^[\d\/\-\sA-Za-z]+$/, 'Seules les lettres, les chiffres, les tirets et les barres obliques sont autorisés'),
        taxationArticle: Yup.number()
            .integer("L'article d'imposition doit être un nombre entier")
            .positive("L'article d'imposition doit être positif"),
        fiscalIdentificationNumber: Yup.number()
            .integer('Le numéro d\'identification fiscale doit être un nombre entier')
            .positive('Le numéro d\'identification fiscale doit être positif'),
        statisticalIdentificationNumber: Yup.number()
            .integer('Le numéro d\'identification statistique doit être un nombre entier')
            .positive('Le numéro d\'identification statistique doit être positif'),
        bankName: Yup.string()
            .matches("^[A-Za-z0-9éèçà.,\\s-]+$", 'Seules les lettres, les chiffres et les tirets sont autorisés'),
        bankAccountNumber: Yup.number()
            .integer('Le numéro de compte bancaire doit être un nombre entier')
            .positive('Le numéro de compte bancaire doit être positif'),
        firstName: Yup.string()
            .matches("^[A-Za-zéèçà-]+$", 'Seules les lettres et les tirets sont autorisés'),
        lastName: Yup.string()
            .matches("^[A-Za-zéèçà-]+$", 'Seules les lettres et les tirets sont autorisés'),
        eMail: Yup.string()
            .email('Adresse e-mail invalide'),
        shareCapital: Yup.string()
            .matches("^[0-9\\s]+[A-Za-z\\p{Sc}]+$", 'Seuls les espaces et les chiffres suivis de caractères et de symboles monétaires sont autorisés')
    });

    const [designation, setDesignation] = useState("");
    const [changesAvailable, setChangesAvailable] = useState(false);
    const [saving, setIsSaving] = useState(false);

    const [establishmentData, setEstablishmentData] = useState({
        firstName: '',
        lastName: '',
        socialReason: '',
        commercialDesignation: '',
        activity: '',
        address: '',
        phoneNumber: '',
        commercialRegisterNumber: '',
        taxationArticle: '',
        fiscalIdentificationNumber: '',
        statisticalIdentificationNumber: '',
        bankName: '',
        bankAccountNumber: '',
        isCustomer: false,
        defaultPrice: "RETAIL",
        isProvider: false,
        salePaymentGracePeriod: 30,
        receptionPaymentGracePeriod: 30,
        eMail: '',
        shareCapital: '',
        category: null
    });

    const [loaded, setLoaded] = useState(false);

    const [selectedImageFile, setSelectedImageFile] = useState("");
    const [imageURL, setImageURL] = useState();
    const [imageAvailable, setImageAvailable] = useState(false);

    // useEffect(() => {
    //     console.log("EST DATA : " + JSON.stringify(establishmentData));
    // }, [establishmentData]);

    const handleImageSelect = (event) => {
        setSelectedImageFile(event.target.files[0]);
        setImageURL(URL.createObjectURL(event.target.files[0]));
        setImageAvailable(true);
        // setChangesAvailable(true);

        // setIsSaving(true);

        // Build form
        const formData = new FormData();
        formData.append("picture", event.target.files[0]);

        PerformSecurePostRequestWithFormData("/api/update-self-logo", formData, (res) => {
            // setChangesAvailable(false);
            // setIsSaving(false);
            // setImageURL(await PerformImageGetRequest("/api/get-product-image?id=" + targetID));
            console.log("DONE");
        });
    }

    const handleImageClear = () => {
        setSelectedImageFile("");
        setImageAvailable(false);
        setChangesAvailable(true);
    }

    const [selectedBlackLogoFile, setSelectedBlackLogoFile] = useState("");
    const [blackLogoURL, setBlackLogoURL] = useState();
    const [blackLogoAvailable, setBlackLogoAvailable] = useState(false);

    const handleBlackLogoSelect = (event) => {
        setSelectedBlackLogoFile(event.target.files[0]);
        setBlackLogoURL(URL.createObjectURL(event.target.files[0]));
        setBlackLogoAvailable(true);
        // setChangesAvailable(true);

        // setIsSaving(true);

        // Build form
        const formData = new FormData();
        formData.append("picture", event.target.files[0]);
        formData.append("version", "black");

        PerformSecurePostRequestWithFormData("/api/update-self-logo", formData, (res) => {
            // setChangesAvailable(false);
            // setIsSaving(false);
            // setImageURL(await PerformImageGetRequest("/api/get-product-image?id=" + targetID));
            console.log("DONE");
        });
    }

    const handleBlackLogoClear = () => {
        setSelectedBlackLogoFile("");
        setBlackLogoAvailable(false);
        setChangesAvailable(true);
    }

    // useEffect(() => {
    //     GetSelfFromDb();
    // }, []);

    const handleDefaultPriceChange = (e) => {
        // console.log("V = " + e.target.value);
        setEstablishmentData({ ...establishmentData, defaultPrice: e.target.value });
        setChangesAvailable(true);
    }

    const GetSelfFromDb = () => {
        PerformGetRequest("/api/get-self-establishment", (res) => {
            // console.log("SELF = " + JSON.stringify(res.data));
            setDesignation(res.data.designation);
            setEstablishmentData(res.data);
            setType(res.data.type);
            setLoaded(true);
        });
    }

    const LoadEstablishmentFromDb = (ParamID) => {
        PerformGetRequest("/api/get-establishment?id=" + ParamID, (res) => {
            // console.log("EST = " + JSON.stringify(res.data));
            setDesignation(res.data.designation);
            setEstablishmentData(res.data);
            setType(res.data.type);
            setLoaded(true);
        });
    }

    const UpdateSelfInDB = async (ParamValues) => {

        // console.log("DESIGNATION = " + designation);
        // console.log("VALUES = " + JSON.stringify(ParamValues));
        // return;

        setIsSaving(true);

        // Build form
        let estToPost = {};
        estToPost.designation = designation;
        estToPost.firstName = ParamValues.firstName;
        estToPost.lastName = ParamValues.lastName;
        estToPost.socialReason = ParamValues.socialReason;
        estToPost.commercialDesignation = ParamValues.commercialDesignation;
        estToPost.activity = ParamValues.activity;
        estToPost.address = ParamValues.address;
        estToPost.phoneNumber = ParamValues.phoneNumber;
        estToPost.commercialRegisterNumber = ParamValues.commercialRegisterNumber;
        estToPost.taxationArticle = ParamValues.taxationArticle;
        estToPost.fiscalIdentificationNumber = ParamValues.fiscalIdentificationNumber;
        estToPost.statisticalIdentificationNumber = ParamValues.statisticalIdentificationNumber;
        estToPost.bankName = ParamValues.bankName;
        estToPost.bankAccountNumber = ParamValues.bankAccountNumber;
        estToPost.isCustomer = ParamValues.isCustomer;
        estToPost.defaultPrice = ParamValues.defaultPrice;
        estToPost.isProvider = ParamValues.isProvider;
        estToPost.salePaymentGracePeriod = ParamValues.salePaymentGracePeriod;
        estToPost.receptionPaymentGracePeriod = ParamValues.receptionPaymentGracePeriod;
        estToPost.type = ParamValues.type;
        estToPost.eMail = ParamValues.eMail;
        estToPost.shareCapital = ParamValues.shareCapital;
        estToPost.category = ParamValues.category;

        PerformSecurePostRequest("/api/update-self-establishment", estToPost, (res) => {
            setChangesAvailable(false);
            setIsSaving(false);
            // setImageURL(await PerformImageGetRequest("/api/get-product-image?id=" + targetID));
        });
    }

    const UpdateTargetInDB = async (ParamValues) => {

        // console.log("DESIGNATION = " + designation);
        // console.log("VALUES = " + JSON.stringify(ParamValues));
        // return;

        setIsSaving(true);

        // Build form
        let estToPost = {};
        estToPost.id = targetID;
        estToPost.designation = designation;
        estToPost.firstName = ParamValues.firstName;
        estToPost.lastName = ParamValues.lastName;
        estToPost.socialReason = ParamValues.socialReason;
        estToPost.commercialDesignation = ParamValues.commercialDesignation;
        estToPost.activity = ParamValues.activity;
        estToPost.address = ParamValues.address;
        estToPost.phoneNumber = ParamValues.phoneNumber;
        estToPost.commercialRegisterNumber = ParamValues.commercialRegisterNumber;
        estToPost.taxationArticle = ParamValues.taxationArticle;
        estToPost.fiscalIdentificationNumber = ParamValues.fiscalIdentificationNumber;
        estToPost.statisticalIdentificationNumber = ParamValues.statisticalIdentificationNumber;
        estToPost.bankName = ParamValues.bankName;
        estToPost.bankAccountNumber = ParamValues.bankAccountNumber;
        estToPost.isCustomer = ParamValues.isCustomer;
        estToPost.defaultPrice = ParamValues.defaultPrice;
        estToPost.isProvider = ParamValues.isProvider;
        estToPost.salePaymentGracePeriod = ParamValues.salePaymentGracePeriod;
        estToPost.receptionPaymentGracePeriod = ParamValues.receptionPaymentGracePeriod;
        estToPost.type = ParamValues.type;
        estToPost.eMail = ParamValues.eMail;
        estToPost.shareCapital = ParamValues.shareCapital;
        estToPost.category = ParamValues.category;

        PerformSecurePostRequest("/api/update-establishment", estToPost, (res) => {
            setChangesAvailable(false);
            setIsSaving(false);
            // setImageURL(await PerformImageGetRequest("/api/get-product-image?id=" + targetID));
        });
    }

    const SaveNewEstablishmentInDB = async (ParamValues) => {

        // console.log("DESIGNATION = " + designation);
        // console.log("VALUES = " + JSON.stringify(ParamValues));
        // return;

        setIsSaving(true);

        // Build form
        let estToPost = {};
        estToPost.designation = designation;
        estToPost.firstName = ParamValues.firstName;
        estToPost.lastName = ParamValues.lastName;
        estToPost.socialReason = ParamValues.socialReason;
        estToPost.commercialDesignation = ParamValues.commercialDesignation;
        estToPost.activity = ParamValues.activity;
        estToPost.address = ParamValues.address;
        estToPost.phoneNumber = ParamValues.phoneNumber;
        estToPost.commercialRegisterNumber = ParamValues.commercialRegisterNumber;
        estToPost.taxationArticle = ParamValues.taxationArticle;
        estToPost.fiscalIdentificationNumber = ParamValues.fiscalIdentificationNumber;
        estToPost.statisticalIdentificationNumber = ParamValues.statisticalIdentificationNumber;
        estToPost.bankName = ParamValues.bankName;
        estToPost.bankAccountNumber = ParamValues.bankAccountNumber;
        estToPost.isCustomer = ParamValues.isCustomer;
        estToPost.defaultPrice = ParamValues.defaultPrice;
        estToPost.isProvider = ParamValues.isProvider;
        estToPost.salePaymentGracePeriod = ParamValues.salePaymentGracePeriod;
        estToPost.receptionPaymentGracePeriod = ParamValues.receptionPaymentGracePeriod;
        estToPost.type = ParamValues.type;
        estToPost.eMail = ParamValues.eMail;
        estToPost.shareCapital = ParamValues.shareCapital;
        estToPost.category = ParamValues.category;

        PerformSecurePostRequest("/api/new-establishment", estToPost, (res) => {
            setChangesAvailable(false);
            setIsSaving(false);
            navigate('/establishment-editor?id=' + res.data.id);
            setTargetID(res.data.id);
            // setImageURL(await PerformImageGetRequest("/api/get-product-image?id=" + targetID));
        });
    }

    const handleSaveOnClick = (ParamValues) => {

        // console.log("Param Values = " + JSON.stringify(ParamValues));

        let valuesToPost = { ...ParamValues };
        valuesToPost.isCustomer = establishmentData.isCustomer;
        valuesToPost.defaultPrice = establishmentData.defaultPrice;
        valuesToPost.isProvider = establishmentData.isProvider;
        valuesToPost.salePaymentGracePeriod = establishmentData.salePaymentGracePeriod;
        valuesToPost.receptionPaymentGracePeriod = establishmentData.receptionPaymentGracePeriod;
        valuesToPost.type = type;
        valuesToPost.category = establishmentData.category;

        // console.log("TARGET = " + targetID);

        if (targetID === "self")
            UpdateSelfInDB(valuesToPost);
        else if (targetID)
            UpdateTargetInDB(valuesToPost);
        else
            SaveNewEstablishmentInDB(valuesToPost);
    }

    const CustomErrorMessage = ({ children }) => <div className='text-xs font-bold text-red-500'>Invalid</div>;

    const handleIsCustomerChange = () => {
        setEstablishmentData({
            ...establishmentData,
            isCustomer: !establishmentData.isCustomer
        });
        setChangesAvailable(true);
    };

    const handleIsProviderChange = () => {
        setEstablishmentData({
            ...establishmentData,
            isProvider: !establishmentData.isProvider
        });
        setChangesAvailable(true);
    };

    const handleSaleGracePeriodChange = (v) => {
        const updatedData = { ...establishmentData, salePaymentGracePeriod: v };
        setEstablishmentData(updatedData);
        setChangesAvailable(true);
    }

    const handleReceptionGracePeriodChange = (v) => {
        const updatedData = { ...establishmentData, receptionPaymentGracePeriod: v };
        setEstablishmentData(updatedData);
        setChangesAvailable(true);
    }

    const handleTypeChange = (event) => {
        setType(event.target.value);
        setChangesAvailable(true);
    };

    const handleCategoryChange = (c) => {
        console.log("c = " + JSON.stringify(c));
        const updatedData = { ...establishmentData, category: c._id };
        setEstablishmentData(updatedData);
        setChangesAvailable(true);
    }

    return (
        <div className='flex flex-col items-center text-neutral-900 dark:text-gray-100'>
            <h1 className='font-bold text-xl my-4'>Personnalisation de l'établissement {targetID}</h1>

            <RknContainer title="Identification" className="flex flex-col items-center justify-center">

                <label className='mb-0 mt-2 text-sm font-medium'>Désignation</label>
                <input type='text' name='designation' value={designation} onChange={(e) => { setDesignation(e.target.value); setChangesAvailable(true); }} className={InputFieldStyle} />

                <label className='text-sm mt-4 mb-1'>Type</label>
                <select
                    name="state"
                    className="py-1 mx-4 mb-6 text-sm text-gray-900 border border-gray-300 rounded-lg bg-gray-50 focus:ring-blue-500 focus:border-blue-500 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500"
                    defaultValue="NATURAL"
                    onChange={handleTypeChange}
                    value={type}
                >
                    <option value="NATURAL">🙂  Naturel</option>
                    <option value="LEGAL">🏛  Legal</option>
                </select>

                {/* <RknSmartSelector url={"/api/get-category-list"} idKey="_id" value={category} labelKey="name" reaktorContext="CATEGORY" onChange={handleCategoryChange} quickAddRoute="/category-manager" /> */}
                <label className='text-sm mt-4 mb-1'>Catégorie</label>
                <RknSmartSelector url={"/api/ec-list"} idKey="_id" value={establishmentData.category} labelKey="name" reaktorContext="EC" onChange={handleCategoryChange} />

                <label className='mt-4 mb-2 text-gray-100 text-xl font-bold'>
                    <input
                        type="checkbox"
                        checked={establishmentData.isCustomer}
                        onChange={handleIsCustomerChange}
                        className='mx-1 mt-4 mb-0 w-4 h-4' />
                    Client
                </label>
                {establishmentData.isCustomer && <div className='flex flex-col items-center justify-center bg-gray-800 p-4 rounded-xl w-72'>
                    <RknNumericInput label="Délai de paiement (Vente)" name="salePaymentGracePeriod" value={establishmentData.salePaymentGracePeriod} onChange={handleSaleGracePeriodChange} />
                    <label className="text-sm text-gray-900 dark:text-white mt-2">Prix par Défaut</label>
                    <select name="state" className={InputFieldStyle} value={establishmentData.defaultPrice} onChange={handleDefaultPriceChange}>
                        <option value="RETAIL">Détail</option>
                        <option value="HALF_WHOLESALE">Demi-Gros</option>
                        <option value="WHOLESALE">Gros</option>
                    </select>
                </div>}

                <label className='mt-4 mb-2 text-gray-100 text-xl font-bold'>
                    <input
                        type="checkbox"
                        checked={establishmentData.isProvider}
                        onChange={handleIsProviderChange}
                        className='mx-1 mt-4 mb-0 w-4 h-4' />
                    Fournisseur
                </label>
                {establishmentData.isProvider && <RknNumericInput label="Délai de paiement (Réception)" name="receptionPaymentGracePeriod" value={establishmentData.receptionPaymentGracePeriod} onChange={handleReceptionGracePeriodChange} />}

            </RknContainer>

            <RknContainer className='flex flex-row items-center justify-center p-4 space-x-4' title="Identité Visuelle">
                {/* Image */}
                <div className='flex flex-col items-center justify-center'>
                    <label className="mb-1 text-sm font-medium">Image</label>
                    {!imageAvailable && <FileSelectAndDrop name="picture" onChange={handleImageSelect} />}
                    {imageAvailable && <img src={imageURL} alt="preview" className="object-cover h-64 w-64 m-auto border-2 border-gray-300 rounded-2xl" />}
                    {imageAvailable && <div className='text-xl text-gray-500 font-bold border-2 border-gray-500 rounded-2xl w-64 m-auto mt-1 hover:bg-gray-500 hover:text-gray-100' onClick={handleImageClear}>X</div>}
                </div>

                {/* Black Logo */}
                <div className='flex flex-col items-center justify-center'>
                    <label className="mb-1 text-sm font-medium">Logo Noir sur Blanc</label>
                    {!blackLogoAvailable && <FileSelectAndDrop name="blackLogo" onChange={handleBlackLogoSelect} />}
                    {blackLogoAvailable && <img src={blackLogoURL} alt="preview" className="object-cover h-64 w-64 m-auto border-2 border-gray-300 rounded-2xl" />}
                    {blackLogoAvailable && <div className='text-xl text-gray-500 font-bold border-2 border-gray-500 rounded-2xl w-64 m-auto mt-1 hover:bg-gray-500 hover:text-gray-100' onClick={handleBlackLogoClear}>X</div>}
                </div>
            </RknContainer>

            {loaded &&
                <Formik
                    initialValues={establishmentData}
                    validationSchema={validationSchema}
                    onSubmit={handleSaveOnClick} // TODO : Can the submit button correctly replace this ?
                >
                    {({ isSubmitting }) => (
                        <Form className='flex flex-col items-center justify-center' onChange={setChangesAvailable}>

                            {type === "NATURAL" && <RknContainer title="Informations Individuelle">
                                <div className='flex flex-col mx-2'>
                                    <label className='font-bold text-sm' htmlFor="firstName">Prénom</label>
                                    <Field className={InputFieldStyle} id="firstName" name="firstName" type="text" />
                                    <ErrorMessage name="firstName" component={CustomErrorMessage} />
                                    <span className='my-4' />
                                </div>

                                <div className='flex flex-col mx-2'>
                                    <label className='font-bold text-sm' htmlFor="lastName">Nom</label>
                                    <Field className={InputFieldStyle} id="lastName" name="lastName" type="text" />
                                    <ErrorMessage name="lastName" component={CustomErrorMessage} />
                                    <span className='my-4' />
                                </div>
                            </RknContainer>}

                            {type === "LEGAL" && <RknContainer title="Informations Légale">
                                <div className='flex flex-col items-center justify-center md:grid md:grid-cols-2 lg:grid-cols-3'>
                                    <div className='flex flex-col mx-2'>
                                        <label className='font-bold text-sm' htmlFor="socialReason">Raison Sociale</label>
                                        <Field className={InputFieldStyle} id="socialReason" name="socialReason" type="text" />
                                        <ErrorMessage name="socialReason" component={CustomErrorMessage} />
                                        <span className='my-4' />
                                    </div>

                                    <div className='flex flex-col mx-2'>
                                        <label className='font-bold text-sm' htmlFor="commercialDesignation">Dénomination Commerciale</label>
                                        <Field className={InputFieldStyle} id="commercialDesignation" name="commercialDesignation" type="text" />
                                        <ErrorMessage name="commercialDesignation" component={CustomErrorMessage} />
                                        <span className='my-4' />
                                    </div>

                                    <div className='flex flex-col mx-2'>
                                        <label className='font-bold text-sm' htmlFor="activity">Activité</label>
                                        <Field className={InputFieldStyle} id="activity" name="activity" type="text" />
                                        <ErrorMessage name="activity" component={CustomErrorMessage} />
                                        <span className='my-4' />
                                    </div>

                                    <div className='flex flex-col mx-2'>
                                        <label className='font-bold text-sm' htmlFor="address">Adresse</label>
                                        <Field className={InputFieldStyle} id="address" name="address" type="text" />
                                        <ErrorMessage name="address" component={CustomErrorMessage} />
                                        <span className='my-4' />
                                    </div>

                                    <div className='flex flex-col mx-2'>
                                        <label className='font-bold text-sm' htmlFor="phoneNumber">Numéro de Téléphone</label>
                                        <Field className={InputFieldStyle} id="phoneNumber" name="phoneNumber" type="tel" />
                                        <ErrorMessage name="phoneNumber" component={CustomErrorMessage} />
                                        <span className='my-4' />
                                    </div>

                                    <div className='flex flex-col mx-2'>
                                        <label className='font-bold text-sm' htmlFor="eMail">eMail</label>
                                        <Field className={InputFieldStyle} id="eMail" name="eMail" type="mail" />
                                        <ErrorMessage name="eMail" component={CustomErrorMessage} />
                                        <span className='my-4' />
                                    </div>

                                    <div className='flex flex-col mx-2'>
                                        <label className='font-bold text-sm' htmlFor="commercialRegisterNumber">Numéro de Registre Commercial</label>
                                        <Field className={InputFieldStyle} id="commercialRegisterNumber" name="commercialRegisterNumber" type="text" />
                                        <ErrorMessage name="commercialRegisterNumber" component={CustomErrorMessage} />
                                        <span className='my-4' />
                                    </div>

                                    <div className='flex flex-col mx-2'>
                                        <label className='font-bold text-sm' htmlFor="taxationArticle">N° Article d'Imposition</label>
                                        <Field className={InputFieldStyle} id="taxationArticle" name="taxationArticle" type="text" />
                                        <ErrorMessage name="taxationArticle" component={CustomErrorMessage} />
                                        <span className='my-4' />
                                    </div>

                                    <div className='flex flex-col mx-2'>
                                        <label className='font-bold text-sm' htmlFor="fiscalIdentificationNumber">Numéro d'Identification Fiscale</label>
                                        <Field className={InputFieldStyle} id="fiscalIdentificationNumber" name="fiscalIdentificationNumber" type="text" />
                                        <ErrorMessage name="fiscalIdentificationNumber" component={CustomErrorMessage} />
                                        <span className='my-4' />
                                    </div>

                                    <div className='flex flex-col mx-2'>
                                        <label className='font-bold text-sm' htmlFor="statisticalIdentificationNumber">Numéro d'Identification Statistique</label>
                                        <Field className={InputFieldStyle} id="statisticalIdentificationNumber" name="statisticalIdentificationNumber" type="text" />
                                        <ErrorMessage name="statisticalIdentificationNumber" component={CustomErrorMessage} />
                                        <span className='my-4' />
                                    </div>

                                    <div className='flex flex-col mx-2'>
                                        <label className='font-bold text-sm' htmlFor="bankName">Nom de la Banque</label>
                                        <Field className={InputFieldStyle} id="bankName" name="bankName" type="text" />
                                        <ErrorMessage name="bankName" component={CustomErrorMessage} />
                                        <span className='my-4' />
                                    </div>

                                    <div className='flex flex-col mx-2'>
                                        <label className='font-bold text-sm' htmlFor="bankAccountNumber">Numéro de Compte Bancaire</label>
                                        <Field className={InputFieldStyle} id="bankAccountNumber" name="bankAccountNumber" type="text" />
                                        <ErrorMessage name="bankAccountNumber" component={CustomErrorMessage} />
                                        <span className='my-4' />
                                    </div>

                                    <div className='flex flex-col mx-2'>
                                        <label className='font-bold text-sm' htmlFor="shareCapital">Capital Social</label>
                                        <Field className={InputFieldStyle} id="shareCapital" name="shareCapital" type="text" />
                                        <ErrorMessage name="shareCapital" component={CustomErrorMessage} />
                                        <span className='my-4' />
                                    </div>
                                </div>
                            </RknContainer>}

                            {saving ? <div>Saving...</div> : <RknSubmitButton label="Enregistrer" disabled={!changesAvailable} className="w-48 my-4" />}
                        </Form>
                    )}
                </Formik>
            }

        </div>
    )
}

export default EstablishmentCustomizer