import { React, useState, useEffect } from 'react';
import { PerformGetRequest, PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import RknSubmitButton from '../components/RknUI/RknSubmitButton';
import { MapContainer, TileLayer, useMap } from 'react-leaflet'
import { Marker } from 'react-leaflet';
import { Popup } from 'react-leaflet';
import { useSearchParams } from 'react-router-dom';
import RknNumericInput from '../components/RknUI/RknNumericInput';

const inputFieldStyle = 'bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500 mt-2';

const CustomerEditor = () => {

    const [searchParams, setSearchParams] = useSearchParams();

    const GetCustomerFromDB = (ParamID) => {
        PerformGetRequest("/api/get-customer?id=" + ParamID, (res) => {
            setCustomerInfo({
                firstName: res.data.firstName,
                familyName: res.data.familyName,
                category: res.data.defaultPrice,
                establishmentID: res.data.establishmentID,
                nif: res.data.nif,
                paymentGracePeriod: res.data.paymentGracePeriod
            });
        });
    };

    useEffect(() => {

        if (searchParams.get("id")) {
            GetCustomerFromDB(searchParams.get("id"));
            setTargetID(searchParams.get("id"));
        }

        PerformGetRequest("/api/get-customer-category-list", (res) => setCategories(res.data));

    }, []);

    const [customerInfo, setCustomerInfo] = useState({ firstName: "", familyName: "", category: "NULL", defaultPrice: "RETAIL", establishmentID: null, nif: "", paymentGracePeriod: 30 });
    const [changesAvailable, setChangesAvailable] = useState(false);
    const [categories, setCategories] = useState([]);
    const [autoEntrepreneur, setAutoEntrepreneur] = useState(false);
    const [targetID, setTargetID] = useState(null);

    const handleChange = ({ currentTarget: input }) => {
        setCustomerInfo({ ...customerInfo, [input.name]: input.value });
        // console.log("C = " + JSON.stringify(customerInfo));
        setChangesAvailable(true);
    }

    const handleGracePeriodChange = (v) => {
        setCustomerInfo({ ...customerInfo, paymentGracePeriod: v });
        setChangesAvailable(true);
    }

    const SaveNewCustomerToDB = () => {
        let customerInfoToPost = customerInfo;
        customerInfoToPost.autoEntrepreneur = autoEntrepreneur;

        PerformSecurePostRequest("/api/new-customer", customerInfoToPost, (res) => {
            setTargetID(res.data.id);
            setChangesAvailable(false);
        });
    }

    const UpdateCustomerInDB = () => {
        let customerInfoToPost = customerInfo;
        customerInfo.id = targetID;
        customerInfoToPost.autoEntrepreneur = autoEntrepreneur;

        PerformSecurePostRequest("/api/update-customer", customerInfoToPost, (res) => {
            setChangesAvailable(false);
        });
    }

    const OnSubmit = async (event) => {

        event.preventDefault();

        if (targetID) {
            UpdateCustomerInDB();
        } else {
            SaveNewCustomerToDB();
        }

    }

    const handleDefaultPriceChange = (e) => {
        // console.log("V = " + e.target.value);
        setCustomerInfo({ ...customerInfo, defaultPrice: e.target.value });
    }

    const handleAutoEntrepreneurChange = () => {
        setAutoEntrepreneur(!autoEntrepreneur);
        setChangesAvailable(true);
    };

    return (
        <div>
            <br />
            <h3 className='text-gray-100 font-bold text-xl'>Ajouter un nouveau client</h3>
            <br />
            <form onSubmit={OnSubmit} className='flex flex-col items-center'>
                <div>
                    <input type="text" name="firstName" className={inputFieldStyle} placeholder="Prénom du client..." value={customerInfo.firstName} onChange={handleChange} required />
                </div>
                <br />
                <div>
                    <input type="text" name="familyName" className={inputFieldStyle} placeholder="Nom du client..." value={customerInfo.familyName} onChange={handleChange} />
                </div>

                <br />

                <label className="block text-sm font-medium text-gray-900 dark:text-white">Catégorie</label>
                <select name="category" className={inputFieldStyle} value={customerInfo.category} onChange={handleChange}>
                    <option value="NULL" defaultValue>Aucune</option>
                    {categories.map((cat, index) => (
                        <option key={index} value={cat._id}>
                            {cat.name}
                        </option>
                    ))}
                </select>
                <span className='block mb-6' />

                <label className="block text-sm font-medium text-gray-900 dark:text-white">Prix par Défaut</label>
                <select name="state" className={inputFieldStyle} defaultValue="RETAIL" onChange={handleDefaultPriceChange}>
                    <option value="RETAIL">Détail</option>
                    <option value="HALF_WHOLESALE">Demi-Gros</option>
                    <option value="WHOLESALE">Gros</option>
                </select>
                <span className='block mb-6' />

                <RknNumericInput label="Délai de paiement" name="paymentGracePeriod" value={customerInfo.paymentGracePeriod} onChange={handleGracePeriodChange} />

                {/* TODO : Remove since AE are establishments */}
                <label className='mb-4 text-gray-100 text-xl font-bold hidden'>
                    <input
                        type="checkbox"
                        checked={autoEntrepreneur}
                        onChange={handleAutoEntrepreneurChange}
                        className='mx-1 mt-4 mb-0 w-4 h-4' />
                    {/* Auto Entrepreneur */}
                    Auto Entrepreneur
                </label>

                {autoEntrepreneur &&
                    <div className='mb-4'>
                        <input type="text" name="nif" className={inputFieldStyle} placeholder="NIF..." value={customerInfo.nif} onChange={handleChange} />
                    </div>
                }

                {/* <MapContainer center={[51.505, -0.09]} zoom={13} scrollWheelZoom={false} className='border-2 border-red-600'>
                    <TileLayer
                        attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
                        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                    />
                    <Marker position={[51.505, -0.09]}>
                        <Popup>
                            A pretty CSS3 popup. <br /> Easily customizable.
                        </Popup>
                    </Marker>
                </MapContainer> */}

                {changesAvailable && <RknSubmitButton label="Enregistrer" />}
            </form>
        </div>
    )
}

export default CustomerEditor