// Deprecated (Replace with RknButton : type={props.submit ? 'submit' : 'button'})
import React from 'react';

const RknSubmitButton = (props) => {

  const handleOnPress = (ParamEvent) => {
    if (props.disabled) {
      // Do Nothing
    } else {
      if (props.onPress)
        props.onPress(ParamEvent);
    }
  }

  return (
    <div className={props.className ? props.className : ''}>
      <button
        type="submit"
        className={`w-full border-b-4 ${props.disabled ? "border-neutral-700 hover:border-neutral-500 bg-neutral-400 hover:bg-neutral-400 text-neutral-500" : "border-blue-700 hover:border-blue-500 bg-blue-500 hover:bg-blue-400 text-gray-100"} font-bold py-2 px-4 rounded my-1 flex flex-row items-center justify-center transition duration-150 active:translate-y-0.5 h-full`}
        onClick={handleOnPress}
      >
        {props.before && <div className='mr-2 pt-1'>{props.before}</div>}
        {props.responsive ? <div className='hidden sm:block'>{props.label ? props.label : "???"}</div> : <div>{props.label ? props.label : "???"}</div>}
      </button>
    </div>
  )
}

export default RknSubmitButton