import { React, useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { FaTimesCircle, FaCheckCircle, FaEdit } from 'react-icons/fa';
import RknDateInput from './RknUI/RknDateInput';
import RknNumericInput from './RknUI/RknNumericInput';

import { useTranslation } from 'react-i18next';
import RknButton from './RknUI/RknButton';
import RknPaymentSelector from './RknUI/RknPaymentSelector';
import { InputFieldStyle } from '../Styles';

const GenerateProformaInvoicePopup = (props) => {

    const { t } = useTranslation();

    // const probeRef = useRef(null);

    useEffect(() => {
        // setTimeout(() => { probeRef.current.focus(); }, 400);
    }, []);

    const [date, setDate] = useState(null);
    const [ref, setRef] = useState("");
    const [deliveryDate, setDeliveryDate] = useState(null);
    const [deliveryEditMode, setDeliveryEditMode] = useState(false);
    const [selectedPaymentMethod, setSelectedPaymentMethod] = useState('CASH');
    const [offerValidity, setOfferValidity] = useState(null);
    const [observation, setObservation] = useState(null);
    const [busy, setBusy] = useState(false);

    const TriggerPropsOnConfirm = () => {
        if (props.onConfirm)
            props.onConfirm(date, ref, deliveryDate, selectedPaymentMethod, offerValidity, observation);
    }

    const OnSubmit = (e) => {
        setBusy(true);
        e.preventDefault();
        TriggerPropsOnConfirm();
    }

    const TriggerPropsOnCancel = () => {
        if (props.onCancel)
            props.onCancel();
    }

    // const handlePaymentMethodChange = (event) => {
    //     setSelectedPaymentMethod(event.target.value);
    // };

    const handlePaymentMethodChange = (ParamValue) => {
        setSelectedPaymentMethod(ParamValue);
    };

    const handleDelivryMessageChange = (e) => {
        setDeliveryDate(e.target.value);
        console.log("Delivery Message = " + deliveryDate);
    }

    return (
        <motion.div
            className='fixed top-0 left-0 right-0 z-10 flex flex-col items-center justify-center w-screen h-screen bg-black bg-opacity-60 backdrop-blur-lg'
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.3 }}
        >
            <motion.div
                className='flex flex-col items-center justify-center p-8 m-auto text-gray-100 bg-gray-900 border-4 border-gray-500 rounded-3xl w-96'
                initial={{ opacity: 0, y: "-50%" }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.3 }}
            >
                <h3 className='mb-4 text-xl font-bold text-gray-100'>{t("pos.toolbar.quote.generateProformaInvoice")}</h3>

                <form onSubmit={OnSubmit} className='flex flex-col items-center justify-center w-80'>

                    <label className='text-sm'>Date :</label>
                    <RknDateInput onChange={setDate} />

                    <label className='mt-4 text-sm'>Référence :</label>
                    <RknNumericInput value={ref} onChange={(v) => setRef(v)} placeholder="Référence..." />

                    <label className='mt-4 text-sm'>{t("pos.toolbar.quote.deliveryDate")} :</label>
                    <div className='flex flex-row items-center justify-center'>
                        {deliveryEditMode ? <input type='text' value={deliveryDate} onChange={handleDelivryMessageChange} className={InputFieldStyle + " w-64"} /> : <RknDateInput onChange={setDeliveryDate} />}
                        {/* Edit Button */}
                        <div
                            className='h-10 w-10 pt-2 pl-0.5 ml-1 mt-1 bg-gray-900 border border-gray-500 rounded-lg hover:bg-gray-500 active:scale-90 transition duration-150 flex flex-col items-center justify-start cursor-pointer'
                            onClick={() => setDeliveryEditMode(!deliveryEditMode)}
                        >
                            <FaEdit size={20} />
                        </div>
                    </div>

                    <span className='my-1' />
                    <RknPaymentSelector onChange={handlePaymentMethodChange} />
                    <span className='my-1' />

                    <label className='mt-4 text-sm'>{t("pos.toolbar.quote.offerValidity")} :</label>
                    <RknNumericInput value={offerValidity} onChange={(v) => setOfferValidity(v)} placeholder={`${t('pos.toolbar.quote.offerValidity')}...`} unit="Jour(s)" />

                    <label className='mt-4 text-sm'>Observation :</label>
                    <input type='text' className={InputFieldStyle} value={observation} onChange={(e) => setObservation(e.target.value)} placeholder="Observation..." />

                    <div className='flex flex-row items-center justify-center mt-4'>
                        <RknButton label={t("button.confirm")} before={<FaCheckCircle className='inline mb-1' size={20} />} submit busy={busy} />
                        <span className='mx-2'></span>
                        <button type='button' onClick={TriggerPropsOnCancel} className="px-4 py-2 font-bold text-white bg-blue-500 border-b-4 border-blue-700 rounded hover:bg-blue-400 hover:border-blue-500"><FaTimesCircle className='inline mb-1' size={20} />  {t("button.cancel")}</button>
                    </div>


                </form>
                <br />

            </motion.div>
        </motion.div>
    )
}

export default GenerateProformaInvoicePopup