import { React, useState, useEffect } from 'react';
import RknInputDialog from '../components/RknUI/RknInputDialog';
import Table from 'rc-table';
import { PerformGetRequest, PerformImageGetRequest, PerformSecurePostRequest, PerformSecurePostRequestWithFormData } from '../Reaknotron/Libs/RknQueryTools';
import RknButton from '../components/RknUI/RknButton';
import { FaEdit, FaFileAudio, FaPlus, FaQuestion, FaTag, FaTools } from 'react-icons/fa';
import RknCategoryEditorPopup from '../components/RknCategoryEditorPopup';
import AppData from '../App.json';
import RknImageUploadPopup from '../components/RknUI/RknImageUploadPopup';
import RknFileUploadPopup from '../components/RknUI/RknFileUploadPopup';

const CategoryManager = () => {

    useEffect(() => {
        PerformGetRequest("/api/get-category-list", (ParamRes) => { setProductCategories(ParamRes.data) });

        if (AppData.CUSTOMER_MANAGEMENT_FLAG)
            PerformGetRequest("/api/get-customer-category-list", (ParamRes) => { setCustomerCategories(ParamRes.data) });

        if (AppData.DDO)
            PerformGetRequest("/api/ddo-category-list", (ParamRes) => { setDDOCategories(ParamRes.data) });

    }, []);

    const customer_columns = [
        {
            title: <FaTools size={20} className='p-1 m-1' />,
            key: 'action',
            width: 32,
            className: 'border border-gray-500',
            render: i => GenerateOperationButtons_Customer(i)
        },
        {
            title: "Icon",
            dataIndex: 'icon',
            key: 'icon',
            width: 64,
            className: 'border border-gray-500',
            render: i => <div className='flex flex-row items-center justify-center'>{i ? i : <FaTag />}</div>
        },
        {
            title: "Designation",
            dataIndex: 'name',
            key: 'name',
            width: 320,
            className: 'border border-gray-500'
        }
    ];

    const ddo_columns = [
        // {
        //     title: <FaTools size={20} className='p-1 m-1' />,
        //     key: 'action',
        //     width: 32,
        //     className: 'border border-gray-500',
        //     render: i => GenerateOperationButtons_Customer(i)
        // },
        {
            title: "Icon",
            dataIndex: 'icon',
            key: 'icon',
            width: 64,
            className: 'border border-gray-500',
            render: i => <div className='flex flex-row items-center justify-center'>{i ? i : <FaTag />}</div>
        },
        {
            title: "Designation",
            dataIndex: 'name',
            key: 'name',
            width: 320,
            className: 'border border-gray-500'
        }
    ];

    // const product_columns = [
    //     {
    //         title: <FaTools size={20} className='p-1 m-1' />,
    //         key: 'action',
    //         width: 32,
    //         className: 'border border-gray-500',
    //         render: i => GenerateOperationButtons_Product(i)
    //     },
    //     {
    //         title: "Icon",
    //         dataIndex: 'icon',
    //         key: 'icon',
    //         width: 64,
    //         className: 'border border-gray-500',
    //         render: i => <div className='flex flex-row items-center justify-center'>{i ? i : <FaTag />}</div>
    //     },
    //     {
    //         title: "Designation",
    //         dataIndex: 'name',
    //         key: 'name',
    //         width: 320,
    //         className: 'border border-gray-500'
    //     }
    // ];

    const [productCategories, setProductCategories] = useState(null);
    const [customerCategories, setCustomerCategories] = useState(null);
    const [ddoCategories, setDDOCategories] = useState(null);

    const [popupDefaultValue, setPopupDefaultValue] = useState(null);
    const [addProductCategoryWindowOpen, setAddProductCategoryWindowOpen] = useState(false);
    const [addCustomerCategoryWindowOpen, setAddCustomerCategoryWindowOpen] = useState(false);
    const [addDDOCategoryWindowOpen, setAddDDOCategoryWindowOpen] = useState(false);

    const [targetImgUploadID, setTargetImgUploadID] = useState(null);
    const [updateTopViewSubjectImagePopupOpen, setUpdateTopViewSubjectImagePopupOpen] = useState(false);
    const [uploadAudioPopupOpen, setUploadAudioPopupOpen] = useState(false);

    const AddNewCustomerCategoryOnConfirm = async (ParamResult) => {

        if (ParamResult.id) {
            PerformSecurePostRequest("/api/update-customer-category", { id: ParamResult.id, name: ParamResult.name, icon: ParamResult.emoji }, () => {
                setAddCustomerCategoryWindowOpen(false);
                PerformGetRequest("/api/get-customer-category-list", (ParamRes) => { setCustomerCategories(ParamRes.data) });
            });
        } else {
            PerformSecurePostRequest("/api/new-customer-category", { name: ParamResult.name, icon: ParamResult.emoji }, () => {
                setAddCustomerCategoryWindowOpen(false);
                PerformGetRequest("/api/get-customer-category-list", (ParamRes) => { setCustomerCategories(ParamRes.data) });
            });
        }

    }

    const AddNewProductCategoryOnConfirm = async (ParamResult) => {

        if (ParamResult.id) {
            PerformSecurePostRequest("/api/update-category", { id: ParamResult.id, name: ParamResult.name, icon: ParamResult.emoji, priceTiers: ParamResult.priceTiers }, () => {
                setAddProductCategoryWindowOpen(false);
                PerformGetRequest("/api/get-category-list", (ParamRes) => { setProductCategories(ParamRes.data) });
            });
        } else {
            PerformSecurePostRequest("/api/new-category", { name: ParamResult.name, icon: ParamResult.emoji, priceTiers: ParamResult.priceTiers }, () => {
                setAddProductCategoryWindowOpen(false);
                PerformGetRequest("/api/get-category-list", (ParamRes) => { setProductCategories(ParamRes.data) });
            });
        }
    }

    const GenerateOperationButtons_Customer = (ParamItem) => {

        const buttonStyle = 'bg-gray-900 text-gray-100 rounded-lg p-1 m-0.5 text-sm hover:bg-gray-700 inline';

        if (ParamItem) {
            return (
                <div className='flex flex-row'>
                    <button className={buttonStyle} onClick={() => { setPopupDefaultValue(ParamItem); setAddCustomerCategoryWindowOpen(true); }} > <FaEdit size={16} /> </button>
                    {/* <button className={buttonStyle} onClick={() => { console.log("DELETE"); DeleteProductInDB(ParamItem.id) }}> <FaTrash size={20} /> </button> */}
                </div>
            )
        }

        return "N/A";
    }

    const GenerateOperationButtons_Product = (ParamItem) => {

        const buttonStyle = 'bg-gray-900 text-gray-100 rounded-lg p-1 m-0.5 text-sm hover:bg-gray-700 inline';

        if (ParamItem) {
            return (
                <div className='flex flex-row'>
                    <button className={buttonStyle} onClick={() => { setPopupDefaultValue(ParamItem); setAddProductCategoryWindowOpen(true); }} > <FaEdit size={16} /> </button>
                    {/* <button className={buttonStyle} onClick={() => { console.log("DELETE"); DeleteProductInDB(ParamItem.id) }}> <FaTrash size={20} /> </button> */}
                </div>
            )
        }

        return "N/A";
    }

    const handleTVSimgUploadOnConfirm = (ParamID, ParamFile) => {

        // let post = { id: ParamID, picture: ParamFile };

        const formData = new FormData();
        formData.append("id", ParamID);
        formData.append("picture", ParamFile);

        PerformSecurePostRequestWithFormData("/api/update-category-tvsimg", formData, (res) => {
            setUpdateTopViewSubjectImagePopupOpen(false);
        });
    }

    const handleUploadAudioOnConfirm = (ParamID, ParamFile) => {

        // let post = { id: ParamID, picture: ParamFile };

        console.log(ParamFile);

        const formData = new FormData();
        formData.append("id", ParamID);
        formData.append("audio", ParamFile);

        PerformSecurePostRequestWithFormData("/api/update-category-audio", formData, (res) => {
            setUploadAudioPopupOpen(false);
        });
    }

    return (
        <div className='mt-24 text-gray-100'>

            {/* Customer Categories */}
            {
                false &&
                <div className='border-2 border-gray-500 rounded-lg p-2 m-4 flex flex-col items-center justify-center'>
                    <h3 className='text-xl text-gray-100 font-bold mb-2'>Catégories des Clients</h3>
                    <br />
                    <RknButton label="Ajouter une catégorie de clients" before={<FaPlus />} onPress={() => { setPopupDefaultValue(null); setAddCustomerCategoryWindowOpen(true) }} />
                    <br />
                    {customerCategories && <Table columns={customer_columns} data={customerCategories} rowKey="_id" className='mx-4' />}
                    <br />
                </div>
            }

            {/* Product Categories */}
            {AppData.PRODUCT_MANAGEMENT_FLAG && <div className='border-2 border-gray-500 rounded-lg p-2 m-4 flex flex-col items-center justify-center'>
                <h3 className='text-xl text-gray-100 font-bold mb-2'>Catégories des Produits</h3>
                <br />
                <RknButton label="Ajouter une catégorie de produits" before={<FaPlus />} onPress={() => { setPopupDefaultValue(null); setAddProductCategoryWindowOpen(true) }} />
                <br />
                {/* {productCategories && <Table columns={product_columns} data={productCategories} rowKey="_id" className='mx-4' />} */}
                {productCategories && productCategories.map((c, i) => {
                    return (
                        <div key={i} className='bg-transparent rounded-xl p-2 m-1 flex flex-row items-center justify-center h-48 w-full'>
                            <div className='border-l-2 border-y-2 border-cyan-700 w-1/6 p-2 h-44 bg-gray-800 hover:bg-gray-600 transition duration-300 cursor-pointer select-none rounded-xl flex flex-col items-center justify-center text-3xl font-bold' onClick={() => { setPopupDefaultValue(c); setAddProductCategoryWindowOpen(true); }} >
                                <div className='mb-2'>{c.icon}</div>
                                <div>{c.name}</div>
                            </div>
                            <div className='border-r-2 border-y-2 border-cyan-700 w-5/6 p-2 h-44 bg-gray-800 rounded-xl flex flex-col items-center justify-center'>
                                <div className='h-20 bg-gray-700 w-full rounded-xl m-0.5 flex flex-col items-center justify-center text-sm font-bold text-gray-400 border-2 border-dashed border-gray-500 cursor-pointer hover:bg-gray-500 transition duration-300 active:scale-95 select-none'>Bannière</div>
                                <div className='relative h-32 bg-gray-700 w-full rounded-xl m-0.5 flex flex-col items-center justify-center text-sm font-bold text-gray-400 border-2 border-dashed border-gray-500 cursor-pointer hover:bg-gray-500 transition duration-300 active:scale-95 select-none' onClick={() => { console.log("BG"); }}>
                                    Arrière Plan

                                    <div className='absolute bottom-2 right-2 h-16 w-16 bg-gray-600 rounded-xl border-4 border-dashed border-gray-500 text-xs flex flex-col items-center justify-center cursor-pointer hover:bg-gray-900 transition duration-300 active:scale-95 select-none' onClick={(e) => { e.stopPropagation(); setTargetImgUploadID(c._id); setUpdateTopViewSubjectImagePopupOpen(true); }}>
                                        Vue de Haut
                                    </div>

                                    <div className='absolute bottom-2 right-20 h-16 w-16 bg-gray-600 rounded-xl border-4 border-dashed border-gray-500 text-xs flex flex-col items-center justify-center cursor-pointer hover:bg-gray-900 transition duration-300 active:scale-95 select-none' onClick={(e) => { e.stopPropagation(); setTargetImgUploadID(c._id); setUploadAudioPopupOpen(true); }}>
                                        <FaFileAudio size={32} />
                                    </div>

                                </div>
                            </div>
                        </div>
                    )
                })}
            </div>}


            {/* DDO Categories */}
            {
                AppData.DDO &&
                <div className='border-2 border-gray-500 rounded-lg p-2 m-4 flex flex-col items-center justify-center'>
                    <h3 className='text-xl text-gray-100 font-bold mb-2'>Catégories des Ordres de Virement</h3>
                    <br />
                    <RknButton label="Ajouter une catégorie d'Ordre de Virement" before={<FaPlus />} onPress={() => { setPopupDefaultValue(null); setAddDDOCategoryWindowOpen(true); }} />
                    <br />
                    {ddoCategories && <Table columns={ddo_columns} data={ddoCategories} rowKey="_id" className='mx-4' />}
                    <br />
                </div>
            }

            {/* Windows */}
            <RknCategoryEditorPopup
                isOpen={addCustomerCategoryWindowOpen}
                onClose={() => setAddCustomerCategoryWindowOpen(false)}
                onConfirm={AddNewCustomerCategoryOnConfirm}
                defaultValue={popupDefaultValue}
            />

            <RknCategoryEditorPopup
                isOpen={addProductCategoryWindowOpen}
                onClose={() => setAddProductCategoryWindowOpen(false)}
                onConfirm={AddNewProductCategoryOnConfirm}
                defaultValue={popupDefaultValue}
            />

            <RknImageUploadPopup
                isOpen={updateTopViewSubjectImagePopupOpen}
                onClose={() => setUpdateTopViewSubjectImagePopupOpen(false)}
                onConfirm={(ParamFile) => { handleTVSimgUploadOnConfirm(targetImgUploadID, ParamFile); }}
                defaultValue={null}
            />

            <RknFileUploadPopup
                isOpen={uploadAudioPopupOpen}
                onClose={() => setUploadAudioPopupOpen(false)}
                onConfirm={(ParamFile) => { handleUploadAudioOnConfirm(targetImgUploadID, ParamFile); }}
                defaultValue={null}
                fileLabel="Audio"
                fileType="audio/*"
            />

        </div>
    )
}

export default CategoryManager