import autoTable from 'jspdf-autotable';
import { StringToNumber_2DecAtMost, StringToNumber_2DecAlways } from '../Libs/RknStringTools';
const AppData = require('../../App.json');
const { GetShortDate, TimeStampToDMY, GetDateTimeDMYHM, GetShortDateOf, ConvertMsToHMS } = require('../Libs/RknTimeTools');
const jspdf = require('jspdf');

const BuildAppointmentsTableData = (ParamItems) => {

    var head = ['Date & Heure', 'Action', 'Date & Heure', 'Action'];

    let body = [];

    let flipFlop = false;

    let tableLine = [];
    for (const item of ParamItems) {

        let action = "?";
        if (item.type === "ENTRY")
            action = "Entrée";
        else if (item.type === "EXIT")
            action = "Sortie";

        tableLine.push(GetDateTimeDMYHM(item.time));
        tableLine.push(action);

        if (flipFlop) {
            body.push(tableLine);
            tableLine = [];
        }

        flipFlop = !flipFlop;

    }

    let result = { head: head, body: body };
    return result;
}

const BuildShiftsTableData = (ParamItems) => {

    var head = ['Début', 'Fin', 'Durée'];

    let body = [];
    let total = 0;
    
    for (const item of ParamItems) {
        
        let tableLine = [];
        tableLine.push(GetDateTimeDMYHM(item.start));
        tableLine.push(GetDateTimeDMYHM(item.end));
        tableLine.push(ConvertMsToHMS(item.duration));

        total += item.duration;
        body.push(tableLine);

    }

    let result = { head: head, body: body, total: total };
    return result;
}

export async function GenerateAttendanceReport(ParamEmployeeLabel, ParamItemsList, ParamShiftList, ParamStart, ParamEnd) {

    var receiptWidth = 210;

    const doc = new jspdf.jsPDF('p', 'mm', [270, receiptWidth]); // Portrait, Milimeter, Height, Width
    var cursorY = 16;

    // Title
    let title = "Rapport des Shifts et Pointages";
    let titleFontSize = 28;

    // Title
    doc.setFont(undefined, 'bold');
    doc.setTextColor(0, 0, 0);
    doc.setFontSize(titleFontSize);
    doc.text(title, 5, cursorY, 'left');
    cursorY += 8;
    
    // Generation Date
    doc.setFont(undefined, 'normal');
    doc.setFontSize(10);
    doc.text("Générer le : " + GetShortDate(), 5.1, cursorY, 'left');
    cursorY += 5;
    
    // Date Range
    doc.text("Période du : " + GetShortDateOf(ParamStart) + " au " + GetShortDateOf(ParamEnd), 5.1, cursorY, 'left');
    cursorY += 5;
    
    // Employee
    doc.text("Employé : " + ParamEmployeeLabel, 5.1, cursorY, 'left');
    cursorY += 9;
    
    // Total
    doc.setFont(undefined, 'bold');
    doc.text("Total des Pointage : " + ParamItemsList.length, 6, cursorY, 'left');
    cursorY += 1.5;
    
    // Attendance table
    const tableData = BuildAppointmentsTableData(ParamItemsList);
    
    let cellTextFontSize = 6;
    autoTable(doc, {
        head: [tableData.head],
        body: tableData.body,
        startY: cursorY,
        margin: 6,
        theme: 'grid',
        tableWidth: receiptWidth - 12,
        styles: {
            fontSize: cellTextFontSize,
            cellPadding: 0.5,
            fontStyle: 'normal',
            textColor: 'black',
            lineWidth: 0.15,
            lineColor: [72, 72, 72]
        },
        headStyles: { fillColor: [0, 0, 0], textColor: [255, 255, 255] },
        didDrawPage: (d) => { cursorY = d.cursor.y }
    });
    cursorY += 9;
    
    // Shift table
    const shiftsTableData = BuildShiftsTableData(ParamShiftList);
    // Total
    doc.setFont(undefined, 'bold');
    doc.text("Durée total des Shifts : " + ConvertMsToHMS(shiftsTableData.total), 6, cursorY, 'left');
    cursorY += 1.5;
    
    autoTable(doc, {
        head: [shiftsTableData.head],
        body: shiftsTableData.body,
        startY: cursorY,
        margin: 6,
        theme: 'grid',
        tableWidth: receiptWidth - 12,
        styles: {
            fontSize: cellTextFontSize,
            cellPadding: 0.5,
            fontStyle: 'normal',
            textColor: 'black',
            lineWidth: 0.15,
            lineColor: [72, 72, 72]
        },
        headStyles: { fillColor: [0, 0, 0], textColor: [255, 255, 255] },
        didDrawPage: (d) => { cursorY = d.cursor.y }
    });
    cursorY += 4;

    return doc;
}