import React, { useState, useEffect } from 'react';
import Table from 'rc-table';
import { InputFieldStyle } from '../Styles';
import { AwesomeButton } from 'react-awesome-button';
import QrCodeLoginMaker from '../components/QrCodeLoginMaker';
import RknSmartSelector from '../components/RknUI/RknSmartSelector';
import { PerformGetRequest, PerformSecurePostRequest } from '../Reaknotron/Libs/RknQueryTools';
import { Link } from 'react-router-dom';
import RknButton from '../components/RknUI/RknButton';

const UserManager = () => {

  useEffect(() => {

    GetUserListFromDB();

    PerformGetRequest("/api/user-role-list", (res) => {
      setRolesTableData(res.data);
    });

  }, []);

  const [tableData, setTableData] = useState();
  const [username, setUsername] = useState("");
  const [password_1, setPassword_1] = useState("");
  const [password_2, setPassword_2] = useState("");
  const [level, setLevel] = useState("NOTHING");
  const [roleID, setRoleID] = useState(null);
  const [rolesTableData, setRolesTableData] = useState(null);

  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword_1, setNewPassword_1] = useState("");
  const [newPassword_2, setNewPassword_2] = useState("");

  const [imapUser, setImapUser] = useState("");
  const [imapPassword, setImapPassword] = useState("");
  const [imapHost, setImapHost] = useState("");

  const columns_users = [
    {
      title: "Nom d'Utilisateur",
      dataIndex: 'username',
      key: 'username',
      width: 256,
      className: 'border border-gray-500'
    },
    {
      title: 'Role',
      dataIndex: 'level',
      key: 'level',
      width: 256,
      className: 'border border-gray-500'
    }
  ];

  const columns_roles = [
    {
      title: "Designation",
      dataIndex: '',
      key: 'name',
      width: 256,
      className: 'border border-gray-500',
      render: r => <Link to={'/role-editor?id=' + r._id} className='cursor-pointer'>{r.name}</Link>
    }
  ];

  const GetUserListFromDB = async () => {

    PerformGetRequest("/api/get-user-list", (res) => {
      UpdateTableData(res.data);
    });

  }

  const UpdateTableData = (ParamQueryResult) => {
    let result = [];
    ParamQueryResult.forEach(u => {
      result.push({ id: u._id, username: u.username, level: UserLevelCodeToLabel(u.level) });
    });
    setTableData(result);
  }

  const UserLevelCodeToLabel = (ParamCode) => {
    if (ParamCode == "ADMIN") {
      return "Administrateur";
    } else if (ParamCode == "NOTHING") {
      return "Aucun";
    } else if (ParamCode == "MANAGER") {
      return "Gérant";
    } else if (ParamCode == "EMPLOYEE") {
      return "Employé";
    } else if (ParamCode == "DELIVERY_PERSON") {
      return "Livreur";
    } else {
      return "?";
    }
  }

  const handleUsernameOnChange = (e) => {
    setUsername(e.target.value);
  }

  const handlePassword1OnChange = (e) => {
    setPassword_1(e.target.value);
  }

  const handlePassword2OnChange = (e) => {
    setPassword_2(e.target.value);
  }

  const AddUserToDB = async () => {

    let userToPost = {
      username: username,
      password: password_1,
      roleID: roleID
    };

    PerformSecurePostRequest("/api/new-user", userToPost, (res) => {
      setUsername("");
      setPassword_1("");
      setPassword_2("");
    });

  }

  const UpdatePasswordInDB = async () => {

    let passwordsToPost = {
      username: localStorage.getItem('user'),
      oldPassword: currentPassword,
      newPassword: newPassword_1
    };

    PerformSecurePostRequest("/api/update-user-password", passwordsToPost, (res) => {
      setCurrentPassword("");
      setNewPassword_1("");
      setNewPassword_2("");
    });

  }

  const UpdateImapCredsInDB = async () => {
    
    let credsToPost = {
      username: localStorage.getItem('user'),
      imapUsername: imapUser,
      imapPassword: imapPassword,
      imapServerAddress: imapHost
    };

    PerformSecurePostRequest("/api/update-imap-info", credsToPost, (res) => {
      setImapUser("");
      setImapPassword("");
      setImapHost("");
    });

  }

  const handleRoleChange = (ParamRole) => {
    console.log("ROLE = " + JSON.stringify(ParamRole));
    setRoleID(ParamRole._id);
    // setChangesAvailable(true);
  }

  return (
    <div>
      <br />
      <h3 className='text-3xl font-bold text-gray-100'>Gestion des Utilisateurs</h3>
      <br />
      <div className='flex flex-col items-center text-gray-100 m-4'>

        {/* List */}
        <div className='border-4 border-gray-500 rounded-3xl w-full m-4 p-2 flex flex-col items-center'>
          <h3 className='text-xl font-bold mt-2'>Liste des Utilisateurs</h3>
          <br />
          <Table columns={columns_users} data={tableData} rowKey="id" className='mx-4' />
          <br />
        </div>

        {/* Roles List */}
        <div className='border-4 border-gray-500 rounded-3xl w-full m-4 p-2 flex flex-col items-center'>
          <h3 className='text-xl font-bold mt-2'>Liste des Roles</h3>
          <br />
          <Table columns={columns_roles} data={rolesTableData} rowKey="id" className='mx-4' />
          <br />
        </div>

        {/* Add New User */}
        <div className='border-4 border-gray-500 rounded-3xl w-full m-4 p-2 flex flex-col items-center'>
          <h3 className='text-xl font-bold mt-2'>Créer Un Utilisateur</h3>
          <br />
          <input type='text' className={InputFieldStyle} placeholder="Nom d'Utilisateur..." onChange={handleUsernameOnChange} value={username} />
          <input type='password' className={InputFieldStyle} placeholder="Mot de Passe..." onChange={handlePassword1OnChange} value={password_1} />
          <input type='password' className={InputFieldStyle} placeholder="Confirmation du Mot de Passe..." onChange={handlePassword2OnChange} value={password_2} />

          <div className='flex flex-row items-center justify-center mt-4'>
            <label className="block text-sm font-medium text-gray-900 dark:text-white mr-2">Role</label>
            <RknSmartSelector url={"/api/user-role-list"} idKey="_id" value={roleID} labelKey="name" reaktorContext="ROLE" onChange={handleRoleChange} quickAddRoute="/role-editor" />
          </div>

          {username && password_1 && password_1 == password_2 && roleID && <AwesomeButton onPress={AddUserToDB} >Confirmer</AwesomeButton>}
          <br />
        </div>

        {/* Update password */}
        <div className='border-4 border-gray-500 rounded-3xl w-full m-4 p-2 flex flex-col items-center'>
          <h3 className='text-lg font-bold mt-2'>Mettre à jour votre mot de passe</h3>
          <br />
          <input type='password' className={InputFieldStyle} placeholder="Ancien Mot de Passe..." onChange={(e) => setCurrentPassword(e.target.value)} value={currentPassword} />
          <input type='password' className={InputFieldStyle} placeholder="Nouveau Mot de Passe..." onChange={(e) => setNewPassword_1(e.target.value)} value={newPassword_1} />
          <input type='password' className={InputFieldStyle} placeholder="Confirmation du Mot de Passe..." onChange={(e) => setNewPassword_2(e.target.value)} value={newPassword_2} />

          <RknButton label="Mettre à Jour" onPress={UpdatePasswordInDB} disabled={!(currentPassword && newPassword_1 && newPassword_1 == newPassword_2)} />

          <br />
        </div>

        {/* Update IMAP creds */}
        <div className='border-4 border-gray-500 rounded-3xl w-full m-4 p-2 flex flex-col items-center'>
          <h3 className='text-lg font-bold mt-2'>Informations d'identification IMAP</h3>
          <br />
          <input type='text' className={InputFieldStyle} placeholder="Nom d'Utilisateur..." onChange={(e) => setImapUser(e.target.value)} value={imapUser} />
          <input type='password' className={InputFieldStyle} placeholder="Mot de Passe..." onChange={(e) => setImapPassword(e.target.value)} value={imapPassword} />
          <input type='text' className={InputFieldStyle} placeholder="Serveur IMAP..." onChange={(e) => setImapHost(e.target.value)} value={imapHost} />

          <RknButton label="Mettre à Jour" onPress={UpdateImapCredsInDB} />

          <br />
        </div>

        {/* QR Code Login Maker */}
        <QrCodeLoginMaker />

      </div>
    </div>
  )
}

export default UserManager