import { React, useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { FaTimesCircle, FaBuilding, FaUser } from 'react-icons/fa';
import { PerformGetRequest } from '../Reaknotron/Libs/RknQueryTools';
import '../ScrollBar.css';

import { useTranslation } from 'react-i18next';

const CustomerSearchPopup = (props) => {

    const { t } = useTranslation();

    useEffect(() => {

        PerformGetRequest("/api/get-customer-list", (res) => {
            setCustomerList(res.data);
        });

    }, []);

    const [customerList, setCustomerList] = useState([]);

    const TriggerPropsOnConfirm = (ParamCustomerInfo) => {
        if (props.onConfirm)
            props.onConfirm(ParamCustomerInfo);
    }

    const TriggerPropsOnCancel = () => {
        if (props.onCancel)
            props.onCancel();
    }

    const handleItemOnClick = (ParamItem) => {
        // console.log(JSON.stringify(ParamItem));
        TriggerPropsOnConfirm(ParamItem);
    }

    return (
        <motion.div
            className='fixed top-0 left-0 right-0 z-10 flex flex-col items-center justify-center w-screen h-screen bg-black bg-opacity-60 backdrop-blur-lg'
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.3 }}
        >
            <motion.div
                className='flex flex-col items-center justify-center p-8 m-auto text-gray-100 bg-gray-900 border-4 border-gray-500 rounded-3xl w-72 sm:w-96'
                initial={{ opacity: 0, y: "-50%" }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.3 }}
            >
                <h3 className='mb-4 text-xl font-bold text-gray-100'>{t("pos.search.selectUser")}</h3>

                <div className='flex flex-col w-64 h-64 overflow-y-scroll text-xs bg-gray-900 border-4 border-gray-500 sm:w-72 rounded-xl scrollbar'>
                    {customerList && customerList.map((c, index) => {
                        return (
                            <div key={c.id}
                                className='pl-2 h-6 w-56 sm:w-64 m-0.5 p-0.5 bg-gray-800 text-gray-100 rounded-full hover:bg-gray-600 transition duration-150 cursor-pointer select-none flex flex-row items-start'
                                onClick={() => { handleItemOnClick(c); }}
                            >
                                {c.type === "NATURAL" && <FaUser size={16} />}
                                {c.type === "LEGAL" && <FaBuilding size={16} />}
                                <div className='ml-2'>{c.designation}</div>
                            </div>
                        )
                    })}
                </div>

                <div className='flex flex-row items-center justify-center mt-4'>
                    <button type='button' onClick={TriggerPropsOnCancel} className="px-4 py-2 font-bold text-white bg-blue-500 border-b-4 border-blue-700 rounded hover:bg-blue-400 hover:border-blue-500"><FaTimesCircle className='inline mb-1' size={20} />  {t("button.cancel")}</button>
                </div>

                <br />

            </motion.div>
        </motion.div>
    )
}

export default CustomerSearchPopup