import React, { useState, useEffect, useImperativeHandle, forwardRef } from 'react';
import RknProductsTableRow from './RknProductsTableRow';

const uuid = require('uuid');

const RknProductsTable = forwardRef((props, ref) => {
    const [products, setProducts] = useState({
        // "1": { name: "Product 1", price: 100 },
        // "2": { name: "Product 2", price: 200 },
        // "3": { name: "Product 3", price: 300 },
        // "4": { name: "Product 4", price: 400 },
        // "5": { name: "Product 5", price: 500 },
        // "6": { name: "Product 6", price: 600 },
        // "7": { name: "Product 7", price: 700 },
        // "8": { name: "Product 8", price: 800 },
        // "9": { name: "Product 9", price: 900 },
        // "10": { name: "Product 10", price: 1000 },
        // "11": { name: "Product 11", price: 1100 },
        // "12": { name: "Product 12", price: 1200 }
    });

    useImperativeHandle(ref, () => ({

        addNewRow: (ParamProd) => {

            // const newId = String(Object.keys(products).length + 1);

            const newProductID = ParamProd._id + uuid.v4();

            let price = ParamProd.price;
            let tva = 0;
            if (props.operation) {

                if (props.operation === 'TO') {
                    price = ParamProd.wap;
                } else if (props.operation === 'FROM') {
                    tva = ParamProd.tva ? ParamProd.tva : 0;
                }

            }

            setProducts(prev => ({
                ...prev,
                [newProductID]: {
                    id: ParamProd._id,
                    name: ParamProd.name,
                    price: price,
                    tva: tva,
                    amount: 1,
                    discount: 0
                }
            }));
        },

        load: (ParamProducts) => {
            setProducts(ParamProducts);
        }

    }));

    const handleRowChange = (ParamID, ParamProduct) => {

        if (!ParamID) {
            // console.error("Invalid product ID");
            return;
        }

        // console.log("INDEX ? " + ParamID);
        // console.log("ON CHANGE : " + JSON.stringify(ParamProduct));

        setProducts(prev => ({
            ...prev,
            [ParamID]: ParamProduct
        }));
    }

    useEffect(() => {
        if (props.onChange) {
            props.onChange(products);
        }
    }, [products]);

    return (
        <div>
            <table className='text-lg font-bold'>
                <thead style={{ position: 'sticky', top: 0 }} className='bg-gray-900 z-10'>
                    <tr className='w-full flex flex-row items-center justify-center'>
                        <th className='bg-gray-900 rounded-xl w-64'>Designation</th>
                        <th className='bg-gray-900 rounded-xl w-64'>Lot N°</th>
                        <th className='bg-gray-900 rounded-xl w-48'>Prix</th>
                        <th className='bg-gray-900 rounded-xl w-48'>Qte.</th>
                        <th className='bg-gray-900 rounded-xl w-48'>TVA</th>
                        <th className='bg-gray-900 rounded-xl w-48'>Total TTC</th>
                        {/* <th className='bg-gray-900 rounded-xl w-48'>Remise</th> */}
                    </tr>
                </thead>
                <tbody>
                    {Object.entries(products).map(([index, product]) => (
                        <RknProductsTableRow key={index} id={index} product={product} onChange={handleRowChange} />
                    ))}
                </tbody>
            </table>
        </div>
    );
});

RknProductsTable.displayName = 'RknProductsTable';

export default RknProductsTable;